window.PHILO_BANQUE={"version":2,"updated":"2026-10-27","legacyIds":{"platon-persuasion":"platon-convaincre-sans-faire-connaitre","platon-recherche":"platon-apprendre-et-se-ressouvenir","platon-ecriture":"platon-le-silence-de-lecrit","platon-caverne":null,"platon-desir":null,"aristote-bonheur":"aristote-le-bonheur-et-le-loisir","aristote-vertu":"aristote-devenir-juste","aristote-savoir":"aristote-connaitre-la-cause","aristote-discours":null,"aristote-cite":"aristote-lanimal-politique","aristote-art":"aristote-imiter-pour-apprendre","nietzsche-valeurs":"nietzsche-le-ressentiment-et-les-valeurs","nietzsche-verite":"nietzsche-lhypothese-scientifique","nietzsche-perspective":null,"nietzsche-liberte":"nietzsche-se-liberer-et-creer","baudelaire-remords-et-irreparable":"baudelaire-memoire-et-duree","baudelaire-conscience-et-miroir":"baudelaire-rencontre-et-possible","racine-bonheur-et-interet":"racine-pouvoir-et-peur","racine-honneur-et-argent":"racine-separation-et-avenir","racine-aimer-sans-contraindre":"racine-desir-et-fuite"},"entries":[{"id":"platon-savoir-et-croire","code":"P01","author":"Platon","title":"Savoir et croire","work":"Gorgias","locator":"454d","quote":"Savoir et croyance ne sont donc pas la même chose, c’est évident.","notions":["verite","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Être certain d’une idée suffit-il pour la connaître ?"},{"function":"L’affirmation","sentence":"Socrate distingue le fait de croire une proposition et le fait de savoir qu’elle est vraie."},{"function":"Les concepts","sentence":"La croyance est une adhésion qui peut être vraie ou fausse, tandis que le savoir ne peut pas être faux sans cesser d’être un savoir."},{"function":"La raison","sentence":"C’est pourquoi la force de notre conviction ne permet pas, à elle seule, de distinguer la croyance du savoir."},{"function":"L’exemple","sentence":"Un accusateur peut croire sincèrement un homme coupable alors que l’enquête établit son innocence."},{"function":"La portée","sentence":"Il faut donc examiner ce qui justifie une affirmation, sans conclure que toute croyance serait nécessairement fausse."}],"uses":[{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Introduire une distinction","reason":"Adhérer à une affirmation ne signifie pas encore posséder les raisons qui permettent de la tenir pour vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Être conscient, est-ce savoir ?","function":"Limiter une première réponse","reason":"Être convaincu de quelque chose ne garantit pas qu’on le connaisse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-convaincre-sans-faire-connaitre","code":"P02","author":"Platon","title":"Convaincre sans faire connaître","work":"Gorgias","locator":"454e–455a","quote":"La rhétorique est donc, semble-t-il, productrice de conviction ; elle fait croire que le juste et l’injuste sont ceci et cela, mais elle ne les fait pas connaître.","notions":["langage","justice","verite"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Un discours qui convainc fait-il nécessairement connaître la vérité ?"},{"function":"L’affirmation","sentence":"Socrate affirme que la rhétorique peut faire adopter un jugement sur le juste sans en donner la connaissance."},{"function":"Les concepts","sentence":"Produire une conviction signifie obtenir l’accord de l’auditeur, tandis que faire connaître exige de lui permettre de comprendre pourquoi le jugement est vrai."},{"function":"La raison","sentence":"Dans une assemblée ou un tribunal, l’orateur peut emporter cet accord sans transmettre un savoir à chacun de ceux qui l’écoutent."},{"function":"L’exemple","sentence":"Un jury ému par un plaidoyer peut ainsi approuver une conclusion sans avoir examiné ce qui la justifie."},{"function":"La portée","sentence":"L’efficacité d’une parole ne garantit donc pas sa vérité, même si une parole vraie peut aussi chercher à convaincre."}],"uses":[{"subject":"Bien parler, est-ce bien penser ?","function":"Contester une assimilation","reason":"L’efficacité persuasive ne prouve pas la justesse de la pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Comment savoir ce qui est juste ?","function":"Écarter un faux critère","reason":"L’accord produit par un orateur n’établit pas le savoir du juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Socrate"},{"id":"platon-subir-ou-commettre-linjustice","code":"P03","author":"Platon","title":"Subir ou commettre l’injustice","work":"Gorgias","locator":"469c","quote":"Mais, s’il était nécessaire soit de commettre l’injustice soit de la subir, je choisirais de la subir plutôt que de la commettre.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Faut-il préserver sa sécurité au prix d’une injustice ?"},{"function":"L’affirmation","sentence":"Socrate affirme que, s’il devait choisir, il préférerait subir l’injustice plutôt que la commettre."},{"function":"Les concepts","sentence":"Subir l’injustice signifie être victime d’un tort, tandis que la commettre signifie devenir responsable d’une action injuste."},{"function":"La raison","sentence":"Il juge ce second mal plus grave parce qu’il abîme la qualité morale de celui qui agit, au lieu de seulement lui infliger un dommage extérieur."},{"function":"L’exemple","sentence":"Accuser un innocent pour éviter soi-même une peine préserverait peut-être notre sécurité, mais nous rendrait responsables de sa condamnation."},{"function":"La portée","sentence":"La justice de notre conduite vaut donc davantage que l’évitement de toute souffrance, sans que cela oblige à rechercher le malheur."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Fixer une limite morale","reason":"La préservation de soi ne justifie pas n’importe quelle action.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Soutenir une réponse négative","reason":"Souffrir ne rend pas juste l’injustice que l’on commet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-justice-et-bonheur","code":"P04","author":"Platon","title":"Justice et bonheur","work":"Gorgias","locator":"470e","quote":"J’affirme que l’être (homme ou femme) doté d’une bonne nature morale est heureux, mais que l’être injuste et méchant est malheureux.","notions":["bonheur","justice"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La puissance et la réussite suffisent-elles pour être heureux ?"},{"function":"L’affirmation","sentence":"Socrate soutient qu’une personne juste est heureuse et qu’une personne injuste est malheureuse."},{"function":"Les concepts","sentence":"Il rapporte ainsi le bonheur à la manière dont une personne conduit sa vie, plutôt qu’à la seule quantité de biens dont elle dispose."},{"function":"La raison","sentence":"Une conduite injuste laisse les désirs et les rapports de force gouverner la vie, au lieu de les régler selon ce qui est bon."},{"function":"L’exemple","sentence":"Un dirigeant capable de faire tout ce qui lui plaît peut encore vivre dans la crainte, l’avidité et le désordre."},{"function":"La portée","sentence":"Le succès extérieur ne prouve donc pas le bonheur, mais le lien affirmé entre justice et bonheur demande encore à être défendu."}],"uses":[{"subject":"L’homme injuste peut-il être heureux ?","function":"Défendre une réponse négative","reason":"Les avantages obtenus par l’injustice ne garantissent pas une vie heureuse : ils peuvent entretenir le désordre des désirs et la peur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"La morale peut-elle se définir comme l’art d’être heureux ?","function":"Construire une réponse affirmative","reason":"La justice peut être comprise comme une condition du bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"}],"speaker":"Socrate"},{"id":"platon-linjustice-ne-justifie-pas-linjustice","code":"P05","author":"Platon","title":"L’injustice ne justifie pas l’injustice","work":"Criton","locator":"49b","quote":"Il s’ensuit que même à l’injustice il ne faut en aucune façon répondre par l’injustice, comme se l’imaginent les gens, dès lors que l’on admet qu’il ne faut jamais commettre l’injustice.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une injustice subie rend-elle juste notre vengeance ?"},{"function":"L’affirmation","sentence":"Socrate refuse de répondre à l’injustice par une autre injustice."},{"function":"Les concepts","sentence":"L’injustice désigne ici le tort que l’on fait à autrui, même lorsque cet autre nous a d’abord nui."},{"function":"La raison","sentence":"Si faire injustement du tort est mauvais, le tort subi ne suffit pas à changer la valeur de l’action par laquelle nous ripostons."},{"function":"L’exemple","sentence":"Être victime d’un mensonge n’autorise pas à fabriquer à son tour une fausse accusation."},{"function":"La portée","sentence":"La riposte doit donc rester juste, ce qui permet de distinguer la sanction d’une faute et la vengeance qui reproduit cette faute."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Réfuter une justification","reason":"La situation de victime ne supprime pas l’exigence de justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Limiter le sentiment comme critère","reason":"Le sentiment d’avoir subi un tort peut encore conduire à faire du tort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-une-opinion-vraie-peut-guider","code":"P06","author":"Platon","title":"Une opinion vraie peut guider","work":"Ménon","locator":"97b","quote":"Donc, une opinion vraie n’est pas un moins bon guide, pour la rectitude de l’action, que la raison.","notions":["raison","verite","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Faut-il toujours savoir pourquoi une action est correcte pour agir correctement ?"},{"function":"L’affirmation","sentence":"Socrate reconnaît qu’une opinion vraie peut guider une action aussi bien qu’un savoir."},{"function":"Les concepts","sentence":"L’opinion vraie atteint le vrai sans nécessairement pouvoir le justifier, alors que le savoir en possède les raisons."},{"function":"La raison","sentence":"Pour arriver au bon résultat, la vérité de l’indication peut suffire, même lorsque celui qui la donne ne sait pas l’expliquer."},{"function":"L’exemple","sentence":"Dans le dialogue, quelqu’un qui a une opinion vraie du chemin de Larissa peut guider les voyageurs aussi bien que celui qui connaît ce chemin."},{"function":"La portée","sentence":"L’efficacité pratique ne permet donc pas de confondre opinion et savoir, car une opinion vraie reste plus fragile qu’une connaissance justifiée."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Nuancer la nécessité du savoir","reason":"Une action correcte peut être guidée par une opinion vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer vérité et justification","reason":"Une croyance peut être vraie sans que son détenteur sache en rendre raison.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}],"speaker":"Socrate"},{"id":"platon-apprendre-et-se-ressouvenir","code":"P07","author":"Platon","title":"Apprendre et se ressouvenir","work":"Ménon","locator":"81d","quote":"Ainsi, le fait de chercher et le fait d’apprendre sont, au total, une réminiscence.","notions":["raison","science"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment chercher une connaissance que l’on ne possède pas encore ?"},{"function":"L’affirmation","sentence":"Socrate propose de comprendre la recherche et l’apprentissage comme une réminiscence."},{"function":"Les concepts","sentence":"La réminiscence est le retour à une connaissance que l’âme aurait acquise avant sa vie présente."},{"function":"La raison","sentence":"Cette hypothèse permet d’expliquer comment une réponse peut être reconnue comme vraie sans avoir été simplement reçue d’un maître."},{"function":"L’exemple","sentence":"L’interrogation du jeune serviteur dans le Ménon fait apparaître une réponse géométrique à travers ses erreurs et ses rectifications."},{"function":"La portée","sentence":"Apprendre serait donc retrouver par l’examen, mais l’expérience du dialogue ne prouve pas à elle seule l’existence antérieure de l’âme."}],"uses":[{"subject":"D’où viennent nos connaissances ?","function":"Proposer une origine du savoir","reason":"La réminiscence fait dépendre l’apprentissage d’un savoir antérieur de l’âme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer possession et accès","reason":"Une connaissance supposée présente dans l’âme peut encore demander à être retrouvée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-pourquoi-les-hommes-sassocient","code":"P08","author":"Platon","title":"Pourquoi les hommes s’associent","work":"La République","locator":"II, 369c","quote":"Dès lors, un homme recourt à un autre pour un besoin particulier, puis à un autre en fonction de tel autre besoin, et parce qu’ils manquent d’une multitude de choses, les hommes se rassemblent nombreux au sein d’une même fondation, s’associant pour s’entraider.","notions":["etat","travail"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi les hommes ne vivent-ils pas chacun de leur côté ?"},{"function":"L’affirmation","sentence":"Socrate explique leur association par la diversité de leurs besoins et leur incapacité à les satisfaire seuls."},{"function":"Les concepts","sentence":"L’entraide consiste à recevoir d’autrui ce que l’on ne peut produire soi-même et à lui apporter en retour une autre contribution."},{"function":"La raison","sentence":"Comme chacun manque de plusieurs choses, la coopération et la répartition des activités rendent la vie commune avantageuse."},{"function":"L’exemple","sentence":"Le cultivateur peut fournir la nourriture tandis que le bâtisseur construit les logements dont tous ont besoin."},{"function":"La portée","sentence":"Les besoins expliquent donc une raison de vivre ensemble, sans suffire à déterminer ce qui rend cette communauté juste."}],"uses":[{"subject":"Est-ce la faiblesse qui nous pousse à vivre en société ?","function":"Installer une première réponse","reason":"L’insuffisance de chacun explique le recours à la coopération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"},{"subject":"Les hommes ne vivent-ils en société que par intérêt ?","function":"Donner sa part de vérité à l’intérêt","reason":"L’entraide répond aux besoins ; il reste à examiner si elle épuise le sens de la société.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"}],"speaker":"Socrate"},{"id":"platon-la-justice-et-les-fonctions","code":"P09","author":"Platon","title":"La justice et les fonctions","work":"La République","locator":"IV, 433b","quote":"Et nous avons dit, de plus, que la justice consiste à s’occuper de ses tâches propres et à ne pas se disperser dans des tâches diverses, et cela, nous l’avons souvent entendu dire de plusieurs autres et nous-mêmes l’avons affirmé à plusieurs reprises.","notions":["justice","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Qu’est-ce qui rend juste l’organisation d’une cité ?"},{"function":"L’affirmation","sentence":"Socrate propose que chacun y accomplisse la tâche qui lui revient sans empiéter sur celles des autres."},{"function":"Les concepts","sentence":"La justice est alors un ordre des fonctions, et non seulement le respect de règles dans les échanges entre personnes."},{"function":"La raison","sentence":"La cité fonctionne comme un ensemble dont chaque activité contribue au bien commun lorsqu’elle tient sa place."},{"function":"L’exemple","sentence":"Les gardiens doivent ainsi protéger la cité plutôt qu’utiliser leur pouvoir pour s’approprier le travail des autres."},{"function":"La portée","sentence":"Cette conception exige un accord entre les fonctions, mais laisse à examiner la justice de leur répartition et la possibilité d’en changer."}],"uses":[{"subject":"Comment savoir ce qui est juste ?","function":"Proposer un critère à examiner","reason":"La justice est ici un ordre des fonctions : la répartition des tâches compte autant que la conduite de chacun.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"L’État doit-il mettre fin aux injustices ?","function":"Préciser ce que l’État devrait réaliser","reason":"Envisager la justice comme un ordre des fonctions, puis en examiner les limites.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-la-liberte-qui-devient-servitude","code":"P10","author":"Platon","title":"La liberté qui devient servitude","work":"La République","locator":"VIII, 564a","quote":"Une liberté excessive ne peut donc apparemment se muer qu’en une servitude excessive, et cela aussi bien pour l’individu que pour la cité.","notions":["liberte","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une liberté sans aucune limite peut-elle se conserver ?"},{"function":"L’affirmation","sentence":"Socrate soutient que la recherche d’une liberté excessive peut aboutir à une servitude excessive."},{"function":"Les concepts","sentence":"La liberté visée ici est le refus de toute autorité et de toute règle, tandis que la servitude est la soumission à un pouvoir qui ne rencontre plus de limites."},{"function":"La raison","sentence":"Dans l’analyse de Platon, le désordre des désirs et des conflits peut préparer l’appel à un protecteur qui finit par dominer tous les autres."},{"function":"L’exemple","sentence":"Un chef d’abord soutenu contre les puissants peut supprimer ses adversaires puis les garanties de ceux qui l’ont soutenu."},{"function":"La portée","sentence":"La liberté peut donc avoir besoin de limites communes, sans que cela permette de présenter toute démocratie comme une tyrannie en devenir."}],"uses":[{"subject":"L’État est-il le garant de ma liberté ?","function":"Faire apparaître une limite","reason":"L’absence de règle commune peut préparer la domination plutôt que la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Dépasser une opposition simple","reason":"Certaines contraintes peuvent empêcher la liberté de se détruire elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"}],"speaker":"Socrate"},{"id":"platon-le-silence-de-lecrit","code":"P11","author":"Platon","title":"Le silence de l’écrit","work":"Phèdre","locator":"275d","quote":"On pourrait croire qu’ils parlent pour exprimer quelque réflexion ; mais, si on les interroge, parce qu’on souhaite comprendre ce qu’ils disent, c’est une seule chose qu’ils se contentent de signifier, toujours la même.","notions":["langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Un texte écrit peut-il expliquer lui-même ce que nous ne comprenons pas en lui ?"},{"function":"L’affirmation","sentence":"Socrate affirme qu’un discours écrit répète la même signification au lieu de répondre à l’interrogation de son lecteur."},{"function":"Les concepts","sentence":"La permanence des signes permet de conserver une parole, mais ne lui donne pas la capacité d’expliquer ce qui reste obscur."},{"function":"La raison","sentence":"Une fois fixé, le discours répète les mêmes signes et ne choisit ni ses lecteurs ni les explications dont ils ont besoin."},{"function":"L’exemple","sentence":"Une définition écrite ne peut pas reconnaître notre erreur de lecture et la corriger comme le ferait un interlocuteur."},{"function":"La portée","sentence":"L’écrit peut soutenir la compréhension, mais sa conservation ne remplace pas le travail vivant de l’explication."}],"uses":[{"subject":"Le langage n’est-il qu’un outil ?","function":"Examiner une limite du support","reason":"Le discours écrit circule sans pouvoir ajuster sa réponse au lecteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"Bien parler, est-ce bien penser ?","function":"Introduire l’exigence de justification","reason":"Un discours fixé ne remplace pas l’aptitude vivante à répondre aux objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}],"speaker":"Socrate","situation":"Socrate examine les discours écrits : leurs signes demeurent identiques quand le lecteur leur demande une explication."},{"id":"platon-linspiration-du-poete","code":"P12","author":"Platon","title":"L’inspiration du poète","work":"Ion","locator":"533e","quote":"En effet, tous les poètes auteurs de vers épiques – je parle des bons poètes – ne sont pas tels par l’effet d’un art, mais c’est inspirés par le dieu et possédés par lui qu’ils profèrent tous ces beaux poèmes.","notions":["art"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un poète peut-il réussir sans savoir expliquer sa réussite ?"},{"function":"L’affirmation","sentence":"Dans l’Ion, Socrate attribue la puissance des bons poètes à une inspiration divine plutôt qu’à la maîtrise d’un art."},{"function":"Les concepts","sentence":"L’art est ici un savoir réglé dont on peut rendre raison, tandis que l’inspiration fait parler sous l’effet d’une puissance qui nous dépasse."},{"function":"La raison","sentence":"Le dialogue distingue ainsi la force d’une parole poétique et les connaissances que son auteur ou son interprète peut réellement justifier."},{"function":"L’exemple","sentence":"Ion peut émouvoir en récitant Homère sans connaître pour autant la médecine ou la stratégie dont les poèmes parlent."},{"function":"La portée","sentence":"La réussite poétique ne prouve donc pas la possession du savoir correspondant, sans que cela suffise à exclure tout travail du poète."}],"uses":[{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Soutenir une hypothèse à discuter","reason":"La beauté produite peut dépasser le savoir explicite de son auteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’artiste est-il maître de son œuvre ?","function":"Limiter la maîtrise","reason":"Le poète ne commande pas entièrement ce qui fait la valeur de sa production.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.2 : construire la nouvelle réponse","reason":"L’inspiration permet de distinguer produire une œuvre réussie et savoir expliquer sa production.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}],"speaker":"Socrate"},{"id":"platon-le-dialogue-interieur","code":"P13","author":"Platon","title":"Le dialogue intérieur","work":"Théétète","locator":"189e–190a","quote":"Car voici ce que me semble faire l’âme quand elle pense : rien d’autre que dialoguer, s’interrogeant elle-même et répondant, affirmant et niant.","notions":["conscience","langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment pouvons-nous discuter une idée lorsque nous sommes seuls ?"},{"function":"L’affirmation","sentence":"Socrate décrit la pensée comme un dialogue que l’âme entretient avec elle-même."},{"function":"Les concepts","sentence":"Dialoguer signifie ici se poser des questions, avancer des réponses et examiner ce que l’on doit affirmer ou nier."},{"function":"La raison","sentence":"La pensée ne reçoit donc pas seulement des idées, elle les confronte avant de se fixer sur un jugement."},{"function":"L’exemple","sentence":"Avant de tenir une promesse pour obligatoire dans une situation nouvelle, nous pouvons en examiner intérieurement les raisons et les objections."},{"function":"La portée","sentence":"La parole intérieure éclaire ainsi le travail du jugement, sans établir que toute forme de pensée soit un discours prononcé en silence."}],"uses":[{"subject":"Penser, est-ce se parler à soi-même ?","function":"Défendre une analyse du penser","reason":"L’interrogation et la réponse peuvent s’effectuer intérieurement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Peut-on penser sans douter ?","function":"Montrer le rôle de l’examen","reason":"Penser implique de mettre des propositions à l’épreuve avant de trancher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}],"speaker":"Socrate"},{"id":"platon-le-temps-et-leternite","code":"P14","author":"Platon","title":"Le temps et l’éternité","work":"Timée","locator":"37d","quote":"Le démiurge a donc l’idée de fabriquer une image mobile de l’éternité ; et, tandis qu’il met le ciel en ordre, il fabrique de l’éternité qui reste dans l’unité une certaine image éternelle progressant suivant le nombre, celle-là même que précisément nous appelons le « temps ».","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un monde changeant peut-il présenter un ordre durable ?"},{"function":"L’affirmation","sentence":"Le Timée présente le temps comme une image mobile de l’éternité produite avec l’organisation du ciel."},{"function":"Les concepts","sentence":"L’éternité demeure dans l’unité, tandis que le temps se déploie dans une succession réglée par le nombre."},{"function":"La raison","sentence":"Les mouvements célestes permettent de retrouver un ordre dans le changement au lieu de le laisser à une succession sans mesure."},{"function":"L’exemple","sentence":"Le retour des jours, des mois et des années donne ainsi des repères réguliers à ce qui naît et se transforme."},{"function":"La portée","sentence":"L’éternité n’est donc pas un temps qui ne finirait jamais, mais ce dont le temps reproduit l’ordre à travers la succession."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer deux modes d’être","reason":"L’éternité ne désigne pas simplement un temps qui durerait sans fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Maîtrise-t-on le temps ?","function":"Préciser l’objet de la maîtrise","reason":"Le nombre et l’ordre rendent le temps mesurable sans le rendre disponible à volonté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"speaker":"Timée"},{"id":"platon-les-richesses-et-la-vertu","code":"P15","author":"Platon","title":"Les richesses et la vertu","work":"Apologie de Socrate","locator":"30b","quote":"Ce n’est pas des richesses que vient la vertu, mais c’est de la vertu que viennent les richesses et tous les autres biens, pour les particuliers comme pour l’État.","notions":["bonheur","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"La possession de richesses suffit-elle à rendre une vie bonne ?"},{"function":"L’affirmation","sentence":"Socrate donne la priorité à la vertu plutôt qu’à l’acquisition des richesses."},{"function":"Les concepts","sentence":"La vertu est la qualité morale qui règle notre conduite, tandis que les richesses sont des ressources dont la valeur dépend aussi de l’usage."},{"function":"La raison","sentence":"Une possession peut servir une action bonne ou aggraver une conduite injuste, de sorte que son utilité ne garantit pas son bon emploi."},{"function":"L’exemple","sentence":"Une fortune peut permettre d’aider des proches, mais aussi d’acheter des complicités pour nuire à autrui."},{"function":"La portée","sentence":"Il faut donc prendre soin de sa conduite pour faire bon usage des biens, sans promettre que la vertu enrichira toujours celui qui la pratique."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer possession et bien véritable","reason":"La possession ne suffit pas : il faut examiner le rapport que l’on entretient avec ce que l’on possède.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Définir une condition morale","reason":"Les avantages matériels ne justifient pas le sacrifice de la vertu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"speaker":"Socrate"},{"id":"aristote-le-desir-de-savoir","code":"A01","author":"Aristote","title":"Le désir de savoir","work":"Métaphysique","locator":"A, 1, 980a21","quote":"Tous les humains ont par nature le désir de savoir.","notions":["science","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"La connaissance n’a-t-elle de valeur que lorsqu’elle sert à quelque chose ?"},{"function":"L’affirmation","sentence":"Aristote affirme que le désir de savoir appartient à la nature humaine."},{"function":"Les concepts","sentence":"Ce désir peut porter sur la connaissance elle-même, sans se réduire à la recherche d’un avantage pratique."},{"function":"La raison","sentence":"Aristote en prend pour indice le plaisir des sensations, particulièrement celui de voir, même lorsque nous n’en attendons aucune action utile."},{"function":"L’exemple","sentence":"Nous pouvons ainsi observer les formes d’un paysage par intérêt pour leurs différences, sans vouloir en tirer un produit."},{"function":"La portée","sentence":"La connaissance peut donc valoir pour elle-même, sans que cela rende toute recherche également souhaitable ou prioritaire."}],"uses":[{"subject":"Peut-on désirer savoir pour savoir ?","function":"Soutenir une valeur propre du connaître","reason":"La recherche de connaissance peut être désirée indépendamment de son utilité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Pourquoi désire-t-on savoir ?","function":"Proposer une origine du désir","reason":"Le texte rattache le désir de savoir à la nature humaine et au plaisir de percevoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"La science doit-elle être utile ?","function":"II.1 : introduire une autre exigence","reason":"Le désir de savoir peut donner une valeur propre à la connaissance, distincte de son utilité pratique.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-la-science-doit-elle-etre-utile.html","a20Step":"II.1","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"aristote-connaitre-la-cause","code":"A02","author":"Aristote","title":"Connaître la cause","work":"Seconds Analytiques","locator":"I, 2, 71b9–12","quote":"Nous pensons connaître scientifiquement chaque chose au sens absolu, et non pas à la manière sophistique par accident, lorsque nous pensons connaître la cause du fait de laquelle la chose est, savoir que c’est bien la cause de la chose et que cette chose ne peut pas être autrement qu’elle n’est.","notions":["science","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Connaître un fait suffit-il pour le comprendre scientifiquement ?"},{"function":"L’affirmation","sentence":"Aristote exige que le savoir scientifique fasse connaître la cause du fait et sa nécessité."},{"function":"Les concepts","sentence":"La cause explique pourquoi la chose est ainsi, tandis que la nécessité signifie qu’elle ne peut pas être autrement dans les conditions considérées."},{"function":"La raison","sentence":"Un constat isolé n’explique pas encore pourquoi le fait se produit et ne donne donc pas à lui seul cette connaissance."},{"function":"L’exemple","sentence":"Voir une éclipse n’équivaut pas à comprendre pourquoi la Terre interposée prive la Lune de lumière."},{"function":"La portée","sentence":"Ce modèle distingue la science du simple constat, mais doit être confronté aux formes de connaissance qui portent sur des faits variables ou probables."}],"uses":[{"subject":"Savoir, est-ce ne rien croire ?","function":"Définir une exigence de connaissance","reason":"La science n’est pas seulement une conviction vraie ; elle doit rendre raison du fait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer assentiment et science","reason":"La croyance peut manquer de l’explication causale requise par le savoir scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"aristote-apprendre-en-faisant","code":"A03","author":"Aristote","title":"Apprendre en faisant","work":"Éthique à Nicomaque","locator":"II, 1, 1103a32–33","quote":"En effet, ce qu’on doit apprendre à faire, c’est en le faisant que nous l’apprenons.","notions":["technique","art"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Comment acquérir une capacité que l’on ne sait pas encore exercer ?"},{"function":"L’affirmation","sentence":"Aristote affirme que certaines activités s’apprennent par leur pratique."},{"function":"Les concepts","sentence":"Apprendre à faire consiste à former une capacité durable, et pas seulement à recevoir une règle."},{"function":"La raison","sentence":"L’exercice transforme progressivement celui qui agit et lui permet de mieux accomplir ce qu’il essaie déjà de faire."},{"function":"L’exemple","sentence":"On apprend à jouer d’un instrument en jouant, en corrigeant ses erreurs et en reprenant les passages difficiles."},{"function":"La portée","sentence":"La pratique est donc formatrice, à condition de ne pas confondre un exercice qui progresse avec la répétition aveugle d’un défaut."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Construire la part de vérité de la pratique","reason":"L’exercice forme des capacités, sans suffire à expliquer toute création.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Installer un acquis à dépasser","reason":"La pratique est nécessaire à une maîtrise, mais ne définit pas seule l’artiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-devenir-juste","code":"A04","author":"Aristote","title":"Devenir juste","work":"Éthique à Nicomaque","locator":"II, 1, 1103b1–2","quote":"De la même façon, c’est donc aussi en exécutant des actes justes que nous devenons justes, des actes tempérants qu’on devient tempérant et des actes courageux qu’on devient courageux.","notions":["devoir","justice"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Suffit-il de connaître la justice pour devenir juste ?"},{"function":"L’affirmation","sentence":"Aristote affirme que les qualités morales se forment par l’accomplissement des actes correspondants."},{"function":"Les concepts","sentence":"Devenir juste signifie acquérir une disposition stable à choisir et à faire ce qui est juste."},{"function":"La raison","sentence":"Nos actes répétés façonnent nos manières de désirer, de décider et de réagir, comme les exercices façonnent une capacité technique."},{"function":"L’exemple","sentence":"Apprendre à partager équitablement prépare à reconnaître et à choisir l’équité dans des situations nouvelles."},{"function":"La portée","sentence":"La formation morale demande donc des actes, mais une action extérieurement juste ne prouve pas encore que son auteur agisse avec justice et pour de bonnes raisons."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Compléter la connaissance par la formation","reason":"Connaître le bien ne remplace pas l’acquisition d’une disposition à l’accomplir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Construire la part de l’acquisition","reason":"La conduite juste suppose une formation par les actes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-le-juste-milieu","code":"A05","author":"Aristote","title":"Le juste milieu","work":"Éthique à Nicomaque","locator":"II, 6, 1106b36–1107a1","quote":"Par conséquent, la vertu est un état décisionnel qui consiste en une moyenne, fixée relativement à nous.","notions":["devoir","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Agir bien consiste-t-il à appliquer partout une quantité identique ?"},{"function":"L’affirmation","sentence":"Aristote définit la vertu comme une disposition à choisir un milieu relatif à celui qui agit."},{"function":"Les concepts","sentence":"Ce milieu évite l’excès et le défaut selon les circonstances, au lieu de partager mécaniquement la distance entre deux extrêmes."},{"function":"La raison","sentence":"Une action réussie doit convenir à la situation et à la personne, ce qui exige un jugement plutôt qu’une recette."},{"function":"L’exemple","sentence":"Le courage évite ainsi la fuite devant tout danger comme l’exposition irréfléchie à n’importe quel risque."},{"function":"La portée","sentence":"La vertu recherche donc ce qui convient, sans signifier que toute action mauvaise pourrait devenir bonne par simple modération."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Préciser le jugement pratique","reason":"La règle doit être appliquée par un choix attentif aux circonstances.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Construire une transformation du désir","reason":"La vertu éduque les affections au lieu de seulement les supprimer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-deliberer-sur-les-moyens","code":"A06","author":"Aristote","title":"Délibérer sur les moyens","work":"Éthique à Nicomaque","locator":"III, 3, 1112b11–12","quote":"D’autre part, nous ne délibérons pas des fins, mais des moyens pour y parvenir.","notions":["technique","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Que cherchons-nous lorsque nous délibérons sur une action ?"},{"function":"L’affirmation","sentence":"Aristote distingue la fin déjà posée et les moyens que la délibération examine pour l’atteindre."},{"function":"Les concepts","sentence":"La fin est ce que nous voulons obtenir, tandis que les moyens sont les actions susceptibles d’y conduire."},{"function":"La raison","sentence":"Une fois le but fixé, la délibération porte sur ce qui dépend de nous et sur les voies réellement possibles."},{"function":"L’exemple","sentence":"Le médecin qui cherche à guérir compare les traitements adaptés plutôt que de redéfinir la guérison à chaque décision."},{"function":"La portée","sentence":"Choisir des moyens efficaces ne suffit donc pas à justifier une fin, dont la valeur peut demander un autre examen."}],"uses":[{"subject":"Existe-t-il des techniques pour être heureux ?","function":"Distinguer fin et moyens","reason":"Un procédé peut aider à atteindre un but sans établir en quoi consiste le bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-les-amis-et-les-autres-biens","code":"A07","author":"Aristote","title":"Les amis et les autres biens","work":"Éthique à Nicomaque","locator":"VIII, 1, 1155a5–6","quote":"Sans amis en effet nul ne choisirait de vivre, aurait-il tous les biens qui restent ; car c’est lorsqu’ils sont riches et en possession des formes du pouvoir et de la puissance que les gens éprouvent surtout le besoin d’amis.","notions":["bonheur"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Posséder tous les autres biens rendrait-il l’amitié superflue ?"},{"function":"L’affirmation","sentence":"Aristote affirme que même une vie comblée de richesses et de pouvoir resterait indésirable sans amis."},{"function":"Les concepts","sentence":"L’amitié est une relation dans laquelle on souhaite du bien à l’autre pour lui-même et de manière réciproque."},{"function":"La raison","sentence":"Les biens possédés ne remplacent ni la possibilité de les partager ni celle d’agir avec des personnes auxquelles on tient."},{"function":"L’exemple","sentence":"Une réussite matérielle peut laisser sans personne avec qui se réjouir ou accomplir une action généreuse."},{"function":"La portée","sentence":"L’amitié appartient donc à la vie bonne au lieu de seulement compenser un manque de ressources."}],"uses":[{"subject":"La recherche du bonheur est-elle un idéal égoïste ?","function":"Contester l’autosuffisance solitaire","reason":"La vie bonne inclut un lien avec autrui qui ne se réduit pas à sa possession.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Limiter l’accumulation des biens","reason":"La possession de nombreux biens peut laisser manquer l’amitié.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-le-bonheur-et-le-loisir","code":"A08","author":"Aristote","title":"Le bonheur et le loisir","work":"Éthique à Nicomaque","locator":"X, 7, 1177b4","quote":"De plus, le bonheur semble impliquer le loisir.","notions":["bonheur","travail"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Être libéré du travail suffit-il pour être heureux ?"},{"function":"L’affirmation","sentence":"Aristote rapporte le bonheur au loisir, c’est-à-dire à une activité choisie pour elle-même."},{"function":"Les concepts","sentence":"Le loisir s’oppose ici à l’occupation imposée par la nécessité, et non à toute activité."},{"function":"La raison","sentence":"Si l’on peine pour obtenir du repos, ce repos doit permettre une manière de vivre qui ait sa valeur propre."},{"function":"L’exemple","sentence":"Étudier une question pour la comprendre peut ainsi donner un sens au temps libéré, au lieu de seulement remplir un vide."},{"function":"La portée","sentence":"Le bonheur ne se réduit donc ni à travailler sans fin ni à ne rien faire, mais demande d’examiner les activités auxquelles la vie peut se consacrer."}],"uses":[{"subject":"Travailler moins, est-ce vivre mieux ?","function":"Distinguer temps libéré et vie bonne","reason":"La réduction de la peine vaut par les activités qu’elle rend possibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"},{"subject":"Faut-il travailler pour être heureux ?","function":"Distinguer condition et fin","reason":"Le travail peut préparer les conditions d’une vie qui trouve sa fin ailleurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"aristote-lanimal-politique","code":"A09","author":"Aristote","title":"L’animal politique","work":"Les Politiques","locator":"I, 2, 1253a7–8","quote":"Que l’homme soit un animal politique plus que n’importe quelle abeille et que n’importe quel animal grégaire, c’est évident.","notions":["etat","langage"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La vie politique n’est-elle qu’une façon de se regrouper ?"},{"function":"L’affirmation","sentence":"Aristote affirme que l’être humain est politique dans un sens plus fort que les animaux vivant en groupe."},{"function":"Les concepts","sentence":"La vie politique suppose une communauté capable de discuter ce qui est avantageux, juste ou injuste."},{"function":"La raison","sentence":"Le langage permet de mettre ces évaluations en commun, au-delà de la simple expression du plaisir ou de la douleur."},{"function":"L’exemple","sentence":"Débattre d’une loi commune demande ainsi de donner des raisons sur ce qui doit valoir pour les citoyens."},{"function":"La portée","sentence":"La communauté humaine ne se comprend donc pas seulement par la proximité physique ou l’instinct de regroupement."}],"uses":[{"subject":"Doit-on tout attendre de l’État ?","function":"Fonder le besoin de communauté","reason":"La communauté politique répond à une dimension constitutive de la vie humaine, sans se confondre avec toute sa vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"Le langage des animaux est-il comparable à celui des hommes ?","function":"Introduire une différence de fonction","reason":"L’enjeu politique du langage distingue la communauté humaine du simple grégarisme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}]},{"id":"aristote-le-langage-et-le-juste","code":"A10","author":"Aristote","title":"Le langage et le juste","work":"Les Politiques","locator":"I, 2, 1253a14–15","quote":"Mais le langage existe en vue de manifester l’avantageux et le nuisible, et par suite aussi le juste et l’injuste.","notions":["langage","justice","etat"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Le langage sert-il seulement à transmettre des sensations ou des informations ?"},{"function":"L’affirmation","sentence":"Aristote lui attribue la capacité de rendre manifestes l’utile, le nuisible, le juste et l’injuste."},{"function":"Les concepts","sentence":"Manifester signifie rendre une évaluation compréhensible et discutable par d’autres personnes."},{"function":"La raison","sentence":"La mise en commun de tels jugements permet aux hommes de former une communauté qui se donne des règles."},{"function":"L’exemple","sentence":"Discuter de la répartition d’une charge publique exige d’expliquer pourquoi une solution serait équitable et pas seulement avantageuse pour soi."},{"function":"La portée","sentence":"Le langage contribue donc à la vie politique, sans garantir que les décisions prises par la parole soient toujours justes."}],"uses":[{"subject":"Faire usage du langage, est-ce renoncer à la violence ?","function":"Construire une alternative à la force","reason":"Discuter publiquement du juste peut remplacer la seule imposition d’un intérêt.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Le langage n’est-il qu’un outil ?","function":"Élargir la fonction du langage","reason":"Le langage participe à la constitution de la communauté politique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-imiter-pour-apprendre","code":"A11","author":"Aristote","title":"Imiter pour apprendre","work":"Poétique","locator":"4, 1448b4–8","quote":"En effet, les êtres humains sont dès leur enfance naturellement enclins à imiter, et cela précisément les distingue des autres animaux : l’homme est l’être le plus enclin à imiter, et il fait ses premiers apprentissages au moyen de l’imitation.","notions":["art","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’imitation empêche-t-elle de comprendre et d’apprendre ?"},{"function":"L’affirmation","sentence":"Aristote voit dans l’imitation une tendance humaine naturelle et une origine des premiers apprentissages."},{"function":"Les concepts","sentence":"Imiter consiste à reprendre ou à représenter une action ou une forme, ce qui n’exclut pas d’en comprendre l’organisation."},{"function":"La raison","sentence":"L’enfant apprend en reproduisant des gestes, et le plaisir de reconnaître ce qui est représenté contribue aussi à l’intérêt des œuvres."},{"function":"L’exemple","sentence":"Un dessin peut nous faire reconnaître la posture d’un animal en sélectionnant quelques traits au lieu de tout copier."},{"function":"La portée","sentence":"L’imitation peut donc former la perception et l’intelligence, sans suffire à expliquer à elle seule toute création artistique."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Installer le rôle de l’imitation","reason":"L’imitation forme les premières capacités et ne s’oppose pas d’emblée à l’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il prendre la nature pour modèle ?","function":"Nuancer l’opposition nature et culture","reason":"L’imitation peut être naturelle à l’être humain sans fixer un modèle unique à reproduire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-la-connaissance-par-la-fiction","code":"A12","author":"Aristote","title":"La connaissance par la fiction","work":"Poétique","locator":"9, 1451b6–7","quote":"En effet, la poésie raconte les événements davantage dans leur généralité ; l’histoire, les événements dans leur particularité.","notions":["art","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une fiction peut-elle nous apprendre quelque chose sans raconter un fait réel ?"},{"function":"L’affirmation","sentence":"Aristote distingue le récit des faits particuliers et la représentation de ce qui pourrait arriver de manière générale."},{"function":"Les concepts","sentence":"Le général désigne ici des rapports vraisemblables ou nécessaires entre un type de situation, une conduite et ses conséquences."},{"function":"La raison","sentence":"Une intrigue inventée peut faire comprendre ces rapports en les organisant de manière cohérente."},{"function":"L’exemple","sentence":"Une tragédie peut montrer comment une décision aveugle conduit au malheur sans que tous ses personnages aient réellement existé."},{"function":"La portée","sentence":"La connaissance apportée par une œuvre ne se mesure donc pas seulement à l’exactitude historique des événements qu’elle représente."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Établir un pouvoir de compréhension","reason":"La fiction fait saisir des rapports vraisemblables ou nécessaires entre les actions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il indifférent à la vérité ?","function":"Distinguer vérité et fait réel","reason":"Ne pas raconter un événement réellement arrivé n’implique pas de ne rien faire comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"aristote-la-main-et-lintelligence","code":"A13","author":"Aristote","title":"La main et l’intelligence","work":"Les Parties des animaux","locator":"IV, 10, 687a7–10","quote":"Anaxagore dit ainsi que c’est du fait qu’il a des mains que l’être humain est le plus intelligent des animaux, alors qu’il est rationnel que ce soit du fait qu’il est le plus intelligent qu’il soit pourvu de mains.","notions":["technique","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’intelligence vient-elle de l’outil ou explique-t-elle la capacité d’en user ?"},{"function":"L’affirmation","sentence":"Aristote refuse la thèse d’Anaxagore qui fait des mains la cause de la supériorité intellectuelle humaine."},{"function":"Les concepts","sentence":"Il distingue la possession d’un instrument et l’aptitude à l’employer de plusieurs manières."},{"function":"La raison","sentence":"Dans son explication, la nature attribue la main à l’être capable de tirer parti de nombreux instruments."},{"function":"L’exemple","sentence":"Posséder une flûte ne donne pas l’art d’en jouer, alors que cet art permet de faire bon usage de l’instrument."},{"function":"La portée","sentence":"La technique suppose donc des capacités d’usage, mais cette explication ne suffit pas à nier que les outils puissent ensuite développer ces capacités."}],"uses":[{"subject":"Y a-t-il de l’intelligence dans les techniques ?","function":"Articuler capacité et instrument","reason":"La main polyvalente rend possible l’exercice de nombreuses techniques, selon une intelligence qui sait en user.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"}]},{"id":"aristote-le-temps-et-le-mouvement","code":"A14","author":"Aristote","title":"Le temps et le mouvement","work":"Physique","locator":"IV, 11, 219b1–2","quote":"Car c’est cela le temps : le nombre d’un mouvement selon l’antérieur et le postérieur.","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Le temps se confond-il avec les changements que nous observons ?"},{"function":"L’affirmation","sentence":"Aristote définit le temps comme ce qui permet de nombrer le mouvement selon l’avant et l’après."},{"function":"Les concepts","sentence":"Le nombre désigne ici l’ordre et la quantité du changement, tandis que l’antérieur et le postérieur distinguent ses moments."},{"function":"La raison","sentence":"Nous reconnaissons un intervalle de temps lorsque nous distinguons des étapes d’un changement et ce qui les sépare."},{"function":"L’exemple","sentence":"Le déplacement régulier d’une aiguille permet de mesurer l’attente d’un événement sans être cet événement lui-même."},{"function":"La portée","sentence":"Le temps se rapporte donc au mouvement sans lui être identique, et sa mesure ne donne pas le pouvoir d’en commander le passage."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer mesure et pouvoir","reason":"Mesurer un mouvement ne signifie pas commander son écoulement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Est-il possible d’échapper au temps ?","function":"Préciser la condition du devenir","reason":"Si le temps permet de nombrer le changement, échapper au temps demanderait autre chose que cesser de regarder une horloge.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"aristote-des-rigueurs-differentes","code":"A15","author":"Aristote","title":"Des rigueurs différentes","work":"Éthique à Nicomaque","locator":"I, 7, 1098a26–29","quote":"Il faut cependant garder aussi en mémoire ce qu’on a dit précédemment, et ne pas réclamer le même genre de rigueur partout.","notions":["raison","science","devoir"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Toute connaissance doit-elle atteindre la précision d’une démonstration mathématique ?"},{"function":"L’affirmation","sentence":"Aristote demande d’ajuster le genre de rigueur à l’objet étudié."},{"function":"Les concepts","sentence":"La rigueur consiste à justifier suffisamment ce que l’on affirme selon la nature du problème."},{"function":"La raison","sentence":"Une matière variable ne permet pas toujours la même exactitude qu’un objet défini par des rapports nécessaires."},{"function":"L’exemple","sentence":"Le géomètre cherche les propriétés de l’angle droit, tandis que le menuisier en cherche une réalisation assez précise pour son travail."},{"function":"La portée","sentence":"Exiger une précision adaptée ne dispense donc pas d’argumenter, mais évite de rendre impossible un jugement en lui demandant une certitude étrangère à son objet."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Distinguer raison pratique et démonstration","reason":"L’incertitude des situations ne supprime pas l’exigence de jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Comment savoir ce qui est juste ?","function":"Délimiter le type de certitude attendu","reason":"La recherche du juste ne se traite pas nécessairement comme un calcul géométrique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}]},{"id":"nietzsche-la-meconnaissance-de-soi","code":"N01","author":"Nietzsche","title":"La méconnaissance de soi","work":"Généalogie de la morale","locator":"Avant-propos, § 1","quote":"Nous ne nous connaissons pas nous-mêmes, nous les hommes de la connaissance, et nous sommes nous-mêmes inconnus à nous-mêmes.","notions":["conscience","inconscient"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"La connaissance du monde garantit-elle la connaissance de soi ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que les hommes voués à la connaissance peuvent demeurer étrangers à eux-mêmes."},{"function":"Les concepts","sentence":"Se connaître demande de comprendre ses propres manières de vivre et de vouloir, au-delà du savoir que l’on accumule sur des objets."},{"function":"La raison","sentence":"L’attention portée à ce que nous cherchons peut nous détourner de l’examen de celui qui cherche."},{"function":"L’exemple","sentence":"Un chercheur peut décrire avec précision son domaine sans reconnaître ce qui oriente son ambition ou ses rivalités."},{"function":"La portée","sentence":"La proximité avec soi ne vaut donc pas connaissance immédiate, sans que cela rende tout examen de soi impossible."}],"uses":[{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Contester un privilège immédiat","reason":"La proximité avec soi peut aller de pair avec la méconnaissance de ses propres activités.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer expérience de soi et connaissance","reason":"Se vivre soi-même ne suffit pas à se comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-les-interpretations-morales","code":"N02","author":"Nietzsche","title":"Les interprétations morales","work":"Par-delà bien et mal","locator":"§ 108","quote":"Il n’y a pas de phénomènes moraux du tout, mais seulement une interprétation morale de phénomènes…","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Le bien et le mal sont-ils des propriétés que l’on constaterait directement dans les faits ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la qualification morale d’un phénomène relève d’une interprétation."},{"function":"Les concepts","sentence":"Interpréter moralement consiste à rapporter ce qui arrive à des valeurs qui permettent de le louer ou de le condamner."},{"function":"La raison","sentence":"La description d’un geste ne contient pas encore les critères au nom desquels nous le jugeons."},{"function":"L’exemple","sentence":"Garder le silence peut être loué comme de la discrétion ou condamné comme de la lâcheté selon le sens qu’on lui donne."},{"function":"La portée","sentence":"Il faut donc examiner les évaluations à l’œuvre dans un jugement moral, sans conclure que toutes les interprétations ont la même valeur."}],"uses":[{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Mettre en cause l’évidence morale","reason":"Une évaluation intériorisée ne prouve pas sa propre validité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Introduire l’histoire de l’évaluation","reason":"Ce qui paraît immédiatement juste peut résulter d’une interprétation acquise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"nietzsche-devenir-ce-que-lon-combat","code":"N03","author":"Nietzsche","title":"Devenir ce que l’on combat","work":"Par-delà bien et mal","locator":"§ 146","quote":"Que celui qui lutte avec des monstres veille à ce que cela ne le transforme pas en monstre.","notions":["justice","etat"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Une lutte juste protège-t-elle toujours celui qui la mène de devenir injuste ?"},{"function":"L’affirmation","sentence":"Nietzsche avertit que le combat contre les monstres peut transformer le combattant en monstre."},{"function":"Les concepts","sentence":"Le monstre désigne ici ce dont on combat la violence ou la cruauté, et la transformation touche les pratiques de celui qui s’y oppose."},{"function":"La raison","sentence":"L’habitude d’affronter un adversaire peut faire adopter ses moyens et perdre de vue la fin initiale."},{"function":"L’exemple","sentence":"Un pouvoir qui prétend combattre la terreur peut en venir à imposer lui-même la peur et l’arbitraire."},{"function":"La portée","sentence":"La valeur d’un combat ne dispense donc pas d’examiner ses moyens et leurs effets sur ceux qui les emploient."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Limiter les moyens de la riposte","reason":"Combattre un mal ne légitime pas la reproduction de ce mal.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"L’État doit-il préférer l’injustice au désordre ?","function":"Mettre à l’épreuve une justification","reason":"Lutter contre le désordre peut corrompre la fin annoncée si les moyens deviennent injustes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}]},{"id":"nietzsche-les-affects-qui-se-combattent","code":"N04","author":"Nietzsche","title":"Les affects qui se combattent","work":"Par-delà bien et mal","locator":"§ 117","quote":"La volonté de surmonter un affect n’est en dernière instance que la volonté d’un autre ou de plusieurs autres affects.","notions":["conscience","inconscient","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Lorsque nous maîtrisons un désir, est-ce nécessairement la raison seule qui commande ?"},{"function":"L’affirmation","sentence":"Nietzsche propose de comprendre la domination d’un affect par la force d’autres affects."},{"function":"Les concepts","sentence":"Un affect est une manière de sentir et d’être poussé à agir, comme la peur, la fierté ou l’attachement."},{"function":"La raison","sentence":"La décision de résister peut donc être soutenue par des forces affectives que l’on ne reconnaît pas immédiatement."},{"function":"L’exemple","sentence":"Refuser une satisfaction présente peut tenir au désir plus fort de réussir, de tenir une promesse ou de garder l’estime d’autrui."},{"function":"La portée","sentence":"La maîtrise de soi demande ainsi de comprendre l’organisation de nos désirs, au lieu de supposer une volonté sans aucun mobile affectif."}],"uses":[{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Déplacer l’opposition raison et désir","reason":"Une conduite réglée peut mobiliser et organiser des affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Interroger le motif de la maîtrise","reason":"Le désir de se maîtriser peut lui-même avoir des mobiles affectifs inaperçus.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"nietzsche-le-ressentiment-et-les-valeurs","code":"N05","author":"Nietzsche","title":"Le ressentiment et les valeurs","work":"Généalogie de la morale","locator":"I, § 10","quote":"L’insurrection des esclaves dans la morale commence lorsque le ressentiment lui-même devient créateur et engendre des valeurs : le ressentiment d’êtres tels que la véritable réaction, celle de l’acte, leur est interdite, qui ne s’en sortent indemnes que par une vengeance imaginaire.","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"Des valeurs morales peuvent-elles naître d’une impossibilité d’agir ?"},{"function":"L’affirmation","sentence":"Nietzsche décrit le ressentiment comme une force capable de créer des valeurs."},{"function":"Les concepts","sentence":"Le ressentiment est une hostilité durable qui, ne pouvant se décharger dans l’action, se transforme en évaluation de l’adversaire."},{"function":"La raison","sentence":"La vengeance devient alors imaginaire, car elle déprécie ce qu’elle ne peut effectivement vaincre."},{"function":"L’exemple","sentence":"Une personne impuissante à rivaliser peut présenter toute réussite adverse comme un vice et sa propre impuissance comme une vertu."},{"function":"La portée","sentence":"Cette analyse invite à interroger l’origine des jugements, sans autoriser à réduire toute demande de justice à du ressentiment."}],"uses":[{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Distinguer ressentiment et jugement juste","reason":"Un sentiment d’impuissance peut produire une évaluation sans en garantir la justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Interroger la provenance des valeurs","reason":"L’origine affective d’un jugement peut rester masquée à celui qui le porte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"nietzsche-les-convictions-comme-prisons","code":"N06","author":"Nietzsche","title":"Les convictions comme prisons","work":"L’Antéchrist","locator":"§ 54","quote":"Les convictions sont des prisons.","notions":["liberte","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel","commentary":[{"function":"Le problème","sentence":"Une conviction peut-elle empêcher de penser librement ?"},{"function":"L’affirmation","sentence":"Nietzsche compare les convictions à des prisons lorsqu’elles soumettent le jugement au lieu de le servir."},{"function":"Les concepts","sentence":"La conviction devient enfermement quand une idée est tenue pour intouchable et décide d’avance de ce que l’on acceptera d’examiner."},{"function":"La raison","sentence":"Celui qui en dépend écarte les objections pour préserver sa certitude au lieu de mesurer celle-ci aux objections."},{"function":"L’exemple","sentence":"Une personne persuadée qu’un groupe a toujours tort peut refuser d’entendre même les raisons qu’il avance."},{"function":"La portée","sentence":"La liberté de penser exige donc de pouvoir reprendre ses convictions, sans imposer l’indécision permanente ni l’absence de toute fin."}],"uses":[{"subject":"Croire nous empêche-t-il de chercher la vérité ?","function":"Soutenir une objection au dogmatisme","reason":"Tenir une affirmation pour intouchable ferme l’enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Montrer une servitude intérieure","reason":"L’enfermement peut venir d’une conviction à laquelle on ne s’autorise plus à toucher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-lhypothese-scientifique","code":"N07","author":"Nietzsche","title":"L’hypothèse scientifique","work":"Le Gai Savoir","locator":"§ 344","quote":"Dans la science, les convictions n’ont pas droit de cité, voilà ce que l’on dit à juste titre : c’est seulement lorsqu’elles s’abaissent au rang modeste d’une hypothèse, d’un point de vue expérimental provisoire, d’une fiction régulatrice, que l’on a le droit de leur accorder l’accès au royaume de la connaissance et de leur y reconnaître même une certaine valeur, – toujours avec cette restriction de demeurer soumises à la surveillance policière, à la police de la méfiance.","notions":["science","verite","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Quelle différence sépare une hypothèse scientifique d’une conviction intangible ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme qu’une proposition n’entre dans la science qu’en acceptant d’être tenue pour provisoire et examinable."},{"function":"Les concepts","sentence":"L’hypothèse est une explication proposée à l’épreuve, tandis que la conviction prétend ici soustraire son contenu à la remise en question."},{"function":"La raison","sentence":"La discipline scientifique exige que les raisons de conserver une proposition puissent être discutées et ses insuffisances recherchées."},{"function":"L’exemple","sentence":"Une explication que des observations contraires ne permettraient jamais de corriger serait protégée de l’examen plutôt que soutenue par lui."},{"function":"La portée","sentence":"Le passage distingue ainsi recherche et dogmatisme, avant d’interroger dans la suite du paragraphe la confiance des savants dans la valeur de la vérité."}],"uses":[{"subject":"Croire en la science, est-ce une forme de religion ?","function":"Distinguer méthode et adhésion inconditionnelle","reason":"L’hypothèse scientifique doit rester exposée à la critique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Savoir, est-ce ne rien croire ?","function":"Nuancer l’opposition","reason":"Une hypothèse est admise provisoirement sans être tenue pour une certitude intangible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"quoteSegments":["Dans la science, les convictions n’ont pas droit de cité,","c’est seulement lorsqu’elles s’abaissent au rang modeste d’une hypothèse,","que l’on a le droit de leur accorder l’accès au royaume de la connaissance"]},{"id":"nietzsche-lart-et-la-lucidite","code":"N08","author":"Nietzsche","title":"L’art et la lucidité","work":"Le Gai Savoir","locator":"§ 107","quote":"Si nous n’avions pas donné notre approbation aux arts et inventé cette espèce de culte du non-vrai : la compréhension de l’universalité du non-vrai et du mensonge que nous offrent à présent les sciences – la compréhension de l’illusion et de l’erreur comme condition de l’existence connaissante et percevante –, nous seraient totalement insupportables.","notions":["art","verite","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Comment supporter une connaissance qui révèle la part d’illusion dans notre existence ?"},{"function":"L’affirmation","sentence":"Nietzsche attribue à l’art la puissance de rendre cette lucidité vivable."},{"function":"Les concepts","sentence":"L’apparence artistique est une forme que nous savons produite et à laquelle nous pouvons pourtant prendre plaisir."},{"function":"La raison","sentence":"Elle permet de ne pas réduire toute expérience à la seule dénonciation de ses erreurs ou de ses imperfections."},{"function":"L’exemple","sentence":"Une œuvre peut donner forme à une souffrance sans la supprimer ni prétendre qu’elle n’a jamais eu lieu."},{"function":"La portée","sentence":"L’art peut donc soutenir une relation à la vérité, sans se confondre avec un mensonge destiné à tromper autrui."}],"uses":[{"subject":"L’art nous aide-t-il à vivre ?","function":"Défendre une nécessité de l’art","reason":"L’expérience esthétique permet une relation supportable à l’existence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Faire apparaître un coût de la lucidité","reason":"La connaissance peut demander une puissance de mise en forme pour être vécue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"nietzsche-donner-forme-a-son-caractere","code":"N09","author":"Nietzsche","title":"Donner forme à son caractère","work":"Le Gai Savoir","locator":"§ 290","quote":"« Donner du style » à son caractère – un art grand et rare !","notions":["conscience","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Devenir soi-même consiste-t-il seulement à découvrir un caractère déjà fixé ?"},{"function":"L’affirmation","sentence":"Nietzsche présente la mise en forme de son caractère comme un art exigeant."},{"function":"Les concepts","sentence":"Donner du style signifie organiser ses forces et ses faiblesses selon une forme que l’on travaille."},{"function":"La raison","sentence":"Ce travail suppose de reconnaître ses dispositions puis de les exercer, de les transformer ou de leur donner une autre place."},{"function":"L’exemple","sentence":"Une grande sensibilité peut devenir un obstacle si elle nous disperse ou une ressource si un travail d’écriture lui donne une forme."},{"function":"La portée","sentence":"La formation de soi unit donc connaissance et exercice, sans permettre de se fabriquer arbitrairement à partir de rien."}],"uses":[{"subject":"Faut-il apprendre à se connaître soi-même ?","function":"Relier connaissance et formation de soi","reason":"Reconnaître ses forces et ses faiblesses peut permettre de les organiser.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=129","sourceLabel":"Recueil académique · p. 129"},{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Déplacer la connaissance vers une tâche","reason":"Se connaître demande un travail de composition plutôt qu’une simple inspection immédiate.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-se-liberer-et-creer","code":"N10","author":"Nietzsche","title":"Se libérer et créer","work":"Ainsi parlait Zarathoustra","locator":"I, « Des trois métamorphoses »","quote":"Créer des valeurs nouvelles, le lion lui-même n’y est pas encore apte ; mais s’affranchir afin de devenir apte à créer des valeurs nouvelles, voilà ce que peut la force du lion.","notions":["liberte","devoir"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Geneviève Bianquis, traduction revue par Paul Mathias","commentary":[{"function":"Le problème","sentence":"Suffit-il de refuser les valeurs reçues pour devenir capable de créer ?"},{"function":"L’affirmation","sentence":"Zarathoustra distingue la libération accomplie par le lion et la création de valeurs nouvelles."},{"function":"Les concepts","sentence":"Le lion représente la force de dire non à une autorité qui impose ses commandements comme sacrés."},{"function":"La raison","sentence":"Ce refus ouvre une liberté, mais ne fournit pas encore les fins auxquelles elle pourra se consacrer."},{"function":"L’exemple","sentence":"Abandonner une règle imposée ne dit pas encore quel engagement nous voulons prendre ni quelle vie nous voulons construire."},{"function":"La portée","sentence":"La liberté ne s’achève donc pas dans l’opposition, puisque l’affirmation de nouvelles valeurs demande une autre puissance, représentée ensuite par l’enfant."}],"uses":[{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Distinguer refus et création","reason":"Dire non à une obligation peut être une étape sans constituer l’autonomie entière.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Construire une émancipation","reason":"La critique des valeurs reçues ouvre une possibilité, sans fournir à elle seule de nouvelles valeurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-les-limites-de-la-connaissance","code":"N11","author":"Nietzsche","title":"Les limites de la connaissance","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 5","quote":"La sagesse trace des limites, même à la connaissance.","notions":["raison","bonheur","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Faut-il vouloir tout connaître sans jamais interroger ce que cette recherche engage ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la sagesse peut fixer des limites au désir de connaissance."},{"function":"Les concepts","sentence":"La sagesse désigne ici une manière de conduire sa vie qui ne traite pas tout savoir comme un bien inconditionnel."},{"function":"La raison","sentence":"La recherche doit aussi répondre de ce qu’elle exige de nous et de la place qu’elle prend parmi nos activités."},{"function":"L’exemple","sentence":"Chercher sans fin à connaître chaque jugement d’autrui sur nous peut nourrir l’inquiétude au lieu d’éclairer une décision."},{"function":"La portée","sentence":"Interroger les limites du connaître ne revient donc pas à préférer toute ignorance, mais à juger la valeur d’une recherche déterminée."}],"uses":[{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger la valeur inconditionnelle du savoir","reason":"Il faut aussi examiner ce que l’exigence de savoir engage pour la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"},{"subject":"Savoir rend-il malheureux ?","function":"Déplacer la question vers l’usage du savoir","reason":"La sagesse peut régler la recherche au lieu d’identifier ignorance et bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}]},{"id":"nietzsche-lepreuve-et-la-force","code":"N12","author":"Nietzsche","title":"L’épreuve et la force","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 8","quote":"Ce qui ne me fait pas mourir me rend plus fort.","notions":["bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Une difficulté doit-elle être jugée seulement d’après la souffrance qu’elle inflige ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme à la première personne qu’une épreuve qui ne le détruit pas peut accroître sa force."},{"function":"Les concepts","sentence":"La force désigne ici une puissance de vivre et de surmonter, et non la simple absence de blessure."},{"function":"La raison","sentence":"Une résistance peut nous obliger à développer des capacités qui ne s’exerceraient pas dans une vie entièrement protégée."},{"function":"L’exemple","sentence":"Un échec peut conduire à reprendre un travail et à mieux comprendre ses exigences."},{"function":"La portée","sentence":"La formule invite ainsi à penser la transformation d’une épreuve, mais ne démontre pas que toute souffrance renforce nécessairement celui qui la subit."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer bonheur et absence d’épreuve","reason":"Une vie peut gagner en puissance en traversant une difficulté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"nietzsche-le-besoin-de-musique","code":"N13","author":"Nietzsche","title":"Le besoin de musique","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 33","quote":"Sans musique la vie serait une erreur.","notions":["art","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"La valeur d’une vie se réduit-elle à la satisfaction des besoins indispensables ?"},{"function":"L’affirmation","sentence":"Nietzsche donne à la musique une importance telle qu’une vie qui en serait privée lui paraît manquer son sens."},{"function":"Les concepts","sentence":"L’erreur désigne ici une manière de vivre appauvrie plutôt qu’une proposition intellectuellement fausse."},{"function":"La raison","sentence":"La musique peut donner rythme, intensité et forme à l’expérience, au-delà de ce qui sert seulement à survivre."},{"function":"L’exemple","sentence":"Un chant peut faire éprouver ensemble une joie ou une douleur que la seule description ne ferait pas vivre de la même manière."},{"function":"La portée","sentence":"L’art peut donc appartenir à ce qui rend une existence désirable, sans que chaque œuvre produise le même effet sur chacun."}],"uses":[{"subject":"Avons-nous besoin d’art ?","function":"Défendre un besoin au-delà de la survie","reason":"Une vie humaine ne s’évalue pas seulement à sa conservation matérielle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il un luxe ?","function":"Contester l’idée d’un simple supplément","reason":"La musique peut être comprise comme une composante de la valeur d’une vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"nietzsche-la-raison-et-les-sens","code":"N14","author":"Nietzsche","title":"La raison et les sens","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 2","quote":"Si nous faussons le témoignage des sens, c’est la « raison » qui en est la cause.","notions":["raison","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Les erreurs viennent-elles toujours des sens plutôt que de nos interprétations ?"},{"function":"L’affirmation","sentence":"Nietzsche accuse certaines constructions de la raison de fausser le témoignage sensible."},{"function":"Les concepts","sentence":"Les sens présentent le changement, tandis que la raison visée ici cherche des choses fixes et identiques derrière ce changement."},{"function":"La raison","sentence":"L’erreur peut donc venir de catégories que nous imposons à l’expérience en les prenant pour la réalité elle-même."},{"function":"L’exemple","sentence":"Nommer une chose peut nous inciter à la croire absolument identique alors même que nous en observons les transformations."},{"function":"La portée","sentence":"La critique demande ainsi d’examiner nos manières d’interpréter, sans déclarer que tout raisonnement serait trompeur."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer la dépendance envers le sensible","reason":"L’interprétation doit répondre de ce qu’elle fait au témoignage des sens.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer perception et interprétation","reason":"L’erreur ne se situe pas nécessairement dans la sensation elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"nietzsche-la-grammaire-et-la-metaphysique","code":"N15","author":"Nietzsche","title":"La grammaire et la métaphysique","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 5","quote":"Je crains bien que nous ne nous débarrassions jamais de Dieu, puisque nous croyons encore à la grammaire…","notions":["langage","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Abandonner une croyance religieuse suffit-il à abandonner les habitudes de pensée qui lui sont liées ?"},{"function":"L’affirmation","sentence":"Nietzsche soutient que certaines croyances métaphysiques peuvent subsister dans notre confiance envers la grammaire."},{"function":"Les concepts","sentence":"Croire à la grammaire signifie ici prendre la structure de nos phrases pour une description nécessaire de la structure du réel."},{"function":"La raison","sentence":"L’habitude de rapporter une action à un sujet peut nous conduire à supposer derrière tout événement un agent ou une substance qui le produirait."},{"function":"L’exemple","sentence":"Dire « je pense » peut ainsi nous faire traiter le « je » comme une réalité déjà connue, alors que la forme de la phrase ne démontre pas son existence comme substance."},{"function":"La portée","sentence":"La critique doit donc examiner les présupposés de nos formulations, au lieu de croire que supprimer le mot « Dieu » libérerait à lui seul la pensée de toute métaphysique."}],"uses":[{"subject":"Le langage déforme-t-il la pensée ?","function":"Interroger une contrainte inaperçue","reason":"La forme grammaticale peut suggérer des êtres ou des causes qu’il reste à justifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Croire, est-ce renoncer à la raison ?","function":"Déplacer l’opposition croyance et rationalité","reason":"La pensée qui se croit délivrée de la croyance peut en conserver certains présupposés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Sommes-nous prisonniers du langage ?","function":"I.2 : renforcer la première réponse","reason":"La grammaire peut imposer à notre pensée des catégories que nous n’avons pas explicitement choisies.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-sommes-nous-prisonniers-du-langage.html","a20Step":"I.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"spinoza-liberte-et-necessite","code":"S01","author":"Spinoza","title":"Liberté et nécessité","work":"Éthique","locator":"I, définition 7","quote":"On dit qu’est libre une chose qui existe par la seule nécessité de sa nature et qui n’est déterminée à agir que par elle seule ; mais on appelle nécessaire ou plutôt contrainte celle qui est déterminée par autre chose à exister et à accomplir ses opérations selon une raison précise et déterminée.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre exige-t-il d’échapper à toute nécessité ?"},{"function":"L’affirmation","sentence":"Spinoza définit la liberté par une action qui découle de la nature propre de ce qui agit."},{"function":"Les concepts","sentence":"La nécessité désigne ce qui suit d’une nature, tandis que la contrainte désigne ici une détermination par autre chose."},{"function":"La raison","sentence":"Une action peut donc être nécessaire sans être imposée du dehors, ce que réalise absolument Dieu seul dans ce système."},{"function":"L’exemple","sentence":"Pour l’homme, comprendre les raisons de sa conduite permet de concevoir une autonomie plus grande que la simple obéissance à une impulsion."},{"function":"La portée","sentence":"La liberté humaine se pense ainsi comme un degré d’activité à conquérir, sans faire de l’homme une cause absolument indépendante."}],"uses":[{"subject":"Être libre, est-ce ne se soumettre à rien ?","function":"Redéfinir la liberté","reason":"Agir librement ne signifie pas être sans cause : une action comprise peut exprimer davantage notre puissance qu’une impulsion subie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Fonder une autonomie active","reason":"Comprendre ce qui nous détermine peut accroître notre activité, sans supprimer notre dépendance envers la nature.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-connaitre-par-les-causes","code":"S02","author":"Spinoza","title":"Connaître par les causes","work":"Éthique","locator":"I, axiome 4","quote":"La connaissance de l’effet dépend de la connaissance de la cause et l’enveloppe.","notions":["science","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Constater qu’un événement se produit suffit-il à le connaître ?"},{"function":"L’affirmation","sentence":"Spinoza lie la connaissance de l’effet à celle de ce qui le produit."},{"function":"Les concepts","sentence":"La cause désigne ce dont l’effet suit, et non un événement qui le précède simplement dans le temps."},{"function":"La raison","sentence":"Comprendre pourquoi une chose existe demande de saisir la relation qui rend compte de sa production."},{"function":"L’exemple","sentence":"Observer la dilatation d’un métal ne l’explique pas encore si l’on ignore le rôle de son échauffement."},{"function":"La portée","sentence":"Cet axiome donne ainsi à la connaissance une exigence explicative qui dépasse le seul relevé des faits."}],"uses":[{"subject":"Connaître est-ce nécessairement expliquer ?","function":"Défendre une connaissance explicative","reason":"Connaître un effet exige ici de comprendre sa production, au-delà de sa seule description.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"},{"subject":"Prévoir, est-ce expliquer ?","function":"Distinguer prévision et causalité","reason":"Une régularité peut permettre une prévision sans donner encore la connaissance de la cause.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"spinoza-l-erreur-comme-connaissance-partielle","code":"S03","author":"Spinoza","title":"L’erreur comme connaissance partielle","work":"Éthique","locator":"II, proposition 35","quote":"La fausseté consiste en une privation de connaissance qu’enveloppent les idées inadéquates, autrement dit mutilées et confuses.","notions":["verite","conscience"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une idée fausse est-elle dépourvue de tout rapport au réel ?"},{"function":"L’affirmation","sentence":"Spinoza situe la fausseté dans ce qui manque à une idée pour être adéquate."},{"function":"Les concepts","sentence":"Une idée inadéquate donne une connaissance partielle dont nous ne saisissons pas suffisamment les causes et les relations."},{"function":"La raison","sentence":"Elle peut donc exprimer une affection réelle tout en nous trompant lorsque nous la prenons pour une connaissance complète de son objet."},{"function":"L’exemple","sentence":"Le Soleil paraît proche même à celui qui connaît sa distance, mais celui-ci ne confond plus cette apparence avec une mesure."},{"function":"La portée","sentence":"Corriger l’erreur consiste alors à compléter et à situer nos représentations, sans exiger la disparition de toutes les apparences."}],"uses":[{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Préciser le manque qui fait erreur","reason":"L’erreur ne se réduit pas à ne rien savoir : elle implique une représentation partielle dont la limite nous échappe.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Dissiper une illusion, est-ce seulement corriger une erreur ?","function":"Distinguer apparence et jugement","reason":"La connaissance peut corriger le jugement alors que l’apparence sensible persiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"spinoza-se-connaitre-par-le-corps","code":"S04","author":"Spinoza","title":"Se connaître par le corps","work":"Éthique","locator":"II, proposition 23","quote":"L’esprit ne se connaît pas lui-même, sinon en tant qu’il perçoit les idées des affections du corps.","notions":["conscience","nature"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La connaissance de soi vient-elle d’un regard intérieur indépendant du corps ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que l’esprit se connaît à travers les idées des modifications corporelles."},{"function":"Les concepts","sentence":"Une affection est ici une modification du corps, dont l’esprit forme une idée et peut percevoir cette idée."},{"function":"La raison","sentence":"L’esprit étant l’idée du corps, sa connaissance de lui-même passe par les manières dont ce corps est affecté."},{"function":"L’exemple","sentence":"Éprouver puis reconnaître sa peur engage ainsi la perception de changements corporels, et pas seulement un jugement abstrait sur soi."},{"function":"La portée","sentence":"La conscience de soi se construit donc dans une expérience incarnée, sans garantir une connaissance complète de ses causes."}],"uses":[{"subject":"Être conscient, est-ce savoir ?","function":"Limiter la transparence à soi","reason":"Percevoir ce que l’on éprouve donne une conscience de soi, sans suffire à en connaître adéquatement les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Peut-on penser sans sentir ?","function":"Montrer le rôle du corps","reason":"La connaissance de soi passe ici par les idées des affections corporelles plutôt que par un esprit isolé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"spinoza-perseverer-dans-son-etre","code":"S05","author":"Spinoza","title":"Persévérer dans son être","work":"Éthique","locator":"III, proposition 6","quote":"Abstraction faite du reste, chaque chose s’efforce de persévérer dans son être.","notions":["nature","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le désir humain s’explique-t-il seulement par ce qui nous manque ?"},{"function":"L’affirmation","sentence":"Spinoza inscrit l’effort humain dans une tendance de chaque chose à persévérer dans son être."},{"function":"Les concepts","sentence":"Cet effort, appelé conatus, désigne une puissance effective d’exister et d’agir, sans supposer un projet conscient chez toute chose."},{"function":"La raison","sentence":"Considérée en elle-même, une chose affirme sa nature, tandis que sa destruction vient de causes qui lui sont contraires."},{"function":"L’exemple","sentence":"Un organisme qui répare une blessure manifeste une activité de conservation sans devoir se représenter une fin."},{"function":"La portée","sentence":"Le désir peut ainsi être compris à partir d’une puissance positive, sans nier les obstacles extérieurs qui la limitent."}],"uses":[{"subject":"Ne désirons-nous que ce qui nous manque ?","function":"Contester une définition par le manque","reason":"L’effort de vivre et d’agir exprime une puissance présente, même lorsqu’il rencontre une privation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Écarter la suppression de tout désir","reason":"Si le désir exprime notre effort d’exister, la liberté doit transformer sa conduite plutôt que supprimer cet effort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"}]},{"id":"spinoza-le-desir-et-le-jugement-de-valeur","code":"S06","author":"Spinoza","title":"Le désir et le jugement de valeur","work":"Éthique","locator":"III, proposition 9, scolie","quote":"Au contraire, si nous jugeons qu’une chose est bonne, c’est parce que nous faisons effort vers elle, que nous la voulons, que nous y aspirons, que nous la désirons.","notions":["raison","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Jugeons-nous une chose bonne avant de la désirer ?"},{"function":"L’affirmation","sentence":"Spinoza renverse cet ordre en faisant du désir le principe de notre jugement de valeur."},{"function":"Les concepts","sentence":"Le bon désigne ici ce que notre effort nous porte à rechercher, plutôt qu’une qualité reconnue indépendamment de toute aspiration."},{"function":"La raison","sentence":"Nos évaluations expriment ainsi une manière d’être affectés et de poursuivre ce qui nous paraît favorable."},{"function":"L’exemple","sentence":"Un aliment paraît précieux à celui qui a faim alors qu’il laisse indifférent celui qui est rassasié."},{"function":"La portée","sentence":"Ce renversement invite à examiner nos désirs, sans conclure que tous les objets désirés sont réellement utiles ou également bons."}],"uses":[{"subject":"Ne désirons-nous que les choses que nous estimons bonnes ?","function":"Renverser le rapport entre désir et valeur","reason":"Notre jugement de valeur peut exprimer un désir déjà présent, au lieu d’être toujours la raison qui le fait naître.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"Le désir est-il aveugle ?","function":"Interroger l’indépendance de nos jugements","reason":"Un jugement apparemment réfléchi peut traduire un désir dont nous ne connaissons pas les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}]},{"id":"spinoza-la-joie-et-la-puissance-d-agir","code":"S07","author":"Spinoza","title":"La joie et la puissance d’agir","work":"Éthique","locator":"IV, proposition 41","quote":"La joie, directement, n’est pas mauvaise, mais bonne ; la tristesse, au contraire, est directement mauvaise.","notions":["bonheur","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La joie a-t-elle seulement une valeur agréable et subjective ?"},{"function":"L’affirmation","sentence":"Spinoza la dit directement bonne et attribue à la tristesse la valeur contraire."},{"function":"Les concepts","sentence":"La joie est un passage à une puissance d’agir plus grande, tandis que la tristesse marque une diminution de cette puissance."},{"function":"La raison","sentence":"Leur valeur directe dépend de cette variation de nos capacités, et pas simplement d’une préférence pour des sensations plaisantes."},{"function":"L’exemple","sentence":"La joie de comprendre une difficulté peut rendre possible un travail qui paraissait jusque-là hors de portée."},{"function":"La portée","sentence":"Cette valeur directe ne rend pourtant pas toute joie bonne dans toutes ses conséquences, car certaines satisfactions partielles peuvent être excessives."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer joie et satisfaction immédiate","reason":"Le gain de puissance permet d’évaluer une joie, puis d’examiner ses effets au-delà de son agrément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Relier raison et vie affective","reason":"La raison peut soutenir une joie active : vivre raisonnablement ne signifie pas vivre sans affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}]},{"id":"spinoza-transformer-les-affects","code":"S08","author":"Spinoza","title":"Transformer les affects","work":"Éthique","locator":"IV, proposition 7","quote":"Un affect ne peut être ni contrarié, ni supprimé, sinon par un affect contraire et plus fort que l’affect à contrarier.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une simple décision suffit-elle à vaincre une passion ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’un affect ne cède que devant un affect contraire dont la force le dépasse."},{"function":"Les concepts","sentence":"Un affect est une modification qui augmente ou diminue notre puissance d’agir, accompagnée de son idée."},{"function":"La raison","sentence":"Une consigne abstraite ne change donc pas une passion tant qu’elle ne prend pas elle-même une force dans notre vie affective."},{"function":"L’exemple","sentence":"Le plaisir effectif d’un travail partagé peut ainsi contrarier une envie de renoncer plus efficacement qu’un ordre sans prise sur nous."},{"function":"La portée","sentence":"La maîtrise de soi exige alors une transformation des affects, où la raison agit par des désirs et des joies qu’elle fait naître."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Préciser les moyens de la libération","reason":"On ne combat pas une passion depuis une volonté sans affects : il faut construire une force contraire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"}]},{"id":"spinoza-un-bien-qui-se-partage","code":"S09","author":"Spinoza","title":"Un bien qui se partage","work":"Éthique","locator":"IV, proposition 36","quote":"Le bien suprême de ceux qui poursuivent la vertu est commun à tous, et tout le monde peut s’en réjouir à égalité.","notions":["bonheur","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le bien des autres diminue-t-il nécessairement le mien ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que le bien suprême de la vie vertueuse peut être partagé par tous."},{"function":"Les concepts","sentence":"Ce bien est la connaissance de Dieu, c’est-à-dire la compréhension de la réalité dont nous faisons partie, et la vertu est une puissance d’agir."},{"function":"La raison","sentence":"Comprendre ne prive personne de comprendre, contrairement à la possession exclusive d’un objet rare."},{"function":"L’exemple","sentence":"Lorsqu’un élève explique une démonstration à un camarade, le second peut la comprendre sans retirer au premier son savoir."},{"function":"La portée","sentence":"Un bien commun devient donc pensable au-delà de la rivalité, sans supposer que tous les biens matériels se partagent de cette manière."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Dépasser la rivalité des intérêts","reason":"Partager une compréhension peut contribuer à la joie d’autrui sans en faire un état que l’on pourrait lui imposer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La raison n’a-t-elle pour fin que la connaissance du réel ?","function":"Montrer une portée éthique du connaître","reason":"La compréhension peut constituer un bien partageable et transformer nos rapports avec les autres.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}]},{"id":"spinoza-agir-par-raison-ou-par-peur","code":"S10","author":"Spinoza","title":"Agir par raison ou par peur","work":"Éthique","locator":"IV, proposition 63","quote":"Qui est conduit par la crainte, et fait le bien pour éviter le mal, n’est pas conduit par la raison.","notions":["devoir","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une conduite conforme au bien est-elle nécessairement raisonnable ?"},{"function":"L’affirmation","sentence":"Spinoza distingue l’action conduite par la crainte de celle qui naît de la raison."},{"function":"Les concepts","sentence":"La crainte nous fait fuir un mal incertain, tandis que la raison nous porte directement vers ce qui accroît notre puissance."},{"function":"La raison","sentence":"Un même comportement peut donc provenir de motifs différents, selon que nous comprenons son utilité ou redoutons une peine."},{"function":"L’exemple","sentence":"Respecter une règle par peur d’être puni diffère de la respecter parce qu’on comprend la protection qu’elle assure à chacun."},{"function":"La portée","sentence":"La valeur rationnelle d’une conduite demande ainsi l’examen de son principe, au-delà de sa seule conformité extérieure."}],"uses":[{"subject":"Obéir, est-ce nécessairement se soumettre ?","function":"Distinguer conformité et motif","reason":"L’obéissance motivée par la peur reste dépendante d’une menace ; celle qui comprend le bien recherché engage une activité de jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Critiquer une obéissance dominée par la peur","reason":"Une conduite prudente en apparence peut rester sous la dépendance d’une passion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-une-sagesse-de-la-vie","code":"S11","author":"Spinoza","title":"Une sagesse de la vie","work":"Éthique","locator":"IV, proposition 67","quote":"L’homme libre ne pense à rien moins qu’à la mort, et sa sagesse est une méditation non de la mort, mais de la vie.","notions":["bonheur","liberte","temps"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La sagesse doit-elle se construire autour de la peur de mourir ?"},{"function":"L’affirmation","sentence":"Spinoza définit la sagesse de l’homme libre par une méditation de la vie."},{"function":"Les concepts","sentence":"L’expression ne penser à rien moins qu’à la mort signifie que la mort est ce qui occupe le moins sa pensée."},{"function":"La raison","sentence":"Conduit par la raison, cet homme recherche directement ce qui lui permet de vivre et d’agir plutôt que de fuir seulement un mal."},{"function":"L’exemple","sentence":"Prendre soin de sa santé peut ainsi viser les activités que l’on aime accomplir au lieu de devenir une obsession de sa fin."},{"function":"La portée","sentence":"La lucidité sur notre condition mortelle ne disparaît pas, mais la crainte de la mort cesse de commander toute l’existence."}],"uses":[{"subject":"Pourquoi craindre la mort ?","function":"Contester le rôle directeur de la crainte","reason":"La sagesse peut reconnaître la mortalité tout en prenant pour objet principal la puissance de vivre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=143","sourceLabel":"Recueil académique · p. 143"},{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Déplacer l’obstacle vers notre rapport à la mort","reason":"La finitude n’empêche pas toute joie, tandis que la peur peut envahir la vie présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"}]},{"id":"spinoza-la-liberte-dans-la-cite","code":"S12","author":"Spinoza","title":"La liberté dans la cité","work":"Éthique","locator":"IV, proposition 73","quote":"L’homme conduit par la raison est plus libre dans la cité où il vit par décision commune, que dans la solitude où il n’obéit qu’à lui seul.","notions":["etat","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre demande-t-il de vivre sans dépendre des autres ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’une vie réglée en commun peut rendre l’homme raisonnable plus libre que la solitude."},{"function":"Les concepts","sentence":"La cité désigne une organisation politique, et la liberté une puissance d’agir guidée par la raison plutôt qu’une absence de liens."},{"function":"La raison","sentence":"La coopération et des droits communs soutiennent des capacités qu’un individu isolé ne pourrait exercer aussi sûrement."},{"function":"L’exemple","sentence":"Une règle commune protégeant chacun de la violence permet des activités que la seule force individuelle ne garantirait pas."},{"function":"La portée","sentence":"L’obéissance peut donc servir la liberté, sous réserve d’examiner les institutions réelles et sans justifier toute domination politique."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","function":"Distinguer obéissance et servitude","reason":"Obéir à une décision commune peut protéger une puissance d’agir au lieu de l’annuler.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Être seul, est-ce être libre ?","function":"Renverser l’idéal d’indépendance","reason":"La solitude supprime certains liens mais prive aussi des moyens d’agir que procure la vie commune.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}]},{"id":"spinoza-comprendre-une-passion","code":"S13","author":"Spinoza","title":"Comprendre une passion","work":"Éthique","locator":"V, proposition 3","quote":"Un affect qui est une passion cesse d’être une passion, sitôt que nous en formons une idée claire et distincte.","notions":["conscience","liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre ce que nous éprouvons peut-il modifier ce que nous subissons ?"},{"function":"L’affirmation","sentence":"Spinoza soutient qu’une connaissance claire de l’affect lui retire son caractère passif."},{"function":"Les concepts","sentence":"La passion est un affect dont nous ne sommes qu’une cause partielle, et son idée demeure confuse."},{"function":"La raison","sentence":"Former une idée adéquate transforme notre rapport à cet affect en y introduisant une activité de compréhension."},{"function":"L’exemple","sentence":"Identifier précisément les mécanismes de sa colère peut permettre d’agir sur la situation au lieu d’en accuser aveuglément une personne."},{"function":"La portée","sentence":"La compréhension devient ainsi un moyen de libération, sans promettre que nommer une émotion suffise à la connaître ni que toute émotion disparaisse."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Remplacer la répression par la compréhension","reason":"La passion peut être transformée par une activité de connaissance plutôt que combattue comme une force étrangère.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"Est-ce l’ignorance de ce que nous sommes qui fait la force de nos passions ?","function":"Établir un lien entre confusion et passivité","reason":"Comprendre l’affect change la manière dont nous en sommes affectés, au-delà d’une simple prise de conscience.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=131","sourceLabel":"Recueil académique · p. 131"}]},{"id":"spinoza-comprendre-la-necessite","code":"S14","author":"Spinoza","title":"Comprendre la nécessité","work":"Éthique","locator":"V, proposition 6","quote":"En tant que l’esprit comprend toutes choses comme nécessaires, il a par là une plus grande puissance sur les affects, autrement dit, il pâtit moins d’eux.","notions":["liberte","raison","bonheur"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre la nécessité nous condamne-t-il à subir davantage ?"},{"function":"L’affirmation","sentence":"Spinoza affirme au contraire que cette compréhension augmente notre puissance sur les affects."},{"function":"Les concepts","sentence":"La nécessité désigne l’enchaînement des causes qui produit les choses, tandis que pâtir signifie dépendre de causes que nous ne maîtrisons pas."},{"function":"La raison","sentence":"Comprendre cet enchaînement réduit les représentations confuses qui nourrissent certains regrets, certaines colères et certaines attentes impossibles."},{"function":"L’exemple","sentence":"Reconnaître les causes d’un échec peut réduire l’accusation aveugle et aider à modifier les conditions d’une action future."},{"function":"La portée","sentence":"La connaissance peut donc transformer notre manière de vivre ce qui arrive, sans nous donner le pouvoir de tout empêcher."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Montrer un effet pratique de la compréhension","reason":"Connaître les causes peut transformer notre rapport à une épreuve, même lorsque l’événement lui-même échappe à notre pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Établir un progrès sans garantir une invulnérabilité","reason":"Comprendre diminue certaines dépendances affectives, mais ne supprime pas notre exposition aux causes extérieures.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"III.2 : faire du savoir une ressource contre la peur","reason":"La compréhension des causes peut diminuer certains regrets et certaines craintes, même lorsqu’elle ne supprime pas la douleur.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"III.2","a20Status":"Insertion proposée après lecture de la copie ; citation absente du modèle."}]},{"id":"spinoza-l-ordre-des-idees-et-des-choses","code":"S15","author":"Spinoza","title":"L’ordre des idées et des choses","work":"Éthique","locator":"II, proposition 7","quote":"L’ordre et enchaînement des idées est le même que l’ordre et enchaînement des choses.","notions":["nature","raison","science"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La pensée et les choses appartiennent-elles à deux mondes sans rapport ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que leurs enchaînements expriment un même ordre."},{"function":"Les concepts","sentence":"Les idées sont des modes de la pensée, tandis que les choses se comprennent sous les attributs dont elles relèvent."},{"function":"La raison","sentence":"Une même réalité s’exprime selon ces attributs sans qu’il faille supposer une action de la pensée sur l’étendue ou de l’étendue sur la pensée."},{"function":"L’exemple","sentence":"Un événement corporel et son idée se comprennent ainsi comme deux expressions d’une même réalité, et non comme deux événements qui se commanderaient du dehors."},{"function":"La portée","sentence":"Cette thèse fonde l’intelligibilité du réel, sans prétendre que toutes nos représentations particulières en donnent une connaissance adéquate."}],"uses":[{"subject":"La raison suffit-elle à connaître le réel ?","function":"Fonder la possibilité d’une connaissance rationnelle","reason":"Le réel présente un ordre intelligible, mais il reste à établir que nos idées particulières le saisissent adéquatement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"L’activité de l’esprit s’explique-t-elle par des causes matérielles ?","function":"Distinguer unité et réduction","reason":"Le même ordre s’exprime sous la pensée et l’étendue sans faire d’un événement matériel la cause d’une idée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"}]},{"id":"cioran-les-faux-absolus","code":"C01","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les faux absolus","work":"Précis de décomposition","locator":"« Généalogie du fanatisme »","quote":"L’histoire n’est qu’un défilé de faux Absolus, une succession de temples élevés à des prétextes, un avilissement de l’esprit devant l’improbable.","notions":["religion","raison"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Abandonner une religion suffit-il à se libérer de toute croyance absolue ?"},{"function":"L’affirmation","sentence":"Cioran présente l’histoire comme une succession d’objets humains transformés en absolus."},{"function":"Les concepts","sentence":"Un faux absolu est ici une valeur ou une cause particulière soustraite à toute discussion et adorée comme une divinité."},{"function":"La raison","sentence":"Le besoin de croire peut donc déplacer sa ferveur vers une nation, une classe ou une idée sans changer de fonctionnement."},{"function":"L’exemple","sentence":"Une cause politique devient ainsi une idole lorsque toute objection passe pour une trahison."},{"function":"La portée","sentence":"Cette image dénonce une possibilité du fanatisme, mais sa généralisation polémique ne démontre pas que toute conviction ou toute histoire se réduise à ce mécanisme."}],"uses":[{"subject":"L’esprit religieux ne se manifeste-t-il que dans les religions ?","function":"Déplacer la frontière du religieux","reason":"Une idéologie qui sacralise sa cause et traite toute objection comme un sacrilège peut reprendre un fonctionnement religieux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"L’histoire enseigne-t-elle la relativité des valeurs ?","function":"Mettre à distance les valeurs proclamées absolues","reason":"La succession des causes sacralisées invite à examiner leur prétention à une validité inconditionnelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=106","sourceLabel":"Recueil académique · p. 106"},{"subject":"Peut-on concevoir une humanité sans religion ?","function":"II.3 : limiter la force du lien religieux","reason":"Une communauté peut transformer sa croyance commune en absolu et exclure la contestation ; une idéologie séculière peut reproduire ce mécanisme.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517529.pdf#page=2","sourceLabel":"Bac 2026 · Antilles et Guyane","a20":"philosophie-bac-2026-peut-on-concevoir-une-humanite-sans-religion.html","a20Step":"II.3","a20Status":"Insertion possible après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-les-mots-et-la-presence-des-choses","code":"C02","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les mots et la présence des choses","work":"Précis de décomposition","locator":"« Dans le cimetière des définitions »","quote":"Sous chaque formule gît un cadavre : l’être ou l’objet meurt sous le prétexte auquel ils ont donné lieu.","notions":["langage","verite"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une formule rend-elle compte d’une chose ou risque-t-elle de s’y substituer ?"},{"function":"L’affirmation","sentence":"Cioran décrit la définition comme une opération qui peut faire disparaître la présence vivante de son objet."},{"function":"Les concepts","sentence":"Le cadavre est une métaphore de la chose réduite à ce que notre formule en retient, et non détruite matériellement."},{"function":"La raison","sentence":"Lorsque l’esprit prend sa définition pour la réalité entière, il néglige ce que la rencontre sensible et singulière lui faisait éprouver."},{"function":"L’exemple","sentence":"Réduire une personne à une étiquette peut ainsi empêcher d’écouter ce qui, dans sa conduite, dément cette étiquette."},{"function":"La portée","sentence":"La formule oblige à éprouver nos mots au contact des choses, sans établir que toute définition soit inutile ou nécessairement trompeuse."}],"uses":[{"subject":"Le langage nous éloigne-t-il du réel ?","function":"Analyser le risque de substitution","reason":"Un énoncé peut devenir un écran lorsqu’il remplace l’attention portée à ce qu’il désigne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","function":"Critiquer une définition figée","reason":"Il faut distinguer l’outil qui permet de chercher de la formule qui prétend clore la recherche.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"}]},{"id":"cioran-l-ennui-et-le-sens-de-vivre","code":"C03","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’ennui et le sens de vivre","work":"Précis de décomposition","locator":"« Désarticulation du temps »","quote":"La vie se crée dans le délire et se défait dans l’ennui.","notions":["bonheur","temps"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le repos et l’absence de difficultés suffisent-ils à donner le sentiment de vivre ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’élan qui peuple la vie de significations à l’ennui qui les défait."},{"function":"Les concepts","sentence":"Le délire désigne ici nos investissements excessifs dans des désirs et des valeurs, tandis que l’ennui les prive de leur évidence."},{"function":"La raison","sentence":"Lorsque plus rien ne nous attire, les instants continuent de passer mais cessent de porter des possibilités auxquelles nous tenons."},{"function":"L’exemple","sentence":"Une journée entièrement libre peut ainsi paraître interminable si aucun projet ne rend ses moments désirables."},{"function":"La portée","sentence":"L’opposition éclaire la fragilité du sens vécu, sans faire de tout engagement une maladie ni de tout repos un vide."}],"uses":[{"subject":"Le bonheur se trouve-t-il dans le repos ?","function":"Limiter l’idéal d’absence de trouble","reason":"Le repos ne suffit pas si la disparition des préoccupations retire aussi tout intérêt à ce que l’on vit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger le rôle des attachements","reason":"L’ennui pose la question du prix de la lucidité : défaire nos illusions peut aussi défaire les valeurs qui soutenaient nos engagements.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-expliquer-et-vivre","code":"C04","author":"Cioran","authorRole":"Écrivain et penseur","title":"Expliquer et vivre","work":"Précis de décomposition","locator":"« Adieu à la philosophie »","quote":"On ne peut éluder l’existence par des explications, on ne peut que la subir, l’aimer ou la haïr, l’adorer ou la craindre, dans cette alternance de félicité et d’horreur qui exprime le rythme même de l’être, ses oscillations, ses dissonances, ses véhémences amères ou allègres.","notions":["raison","bonheur"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comprendre pourquoi nous souffrons suffit-il à nous dispenser de vivre cette souffrance ?"},{"function":"L’affirmation","sentence":"Cioran conteste le pouvoir des explications de nous soustraire à l’épreuve de l’existence."},{"function":"Les concepts","sentence":"Éluder signifie esquiver, tandis qu’expliquer consiste à rendre intelligible ce qui arrive plutôt qu’à l’éprouver à notre place."},{"function":"La raison","sentence":"Une théorie peut décrire une situation sans supprimer les sentiments contradictoires dans lesquels nous la traversons."},{"function":"L’exemple","sentence":"Connaître les mécanismes du deuil ne fait pas disparaître immédiatement la douleur d’une perte."},{"function":"La portée","sentence":"Cette critique limite la prétention du savoir à nous délivrer de toute épreuve, sans prouver qu’une explication ne puisse jamais nous aider à vivre."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Limiter le pouvoir du savoir","reason":"Comprendre une épreuve ne dispense pas de la traverser ; il reste à préciser en quoi la compréhension peut néanmoins aider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"cioran-les-desirs-dementent-nos-principes","code":"C05","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les désirs démentent nos principes","work":"Précis de décomposition","locator":"« Cosmogonie du désir »","quote":"Chaque désir humilie la somme de nos vérités et nous oblige à reconsidérer nos négations.","notions":["raison","liberte"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Nos conclusions intellectuelles commandent-elles effectivement nos désirs ?"},{"function":"L’affirmation","sentence":"Cioran montre le désir revenant contredire les raisons par lesquelles nous prétendions nous détacher de la vie."},{"function":"Les concepts","sentence":"Les vérités et les négations désignent ici les conclusions pessimistes du narrateur, tandis que le désir marque la persistance de son attachement."},{"function":"La raison","sentence":"Le corps peut continuer de vouloir ce que l’esprit avait déclaré vain, révélant un écart entre conviction théorique et conduite effective."},{"function":"L’exemple","sentence":"Celui qui proclame l’inutilité des honneurs peut encore attendre avec impatience un signe de reconnaissance."},{"function":"La portée","sentence":"Le désir éprouve ainsi la portée pratique de nos principes, sans que sa force suffise à démontrer leur fausseté logique."}],"uses":[{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Analyser un conflit sans le généraliser","reason":"Les raisons de se détacher peuvent échouer à éteindre un attachement, ce qui ne condamne pas toute alliance entre raison et désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on être en conflit avec soi-même ?","function":"Distinguer jugement et attachement","reason":"Un même individu peut soutenir une conclusion et continuer de désirer ce qu’elle dévalue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-reflechir-transforme-la-sensation","code":"C06","author":"Cioran","authorRole":"Écrivain et penseur","title":"Réfléchir transforme la sensation","work":"Précis de décomposition","locator":"« Visages de la décadence »","quote":"Méditer ses sensations – savoir que l’on mange, – c’est là une prise de conscience grâce à laquelle un acte élémentaire dépasse son but immédiat.","notions":["conscience","nature"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience accompagne-t-elle seulement nos actes ou en transforme-t-elle la signification ?"},{"function":"L’affirmation","sentence":"Cioran affirme que l’attention portée à une sensation modifie un acte aussi élémentaire que manger."},{"function":"Les concepts","sentence":"Le but immédiat est ici de se nourrir, tandis que méditer sa sensation fait du repas un objet de réflexion et de recherche."},{"function":"La raison","sentence":"L’acte ne se limite plus à satisfaire un besoin lorsque l’esprit s’intéresse à la qualité et aux variations de ce qu’il éprouve."},{"function":"L’exemple","sentence":"Comparer lentement des saveurs introduit ainsi une recherche du goût au-delà de la seule faim."},{"function":"La portée","sentence":"Dans ce passage sur la décadence, ce raffinement reste ambivalent et ne vaut donc pas comme preuve que toute réflexion améliore la vie."}],"uses":[{"subject":"Sommes-nous conscients ou le devenons-nous ?","function":"Distinguer vécu immédiat et réflexion","reason":"La prise de conscience peut modifier le sens d’un acte déjà accompli sans attention réfléchie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Interroger les effets du retour sur soi","reason":"La réflexion enrichit parfois une sensation, mais peut aussi compliquer et inquiéter ce qui se faisait spontanément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-le-doute-et-la-vie-commune","code":"C07","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le doute et la vie commune","work":"La Chute dans le temps","locator":"« Le sceptique et le barbare »","quote":"Une civilisation débute par le mythe et finit dans le doute ; doute théorique qui, lorsqu’elle le retourne contre elle-même, s’achève en doute pratique.","notions":["raison","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La critique des croyances peut-elle finir par atteindre notre capacité d’agir ?"},{"function":"L’affirmation","sentence":"Cioran décrit une civilisation dont le doute passe de l’examen des idées à l’incertitude sur ses propres fins."},{"function":"Les concepts","sentence":"Le doute théorique porte sur ce que l’on tient pour vrai, tandis que le doute pratique atteint les valeurs qui orientent les actes."},{"function":"La raison","sentence":"Lorsqu’une communauté ne reconnaît plus aucun motif de préférer une fin à une autre, sa lucidité peut se convertir en impuissance."},{"function":"L’exemple","sentence":"Un groupe qui remet indéfiniment en question toutes ses raisons de décider peut ne plus parvenir à choisir une action commune."},{"function":"La portée","sentence":"Ce schéma tragique interroge le coût d’un doute généralisé, sans constituer une loi démontrée de la naissance et de la mort de toutes les civilisations."}],"uses":[{"subject":"Douter, est-ce renoncer à la vérité ?","function":"Distinguer examen et désorientation","reason":"Le doute peut servir la recherche, mais son extension à toute raison de juger peut retirer à cette recherche sa direction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Peut-on ne croire en rien ?","function":"Examiner les conditions de l’action","reason":"Une suspension totale des convictions pose la question des raisons qui permettraient encore de décider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"cioran-convertir-et-contraindre","code":"C08","author":"Cioran","authorRole":"Écrivain et penseur","title":"Convertir et contraindre","work":"La Chute dans le temps","locator":"« Portrait du civilisé »","quote":"Ce n’est point pour libérer, c’est pour enchaîner qu’on s’applique à convertir.","notions":["religion","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Vouloir faire adopter sa conviction revient-il toujours à servir la liberté d’autrui ?"},{"function":"L’affirmation","sentence":"Cioran soupçonne la conversion de prolonger une volonté de soumettre sous une promesse de libération."},{"function":"Les concepts","sentence":"Convertir signifie faire adhérer à une croyance, et la chaîne figure ici une dépendance imposée au jugement."},{"function":"La raison","sentence":"Celui qui ne supporte pas sa propre discipline peut vouloir la généraliser plutôt que reconnaître à un autre la possibilité de s’en passer."},{"function":"L’exemple","sentence":"Une doctrine devient contraignante lorsque celui qui prétend sauver autrui lui retire le droit de refuser son salut."},{"function":"La portée","sentence":"La formule démasque une logique possible du prosélytisme, mais son absoluité polémique ne suffit pas à identifier toute transmission d’une croyance à une oppression."}],"uses":[{"subject":"La religion unit-elle ou sépare-t-elle les hommes ?","function":"Interroger les conditions du rassemblement","reason":"L’union autour d’une croyance peut devenir une exigence d’uniformité qui exclut le refus et la différence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"La liberté exclut-elle l’obéissance ?","function":"Critiquer une soumission présentée comme un salut","reason":"Il faut examiner si l’adhésion conserve la possibilité de juger et de refuser, au-delà de la liberté annoncée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"cioran-l-assurance-et-le-besoin-d-eloge","code":"C09","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’assurance et le besoin d’éloge","work":"La Chute dans le temps","locator":"« Désir et horreur de la gloire »","quote":"En apparence, tout le monde est content de soi ; en réalité, personne.","notions":["conscience","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"L’assurance que nous montrons aux autres prouve-t-elle que nous sommes satisfaits de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’image publique de la satisfaction à une insécurité intérieure que l’éloge vient apaiser."},{"function":"Les concepts","sentence":"L’apparence désigne ce que nous affichons, tandis que le contentement de soi désigne ici une estime assez stable pour ne plus chercher de confirmation."},{"function":"La raison","sentence":"Le besoin persistant de compliments peut révéler une dépendance au jugement d’autrui jusque chez celui qui se dit supérieur à ce jugement."},{"function":"L’exemple","sentence":"Une personne affichant son indifférence aux critiques peut pourtant attendre avec impatience des félicitations."},{"function":"La portée","sentence":"La symétrie provocatrice entre tout le monde et personne invite à interroger cette dépendance, sans établir que nul ne puisse jamais acquérir une estime de soi solide."}],"uses":[{"subject":"Avons-nous besoin d’autrui pour avoir conscience de nous-mêmes ?","function":"Distinguer conscience de soi et validation","reason":"Le besoin d’approbation montre un rôle du regard d’autrui, sans prouver que toute conscience de soi dépende de ses éloges.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"},{"subject":"La conscience de soi est-elle trompeuse ?","function":"Interroger l’image que l’on se donne","reason":"Le sentiment d’assurance peut masquer à soi-même une demande de reconnaissance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-le-corps-revele-par-l-epreuve","code":"C10","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le corps révélé par l’épreuve","work":"La Chute dans le temps","locator":"« Sur la maladie »","quote":"Pour que la conscience atteigne à une certaine intensité, il faut que l’organisme pâtisse et même qu’il se désagrège : la conscience, à ses débuts, est conscience des organes.","notions":["conscience","nature","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le corps devient-il plus présent à la conscience lorsqu’il cesse de fonctionner sans difficulté ?"},{"function":"L’affirmation","sentence":"Cioran rapporte l’intensification de la conscience à l’épreuve d’un organisme qui souffre."},{"function":"Les concepts","sentence":"La conscience des organes désigne ici leur présence insistante dans notre expérience, plutôt qu’un savoir anatomique complet."},{"function":"La raison","sentence":"Ce qui se faisait oublier dans une activité aisée retient notre attention dès qu’une gêne ou une douleur interrompt cette activité."},{"function":"L’exemple","sentence":"Une difficulté à respirer peut ainsi rendre sensible une fonction que nous accomplissions sans y penser."},{"function":"La portée","sentence":"Ce diagnostic polémique éclaire une expérience du corps empêché, sans établir que la souffrance soit nécessaire à toute conscience ni que cette conscience accrue rende plus libre."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer un enracinement corporel de la réflexion","reason":"Une modification corporelle peut devenir le point de départ d’une attention et d’une réflexion sur soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience est-elle source de liberté ou de contrainte ?","function":"Distinguer conscience accrue et pouvoir accru","reason":"Mieux sentir sa dépendance corporelle ne donne pas nécessairement les moyens de la surmonter.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"}]},{"id":"cioran-la-creation-et-la-clairvoyance","code":"C11","author":"Cioran","authorRole":"Écrivain et penseur","title":"La création et la clairvoyance","work":"La Chute dans le temps","locator":"« Les dangers de la sagesse »","quote":"Produire, « créer », c’est s’interdire la clairvoyance, c’est avoir le courage ou le bonheur de ne pas percevoir le mensonge de la diversité, le caractère trompeur du multiple.","notions":["art","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une lucidité qui relativise toute apparence laisse-t-elle encore un motif de créer ?"},{"function":"L’affirmation","sentence":"Cioran présente la création comme un engagement dans des différences qu’une sagesse détachée tend à dissoudre."},{"function":"Les concepts","sentence":"La clairvoyance désigne ici ce détachement radical, tandis que la diversité est le monde des formes et des conflits qui fournit ses matériaux à l’artiste."},{"function":"La raison","sentence":"Créer suppose d’accorder assez d’importance à ces différences pour les explorer plutôt que les ramener toutes au même néant."},{"function":"L’exemple","sentence":"Un romancier travaille les conflits de ses personnages parce qu’il consent à prendre au sérieux leurs attachements singuliers."},{"function":"La portée","sentence":"Cette provocation oppose deux rapports au monde, sans démontrer que l’artiste doive ignorer son métier ou renoncer à tout examen critique de son œuvre."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Distinguer attention créatrice et détachement","reason":"Une œuvre peut explorer des apparences auxquelles une certaine sagesse refuserait de s’attacher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger les effets d’une lucidité radicale","reason":"Dévoiler toute apparence comme trompeuse peut détruire des motifs de vivre et de créer, au lieu d’assurer immédiatement une existence meilleure.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.3 : mettre à l’épreuve une création sans lucidité","reason":"Le refus d’un détachement qui dissout toutes les apparences reste compatible avec des choix lucides et un travail de correction de l’œuvre.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.3","a20Status":"Insertion possible comme thèse à discuter après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-l-avenir-deja-passe","code":"C12","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’avenir déjà passé","work":"La Chute dans le temps","locator":"« Tomber du temps »","quote":"Vivre, c’est subir la magie du possible ; mais lorsqu’on perçoit dans le possible même du révolu à venir, tout devient virtuellement passé, et il n’y a plus de présent ni de futur.","notions":["temps","conscience"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Que devient le présent si nous regardons chaque possibilité comme déjà révolue ?"},{"function":"L’affirmation","sentence":"Cioran décrit une expérience où l’anticipation de la disparition retire aux instants leur ouverture."},{"function":"Les concepts","sentence":"Le possible est ce qui peut encore advenir, tandis que le révolu désigne ce qui est achevé et ne peut plus être modifié."},{"function":"La raison","sentence":"Traiter par avance un projet comme un souvenir détruit l’attente qui permettrait de s’y engager et d’en éprouver la nouveauté."},{"function":"L’exemple","sentence":"Imaginer une rencontre uniquement comme ce qui sera bientôt terminé peut empêcher d’être disponible à ce qui s’y passe."},{"function":"La portée","sentence":"La formule éclaire ainsi une manière de perdre le présent, sans affirmer que le temps physique cesse de s’écouler ni que toute anticipation soit paralysante."}],"uses":[{"subject":"Est-il possible de vivre au présent ?","function":"Distinguer présence chronologique et disponibilité","reason":"Être dans l’instant ne suffit pas si l’on le considère déjà comme un passé clos.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer mesure et temps vécu","reason":"Un même intervalle mesuré peut être vécu comme une ouverture ou comme une disparition déjà accomplie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}]},{"id":"cioran-le-malaise-avant-la-faute","code":"C13","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le malaise avant la faute","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"La malédiction qui nous accable pesait déjà sur notre premier ancêtre, bien avant qu’il se tournât vers l’arbre de la connaissance.","notions":["bonheur","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi désirer quitter un bonheur dont on disposerait déjà ?"},{"function":"L’affirmation","sentence":"Cioran situe le malaise d’Adam avant la transgression, au cœur même du paradis."},{"function":"Les concepts","sentence":"La malédiction désigne ici une insatisfaction constitutive, et le premier ancêtre est la figure biblique par laquelle cette condition humaine est interrogée."},{"function":"La raison","sentence":"Si Adam cède si facilement à la tentation, c’est, selon cette lecture, que la paix disponible ne suffisait déjà pas à le satisfaire."},{"function":"L’exemple","sentence":"Un repos longtemps désiré peut ainsi laisser paraître une nouvelle impatience lorsqu’aucun obstacle extérieur ne trouble plus notre vie."},{"function":"La portée","sentence":"La relecture du mythe interroge notre aptitude au bonheur, sans établir que toute insatisfaction soit universelle ni que cette interprétation soit le sens unique de la Genèse."}],"uses":[{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Déplacer la difficulté vers notre rapport au bonheur","reason":"L’obstacle peut tenir à notre incapacité de nous satisfaire d’un bonheur présent, et pas seulement aux événements qui nous en privent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger l’idéal d’une innocence heureuse","reason":"La fiction d’un paradis antérieur au savoir peut elle-même dissimuler une inquiétude déjà présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-connaitre-et-perdre-la-familiarite-du-monde","code":"C14","author":"Cioran","authorRole":"Écrivain et penseur","title":"Connaître et perdre la familiarité du monde","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Le désir de connaître, empreint de perversité et de corruption, plus il nous tient, plus il nous rend incapables de demeurer à l’intérieur de quelque réalité que ce soit.","notions":["raison","verite","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le désir de savoir nous rapproche-t-il toujours du monde dans lequel nous vivons ?"},{"function":"L’affirmation","sentence":"Cioran décrit une connaissance qui éloigne de la participation immédiate aux choses à mesure qu’elle cherche à les analyser."},{"function":"Les concepts","sentence":"Demeurer à l’intérieur d’une réalité signifie ici y être engagé sans la tenir constamment à distance comme un objet à examiner."},{"function":"La raison","sentence":"Dans sa relecture de la Genèse, la curiosité rompt une familiarité et pousse l’homme vers de nouvelles questions plutôt que vers un repos définitif."},{"function":"L’exemple","sentence":"Analyser sans cesse les raisons d’une joie peut modifier cette joie et empêcher de s’y abandonner."},{"function":"La portée","sentence":"Le vocabulaire de la faute dramatise cette rupture, sans démontrer que tout savoir soit nuisible ni que toute analyse interdise de vivre."}],"uses":[{"subject":"Le désir de savoir est-il naturel ?","function":"Distinguer élan spontané et accord avec la nature","reason":"Le désir de connaître peut être puissant tout en nous éloignant, selon Cioran, d’une adhésion immédiate à notre condition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"},{"subject":"La connaissance peut-elle nuire au bonheur ?","function":"Analyser le prix d’une mise à distance","reason":"Le regard qui examine peut défaire certaines évidences dont une expérience heureuse se nourrissait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"I.2 : renforcer l’attrait de l’insouciance","reason":"Le désir d’analyse peut rompre une familiarité heureuse et nourrir l’inquiétude ; cette première réponse reste à confronter aux dangers que l’ignorance ne supprime pas.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"I.2","a20Status":"Insertion possible après lecture de la copie, en complément de Pascal, sans assimiler les deux arguments."}]},{"id":"cioran-la-conscience-de-notre-fragilite","code":"C15","author":"Cioran","authorRole":"Écrivain et penseur","title":"La conscience de notre fragilité","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"L’inorganique se suffit à lui-même ; l’organique est dépendant, menacé, instable ; le conscient est quintessence de caducité.","notions":["conscience","nature","temps"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience de notre condition ajoute-t-elle une épreuve à notre fragilité physique ?"},{"function":"L’affirmation","sentence":"Cioran présente la conscience comme une intensification de la précarité propre au vivant."},{"function":"Les concepts","sentence":"La caducité désigne le caractère périssable, tandis que la quintessence en figure ici la concentration extrême."},{"function":"La raison","sentence":"Dans ce passage, l’homme éprouve sa dépendance et anticipe sa mort, au lieu de seulement subir les limites de son organisme."},{"function":"L’exemple","sentence":"Prévoir la disparition future d’un bonheur peut ainsi troubler une joie qui n’est pas encore menacée dans le présent."},{"function":"La portée","sentence":"Cette gradation éclaire le poids de la mortalité connue, sans décrire scientifiquement tous les vivants ni établir que toute conscience exclue la joie."}],"uses":[{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Distinguer mortalité et anticipation de la mort","reason":"La conscience d’une fin peut peser sur le présent avant que cette fin survienne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"Peut-on être pleinement homme sans penser à la mort ?","function":"Interroger la place de la finitude dans la conscience","reason":"Le passage lie la singularité humaine au savoir de sa précarité, dont il faut examiner aussi les effets sur la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=137","sourceLabel":"Recueil académique · p. 137"}]},{"id":"cioran-le-savoir-nous-precipite-dans-le-temps","code":"C16","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le savoir nous précipite dans le temps","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Précipités par le savoir dans le temps, nous fûmes du même coup dotés d’un destin.","notions":["temps","conscience","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comment le savoir pourrait-il nous faire entrer dans un temps où nous vivons déjà ?"},{"function":"L’affirmation","sentence":"Cioran interprète la sortie du paradis comme l’apparition d’une existence consciente de son devenir."},{"function":"Les concepts","sentence":"Le temps désigne ici l’expérience de la perte et des possibles, tandis que le destin donne à notre vie la forme d’une histoire orientée vers sa fin."},{"function":"La raison","sentence":"Le savoir rompt l’adhésion innocente au présent en faisant apparaître ce qui pourrait arriver et ce qui ne reviendra plus."},{"function":"L’exemple","sentence":"Savoir qu’une rencontre peut être la dernière transforme un moment ordinaire en événement chargé d’attente et de regret."},{"function":"La portée","sentence":"Cette lecture philosophique du mythe distingue le temps vécu de la simple durée, sans prétendre que les êtres privés de ce savoir échappent au changement physique."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer durée physique et conscience du devenir","reason":"Le paradis figure une innocence soustraite à l’expérience inquiète de la perte, plutôt qu’une simple absence de changement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Montrer le poids de l’anticipation","reason":"La conscience de notre avenir et de notre fin peut troubler l’adhésion au présent, sans suffire à condamner toute lucidité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-l-outil-et-la-faiblesse-humaine","code":"C17","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’outil et la faiblesse humaine","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"N’éprouvant nul besoin d’ajouter à sa force, qui est réelle, un fauve ne s’abaisse pas à l’outil.","notions":["technique","nature"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La puissance technique prouve-t-elle une force naturelle supérieure ?"},{"function":"L’affirmation","sentence":"Cioran renverse cette interprétation en présentant l’outil comme une compensation dont l’animal puissant n’aurait pas besoin."},{"function":"Les concepts","sentence":"La force réelle désigne ici une puissance corporelle disponible, tandis que l’outil ajoute des moyens artificiels à un organisme insuffisamment armé."},{"function":"La raison","sentence":"Dans le récit de la sortie du paradis, l’inadaptation humaine devient ainsi le ressort d’une conquête toujours plus ambitieuse."},{"function":"L’exemple","sentence":"Un instrument de coupe permet à une main de réaliser ce qu’elle ne pourrait accomplir par sa seule force."},{"function":"La portée","sentence":"Le verbe s’abaisser exprime une provocation qui renverse notre hiérarchie habituelle, sans fournir une classification scientifique des animaux ni prouver que tout outil soit dégradant."}],"uses":[{"subject":"La technique nous libère-t-elle de la nature ?","function":"Retrouver une dépendance dans la puissance acquise","reason":"L’invention technique peut répondre à des limites naturelles plutôt que nous en rendre absolument indépendants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"},{"subject":"La technique naît-elle de nos besoins ou de nos rêves ?","function":"Relier compensation et ambition","reason":"Un manque initial peut susciter des moyens dont le développement dépasse ensuite la seule satisfaction du besoin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]},{"id":"cioran-devenir-n-est-pas-progresser","code":"C18","author":"Cioran","authorRole":"Écrivain et penseur","title":"Devenir n’est pas progresser","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Devenir et progrès sont notions en apparence voisines, en fait divergentes.","notions":["technique","temps","raison"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le simple fait de changer nous conduit-il nécessairement vers un état meilleur ?"},{"function":"L’affirmation","sentence":"Cioran refuse d’identifier le devenir à un progrès."},{"function":"Les concepts","sentence":"Le devenir désigne une transformation, tandis que le progrès suppose un critère permettant de juger cette transformation meilleure."},{"function":"La raison","sentence":"Une suite de nouveautés ne justifie donc pas à elle seule une confiance dans l’amélioration de la condition humaine."},{"function":"L’exemple","sentence":"Une machine plus puissante peut faciliter une tâche tout en augmentant des dépendances ou des destructions."},{"function":"La portée","sentence":"Cette distinction oblige à évaluer les transformations plutôt qu’à célébrer leur nouveauté, sans prouver que toute amélioration soit impossible ni que tout changement soit une dégradation."}],"uses":[{"subject":"Faut-il voir dans l’histoire humaine un progrès constant ?","function":"Distinguer succession et amélioration","reason":"L’enchaînement des changements n’établit pas leur valeur ni leur direction vers un mieux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Le progrès de l’humanité se réduit-il au progrès technique ?","function":"Distinguer puissance des moyens et valeur des fins","reason":"Une efficacité accrue ne suffit pas à établir une amélioration du bonheur, de la justice ou de la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]},{"id":"kant-experience-et-origine","code":"K01","author":"Kant","title":"Commencer avec l’expérience","work":"Critique de la raison pure","locator":"Introduction, I · B 1–2","quote":"Cela dit, bien que toute notre connaissance s'amorce avec l'expérience, il n'en résulte pas pour autant qu'elle dérive dans sa totalité de l'expérience.","notions":["science","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Tout ce que nous connaissons vient-il de ce que nous avons éprouvé ?"},{"function":"L’affirmation","sentence":"Kant distingue le commencement de la connaissance et l’origine de tous ses éléments."},{"function":"Les concepts","sentence":"L’expérience éveille notre connaissance, mais cela ne prouve pas qu’elle fournisse aussi les règles qui l’organisent."},{"function":"La raison","sentence":"Pour connaître un objet, nous devons relier ce que nous recevons des sens, et non seulement accumuler des impressions."},{"function":"L’exemple","sentence":"Observer plusieurs changements ne suffit pas, à lui seul, à expliquer pourquoi nous recherchons pour chacun une cause."},{"function":"La portée","sentence":"L’expérience est donc indispensable à la connaissance, sans être nécessairement la source de toutes ses conditions."}],"uses":[{"subject":"L’expérience est-elle la seule source de la connaissance ?","function":"Distinguer le commencement et le fondement","reason":"Les règles par lesquelles l’esprit organise les données sensibles ne se réduisent pas à ces données ; l’expérience ne fournit donc pas nécessairement toutes les conditions de la connaissance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"},{"subject":"D’où viennent nos connaissances ?","function":"Dépasser une réponse exclusivement empirique","reason":"Les objets affectent nos sens, mais l’esprit apporte aussi les règles par lesquelles ces données deviennent une connaissance organisée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-penser-et-recevoir","code":"K02","author":"Kant","title":"Penser et recevoir","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, I · A 51 / B 75","quote":"Des pensées sans contenu sont vides, des intuitions sans concepts sont aveugles.","notions":["science","raison","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Suffit-il de penser avec rigueur ou de bien observer pour connaître ?"},{"function":"L’affirmation","sentence":"Kant affirme que notre connaissance exige l’union des concepts et des intuitions sensibles."},{"function":"Les concepts","sentence":"Le concept permet de penser un objet, tandis que l’intuition le donne à notre sensibilité."},{"function":"La raison","sentence":"Une pensée sans objet reste vide, mais ce qui est reçu sans être pensé ne devient pas encore une connaissance de cet objet."},{"function":"L’exemple","sentence":"Reconnaître un arbre exige de rapporter ce que l’on voit à des concepts, sans posséder pour autant une théorie scientifique de cet arbre."},{"function":"La portée","sentence":"La connaissance unit donc réception et pensée ; les concepts qui la rendent possible ne se confondent pas avec une théorie scientifique déjà formulée."}],"uses":[{"subject":"Une expérience sans théorie nous apprend-elle quelque chose ?","function":"Montrer le besoin d’une organisation conceptuelle","reason":"Recevoir des données ne suffit pas à les comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"},{"subject":"Une théorie sans expérience nous apprend-elle quelque chose ?","function":"Fixer une condition de la connaissance des objets","reason":"Un concept cohérent ne donne pas encore son objet : la connaissance exige aussi que quelque chose puisse être donné à la sensibilité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"}]},{"id":"kant-bien-questionner","code":"K03","author":"Kant","title":"Apprendre à questionner","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, III · A 58 / B 82–83","quote":"C'est déjà une grande et nécessaire preuve de sagesse ou d'intelligence que de savoir quelles questions on peut raisonnablement poser.","notions":["raison","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Toute question mérite-t-elle qu’on cherche immédiatement à y répondre ?"},{"function":"L’affirmation","sentence":"Kant fait de l’examen des questions une marque de sagesse."},{"function":"Les concepts","sentence":"Une question raisonnable doit avoir un sens et ne pas présupposer ce qu’il faudrait justement établir."},{"function":"La raison","sentence":"Si sa formulation impose une supposition absurde, répondre risque de nous enfermer dans cette erreur."},{"function":"L’exemple","sentence":"Demander la couleur du nombre sept suppose ainsi qu’un nombre puisse posséder une propriété sensible."},{"function":"La portée","sentence":"Bien raisonner commence donc parfois par corriger la question, plutôt que par choisir entre les réponses qu’elle semble autoriser."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Définir un premier exercice du jugement","reason":"Une question peut contenir un présupposé faux. Apprendre à penser demande alors de corriger la question avant de chercher sa réponse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"La raison peut-elle tout expliquer ?","function":"Examiner la légitimité de la demande","reason":"Une demande mal formulée peut rendre la réponse impossible sans révéler une impuissance de la raison ; la cohérence de la question doit d’abord être établie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"}]},{"id":"kant-coherence-et-verite","code":"K04","author":"Kant","title":"La cohérence ne suffit pas","work":"Critique de la raison pure","locator":"Logique transcendantale, introduction, III · A 59–60 / B 84","quote":"Car quand bien même une connaissance parvient à concorder pleinement avec la forme logique, c'est-à-dire à ne pas se contredire elle-même, elle peut cependant toujours contredire l'objet.","notions":["verite","raison","science"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une pensée sans contradiction est-elle nécessairement vraie ?"},{"function":"L’affirmation","sentence":"Kant affirme qu’une connaissance logiquement cohérente peut pourtant ne pas correspondre à son objet."},{"function":"Les concepts","sentence":"La cohérence concerne l’accord des propositions entre elles, tandis que la vérité engage leur rapport à ce dont elles parlent."},{"function":"La raison","sentence":"Les règles logiques permettent d’écarter certaines erreurs, mais elles ne fournissent pas à elles seules le contenu vrai."},{"function":"L’exemple","sentence":"Un récit inventé peut être parfaitement cohérent sans que les événements qu’il raconte aient eu lieu."},{"function":"La portée","sentence":"La logique demeure donc nécessaire à la recherche du vrai, sans constituer un critère suffisant de toute vérité."}],"uses":[{"subject":"La cohérence d’une pensée suffit-elle à garantir sa vérité ?","function":"Distinguer une condition nécessaire d’une condition suffisante","reason":"Une pensée cohérente peut encore manquer son objet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"La rigueur d’un raisonnement suffit-elle pour garantir la vérité ?","function":"Limiter la portée de la seule rigueur formelle","reason":"Un enchaînement logique valide peut partir d’affirmations fausses ; sa rigueur ne garantit donc pas à elle seule sa conclusion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-sens-et-jugement","code":"K05","author":"Kant","title":"Les sens ne jugent pas","work":"Critique de la raison pure","locator":"Dialectique transcendantale, introduction, I · A 293–294 / B 350","quote":"On peut donc assurément dire avec justesse que les sens ne commettent pas d'erreur, non pas toutefois parce qu'ils jugent toujours de façon juste, mais parce qu'ils ne portent aucun jugement.","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Les sens nous trompent-ils lorsqu’une perception nous conduit à l’erreur ?"},{"function":"L’affirmation","sentence":"Kant distingue ce que les sens donnent et le jugement que nous portons sur cette donnée."},{"function":"Les concepts","sentence":"Sentir est recevoir une représentation, tandis que juger consiste à affirmer quelque chose d’un objet."},{"function":"La raison","sentence":"L’erreur apparaît lorsque nous attribuons à l’objet ce que sa seule apparence ne permet pas d’établir."},{"function":"L’exemple","sentence":"Un bâton plongé dans l’eau paraît brisé, mais c’est affirmer qu’il est réellement brisé qui constitue l’erreur."},{"function":"La portée","sentence":"Il faut donc examiner notre interprétation des perceptions, sans prétendre que toute apparence nous livre immédiatement la réalité."}],"uses":[{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Identifier une erreur d’interprétation","reason":"L’erreur peut venir du jugement qui attribue à l’objet ce qui relève seulement des conditions de son apparition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer voir et affirmer","reason":"Le témoignage des sens demande à être interprété : la confiance dans la vue ne dispense pas de juger ce qu’elle permet réellement d’affirmer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-illusion-et-lucidite","code":"K06","author":"Kant","title":"Comprendre une illusion ne l’abolit pas","work":"Critique de la raison pure","locator":"Dialectique transcendantale, introduction, I · A 297 / B 353–354","quote":"L'apparence transcendantale, au contraire, ne cesse pas, quand bien même on l'a découverte et que la critique transcendantale en a fait voir clairement le néant (par exemple, l'apparence qui se trouve contenue dans la proposition : le monde doit nécessairement posséder un commencement chronologique).","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comprendre pourquoi nous sommes trompés fait-il disparaître toute illusion ?"},{"function":"L’affirmation","sentence":"Kant affirme que certaines apparences produites par la raison persistent après leur explication."},{"function":"Les concepts","sentence":"L’apparence transcendantale consiste à prendre une exigence de notre pensée pour une propriété nécessaire des choses elles-mêmes."},{"function":"La raison","sentence":"Le besoin de donner à nos explications un terme définitif nous pousse ainsi à dépasser ce que nous pouvons connaître."},{"function":"L’exemple","sentence":"Nous sommes tentés d’affirmer un premier commencement du monde parce que la remontée des causes nous paraît devoir s’arrêter."},{"function":"La portée","sentence":"La critique peut empêcher notre adhésion à cette apparence sans supprimer la tendance qui la produit."}],"uses":[{"subject":"Dissiper une illusion, est-ce seulement corriger une erreur ?","function":"Distinguer la persistance de l’apparence et l’adhésion","reason":"Une illusion peut continuer à solliciter notre pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Mettre en évidence une tendance de la raison","reason":"Certaines erreurs naissent d’un besoin d’explication absolue, et non du seul manque d’informations.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"kant-concevoir-et-exister","code":"K07","author":"Kant","title":"Concevoir n’est pas faire exister","work":"Critique de la raison pure","locator":"Dialectique transcendantale, idéal de la raison pure, section IV · A 598–599 / B 626–627","quote":"Être n'est à l'évidence pas un prédicat réel, c'est-à-dire un concept de quelque chose qui puisse s'ajouter au concept d'une chose.","notions":["raison","religion","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Peut-on établir l’existence d’une chose en analysant seulement son concept ?"},{"function":"L’affirmation","sentence":"Kant refuse de traiter l’existence comme une propriété ajoutée à la définition d’une chose."},{"function":"Les concepts","sentence":"Un prédicat réel désigne ici une détermination du contenu du concept, et non le fait que son objet existe."},{"function":"La raison","sentence":"Dire qu’une chose existe ne complète donc pas sa description, mais pose qu’un objet correspond à cette description."},{"function":"L’exemple","sentence":"Cent pièces réelles n’ont pas une propriété descriptive de plus que cent pièces possibles, même si leur possession change ma fortune."},{"function":"La portée","sentence":"La pensée du possible ne suffit donc pas à prouver l’existence, sans que cette critique démontre l’inexistence de ce qu’elle vise."}],"uses":[{"subject":"La raison suffit-elle à connaître le réel ?","function":"Distinguer la possibilité pensée et l’existence","reason":"La construction d’un concept cohérent ne prouve pas que son objet existe ; la raison doit encore établir ce qui correspond à ce concept.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Est-il déraisonnable de croire en Dieu ?","function":"Délimiter la portée d’une preuve rationnelle","reason":"L’échec d’une preuve tirée du seul concept de Dieu limite une prétention de la raison ; il ne démontre pas l’inexistence de Dieu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}]},{"id":"kant-raison-et-libre-critique","code":"K08","author":"Kant","title":"La raison doit accepter la critique","work":"Critique de la raison pure","locator":"Discipline de la raison pure, section II · A 738–739 / B 766–767","quote":"La raison doit, dans toutes ses entreprises, se soumettre à la critique, et elle ne peut par aucun interdit attenter à la liberté de cette dernière sans se nuire à elle-même et sans attirer sur elle un soupçon qui lui est dommageable.","notions":["raison","liberte","verite"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La raison peut-elle protéger son autorité en interdisant qu’on la conteste ?"},{"function":"L’affirmation","sentence":"Kant affirme que la raison se nuit lorsqu’elle soustrait ses entreprises à la critique."},{"function":"Les concepts","sentence":"Critiquer signifie ici examiner les raisons d’une affirmation, et non la rejeter par principe."},{"function":"La raison","sentence":"Une interdiction empêche l’épreuve des arguments et rend suspecte l’autorité qui refuse de s’y soumettre."},{"function":"L’exemple","sentence":"Une théorie qui répond aux objections par la censure ne montre pas pourquoi ses conclusions devraient être admises."},{"function":"La portée","sentence":"La liberté de la critique appartient donc à l’exercice de la raison, sans rendre toutes les objections également fondées."}],"uses":[{"subject":"Une théorie scientifique doit-elle se prémunir contre toute critique ?","function":"Distinguer la défense d’une théorie et sa mise à l’abri","reason":"L’interdiction des objections compromet la justification d’une théorie : sa défense doit exposer ses raisons plutôt que supprimer la critique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Montrer une condition publique de l’examen rationnel","reason":"La liberté d’exposer les objections permet d’éprouver nos raisons ; leur interdiction affaiblit la justification qu’elle prétend protéger.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"kant-persuasion-et-fondement","code":"K09","author":"Kant","title":"Être persuadé ne suffit pas","work":"Critique de la raison pure","locator":"Canon de la raison pure, section III · A 820–821 / B 848–849","quote":"La persuasion est une simple apparence, parce que le fondement du jugement, qui réside uniquement dans le sujet, est tenu pour objectif.","notions":["verite","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La force avec laquelle je crois une proposition suffit-elle à la justifier ?"},{"function":"L’affirmation","sentence":"Kant appelle persuasion l’adhésion qui prend un fondement seulement personnel pour une raison objective."},{"function":"Les concepts","sentence":"Le fondement subjectif explique pourquoi je suis convaincu, tandis qu’une raison objective doit pouvoir justifier le jugement pour d’autres."},{"function":"La raison","sentence":"L’intensité de mon sentiment ne transforme pas ce qui agit sur moi en preuve de ce que j’affirme."},{"function":"L’exemple","sentence":"Une rumeur peut me sembler certaine parce qu’elle confirme mes peurs, sans que cette peur établisse sa vérité."},{"function":"La portée","sentence":"Examiner une certitude exige donc de distinguer ses causes personnelles et ses raisons partageables, sans confondre toute conviction avec une illusion."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer l’assurance personnelle et la justification","reason":"Une certitude personnelle doit encore être soutenue par des raisons partageables pour pouvoir valoir au-delà de celui qui l’éprouve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"La conviction d’avoir raison fait-elle obstacle au dialogue ?","function":"Identifier une fermeture possible de la discussion","reason":"Prendre ses raisons personnelles pour des preuves suffisantes peut empêcher l’examen des objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}]},{"id":"kant-opinion-et-insuffisance","code":"K10","author":"Kant","title":"Une opinion consciente de ses limites","work":"Critique de la raison pure","locator":"Canon de la raison pure, section III · A 822 / B 850","quote":"L'opinion est une créance consciente d'être insuffisante subjectivement tout autant qu'objectivement.","notions":["verite","raison","science"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Avoir une opinion signifie-t-il nécessairement prétendre savoir ?"},{"function":"L’affirmation","sentence":"Kant définit l’opinion comme une adhésion consciente de son insuffisance."},{"function":"Les concepts","sentence":"La créance est le fait de tenir une proposition pour vraie, sans que cette adhésion soit toujours un savoir."},{"function":"La raison","sentence":"Dans l’opinion, les raisons disponibles ne suffisent ni à assurer pleinement celui qui juge ni à justifier le jugement pour chacun."},{"function":"L’exemple","sentence":"Un médecin peut envisager un diagnostic provisoire tout en reconnaissant que les examens nécessaires manquent encore."},{"function":"La portée","sentence":"Une opinion peut donc orienter une recherche si elle reconnaît ses limites, sans acquérir pour autant la valeur d’un savoir."}],"uses":[{"subject":"L’opinion a-t-elle nécessairement tort ?","function":"Distinguer l’insuffisance et la fausseté","reason":"Un jugement provisoire peut reconnaître ses limites sans être nécessairement faux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Le savant doit-il fuir l’incertitude ?","function":"Donner une place au jugement provisoire","reason":"Reconnaître l’insuffisance de ses raisons permet de poursuivre la recherche au lieu d’affirmer prématurément un savoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=133","sourceLabel":"Recueil académique · p. 133"}]},{"id":"kant-bonheur-et-totalite","code":"K11","author":"Kant","title":"Le bonheur et la totalité des désirs","work":"Critique de la raison pure","locator":"Canon de la raison pure, section II · A 806 / B 834","quote":"Le bonheur est la satisfaction de toutes nos inclinations (aussi bien extensive, à l'égard de leur variété, qu'intensive, quant à leur degré, et même protensive, du point de vue de leur durée).","notions":["bonheur","raison"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Être heureux consiste-t-il à obtenir une satisfaction particulière ?"},{"function":"L’affirmation","sentence":"Kant définit le bonheur par la satisfaction de l’ensemble de nos inclinations."},{"function":"Les concepts","sentence":"Cette totalité concerne la variété de nos désirs, l’intensité de leur satisfaction et sa durée."},{"function":"La raison","sentence":"Un plaisir isolé ne suffit donc pas à garantir que les autres dimensions de notre vie nous satisfassent."},{"function":"L’exemple","sentence":"Réussir un projet longtemps désiré peut coexister avec la solitude, l’inquiétude ou la peur de perdre cette réussite."},{"function":"La portée","sentence":"Cette définition explique l’exigence du bonheur, sans prouver que nous sachions toujours quels moyens permettraient de l’atteindre."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer une satisfaction et le bonheur","reason":"Le bonheur exige ici la satisfaction de l’ensemble des inclinations dans la durée ; obtenir un bien particulier ne garantit pas cette totalité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Préciser la difficulté de l’idéal","reason":"La totalité, l’intensité et la durée des satisfactions rendent le bonheur plus exigeant qu’un plaisir momentané.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"kant-apprendre-a-philosopher","code":"K12","author":"Kant","title":"Apprendre à philosopher","work":"Critique de la raison pure","locator":"Architectonique de la raison pure · A 838 / B 866","quote":"On peut seulement apprendre à philosopher, c'est-à-dire à exercer le talent de la raison dans la mise en œuvre de ses principes universels à la faveur de certaines tentatives qui se présentent, même si se trouve toujours réservé le droit qu'a la raison d'examiner ces principes eux-mêmes quant à leurs sources, pour les confirmer ou les rejeter.","notions":["raison","verite","liberte"],"edition":"GF · 3e édition corrigée, réédition 2021","publisher":"Flammarion","editionYear":2021,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Apprendre les pensées des philosophes suffit-il pour savoir philosopher ?"},{"function":"L’affirmation","sentence":"Kant distingue l’apprentissage d’un système et l’exercice personnel de la raison."},{"function":"Les concepts","sentence":"Philosopher consiste à mettre des principes à l’épreuve tout en conservant le droit de les examiner eux-mêmes."},{"function":"La raison","sentence":"Celui qui ne fait que répéter une doctrine dépend encore de la raison d’autrui, même s’il la connaît parfaitement."},{"function":"L’exemple","sentence":"Retenir une démonstration ne dispense pas de comprendre ses raisons ni d’examiner l’objection qui pourrait la fragiliser."},{"function":"La portée","sentence":"Les œuvres peuvent donc former notre jugement, à condition de devenir des occasions de penser plutôt que des autorités à réciter."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Définir les conditions d’un apprentissage autonome","reason":"L’élève doit pouvoir examiner les principes et non seulement répéter les conclusions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on être philosophe sans être savant ?","function":"Distinguer l’érudition et l’exercice du jugement","reason":"L’accumulation des doctrines ne suffit pas à philosopher : les connaissances deviennent formatrices lorsqu’elles permettent un exercice personnel du jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=146","sourceLabel":"Recueil académique · p. 146"}],"quoteSegments":["On peut seulement apprendre à philosopher, c'est-à-dire à exercer le talent de la raison dans la mise en œuvre de ses principes universels"]},{"id":"kant-juger-le-particulier","code":"K13","author":"Kant","title":"Juger le cas particulier","work":"Critique de la faculté de juger","locator":"Introduction publiée, IV","quote":"La faculté de juger en général est le pouvoir de penser le particulier comme compris sous l'universel.","notions":["raison","science"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Juger consiste-t-il seulement à appliquer une règle déjà connue ?"},{"function":"L’affirmation","sentence":"Kant définit le jugement comme le pouvoir de penser un cas particulier sous une règle générale."},{"function":"Les concepts","sentence":"Le particulier est ce cas singulier, tandis que l’universel est la règle ou le principe sous lequel nous le comprenons."},{"function":"La raison","sentence":"Mais nous pouvons soit disposer de cette règle, soit devoir la chercher à partir du cas rencontré."},{"function":"L’exemple","sentence":"Identifier un triangle grâce à sa définition diffère ainsi de chercher une régularité parmi des phénomènes encore mal connus."},{"function":"La portée","sentence":"Juger demande donc tantôt une application, tantôt une recherche, et ne se réduit pas toujours à répéter une règle."}],"uses":[{"subject":"Peut-on apprendre à penser ?","function":"Distinguer deux exercices du jugement","reason":"Juger demande parfois de chercher la règle qui convient au cas rencontré, et pas seulement d’appliquer une règle déjà apprise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"L’expérience nous instruit-elle ?","function":"Expliquer le travail accompli sur les cas","reason":"Rencontrer des faits devient instructif lorsque le jugement cherche une règle qui permette de les comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"kant-plaire-sans-posseder","code":"K14","author":"Kant","title":"Plaire sans vouloir posséder","work":"Critique de la faculté de juger","locator":"§ 5 · définition du beau déduite du premier moment","quote":"Le goût est la faculté de juger un objet ou un mode de représentation par l'intermédiaire de la satisfaction ou du déplaisir, de manière désintéressée.","notions":["art"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Apprécier une beauté revient-il à désirer posséder ce qui nous plaît ?"},{"function":"L’affirmation","sentence":"Kant distingue le jugement de goût et la satisfaction liée à un intérêt pour l’objet."},{"function":"Les concepts","sentence":"Le désintéressement signifie ici que le plaisir ne dépend pas du désir de posséder l’objet ou d’en tirer avantage."},{"function":"La raison","sentence":"Je peux ainsi prendre plaisir à sa représentation sans me demander ce que son existence m’apporte."},{"function":"L’exemple","sentence":"Admirer la forme d’un palais ne revient pas à vouloir y habiter ni à approuver les dépenses de son propriétaire."},{"function":"La portée","sentence":"Le jugement de goût peut donc être désintéressé sans être indifférent, puisque la beauté nous procure précisément une satisfaction."}],"uses":[{"subject":"La valeur de l’art réside-t-elle dans son inutilité ?","function":"Distinguer le désintéressement et l’absence de valeur","reason":"Une satisfaction peut avoir une valeur sans dépendre d’un avantage à obtenir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"Beauté et utilité sont-elles incompatibles ?","function":"Distinguer deux façons d’apprécier le même objet","reason":"Un objet peut être utile, tandis que le plaisir pris à sa beauté ne dépend pas de cet usage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-beau-et-universalite","code":"K15","author":"Kant","title":"Un plaisir qui demande à être partagé","work":"Critique de la faculté de juger","locator":"§ 9 · définition du beau déduite du deuxième moment","quote":"Est beau ce qui plaît universellement sans concept.","notions":["art","raison"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Dire qu’une chose est belle signifie-t-il seulement qu’elle me plaît personnellement ?"},{"function":"L’affirmation","sentence":"Kant affirme que le jugement de beauté prétend à un plaisir partageable par tous sans démonstration par concepts."},{"function":"Les concepts","sentence":"L’universalité est ici une exigence d’accord, et non le constat que chacun apprécie effectivement le même objet."},{"function":"La raison","sentence":"En disant beau plutôt qu’agréable pour moi, je sollicite l’adhésion d’autrui sans pouvoir l’imposer par une preuve."},{"function":"L’exemple","sentence":"Deux visiteurs peuvent discuter de la beauté d’un tableau alors qu’ils ne discuteraient pas de la même manière d’une préférence pour une saveur."},{"function":"La portée","sentence":"Le goût n’est donc ni un simple caprice privé ni une connaissance démontrable, et les désaccords ne disparaissent pas pour autant."}],"uses":[{"subject":"L’art est-il une affaire de goût personnel ?","function":"Dépasser l’opposition entre caprice et preuve","reason":"Un jugement esthétique peut réclamer un accord sans devenir une démonstration.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Peut-on démontrer qu’une œuvre d’art est belle ?","function":"Distinguer l’exigence d’accord et la preuve","reason":"Demander l’adhésion d’autrui ne suppose pas qu’on puisse déduire la beauté de l’œuvre à partir d’un concept.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-beau-sans-recette","code":"K16","author":"Kant","title":"La beauté n’a pas de recette","work":"Critique de la faculté de juger","locator":"§ 17 · De l’idéal de la beauté","quote":"Il ne peut y avoir nulle règle objective du goût qui détermine par concepts ce qui est beau.","notions":["art","raison"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une définition permettrait-elle de décider automatiquement de ce qui est beau ?"},{"function":"L’affirmation","sentence":"Kant refuse l’existence d’une règle objective qui déduirait la beauté à partir de concepts."},{"function":"Les concepts","sentence":"Une telle règle devrait imposer le jugement de goût comme une conclusion démontrée."},{"function":"La raison","sentence":"Or le plaisir esthétique doit être éprouvé par le sujet et ne peut être remplacé par un raisonnement sur des propriétés."},{"function":"L’exemple","sentence":"Connaître les proportions d’un bâtiment ne force pas à trouver sa façade belle."},{"function":"La portée","sentence":"On peut donc éduquer et discuter le goût sans posséder une formule qui dicterait nécessairement l’appréciation de chacun."}],"uses":[{"subject":"Faut-il renoncer à définir le beau ?","function":"Distinguer une réflexion et une règle de décision","reason":"Une définition peut préciser ce que nous appelons beau sans dicter le plaisir éprouvé ; elle ne dispense donc pas de l’expérience du jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Peut-on prouver qu’une œuvre d’art est belle ?","function":"Limiter la portée des arguments démonstratifs","reason":"L’analyse des propriétés de l’œuvre peut éclairer le regard sans contraindre le plaisir comme une conclusion logique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=88","sourceLabel":"Recueil académique · p. 88"}]},{"id":"kant-sublime-et-resistance","code":"K17","author":"Kant","title":"Un plaisir qui résiste aux sens","work":"Critique de la faculté de juger","locator":"Remarque générale après le § 29 · exposition des jugements esthétiques réfléchissants","quote":"Est sublime ce qui plaît immédiatement à travers la résistance qu'il oppose à l'intérêt des sens.","notions":["nature","raison","art"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comment pouvons-nous éprouver une satisfaction devant ce qui contrarie notre sensibilité ?"},{"function":"L’affirmation","sentence":"Kant distingue le sublime d’un plaisir qui satisferait immédiatement les sens."},{"function":"Les concepts","sentence":"Le sublime fait éprouver une résistance sensible, puis révèle dans l’esprit une capacité qui ne se mesure pas à cette résistance."},{"function":"La raison","sentence":"Face à une puissance naturelle, notre faiblesse physique peut ainsi faire ressortir une destination rationnelle qui ne se réduit pas à la force."},{"function":"L’exemple","sentence":"Observer une tempête depuis un lieu sûr peut susciter ce sentiment mêlé de recul et d’élévation."},{"function":"La portée","sentence":"Le sublime n’est donc pas le simple charme d’un spectacle, et il ne suppose ni de rechercher le danger ni d’aimer souffrir."}],"uses":[{"subject":"Faut-il prendre la nature pour modèle ?","function":"Distinguer puissance naturelle et valeur rationnelle","reason":"La puissance de la nature peut révéler une exigence humaine qui ne consiste pas à l’imiter ; l’admiration ne prescrit donc pas à elle seule un modèle de conduite.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Distinguer satisfaction esthétique et agrément immédiat","reason":"Le sublime naturel fait éprouver une satisfaction qui passe par une résistance sensible ; cette possibilité enrichit l’analyse du plaisir sans définir tout l’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-savoir-et-savoir-faire","code":"K18","author":"Kant","title":"Savoir n’est pas encore savoir faire","work":"Critique de la faculté de juger","locator":"§ 43 · De l’art en général","quote":"Seul ce que l'on n'a pas aussitôt l'habileté de faire du simple fait qu'on le connaît de la manière la plus parfaite relève de l'art.","notions":["art","technique","travail"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Connaître parfaitement une manière de faire suffit-il pour savoir la réaliser ?"},{"function":"L’affirmation","sentence":"Kant distingue le savoir théorique et l’habileté pratique que requiert l’art."},{"function":"Les concepts","sentence":"L’art désigne ici un savoir-faire, dans un sens plus large que les seuls beaux-arts."},{"function":"La raison","sentence":"La connaissance du résultat recherché ne donne pas nécessairement la capacité de le produire."},{"function":"L’exemple","sentence":"Décrire avec précision une bonne chaussure ne rend pas capable de la fabriquer."},{"function":"La portée","sentence":"La pratique exige donc une habileté propre, sans que cela rende les connaissances inutiles à celui qui apprend un métier ou un art."}],"uses":[{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Reconnaître d’abord une dimension pratique irréductible","reason":"Une connaissance théorique ne remplace pas l’habileté de produire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"L’art s’apprend-il ?","function":"Préciser ce qui doit être appris","reason":"L’acquisition d’informations ne transmet pas à elle seule l’habileté de produire : l’exercice joue un rôle propre dans l’apprentissage de l’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"kant-genie-et-regles","code":"K19","author":"Kant","title":"Créer des règles par l’œuvre","work":"Critique de la faculté de juger","locator":"§ 46 · Les beaux-arts sont les arts du génie","quote":"Le génie est le talent (don naturel) qui donne à l'art ses règles.","notions":["art","nature","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"L’artiste crée-t-il seulement en appliquant une méthode déjà disponible ?"},{"function":"L’affirmation","sentence":"Kant définit le génie comme un talent qui donne à l’art ses règles."},{"function":"Les concepts","sentence":"Ces règles ne sont pas une recette transmise avant l’œuvre, mais ce qui devient exemplaire à travers une création originale."},{"function":"La raison","sentence":"Une œuvre du génie ouvre ainsi une possibilité que les autres peuvent explorer sans simplement la copier."},{"function":"L’exemple","sentence":"Un poème peut inventer une manière d’associer rythme et images dont d’autres auteurs apprendront à leur tour."},{"function":"La portée","sentence":"Le génie ne se réduit donc pas à l’application technique, sans dispenser l’artiste du travail, de l’apprentissage ou du jugement."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Distinguer l’apprentissage et la création exemplaire","reason":"Les modèles forment le jugement de l’artiste, mais une œuvre originale ne se contente pas de reproduire leurs résultats : elle ouvre elle-même une possibilité exemplaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Donner un contenu précis au don créateur","reason":"L’œuvre originale devient exemplaire au lieu de suivre une recette préexistante ; cette invention des règles n’exclut ni l’apprentissage ni le travail.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"kant-art-et-naturel","code":"K20","author":"Kant","title":"L’art et l’apparence du naturel","work":"Critique de la faculté de juger","locator":"§ 45 · Les beaux-arts et l’apparence de la nature","quote":"La nature était belle lorsqu'en même temps elle avait l'apparence de l'art ; et l'art ne peut être appelé beau que si nous sommes conscients qu'il s'agit d'art et que celui-ci prend cependant pour nous l'apparence de la nature.","notions":["art","nature","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Une œuvre doit-elle montrer la contrainte du travail qui l’a rendue possible ?"},{"function":"L’affirmation","sentence":"Kant affirme que le bel art doit paraître naturel tout en restant reconnu comme de l’art."},{"function":"Les concepts","sentence":"Le naturel désigne ici une liberté apparente à l’égard des règles, et non l’absence de fabrication."},{"function":"La raison","sentence":"Si la méthode s’impose comme une contrainte visible, l’œuvre semble exécutée mécaniquement plutôt que librement composée."},{"function":"L’exemple","sentence":"Un vers très travaillé peut sembler aller de soi sans que le lecteur ignore qu’un poète l’a composé."},{"function":"La portée","sentence":"Le naturel peut donc être un effet de l’art, sans se confondre avec une tromperie qui ferait passer l’œuvre pour un objet naturel."}],"uses":[{"subject":"L’art s’apprend-il ?","function":"Distinguer l’effort de formation et son effet sensible","reason":"La réussite peut consister à ne pas donner l’impression d’une application laborieuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"Faut-il prendre la nature pour modèle ?","function":"Préciser le sens d’un modèle naturel pour l’art","reason":"L’artiste peut rechercher une apparence de liberté plutôt que copier les formes des objets naturels.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"kant-beaute-de-la-representation","code":"K21","author":"Kant","title":"La beauté de la représentation","work":"Critique de la faculté de juger","locator":"§ 48 · Du rapport du génie au goût","quote":"Une beauté naturelle est une belle chose ; la beauté artistique est une belle représentation d'une chose.","notions":["art","nature"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"La beauté d’une œuvre exige-t-elle que son sujet soit lui-même beau ?"},{"function":"L’affirmation","sentence":"Kant distingue une belle chose et la belle représentation d’une chose."},{"function":"Les concepts","sentence":"La beauté naturelle concerne l’objet considéré, tandis que la beauté artistique engage la manière de le présenter."},{"function":"La raison","sentence":"La valeur esthétique d’une représentation ne se déduit donc pas de l’agrément que procurerait son sujet dans la réalité."},{"function":"L’exemple","sentence":"Une peinture peut représenter avec force un visage marqué par l’âge sans chercher à l’embellir."},{"function":"La portée","sentence":"L’art peut ainsi représenter des choses déplaisantes, sans que toute représentation de la laideur devienne pour autant une belle œuvre."}],"uses":[{"subject":"La laideur peut-elle intéresser l’artiste ?","function":"Dissocier la valeur de l’œuvre et l’agrément du sujet","reason":"Une chose déplaisante peut recevoir une belle représentation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’œuvre d’art est-elle nécessairement belle ?","function":"Préciser ce qui est jugé beau","reason":"La beauté de la représentation se distingue de celle du sujet représenté ; représenter une chose laide n’implique donc pas renoncer à toute beauté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"kant-vivant-et-machine","code":"K22","author":"Kant","title":"Le vivant et la machine","work":"Critique de la faculté de juger","locator":"§ 65 · Les choses en tant que fins naturelles","quote":"Un être organisé n'est donc pas simplement une machine, étant donné que la machine a exclusivement la force motrice ; mais il possède en soi une force formatrice qu'il communique aux matières qui n'en disposent pas (il les organise) : c'est donc une force formatrice qui se propage et qui ne peut être expliquée uniquement par le pouvoir moteur (par le mécanisme).","notions":["nature","science","technique"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Comprendre le vivant revient-il à décrire une machine particulièrement complexe ?"},{"function":"L’affirmation","sentence":"Kant distingue la force motrice d’une machine et la force formatrice d’un être organisé."},{"function":"Les concepts","sentence":"Le vivant ne se borne pas à transmettre des mouvements, puisqu’il assimile des matières et contribue à sa propre formation."},{"function":"La raison","sentence":"Dans une machine, les pièces ne produisent pas normalement les autres pièces, alors que l’organisation vivante entretient les conditions de son activité."},{"function":"L’exemple","sentence":"Un arbre grandit en organisant les matières qu’il reçoit, tandis qu’une montre ne fabrique pas elle-même ses rouages."},{"function":"La portée","sentence":"Cette distinction indique une difficulté du modèle mécanique chez Kant, sans établir une limite définitive de la biologie contemporaine."}],"uses":[{"subject":"Un être vivant peut-il être assimilé à une machine ?","function":"Faire apparaître la limite de l’analogie","reason":"Une machine transmet un mouvement, tandis que le vivant organise les matières qui contribuent à sa formation et à son maintien.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=64","sourceLabel":"Recueil académique · p. 64"},{"subject":"Faut-il, pour connaître le vivant, l’assimiler à une machine ?","function":"Distinguer l’utilité d’un modèle et sa suffisance","reason":"Le modèle mécanique explique des fonctionnements, mais doit encore rendre compte de l’organisation par laquelle un vivant se forme et se maintient.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=64","sourceLabel":"Recueil académique · p. 64"}],"quoteSegments":["Un être organisé n'est donc pas simplement une machine,","mais il possède en soi une force formatrice qu'il communique aux matières qui n'en disposent pas (il les organise)"]},{"id":"kant-organisme-et-reciprocite","code":"K23","author":"Kant","title":"Dans le vivant, fin et moyen","work":"Critique de la faculté de juger","locator":"§ 66 · La finalité interne dans les êtres organisés","quote":"Ce principe, qui constitue en même temps la définition des êtres organisés, est le suivant : un produit organisé de la nature est celui dans lequel tout est fin et réciproquement aussi moyen.","notions":["nature","science"],"edition":"GF · édition avec bibliographie mise à jour (2015)","publisher":"Flammarion","editionYear":2015,"translator":"Alain Renaut","commentary":[{"function":"Le problème","sentence":"Peut-on comprendre un organe en l’isolant entièrement de l’organisme ?"},{"function":"L’affirmation","sentence":"Kant propose de juger l’être organisé comme un tout dans lequel les parties sont réciproquement fins et moyens."},{"function":"Les concepts","sentence":"Une partie contribue à l’existence des autres et du tout, dont elle reçoit elle-même les conditions de son maintien."},{"function":"La raison","sentence":"Cette réciprocité conduit à comprendre chaque organe à partir de l’organisation à laquelle il participe."},{"function":"L’exemple","sentence":"Une feuille nourrit l’arbre dont les racines et les autres parties rendent possible sa propre croissance."},{"function":"La portée","sentence":"La finalité guide ici notre jugement sur le vivant, sans prouver qu’un créateur aurait consciemment conçu chaque détail de l’organisme."}],"uses":[{"subject":"Suffit-il de connaître la matière pour connaître le vivant ?","function":"Introduire la relation entre les parties et le tout","reason":"Un inventaire des matières ne suffit pas à expliquer les fonctions réciproques des parties qui constituent l’organisme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=134","sourceLabel":"Recueil académique · p. 134"},{"subject":"Le vivant est-il entièrement explicable ?","function":"Distinguer un principe de recherche et une explication acquise","reason":"Comprendre les organes par leurs relations guide l’étude, sans donner à lui seul l’explication de leur production.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=134","sourceLabel":"Recueil académique · p. 134"}]},{"id":"baudelaire-nature-et-signes","code":"B01","author":"Baudelaire","title":"La nature à interpréter","work":"Correspondances","locator":"v. 1–2 · p. 39","quote":"La Nature est un temple où de vivants piliers\nLaissent parfois sortir de confuses paroles;","notions":["nature","langage","art"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La nature nous livre-t-elle immédiatement ce qu’elle signifie ?"},{"function":"L’affirmation","sentence":"Le poème présente la nature comme un temple dont les paroles restent confuses."},{"function":"Les concepts","sentence":"Les piliers vivants rapprochent l’ordre naturel d’un lieu sacré, tandis que la parole suggère une présence à comprendre."},{"function":"La raison","sentence":"Mais cette parole demande une interprétation, puisque son sens ne se donne pas avec la netteté d’un message ordinaire."},{"function":"L’exemple","sentence":"Une forêt peut ainsi être perçue comme un ensemble de choses ou comme un paysage chargé de correspondances."},{"function":"La portée","sentence":"La poésie ouvre une autre attention au monde, sans démontrer que la nature possède littéralement un langage humain."}],"uses":[{"subject":"L’art peut-il nous apprendre à voir le monde autrement ?","function":"Déplacer notre manière de percevoir","reason":"L’image poétique fait apparaître des relations que le regard habituel néglige.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il une interprétation du monde ?","function":"Distinguer interprétation et explication","reason":"Le temple et les paroles prêtées à la nature construisent une interprétation du monde ; cette lecture des symboles se distingue de la recherche scientifique de ses causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=11","sourceLabel":"Recueil académique · p. 11"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-art-et-temps","code":"B02","author":"Baudelaire","title":"L’œuvre exige plus de temps que la vie","work":"Le Guignon","locator":"v. 3–4 · p. 45","quote":"Bien qu’on ait du cœur à l’ouvrage,\nL’Art est long et le Temps est court.","notions":["art","temps","travail"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La bonne volonté suffit-elle à mener une œuvre à son accomplissement ?"},{"function":"L’affirmation","sentence":"Le poème oppose la longueur du travail artistique à la brièveté du temps disponible."},{"function":"Les concepts","sentence":"Avoir du cœur à l’ouvrage signifie s’y engager, sans disposer pour autant de toute la durée nécessaire."},{"function":"La raison","sentence":"L’artiste peut donc éprouver une disproportion entre son effort, l’exigence de son art et les limites de sa vie."},{"function":"L’exemple","sentence":"Un créateur peut consacrer des années à une œuvre sans lui donner encore la forme qu’il cherche."},{"function":"La portée","sentence":"La création fait ainsi rencontrer notre finitude, sans que la durée de l’effort garantisse à elle seule la valeur du résultat."}],"uses":[{"subject":"L’activité artistique est-elle un travail ?","function":"Mettre au jour l’effort de création","reason":"La disproportion entre l’Art long et le Temps court rend sensible la durée d’élaboration que l’idée d’une inspiration immédiate peut masquer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer l’engagement et la disponibilité du temps","reason":"Vouloir accomplir une œuvre n’abolit pas la limite de la durée dont nous disposons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-beaute-et-bien","code":"B03","author":"Baudelaire","title":"La beauté répond-elle du bien ?","work":"Hymne à la Beauté","locator":"v. 11–12 · p. 52","quote":"Tu sèmes au hasard la joie et les désastres,\nEt tu gouvernes tout et ne réponds de rien.","notions":["art","devoir"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui nous éblouit est-il nécessairement bon ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à une Beauté capable de produire aussi bien la joie que le désastre."},{"function":"Les concepts","sentence":"La beauté devient une puissance personnifiée dont l’efficacité ne s’accompagne d’aucune responsabilité morale."},{"function":"La raison","sentence":"Notre fascination peut donc nous soumettre à ce qui nous attire avant que nous ayons jugé ses effets."},{"function":"L’exemple","sentence":"Une forme admirable peut servir un discours violent sans perdre immédiatement son pouvoir de séduction."},{"function":"La portée","sentence":"L’expérience esthétique doit ainsi être distinguée de l’approbation morale, sans conclure que toute beauté serait mauvaise."}],"uses":[{"subject":"L’art nous rend-il meilleurs ?","function":"Contester le passage automatique du beau au bien","reason":"La fascination esthétique peut produire joie et désastre : sa puissance ne garantit pas une amélioration morale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"La beauté est-elle la seule fin de l’art ?","function":"Ouvrir l’examen de la responsabilité artistique","reason":"La puissance du beau ne suffit pas à justifier les effets d’une œuvre ; la question de sa fin ne se réduit donc pas à son pouvoir de séduire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-souvenir-et-presence","code":"B04","author":"Baudelaire","title":"Rendre le passé présent","work":"Le Balcon","locator":"v. 21–22 · p. 63","quote":"Je sais l’art d’évoquer les minutes heureuses,\nEt revis mon passé blotti dans tes genoux.","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le souvenir rend-il présent ce qui a disparu ?"},{"function":"L’affirmation","sentence":"La voix poétique affirme son pouvoir d’évoquer et de revivre des instants heureux."},{"function":"Les concepts","sentence":"L’évocation est une activité de la mémoire, tandis que revivre dit l’intensité présente de ce rappel."},{"function":"La raison","sentence":"Les sensations et la proximité de l’être aimé semblent rendre au passé une présence que la chronologie lui refuse."},{"function":"L’exemple","sentence":"Un parfum familier peut faire renaître avec force l’atmosphère d’une rencontre ancienne."},{"function":"La portée","sentence":"La mémoire peut donc transformer notre expérience du présent, sans restituer matériellement l’événement ni abolir sa perte."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer le retour sensible et le retour réel","reason":"Le souvenir rend au passé une présence intérieure qui transforme le présent, même s’il n’abolit pas l’irréversibilité des événements.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Est-il possible de vivre au présent ?","function":"Montrer que le présent accueille le passé","reason":"Le présent vécu n’est pas un instant isolé : la mémoire y fait revenir des sensations et des attachements passés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-memoire-et-duree","code":"B05","author":"Baudelaire","title":"Une mémoire plus vieille que soi","work":"Spleen","locator":"LXXVI · v. 1 · p. 94","quote":"J’ai plus de souvenirs que si j’avais mille ans.","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le poids d’une vie se mesure-t-il au nombre des années vécues ?"},{"function":"L’affirmation","sentence":"La voix poétique éprouve une mémoire plus chargée que ne le serait celle d’une existence millénaire."},{"function":"Les concepts","sentence":"L’hyperbole des mille ans oppose la durée comptable à l’accumulation intérieure des souvenirs."},{"function":"La raison","sentence":"Le passé ne demeure pas seulement derrière nous : il peut encombrer le présent et rendre chaque instant lourd de ce qui a été vécu."},{"function":"L’exemple","sentence":"Le poème compare ensuite le cerveau à un meuble rempli, puis à un caveau."},{"function":"La portée","sentence":"La mémoire transforme ainsi l’expérience du temps, sans que sa richesse garantisse une vie plus heureuse ou un savoir plus juste."}],"uses":[{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer âge et durée vécue","reason":"L’hyperbole des mille ans fait sentir une densité du passé que le seul nombre des années ne décrit pas.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Pour se libérer du passé faut-il l’oublier ?","function":"Montrer le poids possible du souvenir","reason":"La mémoire peut encombrer le présent plutôt que l’enrichir ; sa conservation n’est donc pas toujours une libération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-obscurite-et-memoire","code":"B06","author":"Baudelaire","title":"La nuit ne suffit pas à oublier","work":"Obsession","locator":"v. 9–10 · p. 97","quote":"Comme tu me plairais, ô nuit! sans ces étoiles\nDont la lumière parle un langage connu!","notions":["conscience","temps"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on échapper à ce qui nous habite en supprimant les signes du monde extérieur ?"},{"function":"L’affirmation","sentence":"La voix poétique désire une nuit privée des étoiles dont la lumière lui parle encore."},{"function":"Les concepts","sentence":"Le langage connu des étoiles désigne un monde qui réveille des significations et des souvenirs devenus douloureux."},{"function":"La raison","sentence":"Mais la fin du poème peuple aussi les ténèbres de figures disparues qui jaillissent du regard lui-même."},{"function":"L’exemple","sentence":"Fermer les yeux peut ainsi laisser revenir une image que la présence des choses ne suffit pas à expliquer."},{"function":"La portée","sentence":"La fuite du monde rencontre donc une mémoire intérieure, sans que cette expérience poétique établisse l’impossibilité de tout apaisement."}],"uses":[{"subject":"Peut-on se libérer du passé ?","function":"Montrer la limite d’une fuite extérieure","reason":"S’éloigner des lieux ne suffit pas à effacer ce qui revient par la mémoire : la fuite extérieure rencontre une persistance intérieure.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-monde-et-desir","code":"B07","author":"Baudelaire","title":"Quand le monde perd son attrait","work":"Le Goût du néant","locator":"v. 10 · p. 97","quote":"Le Printemps adorable a perdu son odeur!","notions":["bonheur","conscience","nature"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Suffit-il que le monde offre des plaisirs pour que nous puissions en jouir ?"},{"function":"L’affirmation","sentence":"Dans le poème, le printemps semble avoir perdu jusqu’à son odeur."},{"function":"Les concepts","sentence":"Le printemps représente le renouveau sensible, mais l’épuisement intérieur lui retire son pouvoir d’attirer."},{"function":"La raison","sentence":"Le monde n’a pas nécessairement cessé d’offrir ses biens : c’est la relation du sujet à ces biens qui s’est altérée."},{"function":"L’exemple","sentence":"Une fête peut demeurer animée et belle sans éveiller aucun plaisir chez celui qui la traverse dans le désenchantement."},{"function":"La portée","sentence":"Le bonheur suppose donc une capacité d’être affecté par ce qui arrive, sans réduire toute souffrance à une simple attitude volontaire."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Examiner la capacité de goûter les biens","reason":"Obtenir les objets souhaités ne garantit pas de pouvoir encore en jouir ; la satisfaction dépend aussi du rapport vivant que nous entretenons avec eux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"De quel bonheur sommes-nous capables ?","function":"Distinguer la vie intérieure et sa maîtrise","reason":"Les biens offerts ne procurent du bonheur que si nous pouvons encore en éprouver la valeur ; cette disposition sensible ne se commande pas toujours.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-douleur-et-transfiguration","code":"B08","author":"Baudelaire","title":"La douleur transforme ce qu’elle voit","work":"Alchimie de la douleur","locator":"v. 9–10 · p. 98","quote":"Par toi je change l’or en fer\nEt le paradis en enfers;","notions":["conscience","art"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Notre état intérieur peut-il modifier la valeur que le monde prend pour nous ?"},{"function":"L’affirmation","sentence":"La voix poétique attribue à un Hermès mystérieux la transformation de l’or en fer et du paradis en enfers."},{"function":"Les concepts","sentence":"Cette alchimie inverse la promesse d’enrichissement associée à la figure de Midas."},{"function":"La raison","sentence":"La douleur agit sur la représentation : ce qui pouvait apparaître précieux devient le signe d’un malheur."},{"function":"L’exemple","sentence":"Un paysage lumineux peut ainsi sembler funèbre à celui qui vient d’y perdre un être aimé."},{"function":"La portée","sentence":"Le poème montre une transformation du monde vécu, sans soutenir que la tristesse change matériellement la nature des choses."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer la part des affects dans la représentation","reason":"La douleur transforme ce qui est perçu et la valeur qui lui est attribuée : penser le monde engage aussi une manière de le sentir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"L’art est-il une forme de connaissance ?","function":"Reconnaître un savoir de l’expérience vécue","reason":"L’image poétique rend intelligible la puissance de la douleur sans fournir une explication scientifique de ses causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"collection":"Les Fleurs du Mal","editionNote":"Le volume fourni porte « enfers » ; l’édition de 1861 consultée en ligne porte « enfer »."},{"id":"baudelaire-soi-et-conflit","code":"B09","author":"Baudelaire","title":"Être à la fois blessé et blessant","work":"L’Héautontimorouménos","locator":"v. 21–22 · p. 99","quote":"Je suis la plaie et le couteau!\nJe suis le soufflet et la joue!","notions":["conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le conflit intérieur suppose-t-il que deux personnes différentes s’affrontent en nous ?"},{"function":"L’affirmation","sentence":"La voix poétique s’identifie à la fois à la blessure et à l’instrument qui la produit."},{"function":"Les concepts","sentence":"La plaie et le couteau, puis le soufflet et la joue, réunissent dans un même sujet les positions opposées du patient et de l’agent."},{"function":"La raison","sentence":"L’image fait comprendre une souffrance dans laquelle celui qui éprouve le mal participe aussi à sa reprise."},{"function":"L’exemple","sentence":"Une personne peut ainsi se faire souffrir en se répétant une accusation qu’elle ne cesse de retourner contre elle-même."},{"function":"La portée","sentence":"Le sujet peut donc être divisé dans son rapport à soi, sans que cette image rende toute victime responsable de la violence subie."}],"uses":[{"subject":"Peut-on être en conflit avec soi-même ?","function":"Donner une forme précise à la division intérieure","reason":"Un même sujet peut occuper des positions opposées dans son expérience de soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"La conscience de soi est-elle trompeuse ?","function":"Interroger un rapport à soi qui se blesse","reason":"La conscience peut entretenir une interprétation douloureuse de soi, et pas seulement constater un état qui lui serait déjà donné.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-rencontre-et-possible","code":"B10","author":"Baudelaire","title":"L’amour qui aurait pu être","work":"À une passante","locator":"v. 13–14 · p. 114","quote":"Car j’ignore où tu fuis, tu ne sais où je vais,\nO toi que j’eusse aimée, ô toi qui le savais!","notions":["temps","bonheur","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on éprouver la perte d’une relation qui n’a jamais commencé ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à une inconnue disparue comme à celle qu’elle aurait pu aimer."},{"function":"Les concepts","sentence":"Le passé non réalisé de l’amour contraste avec l’affirmation d’un savoir attribué à la passante."},{"function":"La raison","sentence":"Le regard croisé suffit à faire naître un possible, mais ne donne ni connaissance de l’autre ni chemin pour la retrouver."},{"function":"L’exemple","sentence":"Dans la rue, la rencontre ne dure qu’un instant avant que leurs directions les séparent."},{"function":"La portée","sentence":"Une possibilité manquée peut ainsi marquer une vie réelle, sans que l’intensité de l’émotion prouve la réciprocité imaginée du sentiment."}],"uses":[{"subject":"Le désir est-il aveugle ?","function":"Distinguer rencontre et projection","reason":"Le savoir réciproque prêté à la passante dépasse ce que le regard a réellement permis de connaître.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-temps-et-jeu","code":"B11","author":"Baudelaire","title":"Un jeu dont le temps gagne les parties","work":"L’Horloge","locator":"v. 17–18 · p. 102","quote":"Souviens-toi que le Temps est un joueur avide\nQui gagne sans tricher, à tout coup! c’est la loi.","notions":["temps","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Pouvons-nous vaincre le temps en conduisant mieux notre vie ?"},{"function":"L’affirmation","sentence":"L’horloge personnifiée présente le temps comme un joueur dont la victoire est régulière."},{"function":"Les concepts","sentence":"L’image du jeu suggère un affrontement, mais l’absence de tricherie renvoie à une condition commune plutôt qu’à une injustice exceptionnelle."},{"function":"La raison","sentence":"Aucune habileté ne supprime l’écoulement de la durée ni la limite de la vie."},{"function":"L’exemple","sentence":"Organiser parfaitement une journée permet de mieux l’employer, sans empêcher qu’elle s’achève."},{"function":"La portée","sentence":"Le rappel de cette limite peut orienter notre usage du temps, sans imposer la conclusion que toute action serait inutile."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer organiser et abolir l’écoulement","reason":"L’efficacité ne supprime pas notre condition temporelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Interroger la fin de l’efficacité","reason":"Gagner du temps ne répond pas à la question de son usage : l’efficacité ne choisit pas les fins auxquelles consacrer une durée limitée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-ville-et-memoire","code":"B12","author":"Baudelaire","title":"La ville change, la mémoire demeure","work":"Le Cygne","locator":"I, v. 7–8 · p. 107","quote":"Le vieux Paris n’est plus (la forme d’une ville\nChange plus vite, hélas! que le cœur d’un mortel);","notions":["temps","conscience"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Changer le monde extérieur suffit-il à transformer ce que nous y vivons ?"},{"function":"L’affirmation","sentence":"Le poème oppose la transformation rapide de Paris à la lenteur des changements du cœur humain."},{"function":"Les concepts","sentence":"La ville désigne un lieu matériel, tandis que le cœur conserve les attachements et les pertes liés à ses anciennes formes."},{"function":"La raison","sentence":"Le sujet peut donc habiter simultanément une ville présente et celle que sa mémoire continue de lui rendre sensible."},{"function":"L’exemple","sentence":"Une rue reconstruite reste, pour un ancien habitant, le lieu d’une rencontre dont aucun bâtiment ne porte plus la trace."},{"function":"La portée","sentence":"Le changement matériel et le temps vécu suivent ainsi des rythmes différents, sans que la mémoire soit pour autant immobile."}],"uses":[{"subject":"Peut-on se libérer du passé ?","function":"Distinguer disparition matérielle et persistance intérieure","reason":"La transformation des lieux n’efface pas immédiatement les souvenirs et les attachements qui leur donnent encore un sens pour nous.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Faire apparaître la diversité des rythmes vécus","reason":"Les lieux changent et les attachements persistent selon des rythmes différents ; une mesure uniforme ne décrit pas cet écart vécu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-mort-et-consolation","code":"B13","author":"Baudelaire","title":"Une consolation qui aide à vivre","work":"La Mort des pauvres","locator":"v. 1 · p. 148","quote":"C’est la Mort qui console, hélas! et qui fait vivre;","notions":["religion","bonheur"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui met fin à la vie peut-il devenir l’objet d’une consolation pendant la vie ?"},{"function":"L’affirmation","sentence":"Le poème présente paradoxalement la Mort comme ce qui console les pauvres et leur donne la force de vivre."},{"function":"Les concepts","sentence":"La Mort personnifiée devient la promesse d’un repos et d’un accueil refusés dans leur existence présente."},{"function":"La raison","sentence":"L’espoir d’une fin de la misère peut ainsi soutenir ceux qui l’endurent, alors même que cette fin demeure inconnue."},{"function":"L’exemple","sentence":"La suite du poème évoque une auberge où il serait enfin possible de manger, de dormir et de s’asseoir."},{"function":"La portée","sentence":"Cette image permet d’examiner la fonction d’une espérance, sans prouver l’existence d’un au-delà ni présenter la mort comme un conseil."}],"uses":[{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Distinguer la fin redoutée et l’espérance de repos","reason":"Dans une existence misérable, la représentation de la mort peut consoler et soutenir la vie au lieu de lui retirer toute valeur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"La religion a-t-elle pour but de consoler les hommes ?","function":"Préciser ce que peut faire une espérance","reason":"Une représentation de l’au-delà peut soutenir une existence misérable. Cette fonction consolante explique un attachement sans épuiser à elle seule le sens de la religion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-plaisir-et-desir","code":"B14","author":"Baudelaire","title":"Le plaisir nourrit-il le désir ?","work":"Le Voyage","locator":"IV, v. 69 · p. 153","quote":"— La jouissance ajoute au désir de la force.","notions":["bonheur","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La satisfaction met-elle nécessairement fin au désir ?"},{"function":"L’affirmation","sentence":"Dans le récit du voyage, la jouissance est présentée comme ce qui accroît la force du désir."},{"function":"Les concepts","sentence":"La jouissance est la satisfaction éprouvée, tandis que le désir demeure un mouvement vers ce qui n’est pas encore obtenu."},{"function":"La raison","sentence":"Le plaisir peut entretenir ce mouvement en faisant souhaiter son retour ou une satisfaction plus intense."},{"function":"L’exemple","sentence":"Une expérience longtemps attendue peut ainsi susciter, une fois vécue, le désir de la recommencer autrement."},{"function":"La portée","sentence":"Satisfaire un désir ne signifie donc pas toujours l’éteindre, sans que tout plaisir doive nécessairement conduire à une poursuite sans limite."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Mettre en question l’extinction du manque","reason":"La satisfaction peut relancer le désir plutôt qu’installer un contentement durable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"},{"subject":"Satisfaire ses désirs peut-il rendre malheureux ?","function":"Expliquer un renouvellement de la dépendance","reason":"Le plaisir obtenu peut devenir l’exigence d’une répétition ou d’une intensification toujours nouvelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"collection":"Les Fleurs du Mal"},{"id":"baudelaire-douleur-et-dialogue","code":"B15","author":"Baudelaire","title":"Parler à sa douleur","work":"Recueillement","locator":"v. 1 · p. 200","quote":"Sois sage, ô ma Douleur, et tiens-toi plus tranquille.","notions":["conscience","liberte"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Faut-il supprimer une souffrance pour modifier le rapport que nous entretenons avec elle ?"},{"function":"L’affirmation","sentence":"La voix poétique s’adresse à sa Douleur comme à une compagne qu’elle cherche à apaiser."},{"function":"Les concepts","sentence":"La personnification distingue celui qui parle et ce qu’il éprouve, sans les rendre étrangers l’un à l’autre."},{"function":"La raison","sentence":"Mettre la douleur en mots peut ouvrir une distance qui ne se confond ni avec son effacement ni avec son déni."},{"function":"L’exemple","sentence":"La suite du poème transforme cette adresse en une marche commune à l’écart de la fête et de ses remords."},{"function":"La portée","sentence":"L’apaisement peut donc passer par une autre relation à sa souffrance, sans faire de la poésie un remède universel."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer suppression et mise à distance","reason":"Une relation réfléchie à la souffrance peut ouvrir une marge de liberté : l’apaisement ne passe pas nécessairement par sa suppression.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"Le langage nous éloigne-t-il du réel ?","function":"Montrer une médiation qui transforme l’expérience","reason":"S’adresser à sa douleur la rend autrement présente : les mots peuvent transformer une expérience sans nier sa réalité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"collection":"Nouvelles Fleurs du Mal"},{"id":"baudelaire-boue-et-or","code":"B16","author":"Baudelaire","title":"Faire œuvre avec ce qui déplaît","work":"Ébauche d’un épilogue pour la deuxième édition des « Fleurs du Mal »","locator":"deux derniers vers · p. 214","quote":"Car j’ai de chaque chose extrait la quintessence,\nTu m’as donné ta boue et j’en ai fait de l’or.","notions":["art","nature"],"edition":"Les Fleurs du Mal et autres poèmes · préface d’Henri Lemaitre","publisher":"Garnier-Flammarion","editionYear":1964,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’art doit-il choisir une matière déjà belle pour produire de la beauté ?"},{"function":"L’affirmation","sentence":"Dans cette ébauche adressée à Paris, le poète affirme avoir changé la boue reçue en or."},{"function":"Les concepts","sentence":"La boue désigne une matière dépréciée, tandis que l’or figure la valeur que le travail poétique lui donne."},{"function":"La raison","sentence":"La création ne se borne donc pas à reproduire son objet : elle en extrait et en compose une forme nouvelle."},{"function":"L’exemple","sentence":"Une scène urbaine pénible peut devenir, par le rythme et les images, une expérience sensible qui donne à penser."},{"function":"La portée","sentence":"L’art peut ainsi transfigurer sa matière, sans rendre moralement bons les maux qu’il représente."}],"uses":[{"subject":"La laideur peut-elle intéresser l’artiste ?","function":"Distinguer la matière et la valeur de l’œuvre","reason":"La création peut donner une forme précieuse à une matière dépréciée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’art peut-il nous apprendre à voir le monde autrement ?","function":"Définir une transformation du regard","reason":"Une œuvre fait apparaître des rapports et une valeur que l’objet ne livrait pas au regard ordinaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"racine-pouvoir-et-peur","code":"R01","author":"Racine","title":"Faire peur et devoir tout craindre","work":"Britannicus","locator":"Acte IV, scène III","quote":"Craint de tout l'univers, il vous faudra tout craindre,\nToujours punir, toujours trembler dans vos projets,","notions":["etat","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir de faire peur délivre-t-il de la peur ?"},{"function":"L’affirmation","sentence":"Burrhus annonce que Néron, craint de tous, devra lui-même vivre dans une crainte continuelle."},{"function":"Les concepts","sentence":"Le retour de craindre inverse les positions du maître redouté et de celui qui se sent menacé."},{"function":"La raison","sentence":"La violence appelle des vengeurs et conduit à de nouvelles violences pour contenir les ennemis qu’elle produit."},{"function":"L’exemple","sentence":"Burrhus explique que le meurtre de Britannicus susciterait des défenseurs auxquels d’autres succéderaient."},{"function":"La portée","sentence":"La domination peut donc enfermer celui qui l’exerce, sans que cette conséquence dispense de juger aussi le tort fait à ses victimes."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Expliquer un enchaînement de violences","reason":"Un premier crime peut rendre nécessaires, aux yeux du tyran, de nouvelles répressions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer domination et liberté","reason":"Le tyran peut imposer sa volonté tout en devenant dépendant de la peur et des mesures nécessaires à la défense de son pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"speaker":"Burrhus","situation":"Burrhus avertit Néron que le meurtre de Britannicus l’enfermerait dans une suite de violences.","quoteSegments":["Craint de tout l'univers, il vous faudra tout craindre,"]},{"id":"racine-passion-et-destin","code":"R02","author":"Racine","title":"Se livrer à ce qui nous entraîne","work":"Andromaque","locator":"Acte I, scène I","quote":"Je me livre en aveugle au destin qui m’entraîne.","notions":["liberte","conscience"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une passion devient-elle un destin dès lors que nous ne réussissons pas à lui résister ?"},{"function":"L’affirmation","sentence":"Oreste présente son retour vers Hermione comme l’abandon d’une résistance devenue vaine."},{"function":"Les concepts","sentence":"Le destin nomme ce qui l’entraîne, mais le verbe se livrer conserve la trace de sa propre participation."},{"function":"La raison","sentence":"La réplique associe donc l’expérience d’une contrainte intérieure et le geste de céder à cette contrainte."},{"function":"L’exemple","sentence":"Oreste ne vient pas seulement subir une rencontre : il annonce qu’il cherchera à fléchir Hermione ou à l’enlever."},{"function":"La portée","sentence":"La passion peut ainsi être vécue comme une fatalité, sans que cette présentation suffise à abolir toute responsabilité dans les actes."}],"uses":[{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Distinguer subir un désir et s’y abandonner","reason":"Le verbe se livrer montre que le sujet participe à la passion qu’il présente comme une force extérieure.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"},{"subject":"Est-ce l’ignorance de ce que nous sommes qui fait la force de nos passions ?","function":"Limiter la suffisance de la lucidité","reason":"Un personnage peut reconnaître son attachement sans parvenir pour autant à lui résister.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=131","sourceLabel":"Recueil académique · p. 131"}],"speaker":"Oreste","situation":"Oreste explique à Pylade son retour auprès d’Hermione malgré ses efforts pour l’oublier."},{"id":"racine-amour-et-merite","code":"R03","author":"Racine","title":"Aimer au-delà des raisons d’aimer","work":"Andromaque","locator":"Acte IV, scène V","quote":"Je t’aimais inconstant, qu’aurais-je fait fidèle?","notions":["bonheur","raison"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’attachement amoureux se mesure-t-il aux qualités de la personne aimée ?"},{"function":"L’affirmation","sentence":"Hermione affirme avoir aimé Pyrrhus malgré son inconstance et imagine la force d’un amour récompensé par sa fidélité."},{"function":"Les concepts","sentence":"L’opposition entre inconstant et fidèle sépare la conduite réelle de l’être aimé et celle qu’elle attendait de lui."},{"function":"La raison","sentence":"L’amour peut persister lorsque les raisons de faire confiance à l’autre sont démenties par ses actes."},{"function":"L’exemple","sentence":"Hermione reproche à Pyrrhus son abandon tout en avouant qu’elle doute encore de ne plus l’aimer."},{"function":"La portée","sentence":"Le désir ne suit donc pas mécaniquement notre jugement sur l’autre, sans que sa persistance justifie d’accepter toute conduite."}],"uses":[{"subject":"Ne désirons-nous que les choses que nous estimons bonnes ?","function":"Distinguer l’attachement et le jugement","reason":"L’amour persiste alors même que la conduite de l’être aimé est condamnée : le jugement défavorable n’efface pas l’attachement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Préciser un conflit intérieur","reason":"Le jugement porté sur une personne peut entrer en conflit avec un attachement qui ne disparaît pas sur commande.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"}],"speaker":"Hermione","situation":"Hermione reproche à Pyrrhus de l’abandonner pour épouser Andromaque."},{"id":"racine-separation-et-avenir","code":"R04","author":"Racine","title":"Un avenir rendu sensible par l’absence","work":"Bérénice","locator":"Acte IV, scène 5","quote":"Dans un mois, dans un an, comment souffrirons-nous,\nSeigneur, que tant de mers me séparent de vous?","notions":["temps","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Un avenir encore absent peut-il déjà nous faire souffrir ?"},{"function":"L’affirmation","sentence":"Bérénice interroge Titus sur la manière dont ils supporteront leur séparation dans les mois et les années à venir."},{"function":"Les concepts","sentence":"La succession du mois et de l’an donne une durée à l’absence, tandis que les mers en font sentir la distance."},{"function":"La raison","sentence":"Imaginer le futur transporte ainsi dans le présent une douleur dont l’événement n’a pas encore eu lieu."},{"function":"L’exemple","sentence":"Bérénice prolonge sa question en évoquant des journées qui recommenceront sans qu’ils puissent se revoir."},{"function":"La portée","sentence":"Le temps vécu dépend donc aussi de l’anticipation, sans que l’image du malheur à venir en fixe définitivement l’expérience réelle."}],"uses":[{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer calendrier et absence vécue","reason":"Les mois et les années mesurent la séparation, mais ne décrivent pas la souffrance de ceux qui l’anticipent : la durée comptée ne suffit pas à rendre son expérience.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Examiner la souffrance anticipée","reason":"L’anticipation d’une perte peut troubler un bonheur encore présent ; cette fragilité ne démontre toutefois pas l’impossibilité de toute vie heureuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"speaker":"Bérénice","situation":"Bérénice fait éprouver à Titus la durée de leur séparation annoncée."},{"id":"racine-amour-et-domination","code":"R05","author":"Racine","title":"Prendre plaisir au pouvoir sur l’autre","work":"Britannicus","locator":"Acte II, scène II","quote":"J'aimais jusqu'à ses pleurs que je faisais couler.","notions":["liberte","devoir"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Tout plaisir éprouvé auprès d’un être aimé est-il un signe d’amour pour lui ?"},{"function":"L’affirmation","sentence":"Néron avoue aimer jusqu’aux pleurs de Junie dont il se sait la cause."},{"function":"Les concepts","sentence":"Le plaisir ne porte plus seulement sur sa présence, mais sur la manifestation de sa dépendance et de sa souffrance."},{"function":"La raison","sentence":"La situation fait apparaître une satisfaction de domination qui utilise l’autre au lieu de rechercher son bien."},{"function":"L’exemple","sentence":"Néron raconte à Narcisse avoir mêlé les soupirs et la menace dans le dialogue qu’il imaginait avec Junie."},{"function":"La portée","sentence":"Le nom d’amour peut donc couvrir une jouissance du pouvoir, sans que cette réplique autorise à identifier tout attachement à la cruauté."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer le plaisir et sa justification morale","reason":"La satisfaction de Néron prend pour objet la souffrance de Junie ; son plaisir ne suffit donc pas à rendre son bonheur souhaitable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Montrer la limite du bon plaisir","reason":"Le pouvoir de satisfaire son désir peut supprimer la liberté d’autrui ; la liberté de l’un ne se mesure pas à sa seule puissance d’agir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"speaker":"Néron","situation":"Néron raconte à Narcisse sa fascination pour Junie qu’il a fait enlever."},{"id":"racine-geste-et-mensonge","code":"R06","author":"Racine","title":"Un même geste, deux intentions","work":"Britannicus","locator":"Acte IV, scène III","quote":"J'embrasse mon rival, mais c'est pour l'étouffer.","notions":["verite","langage"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le sens d’un geste se lit-il immédiatement dans son apparence ?"},{"function":"L’affirmation","sentence":"Néron annonce qu’il emploiera le geste de l’embrassement pour préparer la destruction de son rival."},{"function":"Les concepts","sentence":"L’embrassade signifie ordinairement l’accord, mais le but avoué lui donne ici une fonction opposée."},{"function":"La raison","sentence":"La confiance produite par le signe peut ainsi devenir l’instrument qui empêche l’autre de se défendre."},{"function":"L’exemple","sentence":"La réconciliation annoncée à Britannicus doit masquer le projet que Néron confie à Burrhus."},{"function":"La portée","sentence":"Interpréter une action demande donc d’examiner son contexte et son intention, sans conclure que toute marque d’affection serait mensongère."}],"uses":[{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer le signe visible et l’intention","reason":"Le geste visible de l’embrassade peut masquer une intention meurtrière ; ce que l’on voit ne suffit donc pas à établir ce que l’autre veut faire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"Le langage trahit-il la pensée ?","function":"Étendre l’examen aux gestes qui signifient","reason":"Un signe de réconciliation peut produire une croyance destinée à cacher le projet véritable de celui qui l’emploie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"speaker":"Néron","situation":"Néron révèle à Burrhus que sa réconciliation avec Britannicus cache un projet meurtrier."},{"id":"racine-regner-et-vivre","code":"R07","author":"Racine","title":"La fonction publique et la vie personnelle","work":"Bérénice","locator":"Acte IV, scène 5","quote":"Mais il ne s'agit plus de vivre, il faut régner.","notions":["devoir","etat","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une fonction publique peut-elle exiger le sacrifice de ce qui donne sens à la vie personnelle ?"},{"function":"L’affirmation","sentence":"Titus oppose la nécessité de régner à la possibilité de vivre auprès de Bérénice."},{"function":"Les concepts","sentence":"Vivre désigne ici la vie affective qui lui est chère, tandis que régner renvoie à l’obligation politique qu’il revendique."},{"function":"La raison","sentence":"Son rôle d’empereur lui paraît imposer une décision que son amour refuse."},{"function":"L’exemple","sentence":"Il reconnaît la souffrance de la séparation au moment même où il l’annonce à Bérénice."},{"function":"La portée","sentence":"La réplique rend sensible un conflit entre devoir et bonheur, sans prouver que la nécessité invoquée par le souverain soit incontestable."}],"uses":[{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Faire apparaître le coût d’une obligation","reason":"La décision de Titus laisse entier le désir sacrifié : l’accomplissement d’un devoir peut entrer en conflit avec le bonheur personnel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"},{"subject":"L’État est-il, par définition, indifférent aux intérêts particuliers ?","function":"Examiner le conflit entre rôle et attachement","reason":"Une responsabilité publique peut être vécue comme une exigence opposée aux désirs de la personne qui l’exerce.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"speaker":"Titus","situation":"Titus explique à Bérénice pourquoi il renonce à leur union au nom de Rome."},{"id":"racine-aimer-et-quitter","code":"R08","author":"Racine","title":"Se séparer sans cesser d’aimer","work":"Bérénice","locator":"Acte V, scène dernière","quote":"Je l'aime, je le fuis; Titus m'aime, il me quitte.","notions":["liberte","devoir","bonheur"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La séparation prouve-t-elle que l’amour a disparu ?"},{"function":"L’affirmation","sentence":"Bérénice affirme que Titus et elle se quittent alors même qu’ils s’aiment encore."},{"function":"Les concepts","sentence":"Le parallélisme des deux propositions distingue la persistance du sentiment et la décision de renoncer à l’union."},{"function":"La raison","sentence":"L’action peut ainsi contredire le désir sans que celui-ci soit simplement effacé."},{"function":"L’exemple","sentence":"Bérénice transforme leur séparation en exemple douloureux et demande à Antiochus de poursuivre sa vie."},{"function":"La portée","sentence":"Aimer et choisir de partir peuvent donc coexister, sans faire de toute séparation la preuve d’un libre accord heureux."}],"uses":[{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer le désir et la conduite","reason":"Bérénice choisit de partir tout en aimant encore ; une décision peut donc répondre à une autre exigence que la satisfaction du souhait le plus vif.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Maintenir les deux exigences dans la décision","reason":"Un renoncement peut laisser entier l’attachement sacrifié, au lieu de résoudre le conflit par sa disparition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"speaker":"Bérénice","situation":"Bérénice annonce sa séparation d’avec Titus et exhorte Antiochus à vivre."},{"id":"racine-desir-et-fuite","code":"R09","author":"Racine","title":"Prolonger le péril que l’on fuit","work":"Mithridate","locator":"Acte II, scène VI","quote":"Plus je vous parle, et plus, trop faible que je suis,\nJe cherche à prolonger le péril que je fuis.","notions":["liberte","conscience","raison"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Savoir qu’une situation nous met en danger suffit-il à vouloir y mettre fin ?"},{"function":"L’affirmation","sentence":"Monime reconnaît que sa conversation avec Xipharès prolonge précisément le péril auquel elle veut échapper."},{"function":"Les concepts","sentence":"Le péril désigne ici le risque de céder à son amour et de trahir l’engagement qui la lie à Mithridate."},{"function":"La raison","sentence":"La lucidité accompagne donc le plaisir au lieu de l’abolir : parler encore permet de différer la séparation jugée nécessaire."},{"function":"L’exemple","sentence":"Monime finit pourtant par partir et demande à Xipharès de l’éviter."},{"function":"La portée","sentence":"Le sujet peut connaître sa contradiction et agir pour y résister, sans que le seul aveu de faiblesse garantisse la maîtrise de ses choix."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer lucidité et maîtrise","reason":"Reconnaître une passion ne suffit pas à interrompre les situations qui la nourrissent ; la lucidité demande encore un effort pratique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Montrer une raison présente dans le conflit","reason":"La conscience du risque peut coexister avec le plaisir de le prolonger : la raison n’est pas simplement absente du désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"}],"speaker":"Monime","situation":"Monime fait ses adieux à Xipharès pour rester fidèle à son engagement envers Mithridate."},{"id":"racine-oracle-et-interpretation","code":"R10","author":"Racine","title":"L’autorité d’une parole et son interprétation","work":"Iphigénie","locator":"Acte IV, scène IV","quote":"Un oracle dit-il tout ce qu'il semble dire?","notions":["religion","raison","langage"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Respecter une parole tenue pour sacrée impose-t-il d’accepter immédiatement le sens qu’on lui donne ?"},{"function":"L’affirmation","sentence":"Clytemnestre met en doute l’interprétation de l’oracle invoqué pour sacrifier Iphigénie."},{"function":"Les concepts","sentence":"Elle distingue ce que la parole semble dire et le sens qu’un examen pourrait faire apparaître."},{"function":"La raison","sentence":"L’autorité accordée à l’oracle ne supprime donc pas la responsabilité de ceux qui décident de son application."},{"function":"L’exemple","sentence":"La mère oppose à la lecture meurtrière la question d’un ciel juste qui demanderait le sang de l’innocence."},{"function":"La portée","sentence":"La croyance peut ainsi appeler un travail d’interprétation, sans que le doute garantisse à lui seul la lecture que nous préférons."}],"uses":[{"subject":"Croire, est-ce renoncer à la raison ?","function":"Distinguer croire et accepter une lecture sans examen","reason":"Reconnaître l’autorité d’un oracle ne supprime pas la nécessité d’en examiner le sens : la croyance n’abolit pas toute responsabilité de la raison.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on interpréter sans inventer ?","function":"Examiner la responsabilité de l’interprète","reason":"La gravité d’une décision oblige à discuter le sens d’une parole, sans autoriser des interprétations arbitraires.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=110","sourceLabel":"Recueil académique · p. 110"}],"speaker":"Clytemnestre","situation":"Clytemnestre conteste devant Agamemnon l’oracle invoqué pour sacrifier leur fille."},{"id":"racine-innocence-et-preuve","code":"R11","author":"Racine","title":"L’innocence vécue ne fait pas preuve","work":"Phèdre","locator":"Acte IV, scène 2","quote":"Le jour n’est pas plus pur que le fond de mon cœur.","notions":["justice","conscience","verite"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La certitude intime d’être innocent suffit-elle à convaincre celui qui nous accuse ?"},{"function":"L’affirmation","sentence":"Hippolyte affirme la pureté de son cœur en la comparant à la clarté du jour."},{"function":"Les concepts","sentence":"La lumière rend sensible une innocence qu’il éprouve, mais que son père ne peut pas directement voir."},{"function":"La raison","sentence":"L’écart entre l’assurance du fils et la défiance de Thésée montre la difficulté de communiquer une vérité sur soi."},{"function":"L’exemple","sentence":"Thésée prend même la rigueur morale d’Hippolyte pour un orgueil qui renforcerait sa culpabilité."},{"function":"La portée","sentence":"Une conviction intérieure peut donc être fondée sans constituer une preuve publique suffisante, ce qui oblige aussi l’accusateur à examiner ses préjugés."}],"uses":[{"subject":"Comment savoir ce qui est juste ?","function":"Distinguer le sentiment et l’établissement de l’innocence","reason":"La conscience du sujet doit être confrontée aux faits, sans présumer pour autant que le refus de le croire soit juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Hippolyte","situation":"Accusé par Œnone, Hippolyte affirme son innocence devant Thésée, qui ne le croit pas."},{"id":"racine-passion-et-corps","code":"R12","author":"Racine","title":"Le corps précède la maîtrise","work":"Phèdre","locator":"Acte I, scène 3","quote":"Je le vis, je rougis, je pâlis à sa vue;","notions":["conscience","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Sommes-nous maîtres de tout ce que notre corps manifeste ?"},{"function":"L’affirmation","sentence":"Phèdre raconte sa rencontre avec Hippolyte par une succession immédiate de réactions corporelles."},{"function":"Les concepts","sentence":"Voir, rougir et pâlir rapprochent la perception de l’autre et une émotion qui transforme le corps."},{"function":"La raison","sentence":"La rapidité des verbes fait éprouver un bouleversement qui n’attend pas une décision réfléchie."},{"function":"L’exemple","sentence":"Le récit permet ainsi à Phèdre de reconnaître après coup ce qu’elle a éprouvé lors de cette première rencontre."},{"function":"La portée","sentence":"La passion peut donc se manifester avant notre maîtrise consciente, sans que toute réaction involontaire détermine nécessairement nos actions futures."}],"uses":[{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Distinguer manifestation et compréhension du désir","reason":"Le corps manifeste un bouleversement avant que le sujet en ait reconnu la nature : éprouver une émotion ne signifie pas en connaître les raisons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Distinguer l’émotion reçue et la décision","reason":"Les réactions corporelles involontaires limitent la maîtrise immédiate de soi, mais ne fixent pas entièrement la conduite qui les suivra.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"}],"speaker":"Phèdre","situation":"Phèdre raconte à Œnone sa première rencontre avec Hippolyte."},{"id":"racine-conscience-et-justification","code":"R13","author":"Racine","title":"Se croire dans son devoir","work":"Athalie","locator":"Acte II, scène V","quote":"Ce que j’ai fait, Abner, j’ai cru le devoir faire.","notions":["conscience","devoir","justice"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Croire avoir accompli son devoir suffit-il à justifier ses actes ?"},{"function":"L’affirmation","sentence":"Athalie présente les violences de son règne comme des actions qu’elle croyait nécessaires."},{"function":"Les concepts","sentence":"La réplique affirme une conviction personnelle, mais n’établit pas encore la justice de ce qui a été fait."},{"function":"La raison","sentence":"Le sentiment du devoir peut devenir une manière de soustraire ses actes au jugement d’autrui."},{"function":"L’exemple","sentence":"Athalie déclare aussitôt qu’elle ne reconnaît pas le peuple comme juge de sa conduite."},{"function":"La portée","sentence":"La bonne conscience doit donc être distinguée de la justification morale, sans supposer qu’une conviction sincère serait toujours mensongère."}],"uses":[{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Distinguer conviction et justification","reason":"La sincérité de la conviction d’Athalie ne justifie pas encore ses actes ; leurs raisons et leurs effets doivent pouvoir être soumis au jugement d’autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Peut-on toujours savoir comment agir avec justice ?","function":"Examiner une certitude qui protège de l’examen","reason":"Une personne peut se croire fondée à agir tout en refusant les objections de ceux qui subissent ses décisions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Athalie","situation":"Athalie justifie devant Abner et Mathan les violences qui ont établi son pouvoir."},{"id":"racine-justice-et-surete","code":"R14","author":"Racine","title":"La sûreté contre la justice","work":"Athalie","locator":"Acte II, scène V","quote":"Est-ce aux rois à garder cette lente justice?\nLeur sûreté souvent dépend d’un prompt supplice.","notions":["etat","justice"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La sécurité du pouvoir autorise-t-elle à supprimer les garanties de la justice ?"},{"function":"L’affirmation","sentence":"Mathan oppose la lenteur de la justice à la rapidité du supplice qu’il recommande."},{"function":"Les concepts","sentence":"La sûreté désigne ici la protection du souverain, tandis que la justice suppose un examen qui retarde la sanction."},{"function":"La raison","sentence":"Présenter cette attente comme un danger permet de traiter le soupçon comme une raison suffisante de tuer."},{"function":"L’exemple","sentence":"Mathan propose ainsi de supprimer l’enfant caché dans le Temple avant que son identité soit pleinement établie."},{"function":"La portée","sentence":"La réplique expose une justification de la violence politique, sans constituer une approbation de cette justification par Racine."}],"uses":[{"subject":"L’État doit-il préférer l’injustice au désordre ?","function":"Mettre à l’épreuve l’argument de l’urgence","reason":"La sûreté du souverain ne justifie pas de transformer un soupçon en preuve ; supprimer l’examen du cas revient à sacrifier la justice à l’urgence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La justice met-elle fin à la loi du plus fort ?","function":"Examiner ce que la rapidité sacrifie","reason":"Raccourcir le jugement peut revenir à le remplacer par la volonté de celui qui dispose de la force.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Mathan","situation":"Mathan conseille à Athalie de supprimer l’enfant caché dans le Temple."},{"id":"racine-pouvoir-et-flatterie","code":"R15","author":"Racine","title":"Le pouvoir peut perdre le jugement","work":"Athalie","locator":"Acte IV, scène III","quote":"De l’absolu pouvoir vous ignorez l’ivresse,\nEt des lâches flatteurs la voix enchanteresse.","notions":["etat","verite","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Disposer d’un pouvoir sans obstacle rend-il plus capable de bien juger ?"},{"function":"L’affirmation","sentence":"Joad avertit Joas que le pouvoir absolu et les flatteries peuvent l’enivrer."},{"function":"Les concepts","sentence":"L’ivresse figure une perte de mesure, tandis que la voix enchanteresse des flatteurs rend cette perte agréable."},{"function":"La raison","sentence":"Celui qui peut tout entendre confirmer risque de confondre ses désirs avec ce qui est juste."},{"function":"L’exemple","sentence":"Joad annonce que des conseillers présenteront au jeune roi les lois comme des contraintes réservées au peuple."},{"function":"La portée","sentence":"Limiter le pouvoir et préserver la contradiction deviennent donc des conditions du jugement, sans garantir qu’un souverain conseillé soit toujours lucide."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Expliquer un mécanisme de démesure","reason":"La flatterie remplace les objections par la confirmation des désirs du roi ; elle affaiblit le jugement au moment où son pouvoir augmente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Toute vérité est-elle bonne à dire ?","function":"Montrer le besoin d’une parole qui résiste","reason":"Un dirigeant privé de paroles contradictoires perd les moyens de corriger ses erreurs ; la vérité qui déplaît peut protéger l’exercice du pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=72","sourceLabel":"Recueil académique · p. 72"}],"speaker":"Joad","situation":"Joad avertit le jeune Joas des dangers du pouvoir et des flatteurs."},{"id":"racine-naissance-et-consentement","code":"R16","author":"Racine","title":"Le titre suffit-il à légitimer le pouvoir ?","work":"La Thébaïde","locator":"Acte II, scène 3","quote":"Est-ce au peuple, Madame, à se choisir un maître?\nSitôt qu’il hait un roi, doit-on cesser de l’être?","notions":["etat","justice","liberte"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le droit de gouverner peut-il se passer de l’accord de ceux qui sont gouvernés ?"},{"function":"L’affirmation","sentence":"Polynice refuse de faire dépendre son titre royal du choix ou de l’hostilité du peuple."},{"function":"Les concepts","sentence":"Il oppose la légitimité qu’il tire de sa naissance à une volonté collective qu’il réduit au caprice."},{"function":"La raison","sentence":"Son raisonnement suppose que la possession du titre suffit à fonder l’obéissance, même lorsque les sujets le rejettent."},{"function":"L’exemple","sentence":"Jocaste lui objecte alors qu’un prince imposé à un peuple hostile risque de devenir un tyran."},{"function":"La portée","sentence":"Le passage permet donc d’interroger le fondement de l’autorité, sans confondre la prétention dynastique du personnage avec une démonstration de sa justice."}],"uses":[{"subject":"De quel droit l’État exerce-t-il un pouvoir ?","function":"Distinguer le titre et l’accord des gouvernés","reason":"L’origine dynastique d’un titre n’établit pas à elle seule que l’obéissance des gouvernés soit légitime.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Le pouvoir politique peut-il appartenir à ceux qui sont gouvernés ?","function":"Distinguer l’examen d’un jugement et le droit de choisir","reason":"Contester une décision collective ne suffit pas à démontrer que les gouvernés ne doivent avoir aucun choix.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"speaker":"Polynice","situation":"Polynice revendique son droit au trône malgré l’hostilité des Thébains."},{"id":"racine-justice-et-information","code":"R17","author":"Racine","title":"Un bon juge peut être trompé","work":"Esther","locator":"Acte III, scène dernière","quote":"On peut des plus grands rois surprendre la justice.","notions":["justice","verite","etat"],"edition":"Œuvres complètes et annexes (annotées)","publisher":"Arvensa Éditions","editionYear":2012,"originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"La volonté d’être juste suffit-elle à empêcher une décision injuste ?"},{"function":"L’affirmation","sentence":"Le chœur affirme qu’il est possible de tromper la justice même des plus grands rois."},{"function":"Les concepts","sentence":"Surprendre signifie ici abuser le jugement en lui présentant des raisons ou des faits trompeurs."},{"function":"La raison","sentence":"Une autorité bien intentionnée peut donc commettre l’injustice si elle dépend d’une information manipulée."},{"function":"L’exemple","sentence":"Dans la pièce, Aman a obtenu d’Assuérus une décision contre les Juifs en abusant de sa confiance."},{"function":"La portée","sentence":"La justice exige ainsi l’examen des témoignages et des intérêts qui les orientent, sans que la bonne intention dispense de cette vigilance."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Ajouter l’exigence d’une information examinée","reason":"Un jugement peut encore être faussé par les faits qu’on lui présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Peut-on toujours savoir comment agir avec justice ?","function":"Distinguer volonté et effet de la décision","reason":"Une autorité trompée peut vouloir le juste et produire l’injustice ; sa responsabilité comprend donc la vérification de ce qui lui est affirmé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Une Israélite du chœur","situation":"Après la chute d’Aman, le chœur médite sur les pièges tendus aux rois."},{"id":"corneille-liberte-dans-les-liens","code":"CO01","author":"Corneille","title":"Être libre jusque dans l’attachement","work":"La Place Royale","locator":"Acte I, scène IV","quote":"Je veux la liberté dans le milieu des fers.","speaker":"Alidor","situation":"Alidor explique à Cléandre pourquoi il veut rompre avec Angélique, qui l’aime.","notions":["liberte","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on aimer sans rien perdre de sa liberté ?"},{"function":"L’affirmation","sentence":"Alidor veut conserver, au sein même de l’attachement amoureux, une entière disposition de lui-même."},{"function":"Les concepts","sentence":"Les fers figurent le lien passionnel, tandis que la liberté désigne le pouvoir d’aimer et de cesser d’aimer à volonté."},{"function":"La raison","sentence":"Il exige ainsi que le sentiment dépende de sa décision, au lieu de découvrir une volonté déjà engagée par ce qu’elle aime."},{"function":"L’exemple","sentence":"Il prépare la rupture avec Angélique alors même qu’elle l’aime et qu’il reconnaît sa perfection."},{"function":"La portée","sentence":"La réplique interroge une liberté comprise comme absence de dépendance, sans justifier les violences commises pour la préserver."}],"uses":[{"subject":"L’indépendance suffit-elle à définir la liberté ?","function":"Éprouver une liberté sans attachement","reason":"En refusant tout lien qui pourrait le transformer, Alidor protège son indépendance mais compromet la relation dont il reconnaît pourtant la valeur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faut-il combattre les passions pour être libre ?","function":"Distinguer maîtrise et refus de l’attachement","reason":"La lutte contre un sentiment peut conduire à maltraiter la personne aimée : supprimer l’attachement ne suffit pas à rendre la conduite libre et juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-temps-et-promesse","code":"CO02","author":"Corneille","title":"Promettre malgré le changement","work":"La Place Royale","locator":"Acte I, scène IV","quote":"Du temps, qui change tout, les révolutions\nNe changent-elles pas nos résolutions ?","speaker":"Alidor","situation":"Alidor invoque le changement des sentiments pour refuser de se lier par le mariage.","notions":["temps","devoir","liberte"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Comment engager son avenir si nos sentiments peuvent changer ?"},{"function":"L’affirmation","sentence":"Alidor invoque les transformations du temps pour mettre en doute la permanence de nos résolutions."},{"function":"Les concepts","sentence":"Les révolutions désignent les changements qui nous affectent, et les résolutions les décisions par lesquelles nous prétendons orienter notre conduite."},{"function":"La raison","sentence":"Le retour sonore des deux mots rapproche ce qui nous arrive et ce que nous croyons décider durablement."},{"function":"L’exemple","sentence":"Alidor craint de demeurer marié lorsque la beauté ou son propre goût ne soutiendront plus son amour."},{"function":"La portée","sentence":"La promesse doit donc être pensée avec la possibilité du changement, sans conclure que toute fidélité serait impossible ou sans valeur."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer décision présente et maîtrise de l’avenir","reason":"Décider aujourd’hui ne garantit pas la permanence des sentiments qui motivent la décision.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"},{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Introduire la durée de l’engagement","reason":"Le changement possible des désirs oblige à penser ce qui soutient un engagement lorsque son attrait initial disparaît.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-trahison","code":"CO03","author":"Corneille","title":"Quand l’amour agit comme la haine","work":"La Place Royale","locator":"Acte IV, scène V","quote":"Si mon feu la trahit, que lui ferait ma haine ?","speaker":"Alidor","situation":"Alidor éprouve des remords après avoir organisé l’enlèvement d’Angélique au profit de son ami.","notions":["devoir","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le sentiment d’aimer garantit-il que nous agissions pour le bien de l’autre ?"},{"function":"L’affirmation","sentence":"Alidor s’étonne que son amour conduise à trahir Angélique comme pourrait le faire la haine."},{"function":"Les concepts","sentence":"Le feu désigne la passion amoureuse, dont les effets contredisent ici la bienveillance attendue."},{"function":"La raison","sentence":"Le rapprochement de l’amour et de la haine oblige à juger une conduite autrement que par le nom du sentiment invoqué."},{"function":"L’exemple","sentence":"Pour retrouver sa liberté, Alidor a favorisé l’enlèvement de celle qui lui demeure attachée."},{"function":"La portée","sentence":"La lucidité du remords met au jour une contradiction de l’action, sans suffire à réparer le mal ni à transformer immédiatement la conduite."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Examiner les actes derrière le sentiment","reason":"Aimer quelqu’un ne garantit pas le respect de ses intérêts : la bienveillance doit être jugée aussi par les actes qu’elle inspire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Évaluer une intention par ses effets","reason":"Le nom honorable donné à son sentiment ne dispense pas d’examiner la trahison qu’il accompagne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-victoire-et-merite","code":"CO04","author":"Corneille","title":"Ce que coûte une victoire","work":"Le Cid","locator":"Acte II, scène II","quote":"A vaincre sans péril, on triomphe sans gloire.","speaker":"Le Comte","situation":"Le Comte tente de dissuader Rodrigue de l’affronter en duel.","notions":["devoir","justice"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Toute victoire mérite-t-elle l’admiration ?"},{"function":"L’affirmation","sentence":"Le Comte affirme qu’une victoire sans danger n’apporte aucune gloire."},{"function":"Les concepts","sentence":"Vaincre désigne le résultat du combat, tandis que la gloire renvoie à la reconnaissance d’une valeur manifestée."},{"function":"La raison","sentence":"La difficulté compte donc dans l’appréciation de l’exploit : le seul succès ne dit pas encore ce que le vainqueur a accompli."},{"function":"L’exemple","sentence":"Le Comte croit qu’affronter le jeune Rodrigue serait pour lui un combat trop inégal."},{"function":"La portée","sentence":"Le vers distingue réussite et mérite, mais l’assurance du personnage rappelle qu’on peut aussi mal évaluer le danger et sa propre supériorité."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Prendre en compte l’inégalité des situations","reason":"Une même victoire peut exiger des efforts différents selon les forces initiales ; en tenir compte peut rendre le jugement plus impartial plutôt que favoriser arbitrairement un camp.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Une inégalité peut-elle être juste ?","function":"Évaluer une différence de mérite","reason":"Des victoires semblables peuvent exiger des efforts différents ; une reconnaissance inégale peut se justifier par cette différence de mérite.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-patrie-et-humanite","code":"CO05","author":"Corneille","title":"Garder l’humain dans le devoir","work":"Horace","locator":"Acte II, scène III","quote":"Je rends grâces aux Dieux de n'être pas Romain,\nPour conserver encore quelque chose d'humain.","speaker":"Curiace","situation":"Curiace refuse l’insensibilité d’Horace alors que leurs cités les obligent à se combattre.","notions":["devoir","etat"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le dévouement à la patrie exige-t-il de ne plus éprouver de compassion ?"},{"function":"L’affirmation","sentence":"Curiace préfère conserver une sensibilité humaine plutôt que d’adopter l’insensibilité présentée par Horace comme une vertu romaine."},{"function":"Les concepts","sentence":"Le rapprochement de Romain et d’humain oppose une identité politique à une exigence qui dépasse l’appartenance civique."},{"function":"La raison","sentence":"Il peut accepter son devoir tout en refusant de tenir la souffrance devant le meurtre d’un proche pour une faiblesse honteuse."},{"function":"L’exemple","sentence":"Désigné pour combattre Horace, il ne se dérobe pas, mais reconnaît l’horreur de leur affrontement."},{"function":"La portée","sentence":"La compassion peut ainsi accompagner le courage, sans que la seule émotion suffise à décider quel devoir doit l’emporter."}],"uses":[{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Interroger le contenu du devoir invoqué","reason":"L’appartenance politique ne suffit pas à rendre toute exigence juste : la compassion peut porter une objection au sacrifice demandé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Préserver la sensibilité dans l’action juste","reason":"Curiace accomplit son devoir sans étouffer sa compassion ; le renoncement au bonheur ne constitue donc pas toute la valeur morale de son acte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-pouvoir-et-maitrise-de-soi","code":"CO06","author":"Corneille","title":"La souveraineté sur sa colère","work":"Cinna","locator":"Acte V, scène III","quote":"Je suis maître de moi comme de l'univers ;","speaker":"Auguste","situation":"Auguste renonce à se venger des conjurés et leur accorde son pardon.","notions":["liberte","etat","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir sur les autres suffit-il à faire de nous les maîtres de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Auguste affirme sa maîtrise intérieure au moment de renoncer à la vengeance."},{"function":"Les concepts","sentence":"Le même mot de maître rapproche la souveraineté politique et le gouvernement de sa propre colère."},{"function":"La raison","sentence":"Pourtant, pouvoir punir et pouvoir retenir sa colère ne sont pas une seule puissance : le second exige de résister à une impulsion."},{"function":"L’exemple","sentence":"Auguste choisit le pardon alors que les conjurés lui ont donné des raisons de s’indigner."},{"function":"La portée","sentence":"La liberté apparaît dans la manière d’exercer son pouvoir, sans que cette proclamation efface les violences antérieures du souverain."}],"uses":[{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Distinguer toute-puissance et maîtrise de soi","reason":"Auguste dispose de la force nécessaire à la vengeance, mais exerce sa liberté en retenant sa colère plutôt qu’en la satisfaisant.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Examiner une retenue possible du pouvoir","reason":"Le pardon montre une limitation volontaire du pouvoir ; il ne remplace toutefois pas les garanties contre l’arbitraire d’un autre souverain.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-desir-et-attente","code":"CO07","author":"Corneille","title":"L’attente nourrit le désir","work":"Polyeucte","locator":"Acte I, scène I","quote":"Et le désir s'accroît quand l'effet se recule.","speaker":"Polyeucte","situation":"Polyeucte explique à Néarque que différer son baptême n’affaiblit pas son désir de le recevoir.","notions":["bonheur","temps"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"L’éloignement d’une satisfaction affaiblit-il nécessairement le désir ?"},{"function":"L’affirmation","sentence":"Polyeucte affirme que le report de son baptême accroît l’ardeur avec laquelle il le souhaite."},{"function":"Les concepts","sentence":"L’effet est ici l’accomplissement attendu, tandis que le désir demeure tourné vers ce qui n’a pas encore lieu."},{"function":"La raison","sentence":"La distance peut entretenir la représentation d’un bien et renforcer l’élan qui porte vers lui."},{"function":"L’exemple","sentence":"Néarque interprète au contraire ce délai comme le signe d’une ferveur qui risque de s’éteindre."},{"function":"La portée","sentence":"La scène oppose donc deux devenirs possibles de l’attente, sans établir que tout obstacle augmente toujours le désir."}],"uses":[{"subject":"Ne désirons-nous que ce qui nous manque ?","function":"Examiner le rôle de la distance","reason":"Le délai maintient l’objet désiré à venir et peut ainsi renforcer l’attachement ; le manque ne constitue pas seulement un vide que l’obtention ferait disparaître.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Interroger la valeur de l’attente","reason":"L’attente peut intensifier le désir, ce qui distingue le mouvement vers la satisfaction du contentement effectivement obtenu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-croire-et-voir","code":"CO08","author":"Corneille","title":"L’évidence vécue de la foi","work":"Polyeucte","locator":"Acte V, scène V","quote":"Je vois, je sais, je crois, je suis désabusée :","speaker":"Pauline","situation":"Après le supplice de Polyeucte, Pauline proclame devant Félix sa conversion au christianisme.","notions":["religion","verite","raison"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une conviction vécue comme une évidence vaut-elle une preuve pour tous ?"},{"function":"L’affirmation","sentence":"Pauline présente sa conversion comme une ouverture des yeux et une sortie de l’erreur."},{"function":"Les concepts","sentence":"Voir, savoir et croire s’enchaînent dans un même élan, sans que leurs différences soient examinées."},{"function":"La raison","sentence":"Le rythme de l’affirmation fait entendre une certitude intérieure dont la force ne constitue pas encore une démonstration partageable."},{"function":"L’exemple","sentence":"Le supplice de Polyeucte devient pour Pauline le signe qui transforme sa manière de comprendre sa vie."},{"function":"La portée","sentence":"Le vers permet de distinguer expérience de la foi et justification publique, sans réduire la conversion du personnage à une simple tromperie."}],"uses":[{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer voir un événement et lui donner un sens","reason":"L’événement perçu peut soutenir une croyance sans imposer à tous l’interprétation religieuse qu’en tire le personnage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer intensité et justification","reason":"La force de la conviction de Pauline ne fournit pas encore aux autres les raisons qui permettraient de la tenir pour vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-mensonge-et-memoire","code":"CO09","author":"Corneille","title":"La mémoire nécessaire au mensonge","work":"Le Menteur","locator":"Acte IV, scène V","quote":"Il faut bonne mémoire après qu'on a menti.","speaker":"Cliton","situation":"Cliton rappelle à Dorante la difficulté de maintenir la cohérence de ses inventions.","notions":["langage","verite","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Inventer librement une histoire nous dispense-t-il de toute contrainte ?"},{"function":"L’affirmation","sentence":"Cliton rappelle que mentir oblige à se souvenir de ce qu’on a déjà raconté."},{"function":"Les concepts","sentence":"La mémoire maintient la continuité entre plusieurs affirmations, même lorsqu’elles ne correspondent pas aux faits."},{"function":"La raison","sentence":"Chaque invention engage ainsi le menteur dans une histoire dont il doit ensuite préserver la cohérence."},{"function":"L’exemple","sentence":"Dorante répond qu’il compte sur son esprit pour réparer ses défauts de mémoire."},{"function":"La portée","sentence":"La cohérence peut donc être fabriquée au service du faux, sans que la vérité se reconnaisse toujours à un récit hésitant ou assuré."}],"uses":[{"subject":"La cohérence d’une pensée suffit-elle à garantir sa vérité ?","function":"Montrer une cohérence mensongère","reason":"Un récit inventé peut lui aussi rester cohérent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Le langage trahit-il la pensée ?","function":"Examiner la difficulté de la dissimulation","reason":"Le mensonge est voulu, mais les contradictions qui le révèlent peuvent échapper à son auteur ; le discours trahit alors ce qu’il cherchait à cacher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-scene-et-realite","code":"CO10","author":"Corneille","title":"Les ennemis sur scène, les amis après","work":"L’Illusion comique","locator":"Acte V, scène V","quote":"Le traître et le trahi, le mort et le vivant,\nSe trouvent à la fin amis comme devant.","speaker":"Alcandre","situation":"Alcandre révèle à Pridamant que la mort de son fils était une représentation théâtrale.","notions":["art","verite"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une émotion réelle exige-t-elle que l’événement représenté ait réellement eu lieu ?"},{"function":"L’affirmation","sentence":"Alcandre révèle que les ennemis montrés sur scène se retrouvent amis une fois la représentation achevée."},{"function":"Les concepts","sentence":"Le mort et le vivant désignent des rôles, tandis que les amis sont les acteurs qui les interprètent."},{"function":"La raison","sentence":"Le spectateur peut donc éprouver une douleur véritable devant une mort qui appartient à la fiction."},{"function":"L’exemple","sentence":"Pridamant a cru voir assassiner son fils avant de le découvrir partageant la recette avec ses compagnons."},{"function":"La portée","sentence":"La vérité de l’émotion se distingue de la réalité de l’événement, sans que toute illusion soit pour autant dépourvue d’effets ou de risques."}],"uses":[{"subject":"L’art est-il indifférent à la vérité ?","function":"Distinguer fiction et tromperie","reason":"Le spectacle produit une émotion réelle devant un événement fictif ; reconnaître son dispositif permet de distinguer ces deux réalités.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=10","sourceLabel":"Recueil académique · p. 10"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Examiner le plaisir d’une émotion douloureuse","reason":"Une représentation tragique peut produire de la peine et contribuer pourtant à l’expérience artistique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-cite-et-legitimite","code":"CO11","author":"Corneille","title":"Où demeure une cité ?","work":"Sertorius","locator":"Acte III, scène I","quote":"Rome n'est plus dans Rome, elle est toute où je suis.","speaker":"Sertorius","situation":"Sertorius oppose à Pompée la légitimité républicaine des Romains rassemblés autour de lui en exil.","notions":["etat","justice"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Une communauté politique se confond-elle avec le lieu où siège son pouvoir ?"},{"function":"L’affirmation","sentence":"Sertorius affirme que la vraie Rome demeure auprès des républicains qui l’accompagnent en exil."},{"function":"Les concepts","sentence":"Le premier nom de Rome désigne une communauté et ses principes, le second l’espace matériel de la ville."},{"function":"La raison","sentence":"La répétition du même mot rend sensible l’écart possible entre l’occupation d’un territoire et la fidélité à un ordre politique."},{"function":"L’exemple","sentence":"Sertorius oppose les soutiens réunis autour de lui aux proscriptions exercées sous l’autorité de Sylla."},{"function":"La portée","sentence":"Le vers permet d’interroger la légitimité au-delà du pouvoir établi, sans prouver que le personnage incarne à lui seul toute la cité."}],"uses":[{"subject":"De quel droit l’État exerce-t-il un pouvoir ?","function":"Distinguer possession et légitimité","reason":"L’occupation des institutions ne règle pas la question de savoir qui représente légitimement la communauté politique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"},{"subject":"Le pouvoir politique peut-il appartenir à ceux qui sont gouvernés ?","function":"Distinguer communauté et gouvernants","reason":"Les gouvernés peuvent opposer des principes communs au pouvoir établi ; leur communauté ne se réduit pas à l’obéissance aux détenteurs du pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-naissance-et-valeur","code":"CO12","author":"Corneille","title":"Ce que nous ne choisissons pas","work":"Othon","locator":"Acte II, scène II","quote":"Un pur hasard sans nous règle notre naissance ;","speaker":"Martian","situation":"L’affranchi Martian répond au mépris de Plautine pour son origine servile.","notions":["justice","liberte"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Ce qui nous a été donné sans choix peut-il mesurer notre valeur ?"},{"function":"L’affirmation","sentence":"Martian rappelle que notre naissance dépend d’un hasard auquel nous n’avons pas pris part."},{"function":"Les concepts","sentence":"La naissance désigne ici l’origine sociale, dont le personnage refuse de faire un mérite personnel."},{"function":"La raison","sentence":"Il oppose à cette condition reçue la valeur qu’il prétend avoir acquise par ses actions."},{"function":"L’exemple","sentence":"Ancien esclave, il répond au mépris de Plautine en faisant valoir sa puissance présente."},{"function":"La portée","sentence":"Le vers détache la dignité de l’origine, mais le contexte oblige aussi à distinguer mérite réel et réussite dans les intrigues du pouvoir."}],"uses":[{"subject":"Être juste, est-ce être neutre ?","function":"Distinguer origine et mérite","reason":"Ne pas compter la naissance comme un mérite préserve l’impartialité ; celle-ci ne demande pas d’ignorer les différences entre conditions reçues et actions accomplies.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Toutes les inégalités sont-elles des injustices ?","function":"Interroger la justification des rangs","reason":"Une différence de naissance ne fonde pas à elle seule un droit de dominer ; le fait d’une inégalité ne suffit pas à la justifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-devoir-et-desir","code":"CO13","author":"Corneille","title":"Ce que l’on se doit contre ce que l’on désire","work":"Pulchérie","locator":"Acte I, scène I","quote":"Ce qu'on se doit combat ce qu'on se veut donner :","speaker":"Pulchérie","situation":"Pulchérie explique à Léon le conflit entre leur amour et les exigences de son rang.","notions":["devoir","bonheur"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Tout ce que nous désirons nous paraît-il compatible avec l’idée que nous avons de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Pulchérie oppose les exigences de son rang au bonheur amoureux qu’elle voudrait s’accorder."},{"function":"Les concepts","sentence":"Ce qu’on se doit désigne une obligation revendiquée, tandis que se donner évoque la satisfaction consentie à son propre désir."},{"function":"La raison","sentence":"Le conflit traverse donc un même sujet, partagé entre son attachement et une dignité qu’il estime devoir préserver."},{"function":"L’exemple","sentence":"Pulchérie aime Léon mais refuse d’abord un mariage qui ne lui conserverait pas le rang impérial."},{"function":"La portée","sentence":"Le vers éclaire un désaccord du désir et du devoir, sans identifier automatiquement l’orgueil social à une exigence morale juste."}],"uses":[{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Faire apparaître le conflit intérieur","reason":"Le même sujet peut s’attacher à un désir et à une obligation qu’il ne parvient pas à satisfaire ensemble.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"},{"subject":"Faire son devoir sans être heureux, est-ce toute la morale ?","function":"Examiner le devoir que l’on s’impose","reason":"Le sacrifice d’un désir n’est pas nécessairement moral : l’obligation invoquée peut protéger un rang plutôt qu’une exigence de justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-duree-douloureuse","code":"CO14","author":"Corneille","title":"L’amour dans une mort qui dure","work":"Suréna","locator":"Acte I, scène III","quote":"Je veux, sans que la mort ose me secourir,\nToujours aimer, toujours souffrir, toujours mourir.","speaker":"Eurydice","situation":"Promise à Pacorus, Eurydice refuse que la mort abrège son amour douloureux pour Suréna.","notions":["temps","bonheur"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Peut-on vouloir prolonger une souffrance plutôt que renoncer à ce qui la fait naître ?"},{"function":"L’affirmation","sentence":"Eurydice souhaite continuer d’aimer et de souffrir sans que la mort interrompe cette fidélité."},{"function":"Les concepts","sentence":"Toujours mourir ne désigne pas des décès répétés, mais une douleur qui semble recommencer à chaque instant."},{"function":"La raison","sentence":"La reprise du même adverbe lie l’amour, la souffrance et la durée dans un mouvement sans repos."},{"function":"L’exemple","sentence":"Promise à Pacorus, Eurydice demande ensuite à Suréna de ne pas épouser Mandane."},{"function":"La portée","sentence":"Le passage montre un attachement dont la valeur ne se réduit pas au plaisir, sans faire de la souffrance une preuve nécessaire de l’amour."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Examiner le prix du renoncement","reason":"Un sujet peut refuser l’apaisement s’il lui paraît signifier l’abandon d’un attachement essentiel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Faire sentir une durée affective","reason":"La répétition de toujours fait sentir une douleur qui recommence ; la durée vécue ne se réduit pas au décompte des instants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-silence-et-aveu","code":"CO15","author":"Corneille","title":"Quand le silence révèle","work":"Suréna","locator":"Acte IV, scène IV","quote":"Le soin de le cacher découvre ce qu'il cache,\nEt son silence dit tout ce qu'il craint qu'on sache.","speaker":"Pacorus","situation":"Pacorus soupçonne l’amour secret de Suréna malgré les précautions prises pour le dissimuler.","notions":["langage","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Se taire suffit-il à garder un secret ?"},{"function":"L’affirmation","sentence":"Pacorus affirme que les précautions prises pour cacher un amour finissent par le révéler."},{"function":"Les concepts","sentence":"Le silence ne vaut plus absence de signe : il devient une conduite susceptible d’être interprétée."},{"function":"La raison","sentence":"Le souci de dissimuler modifie les gestes et les refus, qui peuvent attirer précisément l’attention que l’on voulait éviter."},{"function":"L’exemple","sentence":"Pacorus juge trop préparées les raisons par lesquelles Suréna refuse d’épouser Mandane."},{"function":"La portée","sentence":"Le langage déborde ainsi les paroles prononcées, sans que tout silence autorise une interprétation certaine ni une intrusion dans la vie d’autrui."}],"uses":[{"subject":"Le langage trahit-il la pensée ?","function":"Examiner les signes involontaires","reason":"Une précaution ou un silence peut exprimer ce que le sujet voulait taire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage n’est-il qu’un outil ?","function":"Interroger la maîtrise des signes","reason":"Le silence et les précautions deviennent des signes qui échappent au projet du locuteur ; le langage déborde ainsi son usage volontaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-service-et-ingratitude","code":"CO16","author":"Corneille","title":"Le bienfait qui devient une menace","work":"Suréna","locator":"Acte V, scène II","quote":"Plus on sert des ingrats, plus on s'en fait haïr :\nTout ce qu'on fait pour eux ne fait que nous trahir.","speaker":"Suréna","situation":"Suréna explique à Eurydice pourquoi ses services rendus au roi se retournent contre lui.","notions":["etat","devoir"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Rendre service assure-t-il la reconnaissance de celui qui en bénéficie ?"},{"function":"L’affirmation","sentence":"Suréna explique que ses services ont accru la haine du roi au lieu de lui garantir sa faveur."},{"function":"Les concepts","sentence":"Le service crée une dette, mais aussi la conscience d’une dépendance envers celui dont le mérite devient difficile à égaler."},{"function":"La raison","sentence":"Le souverain peut alors éprouver comme une humiliation ce qui devrait l’engager à la gratitude."},{"function":"L’exemple","sentence":"Suréna estime que sa gloire et les victoires qui ont soutenu le roi sont devenues son véritable crime."},{"function":"La portée","sentence":"La gratitude dépend donc du rapport au bienfaiteur, sans que cette situation permette de déclarer tout service vain ou toute reconnaissance impossible."}],"uses":[{"subject":"L’abus de pouvoir est-il inévitable ?","function":"Examiner la peur du mérite d’autrui","reason":"Un souverain peut transformer son besoin d’être aidé en désir d’abaisser celui dont il dépend.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-amour-et-contrainte","code":"CO17","author":"Corneille","title":"L’amour ne se commande pas","work":"Suréna","locator":"Acte IV, scène IV","quote":"Il hait tous les emplois où la force l'appelle :\nDès qu'on le violente, on en fait un rebelle ;","speaker":"Suréna","situation":"Suréna explique à Pacorus que l’amour ne peut obéir aux ordres du pouvoir.","notions":["liberte","etat"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le pouvoir de commander les actes donne-t-il celui de commander les sentiments ?"},{"function":"L’affirmation","sentence":"Suréna affirme que l’amour se révolte contre les tâches auxquelles la force veut l’employer."},{"function":"Les concepts","sentence":"La personnification fait de l’amour un sujet rebelle, distinct de l’obéissance qu’un souverain peut exiger."},{"function":"La raison","sentence":"La contrainte peut obtenir une conduite extérieure sans produire l’attachement qui lui donnerait un autre sens."},{"function":"L’exemple","sentence":"Pacorus exige que Suréna intervienne pour changer les sentiments d’Eurydice, alors qu’il ne maîtrise pas davantage les siens."},{"function":"La portée","sentence":"Le passage révèle une limite du commandement, sans faire de toute passion une liberté déjà réfléchie ni de tout refus un droit sans condition."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","function":"Distinguer conduite et adhésion","reason":"Un ordre peut contraindre une conduite extérieure, mais ne suffit pas à produire l’attachement demandé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"L’État est-il, par définition, indifférent aux intérêts particuliers ?","function":"Délimiter la prétention du pouvoir","reason":"Le projet politique devient intrusif lorsqu’il réclame non seulement des actes, mais la transformation des sentiments privés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"corneille-alliance-et-interet","code":"CO18","author":"Corneille","title":"L’allié et l’ennemi de l’ennemi","work":"Nicomède","locator":"Acte IV, scène V","quote":"Rome ne m'aime pas : elle hait Nicomède ;","speaker":"Attale","situation":"Attale reconnaît devant Flaminius que Rome le soutient pour affaiblir son frère Nicomède.","notions":["etat","conscience"],"edition":"Œuvres complètes · texte modernisé","publisher":"Arvensa Éditions","editionYear":"date non indiquée dans le volume","originalLanguage":"français","translator":null,"verse":true,"commentary":[{"function":"Le problème","sentence":"Le soutien d’une puissance prouve-t-il qu’elle recherche notre bien ?"},{"function":"L’affirmation","sentence":"Attale comprend que Rome le favorise pour affaiblir Nicomède plutôt que par attachement à sa personne."},{"function":"Les concepts","sentence":"L’opposition entre aimer et haïr sépare le bénéficiaire apparent de l’action et sa cible véritable."},{"function":"La raison","sentence":"Une aide peut donc servir celui qui la reçoit tout en restant subordonnée à un intérêt qui lui est extérieur."},{"function":"L’exemple","sentence":"Flaminius soutient les ambitions d’Attale, mais refuse qu’elles conduisent à l’union politique qui renforcerait le royaume."},{"function":"La portée","sentence":"La convergence provisoire des intérêts ne suffit pas à établir une fidélité, sans rendre pour autant toute coopération mensongère."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Distinguer aide et bienveillance","reason":"Le profit d’Attale reste un moyen de nuire à Nicomède ; favoriser autrui n’équivaut donc pas toujours à rechercher son bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La recherche du bonheur est-elle un idéal égoïste ?","function":"Examiner un avantage partagé sans désintéressement","reason":"Une convergence d’intérêts peut favoriser autrui sans que son bien soit recherché pour lui-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"editionNote":"Le volume indique une mise en français moderne par Charles Wincesky et prend pour référence les Œuvres de P. Corneille éditées par Charles Marty-Laveaux (Hachette, 1862). Les vers sont repris dans la forme du livre fourni."},{"id":"bachelard-lumiere-et-ombres","code":"BA01","author":"Bachelard","title":"La connaissance éclaire et laisse des ombres","quote":"La connaissance du réel est une lumière qui projette toujours quelque part des ombres.","locator":"Chapitre I, section I","notions":["science","verite","raison"],"commentary":[{"function":"Le problème","sentence":"Connaître un aspect du réel signifie-t-il dissiper toute obscurité ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que la connaissance éclaire tout en laissant subsister des zones d’ombre."},{"function":"Les concepts","sentence":"La lumière désigne une compréhension déterminée, tandis que l’ombre marque ses limites et les difficultés qu’elle peut masquer."},{"function":"La raison","sentence":"Un savoir acquis peut devenir un obstacle lorsqu’on le prend pour une explication complète et qu’on cesse de l’interroger."},{"function":"L’exemple","sentence":"Une généralisation utile peut ainsi empêcher de remarquer les phénomènes qui exigent de la modifier."},{"function":"La portée","sentence":"L’image invite à prolonger la recherche et à rectifier le savoir, sans conclure que toutes les connaissances seraient illusoires."}],"uses":[{"subject":"Faut-il attendre de la science qu’elle ait réponse à tout ?","function":"Limiter une attente de savoir total","reason":"Une connaissance fondée éclaire un problème déterminé, mais peut laisser des difficultés que son succès même rend moins visibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Les progrès de la connaissance nous rapprochent-ils d’une vérité définitive ?","function":"Interroger l’idée d’achèvement","reason":"Un progrès peut faire apparaître des limites nouvelles et appeler une nouvelle enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=72","sourceLabel":"Recueil académique · p. 72"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-question-et-connaissance","code":"BA02","author":"Bachelard","title":"Le savoir répond à un problème","quote":"Pour un esprit scientifique, toute connaissance est une réponse à une question.","locator":"Chapitre I, section I","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"Suffit-il d’accumuler des faits pour posséder un savoir ?"},{"function":"L’affirmation","sentence":"Bachelard rapporte la connaissance scientifique à la question qui lui donne son sens."},{"function":"Les concepts","sentence":"La question est ici un problème construit, et la réponse une proposition dont on peut comprendre la nécessité et les conditions."},{"function":"La raison","sentence":"Sans problème précis, un fait risque de rester une curiosité ou de confirmer une opinion déjà installée."},{"function":"L’exemple","sentence":"Demander comment varie une résistance électrique permet d’organiser des mesures plutôt que de collectionner des étincelles spectaculaires."},{"function":"La portée","sentence":"La recherche demande donc une activité de l’esprit, sans que cette construction dispense de contrôler expérimentalement la réponse."}],"uses":[{"subject":"Les faits parlent-ils d’eux-mêmes ?","function":"Établir la nécessité d’une question","reason":"Un fait ne devient instructif qu’à l’intérieur d’un problème qui précise ce qu’il permet de vérifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La connaissance scientifique progresse-t-elle par l’accumulation des observations ?","function":"Distinguer accumulation et recherche","reason":"Multiplier les observations ne remplace pas la formulation d’un problème et le choix des observations pertinentes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-formation-et-reforme","code":"BA03","author":"Bachelard","title":"Apprendre exige de se corriger","quote":"L'esprit scientifique doit se former en se réformant.","locator":"Chapitre II, section I","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"L’esprit devient-il scientifique en ajoutant simplement des connaissances à ce qu’il sait déjà ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que sa formation exige une transformation de ses façons de penser."},{"function":"Les concepts","sentence":"Se former signifie acquérir une capacité, tandis que se réformer implique de corriger des habitudes et des convictions antérieures."},{"function":"La raison","sentence":"Les premières explications ne sont pas seulement incomplètes, car elles peuvent empêcher de poser les questions utiles."},{"function":"L’exemple","sentence":"L’élève qui admire une expérience spectaculaire doit apprendre à isoler la relation précise qu’elle permet d’étudier."},{"function":"La portée","sentence":"La correction participe ainsi du progrès, sans faire de toute erreur une découverte ni de toute nouveauté une vérité."}],"uses":[{"subject":"L’erreur a-t-elle un rôle dans l’élaboration de la vérité ?","function":"Montrer une correction formatrice","reason":"L’analyse d’une erreur peut obliger à réformer la manière de poser un problème ; elle ne consiste pas seulement à remplacer un résultat faux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"La connaissance commune est-elle, pour la connaissance scientifique, un point d’appui ou un obstacle ?","function":"Décrire une transformation du savoir premier","reason":"Passer à une enquête scientifique peut exiger de réformer les évidences de l’expérience quotidienne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-concept-et-deformation","code":"BA04","author":"Bachelard","title":"Un concept fécond peut se transformer","quote":"En effet, d'après nous, la richesse d'un concept scientifique se mesure à sa puissance de déformation.","locator":"Chapitre III, section III","notions":["science","raison"],"commentary":[{"function":"Le problème","sentence":"Un concept est-il d’autant plus solide qu’il reste identique en toute circonstance ?"},{"function":"L’affirmation","sentence":"Bachelard mesure sa richesse à sa capacité de transformation."},{"function":"Les concepts","sentence":"La déformation désigne une modification réglée du concept pour intégrer des conditions nouvelles, et non une déformation arbitraire des faits."},{"function":"La raison","sentence":"Une définition trop rigide peut réunir des ressemblances apparentes tout en empêchant d’étudier les différences pertinentes."},{"function":"L’exemple","sentence":"L’étude de la fermentation progresse lorsqu’elle distingue les processus et leurs conditions, au lieu d’expliquer tout changement par un même mot."},{"function":"La portée","sentence":"La rigueur consiste donc aussi à rendre les concepts révisables, sans renoncer à leur précision."}],"uses":[{"subject":"Les vérités scientifiques sont-elles définitives ?","function":"Distinguer rigueur et immobilité","reason":"La transformation d’un concept peut accroître la précision du savoir au lieu de simplement le rendre incertain.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Une théorie scientifique doit-elle se prémunir contre toute critique ?","function":"Donner une fonction positive à la révision","reason":"Protéger un concept de toute modification peut diminuer sa capacité à rendre compte de nouveaux phénomènes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-concept-et-realisation","code":"BA05","author":"Bachelard","title":"La technique participe au concept scientifique","quote":"Un concept est devenu scientifique dans la proportion où il est devenu technique, où il est accompagné d'une technique de réalisation.","locator":"Chapitre III, section III","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"La technique intervient-elle seulement après que la science a produit ses connaissances ?"},{"function":"L’affirmation","sentence":"Bachelard lie le caractère scientifique d’un concept à une technique qui permet de le réaliser."},{"function":"Les concepts","sentence":"Réaliser signifie ici produire ou isoler un phénomène dans des conditions déterminées, pour éprouver ce que le concept affirme."},{"function":"La raison","sentence":"Les opérations techniques donnent aux distinctions théoriques une prise sur des phénomènes contrôlables."},{"function":"L’exemple","sentence":"Les procédés de stérilisation permettent ainsi de préciser les conditions de la fermentation et de distinguer ce qui la rend possible."},{"function":"La portée","sentence":"La technique peut donc contribuer à la construction du savoir, sans que toute recette efficace constitue déjà une science."}],"uses":[{"subject":"La technique n’est-elle qu’une application de la science ?","function":"Renverser une dépendance à sens unique","reason":"Certaines opérations techniques permettent de définir et de contrôler le phénomène dont la science forme le concept.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Le progrès scientifique est-il lié à l’évolution des techniques ?","function":"Expliquer une dépendance concrète","reason":"De nouvelles techniques permettent de produire et de contrôler des phénomènes qui donnent un contenu plus précis aux concepts scientifiques.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-metaphores-et-raison","code":"BA06","author":"Bachelard","title":"Une image séduisante peut arrêter la pensée","quote":"Qu'on le veuille ou non, les métaphores séduisent la raison.","locator":"Chapitre IV, section III","notions":["langage","raison","science"],"commentary":[{"function":"Le problème","sentence":"Une image qui rend un phénomène familier nous en donne-t-elle l’explication ?"},{"function":"L’affirmation","sentence":"Bachelard souligne le pouvoir de séduction des métaphores sur la raison elle-même."},{"function":"Les concepts","sentence":"La séduction produit une adhésion, tandis que l’explication doit établir des relations contrôlables."},{"function":"La raison","sentence":"En projetant les propriétés d’un objet connu sur un phénomène différent, une image peut faire croire que la question est résolue."},{"function":"L’exemple","sentence":"Comparer l’air à une éponge suggère qu’il absorbe des matières sans expliquer les conditions précises de cette absorption."},{"function":"La portée","sentence":"La critique vise l’image prise pour une preuve, sans supprimer la valeur poétique des métaphores ni leur usage pédagogique contrôlé."}],"uses":[{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","function":"Analyser une fausse explication","reason":"Une métaphore familière peut donner l’impression de comprendre et interrompre l’enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"},{"subject":"La démarche scientifique exclut-elle tout recours à l’imagination ?","function":"Distinguer suggestion et justification","reason":"Une image peut orienter la recherche si ses suggestions sont reprises et contrôlées par un travail conceptuel ; elle ne vaut pas à elle seule comme explication.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=59","sourceLabel":"Recueil académique · p. 59"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-passion-et-erreur","code":"BA07","author":"Bachelard","title":"Une passion vraie peut protéger une idée fausse","quote":"C'est alors la passion vraie qui forme obstacle à la rectification de l'idée fausse.","locator":"Chapitre VII, section III","notions":["verite","conscience","raison"],"commentary":[{"function":"Le problème","sentence":"La sincérité d’un sentiment garantit-elle la vérité du jugement qu’il soutient ?"},{"function":"L’affirmation","sentence":"Bachelard montre qu’une passion réellement éprouvée peut empêcher de corriger une idée fausse."},{"function":"Les concepts","sentence":"Vraie qualifie ici l’existence de la passion, non la justesse de la croyance qui lui est associée."},{"function":"La raison","sentence":"Le sujet peut prendre le réconfort qu’il ressent pour une preuve de la propriété qu’il attribue à un objet."},{"function":"L’exemple","sentence":"La joie de posséder de l’or a ainsi été confondue avec une prétendue efficacité médicale de cette matière."},{"function":"La portée","sentence":"Il faut donc distinguer authenticité affective et validation objective, sans nier la réalité de l’expérience vécue."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Distinguer force de conviction et preuve","reason":"Une conviction peut être intense parce qu’elle protège une satisfaction, plutôt que parce qu’elle est fondée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Suffit-il de connaître la vérité pour renoncer à ses préjugés ?","function":"Identifier une résistance affective","reason":"Un attachement peut survivre à l’objection parce que l’abandon de l’idée coûterait aussi une satisfaction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=75","sourceLabel":"Recueil académique · p. 75"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-mesure-et-reflexion","code":"BA08","author":"Bachelard","title":"Mesurer demande de penser","quote":"Il faut réfléchir pour mesurer et non pas mesurer pour réfléchir.","locator":"Chapitre XI, section II","notions":["science","raison","technique"],"commentary":[{"function":"Le problème","sentence":"Une mesure chiffrée est-elle objective du seul fait qu’elle donne un nombre ?"},{"function":"L’affirmation","sentence":"Bachelard subordonne la mesure à une réflexion préalable sur ses conditions."},{"function":"Les concepts","sentence":"Mesurer suppose de définir la grandeur pertinente, la méthode employée et le degré de précision accessible."},{"function":"La raison","sentence":"Des décimales supplémentaires ne donnent aucun savoir si elles dépassent la sensibilité de l’appareil ou la stabilité de l’objet."},{"function":"L’exemple","sentence":"Calculer très précisément le rayon d’un arbre à partir d’une circonférence approximative fabrique une exactitude illusoire."},{"function":"La portée","sentence":"L’objectivité demande donc une précision justifiée, sans confondre l’approximation maîtrisée avec une mesure négligente."}],"uses":[{"subject":"Une vérité scientifique peut-elle être approximative ?","function":"Justifier une approximation réglée","reason":"La précision d’une mesure dépend des limites reconnues de l’appareil ; accumuler des chiffres ne rend pas le résultat plus objectif.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"N’y a-t-il de science que de ce qui est mathématisable ?","function":"Préciser ce que signifie quantifier","reason":"La présence de nombres ne suffit pas : il faut établir ce qui est mesuré et avec quelle validité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-instrument-et-objectivite","code":"BA09","author":"Bachelard","title":"L’instrument transforme l’observation","quote":"La connaissance devient objective dans la proportion où elle devient instrumentale.","locator":"Chapitre XI, section III","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"L’instrument remplace-t-il simplement un sens humain moins précis ?"},{"function":"L’affirmation","sentence":"Bachelard lui attribue un rôle dans la constitution même de l’objectivité."},{"function":"Les concepts","sentence":"Une connaissance instrumentale repose sur un dispositif construit, étalonné et soumis à des contrôles."},{"function":"La raison","sentence":"L’appareil ne donne un résultat fiable que si ses conditions de fonctionnement sont définies et ses erreurs repérées."},{"function":"L’exemple","sentence":"Une bulle d’air oubliée dans un baromètre suffit à modifier sa hauteur et à fausser les comparaisons."},{"function":"La portée","sentence":"La technique rend donc l’observation contrôlable, sans assurer par sa seule présence la vérité de toute interprétation."}],"uses":[{"subject":"Peut-on dire que la connaissance scientifique consiste à substituer à la sensibilité de l’homme celle d’un instrument de mesure ?","function":"Dépasser l’idée d’un simple remplacement","reason":"L’instrument impose aussi une méthode, des conditions de comparaison et un contrôle des erreurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Le progrès scientifique est-il lié à l’évolution des techniques ?","function":"Montrer une condition de l’observation objective","reason":"La construction et le contrôle d’un instrument permettent de définir plus précisément un phénomène ; le progrès technique peut donc modifier le contenu même du savoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-resultats-et-demonstration","code":"BA10","author":"Bachelard","title":"Savoir les résultats ne suffit pas","quote":"Mais l'enseignement des résultats de la science n'est jamais un enseignement scientifique.","locator":"Chapitre XI, section VII","notions":["science","raison","verite"],"commentary":[{"function":"Le problème","sentence":"Connaître les conclusions d’une science suffit-il pour penser scientifiquement ?"},{"function":"L’affirmation","sentence":"Bachelard distingue la transmission des résultats et la formation à leur démarche de production."},{"function":"Les concepts","sentence":"Le résultat est une proposition retenue, tandis que l’enseignement scientifique rend compréhensibles les raisons qui l’établissent."},{"function":"La raison","sentence":"Sans ces raisons, l’élève risque de rattacher la formule apprise à des images ou à des explications personnelles erronées."},{"function":"L’exemple","sentence":"Retenir que l’orbite terrestre est une ellipse ne fait pas comprendre le rôle de ses foyers ni la loi du mouvement."},{"function":"La portée","sentence":"Apprendre une science demande donc de pouvoir reconstruire et discuter ses raisons, au-delà de la récitation de ses acquis."}],"uses":[{"subject":"Savoir, est-ce ne rien croire ?","function":"Distinguer savoir personnel et confiance reçue","reason":"Un résultat appris sur l’autorité d’un cours demeure insuffisamment compris tant que l’élève ne peut pas en reconstruire les raisons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Les résultats des sciences sont-ils indiscutables ?","function":"Réintroduire les raisons du résultat","reason":"Une conclusion ne devient pas scientifique en étant soustraite à l’explication et à l’examen.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-enseigner-et-apprendre","code":"BA11","author":"Bachelard","title":"Transmettre met le savoir à l’épreuve","quote":"Une instruction qu'on reçoit sans la transmettre forme des esprits sans dynamisme, sans autocritique.","locator":"Chapitre XII, section II","notions":["science","langage","raison"],"commentary":[{"function":"Le problème","sentence":"Recevoir une connaissance assure-t-il qu’on puisse en répondre par soi-même ?"},{"function":"L’affirmation","sentence":"Bachelard fait de la transmission un exercice qui développe l’activité et la critique de l’esprit."},{"function":"Les concepts","sentence":"Transmettre demande de rendre des raisons accessibles à autrui, et l’autocritique consiste à examiner ses propres insuffisances."},{"function":"La raison","sentence":"Les difficultés d’un interlocuteur obligent à reprendre ce qui paraissait évident et à préciser les étapes laissées implicites."},{"function":"L’exemple","sentence":"Un élève qui explique une démonstration à un camarade découvre parfois qu’il en connaissait la conclusion sans maîtriser un passage."},{"function":"La portée","sentence":"L’apprentissage gagne ainsi à devenir réciproque, sans réduire la vérité à l’accord du groupe ni dévaloriser tout travail solitaire."}],"uses":[{"subject":"A-t-on besoin des autres pour trouver la vérité ?","function":"Donner une fonction au contrôle réciproque","reason":"Expliquer à autrui peut révéler une difficulté et conduire à rectifier son propre raisonnement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=75","sourceLabel":"Recueil académique · p. 75"},{"subject":"Pourquoi échanger des idées ?","function":"Dépasser la simple circulation des opinions","reason":"L’échange met les raisons à l’épreuve des difficultés d’autrui et peut ainsi transformer ce que chacun croyait avoir compris.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-objet-et-transformation","code":"BA12","author":"Bachelard","title":"Connaître transforme celui qui connaît","quote":"Si l'objet m'instruit, il me modifie.","locator":"Chapitre XII, section II","notions":["science","conscience","raison"],"commentary":[{"function":"Le problème","sentence":"Connaître change-t-il seulement ce que nous savons du monde ?"},{"function":"L’affirmation","sentence":"Bachelard affirme que l’objet instruit en transformant aussi l’esprit qui l’étudie."},{"function":"Les concepts","sentence":"L’instruction n’est pas ici une simple information ajoutée, mais une modification de nos manières de comprendre."},{"function":"La raison","sentence":"Un phénomène qui résiste à nos prévisions oblige à réviser nos concepts et les attentes qui guidaient l’enquête."},{"function":"L’exemple","sentence":"La découverte d’un mouvement que le modèle prévu n’explique pas peut imposer de nouvelles relations mathématiques."},{"function":"La portée","sentence":"La connaissance possède ainsi une force formatrice, sans que le réel se réduise à ce que le sujet souhaite y trouver."}],"uses":[{"subject":"Avons-nous quelque chose à apprendre de nos erreurs ?","function":"Montrer une transformation du sujet","reason":"Une erreur analysée peut transformer les habitudes de pensée qui la produisaient : elle instruit lorsqu’elle conduit à reprendre la manière de connaître.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=76","sourceLabel":"Recueil académique · p. 76"},{"subject":"La science nous éloigne-t-elle de la réalité ?","function":"Distinguer rencontre et projection","reason":"Atteindre le réel peut demander de renoncer à nos représentations familières plutôt que de les retrouver partout.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"bachelard-maitre-et-contradiction","code":"BA13","author":"Bachelard","title":"Continuer une pensée en la contredisant","quote":"Dans l'œuvre de la science seulement on peut aimer ce qu'on détruit, on peut continuer le passé en le niant, on peut vénérer son maître en le contredisant.","locator":"Chapitre XII, section III","notions":["science","verite","raison","temps"],"commentary":[{"function":"Le problème","sentence":"Respecter un héritage intellectuel exige-t-il de le conserver intact ?"},{"function":"L’affirmation","sentence":"Bachelard présente la contradiction scientifique comme une manière de prolonger ce que l’on admire."},{"function":"Les concepts","sentence":"Détruire et nier désignent ici la critique de résultats ou de cadres explicatifs, tandis que continuer signifie reprendre leur exigence de recherche."},{"function":"La raison","sentence":"On peut rester fidèle à la démarche d’un maître précisément en refusant de transformer ses réponses en dogmes."},{"function":"L’exemple","sentence":"Une théorie nouvelle peut limiter la validité d’une théorie ancienne tout en expliquant pourquoi celle-ci réussissait dans certaines conditions."},{"function":"La portée","sentence":"La fidélité devient alors un travail critique, sans faire de toute rupture un progrès ni de cette formule une loi de toute activité humaine."}],"uses":[{"subject":"Y a-t-il contradiction entre la prétention des sciences à la vérité et le fait qu’elles ont une histoire ?","function":"Penser une continuité par rectification","reason":"La reprise critique du passé peut conserver ses problèmes et expliquer ses réussites en limitant ses prétentions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"},{"subject":"Peut-on remettre en question une vérité établie scientifiquement ?","function":"Distinguer critique et rejet arbitraire","reason":"Une contestation justifiée prolonge l’exigence scientifique d’un maître au lieu de la trahir par la récitation de ses conclusions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"}],"work":"La Formation de l’esprit scientifique","edition":"Édition numérique fournie, sans pagination","publisher":"J. Vrin","editionYear":"date de l’édition numérique non indiquée","originalLanguage":"français","translator":null,"editionNote":"Première publication en 1938 ; la mention 1934 du fichier est erronée. Le texte est repéré par chapitre et section."},{"id":"freud-souvenirs-remanies","code":"F01","author":"Freud","title":"Se souvenir, c’est aussi remanier","quote":"Nos souvenirs d’enfance ne nous montrent pas les premières années de la vie telles qu’elles étaient, mais telles qu’elles sont apparues au cours de périodes d’éveil ultérieures.","locator":"Conclusion du texte (1899)","notions":["temps","conscience","inconscient"],"commentary":[{"function":"Le problème","sentence":"Nos souvenirs nous donnent-ils un accès intact à ce que nous avons vécu ?"},{"function":"L’affirmation","sentence":"Freud soutient que les souvenirs d’enfance portent la marque de remaniements ultérieurs."},{"function":"Les concepts","sentence":"Le passé vécu se distingue de sa présentation psychique, qui peut être réorganisée par des désirs et des préoccupations plus tardifs."},{"function":"La raison","sentence":"Un détail conservé peut prendre sa force dans une situation postérieure et servir de substitut à un autre contenu."},{"function":"L’exemple","sentence":"Dans le souvenir de la prairie, les fleurs et le pain prennent sens lorsque Freud les rapproche des préoccupations ultérieures de son interlocuteur."},{"function":"La portée","sentence":"La mémoire devient ainsi un objet d’interprétation, sans que cela autorise à déclarer tout souvenir inventé."}],"uses":[{"subject":"Pourquoi cherchons-nous à connaître notre passé ?","function":"Distinguer souvenir et connaissance de soi","reason":"L’enquête sur le passé doit aussi examiner la manière dont le souvenir s’est constitué.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"La conscience de soi est-elle une connaissance ?","function":"Limiter l’évidence du souvenir","reason":"Un souvenir présent à la conscience peut demander une interprétation au lieu de fournir immédiatement la vérité du passé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"work":"Les souvenirs-écrans","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil."},{"id":"freud-repeter-sans-savoir","code":"F02","author":"Freud","title":"Le passé peut revenir dans l’action","quote":"Il ne le reproduit pas comme souvenir, mais comme acte, il le réitère, sans savoir bien entendu qu’il le répète.","locator":"L’agir dans la cure (1914)","notions":["inconscient","conscience","liberte","temps"],"commentary":[{"function":"Le problème","sentence":"Un passé oublié cesse-t-il pour autant d’agir dans le présent ?"},{"function":"L’affirmation","sentence":"Freud décrit un patient qui reproduit dans ses actes ce qu’il ne se remémore pas."},{"function":"Les concepts","sentence":"Le pronom renvoie au contenu oublié ou refoulé, et la répétition désigne son retour dans une conduite présente."},{"function":"La raison","sentence":"Le sujet peut donc éprouver comme une réaction actuelle ce qui reprend une ancienne manière d’entrer en relation."},{"function":"L’exemple","sentence":"Dans la cure, il peut se montrer méfiant envers l’analyste sans reconnaître le retour d’une défiance ancienne envers une figure d’autorité."},{"function":"La portée","sentence":"L’oubli ne suffit donc pas à libérer du passé, sans que toute conduite répétée prouve à elle seule un refoulement."}],"uses":[{"subject":"Pour se libérer du passé faut-il l’oublier ?","function":"Contester la suffisance de l’oubli","reason":"L’absence de souvenir conscient peut coexister avec la persistance d’une conduite héritée du passé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"L’inconscient pèse-t-il sur nous comme un destin ?","function":"Distinguer contrainte méconnue et fatalité","reason":"Reconnaître une répétition donne prise sur une détermination jusque-là subie ; son influence ne constitue donc pas nécessairement un destin irréversible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=28","sourceLabel":"Recueil académique · p. 28"}],"work":"Remémoration, répétition et perlaboration","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil."},{"id":"freud-modele-et-limites","code":"F03","author":"Freud","title":"Ce que le bloc magique ne peut pas reproduire","quote":"Le bloc magique ne peut pas non plus, il est vrai, « reproduire » l’écriture de l’intérieur une fois qu’elle a été effacée ;","locator":"Les limites du modèle (1925)","notions":["science","technique","raison"],"commentary":[{"function":"Le problème","sentence":"Un appareil qui ressemble à un fonctionnement psychique permet-il de l’expliquer entièrement ?"},{"function":"L’affirmation","sentence":"Freud distingue les traces conservées par le bloc magique et le rappel dont notre mémoire est capable."},{"function":"Les concepts","sentence":"Conserver une inscription signifie en garder la trace, tandis que se souvenir peut en faire revenir le contenu sans un nouvel apport extérieur."},{"function":"La raison","sentence":"La comparaison rend certaines relations intelligibles sans garantir que tous les fonctionnements se correspondent."},{"function":"L’exemple","sentence":"Le bloc magique associe une surface disponible pour de nouvelles inscriptions et des traces durables, mais ne reproduit pas par lui-même ces traces de manière vivante."},{"function":"La portée","sentence":"Un modèle doit donc être jugé aussi par ses limites, sans perdre pour autant toute valeur explicative."}],"uses":[{"subject":"L’imagination a-t-elle une place dans la connaissance scientifique ?","function":"Délimiter la valeur d’une analogie","reason":"Un modèle imaginé peut rendre un problème intelligible si l’on précise ce qu’il permet et ce qu’il ne reproduit pas.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=59","sourceLabel":"Recueil académique · p. 59"},{"subject":"Le vivant est-il un objet comme les autres ?","function":"Limiter la comparaison avec un appareil","reason":"Le bloc reproduit la conservation des traces mais non leur rappel vivant ; une fonction psychique ne se réduit donc pas aux propriétés de l’objet qui la modélise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=58","sourceLabel":"Recueil académique · p. 58"}],"work":"Note sur le « bloc magique »","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Olivier Mannoni","editionNote":"Traduction de 2019 ; référence au texte original, repris dans ce recueil.","situation":"Freud compare la mémoire à une tablette dont les inscriptions effacées restent tracées dans une couche de cire."},{"id":"freud-moi-et-inconscient","code":"F04","author":"Freud","title":"Le moi déborde la conscience","quote":"Il est certain qu’une grande part du moi est elle-même inconsciente, précisément ce que l’on peut nommer le noyau du moi ; le terme de préconscient ne recouvre qu’une petite partie du moi.","locator":"Chapitre III, passage sur la résistance (formulation remaniée en 1921)","notions":["inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Le moi coïncide-t-il avec ce dont le sujet a conscience ?"},{"function":"L’affirmation","sentence":"Freud affirme qu’une part importante du moi demeure elle-même inconsciente."},{"function":"Les concepts","sentence":"Le moi désigne une organisation psychique, tandis que conscient et préconscient qualifient des modes d’accès aux contenus psychiques."},{"function":"La raison","sentence":"Les défenses qui maintiennent certains contenus à distance peuvent agir sans être reconnues par celui qui les exerce."},{"function":"L’exemple","sentence":"Dans la cure, le patient peut résister à une association sans connaître le motif de cette résistance."},{"function":"La portée","sentence":"L’inconscient ne se réduit donc pas à un second personnage opposé au moi, et cette distinction demande une enquête au-delà de l’introspection immédiate."}],"uses":[{"subject":"L’hypothèse de l’inconscient psychique revient-elle à admettre un autre moi en moi ?","function":"Écarter le dédoublement en personnages","reason":"Une part du moi peut être inconsciente sans constituer un autre personnage : l’inconscient n’est pas un second sujet qui déciderait à notre place.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=29","sourceLabel":"Recueil académique · p. 29"},{"subject":"Peut-on parvenir à une complète conscience de soi ?","function":"Identifier une difficulté de l’introspection","reason":"Le sujet ne reconnaît pas immédiatement les mécanismes par lesquels il se défend contre certaines pensées.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"work":"Au-delà du principe de plaisir","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Jean Laplanche et J.-B. Pontalis","editionNote":"Extrait d’Au-delà du principe de plaisir, dans la traduction publiée chez Payot en 2010 et reprise dans ce recueil ; les trois premiers essais du recueil ont un autre traducteur."},{"id":"freud-jeu-et-deplaisir","code":"F05","author":"Freud","title":"Le jeu peut reprendre une expérience pénible","quote":"On observe aussi que le caractère déplaisant de l’expérience vécue ne la rend pas toujours inutilisable pour le jeu.","locator":"Chapitre II, le jeu de la bobine","notions":["inconscient","art","conscience"],"commentary":[{"function":"Le problème","sentence":"Jouer consiste-t-il seulement à reproduire des expériences agréables ?"},{"function":"L’affirmation","sentence":"Freud observe qu’une expérience pénible peut aussi fournir la matière d’un jeu."},{"function":"Les concepts","sentence":"Le déplaisir de ce qui a été subi se distingue du plaisir possible à le reprendre activement."},{"function":"La raison","sentence":"Le changement de position permet d’envisager un gain de maîtrise, même si cette interprétation ne suffit pas à trancher tous les cas."},{"function":"L’exemple","sentence":"L’enfant qui fait disparaître et revenir une bobine reprend ainsi la situation de l’absence maternelle en devenant l’auteur du mouvement."},{"function":"La portée","sentence":"Le jeu ne reflète donc pas seulement un plaisir passé, sans constituer à lui seul une preuve de pulsion de mort ni une guérison assurée."}],"uses":[{"subject":"Nos désirs s’expliquent-ils seulement par la recherche du plaisir ?","function":"Distinguer plaisir immédiat et reprise d’une épreuve","reason":"Reprendre activement un événement pénible peut procurer une maîtrise qui manquait lors de son déroulement ; le déplaisir initial n’exclut pas toute satisfaction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"L’art est-il un divertissement ?","function":"Proposer une comparaison avec le jeu","reason":"Une représentation peut intéresser par la reprise active d’une expérience pénible, et pas seulement par son agrément ; le jeu enfantin ne définit cependant pas toute œuvre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"work":"Au-delà du principe de plaisir","collection":"La Répétition : mémoire et compulsion","edition":"Petite Bibliothèque Payot","publisher":"Payot & Rivages","editionYear":"2019","translator":"Jean Laplanche et J.-B. Pontalis","editionNote":"Extrait d’Au-delà du principe de plaisir, dans la traduction publiée chez Payot en 2010 et reprise dans ce recueil ; les trois premiers essais du recueil ont un autre traducteur."},{"id":"freud-pulsion-et-objet","code":"F06","author":"Freud","title":"L’objet ne suffit pas à expliquer le désir","quote":"Il est probable que la pulsion sexuelle commence par être indépendante de son objet et que ce n’est pas non plus aux charmes de celui-ci qu’elle doit sa genèse.","locator":"Premier essai, « Déduction »","notions":["nature","inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Désirons-nous un objet uniquement parce qu’il possède des qualités attirantes ?"},{"function":"L’affirmation","sentence":"Freud avance que la pulsion sexuelle ne naît probablement pas de l’objet auquel elle s’attache."},{"function":"Les concepts","sentence":"La pulsion est une poussée, tandis que l’objet est ce par quoi elle cherche une satisfaction."},{"function":"La raison","sentence":"La diversité des attachements conduit à desserrer le lien apparemment naturel et nécessaire entre les deux."},{"function":"L’exemple","sentence":"Des personnes peuvent investir des objets différents, sans que les propriétés de ces objets suffisent à expliquer l’existence même de la poussée."},{"function":"La portée","sentence":"La proposition invite à examiner l’histoire des attachements, sans faire de tout désir un choix volontaire ni nier toute qualité des objets."}],"uses":[{"subject":"L’objet du désir en est-il la cause ?","function":"Distinguer poussée et objet d’attachement","reason":"La pulsion ne naît pas simplement des qualités de l’objet : l’histoire du sujet contribue à expliquer ce qui devient désirable pour lui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Les hommes savent-ils ce qu’ils désirent ?","function":"Séparer objet désigné et origine du désir","reason":"Nommer ce qu’on désire ne signifie pas connaître les processus qui nous y attachent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-amour-et-autorite","code":"F07","author":"Freud","title":"L’amour peut donner autorité","quote":"La crédulité de l’amour devient ainsi une source importante, sinon originaire, de l’autorité.","locator":"Premier essai, « Surestimation de l’objet sexuel »","notions":["raison","conscience","liberte"],"commentary":[{"function":"Le problème","sentence":"Accordons-nous toujours notre confiance à quelqu’un parce que ses jugements sont fondés ?"},{"function":"L’affirmation","sentence":"Freud montre que l’attachement amoureux peut devenir une source d’autorité."},{"function":"Les concepts","sentence":"La crédulité désigne une adhésion insuffisamment examinée, et l’autorité le pouvoir reconnu à la parole d’une personne."},{"function":"La raison","sentence":"La surestimation de l’être aimé peut s’étendre de ses qualités désirées à ses capacités intellectuelles et à ses opinions."},{"function":"L’exemple","sentence":"On peut ainsi accepter le jugement d’une personne admirée dans un domaine où aucune compétence ne lui est pourtant reconnue."},{"function":"La portée","sentence":"L’analyse éclaire une origine affective de l’obéissance, sans réduire toute autorité à l’amour ni toute confiance à la crédulité."}],"uses":[{"subject":"La certitude est-elle une garantie de vérité ?","function":"Examiner une adhésion affective","reason":"L’assurance reçue d’une personne aimée peut être confondue avec une raison de tenir son jugement pour vrai.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Le désir est-il aveugle ?","function":"Décrire une extension de l’idéalisation","reason":"L’attrait amoureux peut s’étendre aux opinions de l’être aimé ; l’intensité du désir favorise alors une confiance qui échappe à l’examen.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-pulsion-et-corps","code":"F08","author":"Freud","title":"Le psychisme ne se sépare pas simplement du corps","quote":"Pulsion est ainsi l’un des concepts de la démarcation entre le psychique et le corporel.","locator":"Premier essai, « Pulsions partielles et zones érogènes » (ajout de 1915)","notions":["nature","conscience","inconscient"],"commentary":[{"function":"Le problème","sentence":"Une poussée corporelle est-elle déjà une pensée, ou reste-t-elle étrangère au psychisme ?"},{"function":"L’affirmation","sentence":"Freud situe le concept de pulsion à la limite du corporel et du psychique."},{"function":"Les concepts","sentence":"La pulsion exprime dans la vie psychique une excitation interne continue du corps, plutôt que l’effet ponctuel d’un stimulus extérieur."},{"function":"La raison","sentence":"Un processus organique peut ainsi imposer une exigence au travail psychique sans être directement connu par la conscience."},{"function":"L’exemple","sentence":"Le besoin de satisfaction mobilise des représentations et des conduites, au lieu de rester une modification locale d’un organe."},{"function":"La portée","sentence":"Le concept oblige donc à articuler corps et vie psychique, sans réduire cette dernière à la conscience ni expliquer toutes ses opérations par la physiologie."}],"uses":[{"subject":"La notion d’inconscient psychique est-elle contradictoire ?","function":"Distinguer psychique et conscient","reason":"Une force peut participer à la vie psychique par ses représentations et ses effets sans être immédiatement consciente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=28","sourceLabel":"Recueil académique · p. 28"},{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Distinguer exigence et connaissance","reason":"Subir une poussée et en connaître les sources ou les objets ne constituent pas une même opération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-plaisir-et-relance","code":"F09","author":"Freud","title":"Le plaisir peut relancer le désir","quote":"Comment se fait-il que le plaisir ressenti suscite le besoin d’un plaisir plus grand ?","locator":"Troisième essai, « La tension sexuelle »","notions":["bonheur","raison","conscience"],"commentary":[{"function":"Le problème","sentence":"Le plaisir apaise-t-il nécessairement le besoin qui l’a fait rechercher ?"},{"function":"L’affirmation","sentence":"Freud demande pourquoi un plaisir peut au contraire susciter la recherche d’un plaisir accru."},{"function":"Les concepts","sentence":"Il distingue un plaisir qui stimule l’excitation et un plaisir de satisfaction qui met momentanément fin à la tension."},{"function":"La raison","sentence":"Une même expérience peut donc être agréable tout en faisant naître une exigence nouvelle."},{"function":"L’exemple","sentence":"Dans son analyse du plaisir préliminaire, une stimulation plaisante accroît l’excitation au lieu de l’éteindre."},{"function":"La portée","sentence":"Cette difficulté empêche d’identifier toute jouissance à un repos, sans établir que toute satisfaction humaine serait impossible."}],"uses":[{"subject":"Le désir nous condamne-t-il à l’insatisfaction ?","function":"Distinguer deux effets du plaisir","reason":"Un plaisir peut relancer la demande sans que tout plaisir ait nécessairement cet effet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Interroger la suffisance de la satisfaction ponctuelle","reason":"Un plaisir obtenu peut augmenter la demande au lieu de la clore ; sa satisfaction ponctuelle ne garantit donc pas un contentement durable.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-trouvaille-et-retrouvaille","code":"F10","author":"Freud","title":"Le nouveau porte la trace d’un ancien bonheur","quote":"La trouvaille d’objet est proprement une re-trouvaille.","locator":"Troisième essai, « La trouvaille d’objet »","notions":["temps","inconscient","conscience"],"commentary":[{"function":"Le problème","sentence":"Le premier objet d’un amour est-il entièrement nouveau pour celui qui le désire ?"},{"function":"L’affirmation","sentence":"Freud soutient que la trouvaille d’un objet reprend le modèle d’une satisfaction antérieure."},{"function":"Les concepts","sentence":"La retrouvaille désigne une relation à des traces psychiques, et non le retour nécessaire de la même personne."},{"function":"La raison","sentence":"L’attachement nouveau peut être orienté par les premières expériences de soin et de satisfaction, même lorsque celles-ci ne sont pas remémorées."},{"function":"L’exemple","sentence":"Freud prend pour modèle la satisfaction initiale de l’enfant nourri au sein et les relations qui se construisent dans son prolongement."},{"function":"La portée","sentence":"Aimer engage ainsi une histoire, sans condamner chacun à reproduire à l’identique ses attachements infantiles."}],"uses":[{"subject":"Mon passé détermine-t-il mon avenir ?","function":"Distinguer modèle et fatalité","reason":"Les attachements présents reprennent des traces du passé sans devoir les reproduire à l’identique : une influence n’est pas un scénario entièrement fixé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=67","sourceLabel":"Recueil académique · p. 67"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-beaute-et-desir","code":"F11","author":"Freud","title":"Le beau et le désir peuvent avoir une histoire commune","quote":"Il me semble indubitable que le concept de « beau » s’enracine dans le terreau de l’excitation sexuelle et signifie originairement ce qui est sexuellement stimulant (« die Reize »).","locator":"Premier essai, « Palper et regarder », note 27 (ajout de 1915)","notions":["art","nature","conscience"],"commentary":[{"function":"Le problème","sentence":"Le jugement de beauté peut-il être compris sans examiner ses liens avec le désir ?"},{"function":"L’affirmation","sentence":"Freud propose de chercher une origine du beau dans l’excitation sexuelle."},{"function":"Les concepts","sentence":"S’enraciner désigne une genèse, tandis que signifier originairement ne revient pas à définir tous les usages ultérieurs du mot."},{"function":"La raison","sentence":"Une recherche sur la provenance d’un intérêt esthétique se distingue de l’affirmation que tout jugement de goût viserait une satisfaction sexuelle immédiate."},{"function":"L’exemple","sentence":"Dans la même note, Freud souligne que les organes les plus excitants ne sont pas nécessairement jugés beaux."},{"function":"La portée","sentence":"L’hypothèse ouvre donc une enquête sur les transformations du désir, sans suffire à réduire toute beauté à l’agrément sensuel."}],"uses":[{"subject":"Pourquoi sommes-nous sensibles à la beauté ?","function":"Proposer une hypothèse sur l’origine de l’intérêt esthétique","reason":"Une hypothèse sur l’origine pulsionnelle du beau n’établit pas encore la valeur ni le sens de chaque expérience esthétique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Distinguer origine et finalité","reason":"L’intérêt pour le beau peut s’enraciner dans le désir sans que la recherche d’un plaisir immédiat définisse la fin de toute œuvre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée."},{"id":"freud-parole-et-presence","code":"F12","author":"Freud","title":"Une voix rend le proche présent","quote":"Ça ne fait rien, répondit l’enfant, quand quelqu’un parle, il fait jour.","locator":"Troisième essai, « Angoisse infantile », note 17","notions":["langage","conscience"],"commentary":[{"function":"Le problème","sentence":"Une parole agit-elle seulement par les informations qu’elle transmet ?"},{"function":"L’affirmation","sentence":"Freud rapporte la réponse d’un enfant que la voix de sa tante rassure dans l’obscurité."},{"function":"Les concepts","sentence":"Le jour désigne ici une présence ressentie, et non un changement de l’éclairage matériel."},{"function":"La raison","sentence":"Entendre une personne aimée peut modifier la situation vécue en donnant un signe sensible que l’on n’est pas seul."},{"function":"L’exemple","sentence":"L’enfant demande à sa tante de parler alors même qu’il sait qu’il ne pourra pas la voir."},{"function":"La portée","sentence":"Cette scène éclaire la portée relationnelle de la parole, sans prouver qu’elle suffise à dissiper toute peur."}],"uses":[{"subject":"La parole a-t-elle le pouvoir de changer les choses ?","function":"Distinguer situation matérielle et expérience vécue","reason":"Une voix peut modifier le sentiment de solitude sans transformer la lumière ni les objets présents.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Le langage ne sert-il qu’à communiquer ?","function":"Préciser ce qui se joue dans la parole","reason":"La parole donne aussi un signe de présence qui transforme le sentiment de solitude ; sa portée dépasse la seule transmission d’informations.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"Trois essais sur la théorie sexuelle","edition":"Champs · traduction de Fernand Cambon (2011)","publisher":"Flammarion","editionYear":"2019","translator":"Fernand Cambon","editionNote":"Texte de 1905, remanié jusqu’en 1924 ; traduction de la version de 1924. Les pages du PDF ne sont pas celles de l’édition imprimée.","speaker":"Un garçon de trois ans","situation":"Freud rapporte les paroles d’un enfant qui demande à sa tante de le rassurer en parlant dans le noir."},{"id":"simondon-culture-et-rencontre","code":"SI01","author":"Simondon","title":"La culture rapproche des vies éloignées","quote":"Car la culture est le seul moyen que nous ayons de participer à la vie des temps révolus et des sociétés étrangères de manière à les rendre moins révolus et moins étrangères.","locator":"« Humanisme culturel, humanisme négatif, humanisme nouveau » (1953)","notions":["raison","temps"],"commentary":[{"function":"Le problème","sentence":"La différence des époques et des coutumes condamne-t-elle les hommes à rester étrangers les uns aux autres ?"},{"function":"L’affirmation","sentence":"Simondon affirme que la culture permet de participer à des vies éloignées de la nôtre."},{"function":"Les concepts","sentence":"Participer signifie ici comprendre une expérience humaine, sans avoir à adopter toutes ses croyances."},{"function":"La raison","sentence":"Les œuvres et les savoirs transmis rendent accessibles des façons de vivre que notre seule expérience ne nous ferait pas rencontrer."},{"function":"L’exemple","sentence":"Lire une tragédie antique permet ainsi de reconnaître une épreuve humaine dans un monde très différent du nôtre."},{"function":"La portée","sentence":"La culture ouvre donc une possibilité de rapprochement, dont la réalisation exige un effort de compréhension."}],"uses":[{"subject":"La culture sépare-t-elle ou rapproche-t-elle les hommes ?","function":"Construire la possibilité du rapprochement","reason":"La différence culturelle peut devenir l’occasion de comprendre une autre expérience humaine plutôt qu’un obstacle définitif.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=85","sourceLabel":"Recueil académique · p. 85"},{"subject":"La culture libère-t-elle des préjugés ?","function":"Préciser une condition de la libération","reason":"Rencontrer des vies éloignées peut défaire la croyance selon laquelle nos propres usages seraient la seule mesure de l’humanité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=84","sourceLabel":"Recueil académique · p. 84"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-langage-perfectible","code":"SI02","author":"Simondon","title":"Le langage reste à inventer","quote":"Pour démystifier le langage, il faut le montrer inachevé, perfectible, en voie de constitution.","locator":"« Les encyclopédies et l’esprit encyclopédique » (vers 1950)","notions":["langage","raison"],"commentary":[{"function":"Le problème","sentence":"Les mots imposent-ils à la pensée un cadre définitivement fixé ?"},{"function":"L’affirmation","sentence":"Simondon invite à comprendre le langage comme une œuvre humaine encore perfectible."},{"function":"Les concepts","sentence":"Démystifier consiste à retirer aux mots leur apparence de réalités immuables et mystérieuses."},{"function":"La raison","sentence":"Retrouver leur histoire et les inventions de sens qu’ils conservent permet de les examiner et de les transformer."},{"function":"L’exemple","sentence":"Préciser le sens du mot liberté dans une discussion peut ainsi défaire une opposition qui semblait insurmontable."},{"function":"La portée","sentence":"Le langage peut être travaillé par la pensée, même si cette pensée doit partir de mots déjà disponibles."}],"uses":[{"subject":"Le langage trahit-il la pensée ?","function":"Dépasser la plainte contre les mots","reason":"Les limites du vocabulaire appellent un travail de précision et d’invention plutôt qu’un abandon du langage.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage détermine-t-il notre rapport au réel ?","function":"Limiter le caractère définitif de la détermination","reason":"Les mots orientent notre compréhension, mais leur histoire et leur caractère inachevé permettent à la pensée d’en reprendre le sens.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-technique-et-invention","code":"SI03","author":"Simondon","title":"La technique possède sa pensée propre","quote":"C’est refuser de comprendre la nature de l’être technique que de le considérer comme un sous-produit de la pensée scientifique ou un instrument au service des fins morales.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["technique","science","devoir"],"commentary":[{"function":"Le problème","sentence":"Comprend-on une machine en connaissant seulement les lois qu’elle applique ou le but qu’elle sert ?"},{"function":"L’affirmation","sentence":"Simondon refuse de réduire l’être technique à l’application d’un savoir ou à un simple moyen."},{"function":"Les concepts","sentence":"L’être technique est ici un fonctionnement organisé qui relie des contraintes naturelles à des possibilités d’action."},{"function":"La raison","sentence":"Son invention exige de rendre compatibles plusieurs nécessités que la connaissance séparée des lois ne réunit pas encore."},{"function":"L’exemple","sentence":"Concevoir un moteur suppose ainsi d’organiser ensemble combustion, refroidissement et transmission du mouvement."},{"function":"La portée","sentence":"Cette autonomie de l’invention oblige à comprendre les techniques, sans les soustraire à la responsabilité morale."}],"uses":[{"subject":"La technique n’est-elle qu’une application de la science ?","function":"Contester la réduction à la science appliquée","reason":"Connaître séparément des lois ne donne pas encore le fonctionnement qui les fait agir ensemble : l’invention technique possède un travail propre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"La technique est-elle moralement neutre ?","function":"Distinguer compréhension technique et évaluation morale","reason":"Un objet technique possède une organisation propre qui ne se réduit pas aux intentions de son utilisateur ; comprendre cette organisation n’exonère pas de juger les fins qu’il permet de servir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=63","sourceLabel":"Recueil académique · p. 63"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-liberte-et-relation","code":"SI04","author":"Simondon","title":"Agir librement entre soi et les autres","quote":"Un pur individualisme ou un pur sociologisme font évanouir la liberté de l’acte.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["liberte","devoir"],"commentary":[{"function":"Le problème","sentence":"La liberté vient-elle seulement de l’individu ou des règles de la société ?"},{"function":"L’affirmation","sentence":"Simondon refuse d’expliquer l’acte libre exclusivement par l’un de ces deux termes."},{"function":"Les concepts","sentence":"L’individualisme isole les exigences personnelles, tandis que le sociologisme ramène l’action aux déterminations sociales."},{"function":"La raison","sentence":"L’acte libre invente une manière de rendre compatibles des exigences que les règles déjà établies ne suffisaient pas à accorder."},{"function":"L’exemple","sentence":"Dans un travail commun, proposer une nouvelle répartition des tâches peut concilier initiative personnelle et engagements collectifs."},{"function":"La portée","sentence":"La liberté se pense ainsi comme une invention dans la relation, dont la valeur reste à justifier."}],"uses":[{"subject":"Les hommes peuvent-ils s’associer sans renoncer à leur liberté ?","function":"Chercher une liberté dans l’action commune","reason":"Une association peut permettre l’invention de rapports nouveaux plutôt que la seule soumission à des règles déjà fixées.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"La vie en société favorise-elle la liberté ?","function":"Distinguer cadre social et initiative","reason":"Une initiative peut transformer les relations sociales qu’elle reçoit ; la vie collective n’est donc ni la cause suffisante ni l’ennemie nécessaire de la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-juger-et-reparer","code":"SI05","author":"Simondon","title":"Le jugement moral engage un geste","quote":"Le vrai jugement moral, comme le vrai jugement technique, est inadéquat s’il vise à être une pure expertise : il ne peut se dissocier du début du geste réparateur.","locator":"« L’ordre des objets techniques comme paradigme d’universalité axiologique dans la relation interhumaine » (vers 1956)","notions":["justice","devoir"],"commentary":[{"function":"Le problème","sentence":"Juger moralement consiste-t-il seulement à établir un diagnostic sur une personne ou sur son acte ?"},{"function":"L’affirmation","sentence":"Simondon affirme qu’un jugement moral adéquat doit amorcer une réparation."},{"function":"Les concepts","sentence":"La pure expertise désigne ici une évaluation qui constate et classe sans commencer à transformer la situation."},{"function":"La raison","sentence":"La comparaison avec la technique invite à chercher comment rendre possible un fonctionnement meilleur plutôt qu’à fixer une identité définitive."},{"function":"L’exemple","sentence":"Reconnaître une faute dans un groupe peut ainsi conduire à réparer le dommage et à modifier l’organisation qui l’a favorisée."},{"function":"La portée","sentence":"Cette exigence élargit le jugement à la responsabilité pratique, sans effacer la faute ni remplacer les procédures judiciaires."}],"uses":[{"subject":"Un homme peut-il en juger un autre ?","function":"Proposer une condition du jugement moral","reason":"Un jugement peut engager une possibilité de réparation au lieu de fixer une personne dans l’identité de sa faute.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=32","sourceLabel":"Recueil académique · p. 32"},{"subject":"Pourquoi demander justice ?","function":"Élargir la demande au-delà du constat","reason":"La demande de justice peut viser la réparation du tort et pas seulement sa qualification ; cette exigence morale ne définit pas à elle seule les procédures judiciaires.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"work":"Sur la philosophie (1950–1980)","edition":"Édition établie par Nathalie Simondon et Irlande Saurin","publisher":"Presses universitaires de France","editionYear":"2016","translator":null,"originalLanguage":"français","editionNote":"Recueil de textes rédigés entre 1950 et 1980 ; la date du texte cité est précisée dans la référence."},{"id":"simondon-matiere-et-forme","code":"SI06","author":"Simondon","title":"La matière contribue à la forme","quote":"La qualité de la matière est source de forme, élément de forme que l’opération technique fait changer d’échelle.","locator":"Première partie, chap. I « Forme et matière », I, 1, p. 39","notions":["travail","technique","nature"],"commentary":[{"function":"Le problème","sentence":"Travailler une matière consiste-t-il à lui imposer une forme qu’elle ne possède aucunement ?"},{"function":"L’affirmation","sentence":"Simondon soutient que les propriétés de la matière contribuent à la forme obtenue."},{"function":"Les concepts","sentence":"La qualité désigne ici des propriétés physiques, et l’opération technique le travail concret qui les met en œuvre."},{"function":"La raison","sentence":"Le moule ne suffit pas à produire une brique : l’argile doit pouvoir se déformer puis conserver le contour reçu."},{"function":"L’exemple","sentence":"L’artisan prépare donc la terre en la broyant, en la mouillant et en la pétrissant."},{"function":"La portée","sentence":"Le travail apparaît ainsi comme une mise en œuvre de possibilités naturelles, qui exige aussi de connaître leurs limites."}],"uses":[{"subject":"Le travail n’est-il qu’une lutte avec la nature ?","function":"Contester la seule logique de la lutte","reason":"L’efficacité du travail vient aussi de propriétés naturelles dont l’artisan apprend à se servir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"},{"subject":"Travailler, est-ce seulement mettre en œuvre une technique ?","function":"Éclairer l’intelligence de la situation concrète","reason":"Le travail exige une attention aux propriétés de la matière : la recette ne détermine pas seule la forme effectivement obtenue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-individu-et-relations","code":"SI07","author":"Simondon","title":"L’individu se forme dans la relation","quote":"L’individu est réalité d’une relation constituante, non intériorité d’un terme constitué.","locator":"Première partie, chap. I « Forme et matière », III, 1, p. 60","notions":["conscience","nature"],"commentary":[{"function":"Le problème","sentence":"Faut-il concevoir l’individu comme un être déjà achevé avant toute relation ?"},{"function":"L’affirmation","sentence":"Simondon propose de comprendre l’individu par la relation qui le constitue."},{"function":"Les concepts","sentence":"Une relation constituante fait naître une réalité, tandis qu’un terme constitué serait déjà donné avant elle."},{"function":"La raison","sentence":"Dans l’individuation physique étudiée ici, matière, énergie et milieu participent à une même opération de formation."},{"function":"L’exemple","sentence":"Le cristal se forme ainsi dans des conditions de milieu dont sa croissance ne peut être séparée."},{"function":"La portée","sentence":"Cette thèse invite à repenser aussi la formation du sujet dans ses relations, sans réduire sa vie psychique à un processus physique."}],"uses":[{"subject":"Suis-je ce que mon passé a fait de moi ?","function":"Introduire la formation plutôt qu’une essence fixe","reason":"Un individu se comprend à partir de sa genèse ; le passé ne constitue pourtant pas une identité achevée avant toute relation nouvelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=67","sourceLabel":"Recueil académique · p. 67"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-animal-et-pensee","code":"SI08","author":"Simondon","title":"La pensée ne trace pas une frontière simple","quote":"Ceci ne signifie pas qu’il y ait des êtres seulement vivants et d’autres vivants et pensants : il est probable que les animaux se trouvent parfois en situation psychique.","locator":"Deuxième partie, chap. I, I, 2, p. 163, note 6","notions":["nature","raison","conscience"],"commentary":[{"function":"Le problème","sentence":"La pensée permet-elle de séparer absolument l’homme des autres vivants ?"},{"function":"L’affirmation","sentence":"Simondon envisage que les animaux puissent eux aussi rencontrer des situations psychiques."},{"function":"Les concepts","sentence":"Le psychisme désigne ici la recherche d’une résolution quand les régulations vitales ne suffisent plus."},{"function":"La raison","sentence":"La différence porte alors sur la fréquence et les possibilités de cette recherche plutôt que sur deux essences entièrement séparées."},{"function":"L’exemple","sentence":"Selon la note, les ressources du symbolisme permettent à l’homme de faire plus souvent appel au psychisme."},{"function":"La portée","sentence":"Présentée comme probable, cette hypothèse conteste une séparation absolue sans effacer les différences ni constituer une preuve expérimentale."}],"uses":[{"subject":"Y a-t-il une différence de nature entre l’homme et l’animal ?","function":"Mettre en question une frontière absolue","reason":"L’hypothèse de situations psychiques animales conteste une frontière qui réserverait toute pensée à une essence exclusivement humaine.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"},{"subject":"Prétendre distinguer l’homme de l’animal, est-ce légitime ?","function":"Préciser ce que la distinction peut signifier","reason":"La différence peut porter sur les possibilités et la fréquence d’une activité plutôt que sur l’opposition absolue entre pensée humaine et vie animale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"simondon-ethique-et-vie-courante","code":"SI09","author":"Simondon","title":"La morale se construit dans la vie","quote":"Une véritable éthique serait celle qui tiendrait compte de la vie courante sans s’assoupir dans le courant de cette vie, qui saurait définir à travers les normes un sens qui les dépasse.","locator":"Conclusion, p. 244","notions":["devoir","raison"],"commentary":[{"function":"Le problème","sentence":"La morale doit-elle quitter la vie quotidienne ou se conformer à ses habitudes ?"},{"function":"L’affirmation","sentence":"Simondon cherche une éthique attentive à la vie courante et capable de dépasser ses règles établies."},{"function":"Les concepts","sentence":"Les normes sont ici les règles d’une situation donnée, tandis que leur sens permet de les interroger et de les transformer."},{"function":"La raison","sentence":"Une morale séparée de la vie perd sa prise sur l’action, mais l’obéissance aux usages ne justifie pas leur valeur."},{"function":"L’exemple","sentence":"Une règle de coopération peut être révisée lorsque son application empêche certains membres du groupe de participer."},{"function":"La portée","sentence":"L’exigence morale se cherche ainsi dans la transformation réfléchie des pratiques, plutôt que dans leur simple répétition."}],"uses":[{"subject":"Faire son devoir, est-ce là toute la morale ?","function":"Interroger les règles du devoir","reason":"L’éthique interroge le sens des règles reçues et peut conduire à les transformer ; faire son devoir ne se réduit donc pas à leur exécution habituelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=24","sourceLabel":"Recueil académique · p. 24"},{"subject":"Les conventions sociales peuvent-elles tenir lieu de morale ?","function":"Dépasser la conformité aux usages","reason":"Une éthique doit prendre appui sur la vie commune tout en gardant la capacité d’en interroger les normes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=118","sourceLabel":"Recueil académique · p. 118"}],"work":"L’Individu et sa genèse physico-biologique","edition":"Krisis · nouvelle édition augmentée","publisher":"Jérôme Millon","editionYear":"1995","translator":null,"originalLanguage":"français","editionNote":"Première publication partielle en 1964 ; édition augmentée de 1995. Les pages indiquées sont celles de l’édition imprimée."},{"id":"alain-obeir-et-resister","code":"AN01","author":"Alain","title":"Obéir et résister","work":"Propos","locator":"4 septembre 1912 · recueil des textes du bac, p. 689","quote":"Résistance et obéissance, voilà les deux vertus du citoyen.","notions":["etat","liberte","devoir"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=689","quoteSourceLabel":"Lire le texte du bac · p. 689","commentary":[{"function":"Le problème","sentence":"Comment préserver la liberté sans détruire l’ordre commun ?"},{"function":"L’affirmation","sentence":"Alain demande au citoyen d’associer l’obéissance aux lois et la résistance à l’arbitraire."},{"function":"Les concepts","sentence":"L’obéissance rend possible une vie réglée, tandis que la résistance désigne ici la vigilance et la critique du pouvoir."},{"function":"La raison","sentence":"Un ordre soustrait à toute contestation menace les libertés qu’il devrait protéger."},{"function":"L’exemple","sentence":"Un citoyen peut respecter une décision publique tout en la critiquant et en demandant sa révision."},{"function":"La portée","sentence":"La formule permet ainsi de penser une citoyenneté active, sans transformer toute désobéissance en vertu."}],"uses":[{"subject":"Obéir, est-ce nécessairement se soumettre ?","function":"Distinguer deux formes d’obéissance","reason":"Une obéissance accompagnée de vigilance et de contestation ne livre pas son jugement au pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"L’État est-il menacé quand les citoyens discutent les lois ?","function":"Renverser une objection","reason":"La critique peut protéger les libertés et maintenir un ordre légitime plutôt que le détruire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Date du propos vérifiée dans l’édition de l’Association des Amis d’Alain."},{"id":"alain-la-distance-a-soi","code":"AN02","author":"Alain","title":"La distance à soi","work":"Vigiles de l’esprit","locator":"« L’inconscient », 17 juin 1923 · recueil des textes du bac, p. 1071","quote":"Pour prendre conscience, il faut se diviser soi-même.","notions":["conscience","liberte","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1071","quoteSourceLabel":"Lire le texte du bac · p. 1071","commentary":[{"function":"Le problème","sentence":"Peut-on prendre conscience de ses actes en se laissant entièrement absorber par eux ?"},{"function":"L’affirmation","sentence":"Alain affirme que la réflexion exige une distance à l’égard de soi."},{"function":"Les concepts","sentence":"Se diviser signifie devenir pour soi un objet d’examen, sans se transformer en deux personnes."},{"function":"La raison","sentence":"Celui qui s’interroge sur son impulsion cesse déjà de lui obéir sans réserve."},{"function":"L’exemple","sentence":"Au moment de répondre avec colère, se demander pourquoi l’on s’emporte ouvre une possibilité de retenue."},{"function":"La portée","sentence":"La conscience apparaît ainsi comme un exercice critique, et non comme une connaissance immédiate et complète de soi."}],"uses":[{"subject":"Prendre conscience de soi, est-ce devenir étranger à soi ?","function":"Préciser une condition de la réflexion","reason":"La distance requise pour examiner ses actes ne signifie pas devenir une autre personne : elle permet de reprendre son propre jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"},{"subject":"La conscience de soi rend-elle libre ?","function":"Établir une possibilité de libération","reason":"L’examen d’une impulsion permet de suspendre une réaction, sans garantir une maîtrise totale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"}],"editionNote":"Titre et date vérifiés dans Vigiles de l’esprit (1942), section L ; le sujet ne précise pas ce recueil."},{"id":"bergson-inventer-prend-temps","code":"AN03","author":"Bergson","title":"Inventer prend du temps","work":"L’Évolution créatrice","locator":"Chapitre IV · recueil des textes du bac, p. 1019","quote":"Le temps d’invention ne fait qu’un ici avec l’invention même.","notions":["temps","art","travail"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1019","quoteSourceLabel":"Lire le texte du bac · p. 1019","commentary":[{"function":"Le problème","sentence":"Le temps consacré à créer est-il seulement un délai avant le résultat ?"},{"function":"L’affirmation","sentence":"Bergson soutient que l’invention se forme dans une durée qui appartient à son contenu."},{"function":"Les concepts","sentence":"Inventer diffère d’assembler un résultat déjà donné, car l’idée se transforme en se réalisant."},{"function":"La raison","sentence":"Réduire cette durée pourrait donc modifier l’œuvre elle-même et pas seulement avancer sa livraison."},{"function":"L’exemple","sentence":"Un peintre découvre dans son travail des rapports de couleurs qu’aucun plan initial ne fixait entièrement."},{"function":"La portée","sentence":"Le temps peut ainsi produire du nouveau, sans que toute lenteur soit pour autant créatrice."}],"uses":[{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Contester une règle générale","reason":"Accélérer une invention peut en modifier le contenu, au lieu de donner le même résultat plus vite.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"La création artistique est-elle un travail ?","function":"Caractériser le travail créateur","reason":"Créer peut demander une maturation qui transforme l’œuvre ; ce travail ne se confond pas avec l’exécution d’un résultat déjà fixé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"comte-les-limites-de-lintrospection","code":"AN04","author":"Comte","title":"Les limites de l’introspection","work":"Cours de philosophie positive","locator":"Première leçon · recueil des textes du bac, p. 529","quote":"L’individu pensant ne saurait se partager en deux dont l’un raisonnerait, tandis que l’autre regarderait raisonner.","notions":["conscience","science","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=529","quoteSourceLabel":"Lire le texte du bac · p. 529","commentary":[{"function":"Le problème","sentence":"Peut-on observer son raisonnement pendant qu’on le produit ?"},{"function":"L’affirmation","sentence":"Comte conteste la possibilité d’une observation intérieure simultanée des opérations intellectuelles."},{"function":"Les concepts","sentence":"L’introspection prétend faire du même esprit le sujet qui pense et l’observateur de cette pensée."},{"function":"La raison","sentence":"Or l’attention consacrée à observer risque de transformer ou d’interrompre l’activité étudiée."},{"function":"L’exemple","sentence":"Chercher à surveiller chaque étape d’un calcul peut faire perdre le fil du calcul lui-même."},{"function":"La portée","sentence":"Cette difficulté invite à examiner les méthodes de connaissance de soi, sans prouver que toute réflexion intérieure serait impossible."}],"uses":[{"subject":"Peut-on se connaître soi-même ?","function":"Soulever une difficulté de méthode","reason":"L’observation de son raisonnement peut en modifier le cours ; cette difficulté de l’introspection simultanée n’interdit pas toute réflexion rétrospective.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"L’esprit peut-il être objet de science ?","function":"Mettre à l’épreuve une méthode","reason":"L’observation intérieure immédiate demande un examen critique avant de servir de méthode scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"}]},{"id":"diderot-le-bon-despote","code":"AN05","author":"Diderot","title":"Le bon despote","work":"Réfutation suivie de l’ouvrage d’Helvétius","locator":"Passage sur le gouvernement arbitraire · recueil des textes du bac, p. 266","quote":"Le gouvernement arbitraire d’un prince juste et éclairé est toujours mauvais.","notions":["etat","justice","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=266","quoteSourceLabel":"Lire le texte du bac · p. 266","commentary":[{"function":"Le problème","sentence":"Les qualités d’un gouvernant suffisent-elles à rendre son pouvoir légitime ?"},{"function":"L’affirmation","sentence":"Diderot condamne même le pouvoir arbitraire d’un prince bien intentionné."},{"function":"Les concepts","sentence":"L’arbitraire tient à l’absence de limites et de droit d’opposition, non à la seule cruauté du chef."},{"function":"La raison","sentence":"Une autorité bienfaisante habitue ses sujets à la dépendance et les expose aux décisions de ses successeurs."},{"function":"L’exemple","sentence":"Un prince généreux peut accorder un avantage que le suivant retirera sans recours possible."},{"function":"La portée","sentence":"La liberté exige donc des garanties durables, au-delà de la confiance accordée à une personne."}],"uses":[{"subject":"L’État doit-il reconnaître des limites à sa puissance ?","function":"Justifier une limite institutionnelle","reason":"La bienveillance du pouvoir ne remplace ni les droits des citoyens ni leur possibilité de s’opposer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"L’État doit-il garantir le bonheur des citoyens ?","function":"Écarter une justification insuffisante","reason":"Un bonheur dispensé par un pouvoir sans limites peut installer une dépendance politiquement dangereuse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"}],"editionNote":"Le titre est celui du recueil actuel, confirmé dans l’œuvre ; l’ancienne compilation attribuait à tort ce passage à une Lettre à Helvétius."},{"id":"durkheim-des-pouvoirs-qui-se-limitent","code":"AN06","author":"Durkheim","title":"Des pouvoirs qui se limitent","work":"Une révision de l’idée socialiste","locator":"Article de 1899 · recueil des textes du bac, p. 420","quote":"Ce qui libère l’individu, ce n’est pas la suppression de tout centre régulateur, c’est leur multiplication, pourvu que ces centres multiples soient coordonnés et subordonnés les uns aux autres.","notions":["etat","liberte","justice"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=420","quoteSourceLabel":"Lire le texte du bac · p. 420","commentary":[{"function":"Le problème","sentence":"La liberté demande-t-elle de supprimer toute autorité sociale ?"},{"function":"L’affirmation","sentence":"Durkheim soutient qu’elle peut dépendre de plusieurs pouvoirs capables de se limiter mutuellement."},{"function":"Les concepts","sentence":"Les centres régulateurs sont l’État et les groupes organisés, notamment territoriaux ou professionnels."},{"function":"La raison","sentence":"L’État protège contre l’oppression des groupes, tandis que leur autonomie freine les empiétements du pouvoir central."},{"function":"L’exemple","sentence":"Une organisation professionnelle peut défendre ses membres face à l’administration tout en restant soumise à des règles communes."},{"function":"La portée","sentence":"La pluralité protège donc à condition d’être organisée, et non par la simple accumulation d’autorités concurrentes."}],"uses":[{"subject":"L’État est-il l’ennemi de l’individu ?","function":"Dépasser une opposition trop simple","reason":"L’État et les groupes intermédiaires peuvent limiter réciproquement leurs empiétements et protéger ainsi l’individu contre une autorité sans contrepoids.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La liberté consiste-t-elle à n’obéir à personne ?","function":"Proposer une autre condition de la liberté","reason":"Des autorités coordonnées peuvent empêcher la domination d’une autorité unique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"editionNote":"Le sujet donne le titre L’État et la société civile ; le passage est retrouvé dans l’article Une révision de l’idée socialiste (1899)."},{"id":"montesquieu-commerce-et-paix","code":"AN07","author":"Montesquieu","title":"Commerce et paix","work":"De l’Esprit des lois","locator":"Livre XX, chapitre II · recueil des textes du bac, p. 693","quote":"L’effet naturel du commerce est de porter à la paix.","notions":["etat","justice","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=693","quoteSourceLabel":"Lire le texte du bac · p. 693","commentary":[{"function":"Le problème","sentence":"Des intérêts économiques peuvent-ils rapprocher des peuples que tout oppose ?"},{"function":"L’affirmation","sentence":"Montesquieu montre que le commerce peut favoriser des relations pacifiques."},{"function":"Les concepts","sentence":"L’échange crée une dépendance réciproque entre celui qui souhaite acheter et celui qui souhaite vendre."},{"function":"La raison","sentence":"La guerre risque alors de détruire un avantage que chacun trouve dans la relation."},{"function":"L’exemple","sentence":"Deux pays qui dépendent de leurs débouchés respectifs ont un motif de préserver leurs échanges."},{"function":"La portée","sentence":"Il s’agit d’une raison de préférer la paix, sans garantie que l’intérêt économique suffise à empêcher toute guerre."}],"uses":[{"subject":"Le commerce favorise-t-il la paix ?","function":"Expliquer un mécanisme pacificateur","reason":"La dépendance des acheteurs et des vendeurs donne à chacun un intérêt à préserver l’échange ; ce motif pacifique ne supprime pas toutes les causes de conflit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=97","sourceLabel":"Recueil académique · p. 97"},{"subject":"Les échanges nous rapprochent-ils toujours les uns des autres ?","function":"Distinguer rapprochement et vertu","reason":"Une dépendance utile peut unir des nations sans produire nécessairement la générosité entre les personnes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=97","sourceLabel":"Recueil académique · p. 97"}],"editionNote":"Le texte poursuit en distinguant l’union des nations et les rapports entre particuliers ; sa réserve est conservée dans l’explication."},{"id":"tocqueville-la-limite-de-la-majorite","code":"AN08","author":"Tocqueville","title":"La limite de la majorité","work":"De la démocratie en Amérique","locator":"Première Démocratie (1835), deuxième partie, chapitre VII · recueil des textes du bac, p. 627","quote":"La justice forme donc la borne du droit de chaque peuple.","notions":["etat","justice","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=627","quoteSourceLabel":"Lire le texte du bac · p. 627","commentary":[{"function":"Le problème","sentence":"Une décision devient-elle juste dès lors que la majorité l’approuve ?"},{"function":"L’affirmation","sentence":"Tocqueville oppose une limite de justice au pouvoir souverain d’un peuple."},{"function":"Les concepts","sentence":"La souveraineté désigne l’autorité de décider, tandis que la justice permet de juger la décision elle-même."},{"function":"La raison","sentence":"Une majorité peut poursuivre ses intérêts contre une minorité aussi bien qu’un individu abuse de sa force."},{"function":"L’exemple","sentence":"Un vote qui prive une minorité de droits ne devient pas juste par le seul nombre de ses partisans."},{"function":"La portée","sentence":"Le principe majoritaire doit donc s’accompagner de limites, sans que toute opposition particulière incarne automatiquement la justice."}],"uses":[{"subject":"La consultation des citoyens suffit-elle à faire la démocratie ?","function":"Montrer une condition supplémentaire","reason":"Le vote ne suffit pas si la majorité peut supprimer les droits d’une minorité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=121","sourceLabel":"Recueil académique · p. 121"},{"subject":"Pour être juste, suffit-il d’obéir aux lois ?","function":"Distinguer légalité et justice","reason":"Une loi voulue par la majorité peut rester soumise à une exigence de justice qui en limite l’autorité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}]},{"id":"rousseau-le-bonheur-despere","code":"AN09","author":"Rousseau","title":"Le bonheur d’espérer","work":"Julie ou La Nouvelle Héloïse","locator":"Sixième partie, lettre VIII · recueil des textes du bac, p. 607","quote":"On jouit moins de ce qu’on obtient que de ce qu’on espère et l’on n’est heureux qu’avant d’être heureux.","notions":["bonheur","conscience","temps"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=607","quoteSourceLabel":"Lire le texte du bac · p. 607","commentary":[{"function":"Le problème","sentence":"Le bonheur dépend-il davantage de la possession ou de l’attente ?"},{"function":"L’affirmation","sentence":"Rousseau fait exprimer à Julie le plaisir que l’espoir ajoute à l’objet désiré."},{"function":"Les concepts","sentence":"L’imagination embellit ce qui manque et permet d’en jouir avant de le posséder."},{"function":"La raison","sentence":"L’obtention confronte au contraire l’objet réel à la richesse de ce qu’on avait imaginé."},{"function":"L’exemple","sentence":"Un voyage longtemps rêvé peut perdre une partie de son charme une fois confronté à ses conditions concrètes."},{"function":"La portée","sentence":"La formule éclaire la déception du désir satisfait, sans établir que toute satisfaction réelle serait malheureuse."}],"uses":[{"subject":"Le bonheur n’est-il que dans l’attente du bonheur ?","function":"Soutenir une réponse paradoxale","reason":"L’espérance produit dès maintenant une jouissance que la possession peut dissiper.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Contester une condition suffisante","reason":"L’objet obtenu ne contient pas nécessairement le plaisir que l’imagination lui ajoutait pendant l’attente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}],"speaker":"Julie de Wolmar","situation":"Dans une lettre à Saint-Preux, Julie examine le désir et la déception de la possession."},{"id":"pascal-etre-ou-paraitre-courageux","code":"AN10","author":"Pascal","title":"Être ou paraître courageux","work":"Pensées","locator":"Fragment 147, numérotation Brunschvicg · recueil des textes du bac, p. 1115","quote":"Nous serions de bon cœur poltrons pour en acquérir la réputation d’être vaillants.","notions":["conscience","devoir","liberte"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1115","quoteSourceLabel":"Lire le texte du bac · p. 1115","commentary":[{"function":"Le problème","sentence":"Préférons-nous posséder une vertu ou être reconnus pour elle ?"},{"function":"L’affirmation","sentence":"Pascal décrit le renversement par lequel la réputation devient plus précieuse que la qualité réelle."},{"function":"Les concepts","sentence":"L’être imaginaire est l’image de nous qui vit dans l’esprit des autres."},{"function":"La raison","sentence":"À vouloir embellir cette image, nous pouvons sacrifier la conduite qui justifierait réellement l’estime."},{"function":"L’exemple","sentence":"Un soldat pourrait éviter le danger tout en s’attribuant les exploits d’un autre pour passer pour courageux."},{"function":"La portée","sentence":"La recherche de reconnaissance demande donc un examen moral, sans que toute estime publique soit trompeuse."}],"uses":[{"subject":"Ne fait-on son devoir que par crainte du regard d’autrui ?","function":"Mettre en évidence un mobile ambigu","reason":"Le souci du jugement public peut pousser à rechercher les signes de la vertu plutôt qu’à agir vertueusement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"},{"subject":"Puis-je être moi-même sans le regard d’autrui ?","function":"Examiner un risque de dépendance","reason":"L’image sociale peut prendre tant de valeur que l’on sacrifie sa conduite réelle pour la préserver.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"}]},{"id":"leibniz-condition-et-essence","code":"AN11","author":"Leibniz","title":"Condition et essence","work":"Sur ce qui passe les sens et la matière","locator":"Texte français, daté de juin 1702 par l’édition critique · recueil des textes du bac, p. 1050","quote":"Mais ce qui est nécessaire pour quelque chose, n’en fait point l’essence pour cela.","notions":["raison","science","verite"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=1050","quoteSourceLabel":"Lire le texte du bac · p. 1050","commentary":[{"function":"Le problème","sentence":"Ce dont une chose dépend suffit-il à définir ce qu’elle est ?"},{"function":"L’affirmation","sentence":"Leibniz distingue une condition nécessaire et l’essence de ce qu’elle rend possible."},{"function":"Les concepts","sentence":"La condition doit être présente pour qu’une chose existe, tandis que l’essence dit ce qui la constitue."},{"function":"La raison","sentence":"Les sens peuvent ainsi être indispensables à notre pensée sans expliquer à eux seuls les vérités nécessaires du raisonnement."},{"function":"L’exemple","sentence":"L’air est nécessaire à notre vie, mais notre vie ne se confond pas avec l’air que nous respirons."},{"function":"La portée","sentence":"Cette distinction oblige à examiner ce qu’une explication établit vraiment, sans nier le rôle des conditions sensibles."}],"uses":[{"subject":"L’expérience est-elle la seule source du savoir ?","function":"Distinguer condition et fondement","reason":"Les sens peuvent être nécessaires à l’éveil du savoir sans suffire à expliquer les vérités nécessaires du raisonnement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=57","sourceLabel":"Recueil académique · p. 57"},{"subject":"La raison est-elle plus fiable que l’expérience ?","function":"Préciser les contributions respectives","reason":"Le rôle des sensations dans l’acquisition d’un savoir ne suffit pas à justifier la nécessité des relations que la raison y établit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}],"editionNote":"Datation de l’édition critique de Münster : début à mi-juin 1702 ; la date de 1704 parfois donnée en ligne n’est pas retenue."},{"id":"weil-des-hommes-traites-en-choses","code":"AN12","author":"Simone Weil","title":"Des hommes traités en choses","work":"La Condition ouvrière","locator":"Passage sur les rapports dans l’usine · recueil des textes du bac, p. 105","quote":"Les choses jouent le rôle des hommes, les hommes jouent le rôle des choses ; c’est la racine du mal.","notions":["travail","technique","justice"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=105","quoteSourceLabel":"Lire le texte du bac · p. 105","commentary":[{"function":"Le problème","sentence":"Que devient le travailleur quand la production compte davantage que sa personne ?"},{"function":"L’affirmation","sentence":"Simone Weil décrit une organisation où l’ouvrier est traité comme un élément interchangeable."},{"function":"Les concepts","sentence":"L’inversion oppose les produits suivis et identifiés aux personnes réduites à une fonction et à un rythme imposés."},{"function":"La raison","sentence":"Lorsque la compréhension de l’ensemble est réservée aux dirigeants, l’exécutant perd la maîtrise du sens de son activité."},{"function":"L’exemple","sentence":"Un ouvrier déplacé d’une machine à l’autre sans explication peut être géré comme une pièce disponible."},{"function":"La portée","sentence":"La critique vise cette organisation du travail, et ne condamne pas toute activité industrielle à déshumaniser."}],"uses":[{"subject":"Le travail fait-il violence à notre humanité ?","function":"Identifier une forme de déshumanisation","reason":"Traiter le travailleur comme un élément interchangeable lui retire la maîtrise du sens de son activité ; la violence dépasse alors la seule pénibilité physique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"},{"subject":"La technique résout-elle tous les problèmes qui se posent au travail ?","function":"Déplacer le problème vers l’organisation","reason":"Une production techniquement efficace peut laisser intacte la dépossession des exécutants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"}],"editionNote":"Le sujet porte la date 1942 ; La Condition ouvrière est un recueil posthume publié en 1951."},{"id":"weil-leffort-et-la-maitrise-de-soi","code":"AN13","author":"Simone Weil","title":"L’effort et la maîtrise de soi","work":"Réflexions sur les causes de la liberté et de l’oppression sociale","locator":"Texte rédigé en 1934 · recueil des textes du bac, p. 86","quote":"Ce sont les obstacles auxquels on se heurte et qu’il faut surmonter qui fournissent l’occasion de se vaincre soi-même.","notions":["travail","liberte","raison"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":null,"originalLanguage":"français","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=86","quoteSourceLabel":"Lire le texte du bac · p. 86","commentary":[{"function":"Le problème","sentence":"L’absence d’obstacles suffirait-elle à nous rendre maîtres de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Simone Weil voit dans l’effort demandé par le réel une occasion de discipliner ses propres impulsions."},{"function":"Les concepts","sentence":"Se vaincre signifie ici apprendre à régler sa conduite plutôt que suivre chaque caprice."},{"function":"La raison","sentence":"Une difficulté extérieure impose une exigence que notre fantaisie ne peut pas supprimer à volonté."},{"function":"L’exemple","sentence":"Un apprenti ajuste patiemment son geste à la résistance du matériau au lieu d’abandonner à la première contrariété."},{"function":"La portée","sentence":"Le travail peut ainsi former la liberté, sans que toute souffrance ou toute oppression devienne pour autant éducative."}],"uses":[{"subject":"Le travail peut-il rendre libre ?","function":"Expliquer une formation de la liberté","reason":"L’effort réglé par les exigences d’une tâche peut libérer de la soumission au caprice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=69","sourceLabel":"Recueil académique · p. 69"},{"subject":"Tout travail est-il un travail sur soi ?","function":"Établir une possibilité à examiner","reason":"L’effort peut transformer le sujet, mais cette formation suppose un travail où l’obstacle permet un exercice réel du jugement et du geste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"mill-choisir-au-lieu-de-suivre","code":"AN14","author":"Mill","title":"Choisir au lieu de suivre","work":"De la liberté","locator":"Chapitre III · recueil des textes du bac, p. 264","quote":"Celui qui n’agit jamais que suivant la coutume ne fait pas de choix.","notions":["liberte","raison","devoir"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":"Non indiqué dans le recueil","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=264","quoteSourceLabel":"Lire le texte du bac · p. 264","commentary":[{"function":"Le problème","sentence":"Une conduite correcte suffit-elle à prouver que l’on agit librement ?"},{"function":"L’affirmation","sentence":"Mill distingue suivre une coutume et choisir soi-même sa conduite."},{"function":"Les concepts","sentence":"La coutume transmet une expérience collective, tandis que le choix exerce le jugement personnel."},{"function":"La raison","sentence":"Même une règle adaptée ne développe pas ce jugement lorsqu’on la suit uniquement parce que tous la suivent."},{"function":"L’exemple","sentence":"Reprendre le métier familial sans en examiner les raisons ne constitue pas le même acte que le choisir après réflexion."},{"function":"La portée","sentence":"La liberté demande donc un exercice du discernement, sans imposer de rejeter toutes les traditions."}],"uses":[{"subject":"Peut-on choisir sa vie ?","function":"Préciser ce que signifie choisir","reason":"Reprendre une coutume après examen exerce le jugement, tandis que la suivre uniquement parce qu’elle est reçue laisse le choix à autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=44","sourceLabel":"Recueil académique · p. 44"},{"subject":"Être libre, est-ce faire ce que l’on veut ?","function":"Interroger l’origine de la volonté","reason":"Faire ce que l’on veut peut encore reproduire une coutume : la liberté demande aussi l’examen de la manière dont cette volonté s’est formée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}],"editionNote":"Phrase également attestée dans la traduction de Charles Brook Dupont-White (1860) ; le recueil ne précise pas la traduction de son extrait."},{"id":"arendt-un-espace-pour-la-liberte","code":"AN15","author":"Arendt","title":"Un espace pour la liberté","work":"La Crise de la culture","locator":"« Qu’est-ce que la liberté ? » · recueil des textes du bac, p. 124","quote":"Sans une vie publique politiquement garantie, il manque à la liberté l’espace du monde où faire son apparition.","notions":["liberte","etat","langage"],"edition":"Sujets de textes de philosophie du bac, 1996–2026, recueil de Marc Anglaret mis à jour par Paul Hamel","publisher":"Académie de Montpellier","editionYear":2026,"translator":"Non indiqué dans le recueil","quoteSource":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-textes-philo-1996-2026.pdf#page=124","quoteSourceLabel":"Lire le texte du bac · p. 124","commentary":[{"function":"Le problème","sentence":"La liberté peut-elle devenir effective si chacun reste enfermé dans sa vie privée ?"},{"function":"L’affirmation","sentence":"Arendt affirme que la liberté politique a besoin d’un espace public garanti."},{"function":"Les concepts","sentence":"Cet espace permet à des personnes différentes de parler et d’agir ensemble devant d’autres."},{"function":"La raison","sentence":"Une aspiration intérieure ne suffit pas à produire une action libre lorsque toute initiative publique est interdite."},{"function":"L’exemple","sentence":"Pouvoir discuter d’une décision commune et proposer une action rend la liberté visible dans le monde partagé."},{"function":"La portée","sentence":"La formule distingue donc la liberté politique de son seul désir intérieur, sans nier l’existence de ce désir sous la contrainte."}],"uses":[{"subject":"Y a-t-il d’autres formes de liberté que la liberté politique ?","function":"Définir une forme particulière de liberté","reason":"L’aspiration intérieure à la liberté ne remplace pas sa manifestation par l’action et la parole dans un monde commun.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"L’État est-il le garant de ma liberté ?","function":"Énoncer une condition politique","reason":"L’expression et l’initiative publiques exigent des garanties politiques ; l’absence d’entraves privées ne suffit pas à les rendre possibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=26","sourceLabel":"Recueil académique · p. 26"}],"editionNote":"Formulation française exacte du sujet : « l’espace du monde » ; l’ancienne compilation porte une autre variante, « l’espace mondain »."},{"id":"la-fontaine-accuser-le-miroir","code":"LF01","author":"La Fontaine","title":"Accuser le miroir","work":"L’Homme et son Image","collection":"Fables choisies mises en vers","locator":"Livre I, fable XI · p. 44 (PDF p. 110)","quote":"Il accusait toujours les miroirs d’être faux,\nVivant plus que content dans son erreur profonde.","verse":true,"notions":["conscience","verite","bonheur"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un homme épris de lui-même refuse les reflets qui contredisent la haute opinion qu’il a de sa beauté.","commentary":[{"function":"Le problème","sentence":"Pourquoi la connaissance de soi rencontre-t-elle parfois une résistance en nous-mêmes ?"},{"function":"L’affirmation","sentence":"La Fontaine peint un homme qui préfère condamner les miroirs plutôt que corriger son jugement."},{"function":"Les concepts","sentence":"Le miroir représente ici un témoignage extérieur, tandis que l’erreur entretient une satisfaction intérieure."},{"function":"La raison","sentence":"Ce qui déplaît au personnage lui paraît faux parce qu’il confond son désir d’être beau avec une preuve."},{"function":"L’exemple","sentence":"De même, un reproche justifié peut être rejeté comme malveillant lorsqu’il blesse notre amour-propre."},{"function":"La portée","sentence":"Le récit fait donc voir un obstacle affectif à la connaissance de soi, sans établir que toute critique serait vraie."}],"uses":[{"subject":"Peut-on se voir tel que l’on est ?","function":"Montrer une résistance à la connaissance de soi","reason":"L’homme dispose de reflets, mais refuse leur témoignage : l’obstacle tient à l’accueil du jugement autant qu’au manque d’informations.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Mettre à l’épreuve un bonheur fondé sur l’illusion","reason":"La satisfaction du personnage dépend d’une erreur qu’il protège contre les démentis ; son contentement reste donc fragile devant le réel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"la-fontaine-appeler-la-mort-retenir-la-vie","code":"LF02","author":"La Fontaine","title":"Appeler la mort, retenir la vie","work":"La Mort et le Bûcheron","collection":"Fables choisies mises en vers","locator":"Livre I, fable XVI · p. 50 (PDF p. 118)","quote":"C’est, dit-il, afin de m’aider\nA recharger ce bois; tu ne tarderas guère.","verse":true,"notions":["conscience","bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Bûcheron","situation":"Épuisé, le bûcheron appelle la Mort ; lorsqu’elle paraît, il lui demande seulement de l’aider à porter son bois.","commentary":[{"function":"Le problème","sentence":"Savons-nous toujours ce que nous désirons lorsque nous exprimons notre détresse ?"},{"function":"L’affirmation","sentence":"Le bûcheron qui appelait la Mort lui demande finalement de l’aider à poursuivre sa vie."},{"function":"Les concepts","sentence":"Vouloir la fin d’une souffrance se distingue alors de vouloir la fin de son existence."},{"function":"La raison","sentence":"La présence de la Mort révèle un attachement à la vie que la plainte semblait avoir effacé."},{"function":"L’exemple","sentence":"Dans cette scène, le bois rechargé représente le retour à une condition pénible que le personnage préfère néanmoins conserver."},{"function":"La portée","sentence":"La réplique invite ainsi à interroger le sens d’un désir déclaré, sans transformer ce cas fictif en vérité universelle sur la souffrance."}],"uses":[{"subject":"Les hommes savent-ils ce qu’ils désirent ?","function":"Distinguer la plainte et son objet véritable","reason":"L’appel de la Mort devient une demande d’aide : la confrontation avec l’objet annoncé révèle un désir de soulagement plutôt qu’un désir de disparaître.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"La souffrance est-elle au cœur de l’existence ?","function":"Nuancer l’identification de vivre et souffrir","reason":"La scène associe le poids de l’existence à un attachement persistant à la vie ; elle ouvre la discussion sans justifier toute souffrance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"la-fontaine-qui-peint-la-victoire","code":"LF03","author":"La Fontaine","title":"Qui peint la victoire ?","work":"Le Lion abattu par l’Homme","collection":"Fables choisies mises en vers","locator":"Livre III, fable X · p. 94 (PDF p. 174)","quote":"Avec plus de raison nous aurions le dessus,\nSi mes confrères savaient peindre.","verse":true,"notions":["art","verite","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Lion","situation":"Devant un tableau glorifiant un homme victorieux d’un lion, un lion conteste le privilège humain de produire les images.","commentary":[{"function":"Le problème","sentence":"Une image montre-t-elle les faits indépendamment de celui qui la produit ?"},{"function":"L’affirmation","sentence":"Le lion suggère que la victoire humaine représentée dépend aussi du pouvoir humain de peindre."},{"function":"Les concepts","sentence":"La représentation sélectionne un point de vue et ne se confond donc pas avec une preuve impartiale."},{"function":"La raison","sentence":"Celui qui possède les moyens de représenter peut rendre sa propre supériorité visible et laisser celle des autres sans image."},{"function":"L’exemple","sentence":"Le tableau admiré par les hommes devient ainsi, pour le lion, le témoignage de leur avantage dans la fabrication des récits."},{"function":"La portée","sentence":"La réplique invite à examiner la position du représentant, sans garantir qu’une peinture de lion serait plus objective."}],"uses":[{"subject":"Que peut nous apprendre une image ?","function":"Distinguer ce qui est représenté et le point de vue du représentant","reason":"Le tableau renseigne sur la gloire que les hommes se donnent autant que sur le combat qu’il prétend montrer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"Peut-on reprocher à l’art d’être mensonger ?","function":"Interroger une représentation qui se donne pour une preuve","reason":"Le tableau peut faire passer un point de vue favorable à son auteur pour une preuve ; cette prétention se distingue d’une fiction reconnue comme telle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=10","sourceLabel":"Recueil académique · p. 10"}]},{"id":"la-fontaine-enfermer-sa-joie-avec-son-argent","code":"LF04","author":"La Fontaine","title":"Enfermer sa joie avec son argent","work":"Le Savetier et le Financier","collection":"Fables choisies mises en vers","locator":"Livre VIII, fable II · p. 208 (PDF p. 304)","quote":"Il retourne chez lui : dans sa cave il enserre\nL’argent et sa joie à la fois.","verse":true,"notions":["bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Après avoir reçu cent écus du financier, le savetier cache l’argent et perd la tranquillité qui le faisait chanter.","commentary":[{"function":"Le problème","sentence":"Posséder davantage suffit-il à mieux vivre ?"},{"function":"L’affirmation","sentence":"La Fontaine représente un savetier dont l’argent nouvellement reçu enferme aussi la joie."},{"function":"Les concepts","sentence":"La possession matérielle se distingue ici de la disponibilité intérieure nécessaire au bonheur."},{"function":"La raison","sentence":"En craignant constamment de perdre son trésor, le personnage transforme un avantage en source de dépendance."},{"function":"L’exemple","sentence":"L’argent caché dans la cave mobilise désormais son attention et fait taire les chansons qui accompagnaient son travail."},{"function":"La portée","sentence":"L’image permet donc de discuter la valeur des biens par leurs effets sur la vie, sans présenter la pauvreté comme un idéal."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Opposer la possession d’un bien et la capacité d’en jouir","reason":"Le don enrichit le savetier mais suscite la peur de perdre ; la satisfaction matérielle ne garantit pas la tranquillité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"la-fontaine-le-plaisir-de-comprendre","code":"LF05","author":"La Fontaine","title":"Le plaisir de comprendre","work":"Le Pâtre et le Lion","collection":"Fables choisies mises en vers","locator":"Livre VI, fable I · p. 153 (PDF p. 243)","quote":"Une Morale nue apporte de l’ennui;\nLe conte fait passer le précepte avec lui.","verse":true,"notions":["art","langage","raison"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Avant de raconter la rencontre d’un pâtre et d’un lion, le poète explique comment la fable associe plaisir et instruction.","commentary":[{"function":"Le problème","sentence":"Le plaisir d’une œuvre empêche-t-il de réfléchir ?"},{"function":"L’affirmation","sentence":"La Fontaine soutient que le récit peut rendre une leçon plus accessible qu’un précepte isolé."},{"function":"Les concepts","sentence":"Le conte donne une situation sensible à une règle morale qui resterait autrement abstraite."},{"function":"La raison","sentence":"L’intérêt pris aux personnages conduit le lecteur à suivre les conséquences de leurs actions et à examiner leurs choix."},{"function":"L’exemple","sentence":"L’ours qui tue son ami en voulant le protéger fait comprendre les dangers d’une intention privée de jugement."},{"function":"La portée","sentence":"La formule montre ainsi une coopération possible entre plaisir et réflexion, sans réduire toute œuvre d’art à une leçon."}],"uses":[{"subject":"L’art n’a-t-il pour but que le plaisir ?","function":"Associer le plaisir du récit à un travail de réflexion","reason":"La fable plaît en faisant suivre une action dont les conséquences instruisent ; le plaisir peut participer à une autre fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art doit-il nous instruire ?","function":"Décrire une manière d’instruire propre au récit","reason":"Le précepte devient intelligible dans une situation imaginée ; cette possibilité ne suffit pas à imposer une mission morale à tout art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"la-fontaine-changer-de-maitre-rester-soumis","code":"LF06","author":"La Fontaine","title":"Changer de maître, rester soumis","work":"Le Vieillard et l’Âne","collection":"Fables choisies mises en vers","locator":"Livre VI, fable VIII · p. 160 (PDF p. 250)","quote":"Notre ennemi, c’est notre Maître :\nJe vous le dis en bon François.","verse":true,"notions":["liberte","etat","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"L’Âne","situation":"L’âne refuse de fuir l’ennemi : il pense que changer de propriétaire ne modifiera pas la charge qu’il doit porter.","commentary":[{"function":"Le problème","sentence":"Un changement de pouvoir suffit-il à supprimer la domination ?"},{"function":"L’affirmation","sentence":"L’âne considère son maître actuel comme son ennemi parce qu’il demeure celui qui lui impose sa charge."},{"function":"Les concepts","sentence":"La liberté se distingue ici du simple remplacement de la personne qui commande."},{"function":"La raison","sentence":"Du point de vue du dominé, la victoire d’un camp importe peu si elle laisse intacte la relation de servitude."},{"function":"L’exemple","sentence":"Dans la fable, l’animal compare les charges attendues plutôt que les fidélités que le vieillard voudrait lui faire partager."},{"function":"La portée","sentence":"Sa réplique oblige donc à examiner les conditions concrètes de l’obéissance, sans prouver que tous les pouvoirs se valent."}],"uses":[{"subject":"L’État exerce-t-il nécessairement une domination ?","function":"Introduire le point de vue de celui qui subit le pouvoir","reason":"La réplique distingue l’identité des dirigeants et les effets de leur autorité ; elle sert de comparaison, sans assimiler d’emblée l’État au propriétaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"La liberté consiste-t-elle à n’obéir à personne ?","function":"Distinguer changement de maître et libération","reason":"Changer de maître peut reconduire la même charge ; la liberté dépend donc du rapport d’obéissance, et pas seulement de l’identité de celui qui commande.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"la-fontaine-la-puissance-devant-le-juge","code":"LF07","author":"La Fontaine","title":"La puissance devant le juge","work":"Les Animaux malades de la peste","collection":"Fables choisies mises en vers","locator":"Livre VII, fable I · p. 180 (PDF p. 270)","quote":"Selon que vous serez puissant ou misérable,\nLes jugements de cour vous rendront blanc ou noir.","verse":true,"notions":["justice","etat","verite"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le lion est absous de ses violences ; l’âne, coupable d’avoir brouté un peu d’herbe, est désigné comme victime expiatoire.","commentary":[{"function":"Le problème","sentence":"Une décision prononcée par un tribunal est-elle nécessairement juste ?"},{"function":"L’affirmation","sentence":"La Fontaine dénonce des jugements qui changent selon la puissance de l’accusé."},{"function":"Les concepts","sentence":"Le verdict officiel se sépare alors de l’examen impartial des actes commis."},{"function":"La raison","sentence":"La peur des puissants fait excuser leurs crimes, tandis que la faiblesse de l’âne rend sa faute disproportionnellement punissable."},{"function":"L’exemple","sentence":"Le même conseil absout ainsi le lion et condamne celui qui ne peut se défendre contre lui."},{"function":"La portée","sentence":"Ces vers permettent de penser les conditions d’une justice indépendante, plutôt que de conclure que tout jugement est nécessairement corrompu."}],"uses":[{"subject":"La justice met-elle fin à la loi du plus fort ?","function":"Montrer une institution judiciaire capturée par la puissance","reason":"Le jugement prolonge ici le rapport de force. Une justice qui prétend le corriger doit protéger l’examen des actes contre le rang de l’accusé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"La loi est-elle une garantie contre l’injustice ?","function":"Établir que l’impartialité de l’application est décisive","reason":"Une procédure reste injuste si le rang décide du verdict : la forme légale ne remplace pas l’impartialité de son application.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=33","sourceLabel":"Recueil académique · p. 33"}]},{"id":"la-fontaine-redresser-le-baton-par-le-jugement","code":"LF08","author":"La Fontaine","title":"Redresser le bâton par le jugement","work":"Un Animal dans la Lune","collection":"Fables choisies mises en vers","locator":"Livre VII, fable XVII · p. 201 (PDF p. 297)","quote":"Quand l’eau courbe un bâton ma raison le redresse,\nLa raison décide en maîtresse.","verse":true,"notions":["raison","science","verite"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le poète examine les apparences trompeuses avant de raconter comment une souris dans une lunette fut prise pour un animal lunaire.","commentary":[{"function":"Le problème","sentence":"Faut-il rejeter les sens parce que certaines apparences nous trompent ?"},{"function":"L’affirmation","sentence":"La Fontaine attribue à la raison le pouvoir de corriger le jugement immédiatement suggéré par la vue."},{"function":"Les concepts","sentence":"Le bâton paraît courbé dans l’eau sans que sa forme réelle ait changé."},{"function":"La raison","sentence":"Comprendre les conditions de l’observation permet de distinguer ce que l’on voit de ce que l’on doit en conclure."},{"function":"L’exemple","sentence":"Dans la suite du récit, l’examen de la lunette explique l’animal aperçu dans la Lune par une souris logée entre les verres."},{"function":"La portée","sentence":"La citation défend donc une perception examinée par la raison, sans établir que celle-ci connaîtrait tout indépendamment de l’expérience."}],"uses":[{"subject":"La raison est-elle plus fiable que l’expérience ?","function":"Distinguer l’observation et son interprétation","reason":"Le bâton apparent ne doit pas être pris pour une description immédiate du réel ; la raison explique l’apparence en tenant compte du milieu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Faut-il chercher la vérité au-delà des apparences ?","function":"Préciser le sens du dépassement des apparences","reason":"Dépasser la première impression consiste ici à en comprendre la cause, et non à abandonner l’observation du monde sensible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"la-fontaine-vouloir-aider-ne-suffit-pas","code":"LF09","author":"La Fontaine","title":"Vouloir aider ne suffit pas","work":"L’Ours et l’Amateur des Jardins","collection":"Fables choisies mises en vers","locator":"Livre VIII, fable X · p. 218 (PDF p. 314)","quote":"Rien n’est si dangereux qu’un ignorant ami;\nMieux vaudrait un sage ennemi.","verse":true,"notions":["devoir","raison","justice"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Pour chasser une mouche du visage de son ami endormi, l’ours lance un pavé et tue celui qu’il voulait protéger.","commentary":[{"function":"Le problème","sentence":"La bonne intention garantit-elle la valeur d’une action ?"},{"function":"L’affirmation","sentence":"La Fontaine montre qu’un ami peut devenir dangereux lorsqu’il agit sans jugement."},{"function":"Les concepts","sentence":"La bienveillance désigne la fin recherchée, tandis que la prudence examine les moyens et leurs conséquences."},{"function":"La raison","sentence":"L’ours vise un bien mais choisit un moyen qui détruit la personne à laquelle il voulait le procurer."},{"function":"L’exemple","sentence":"Le pavé lancé contre la mouche rend visible cette disproportion entre l’aide désirée et le dommage produit."},{"function":"La portée","sentence":"La formule appelle donc à joindre le discernement à l’affection, sans recommander de préférer systématiquement les ennemis aux amis."}],"uses":[{"subject":"Suffit-il que son intention soit bonne pour qu’une action soit morale ?","function":"Construire un contre-exemple à la suffisance de l’intention","reason":"L’ours veut protéger son ami mais le tue : la valeur de l’action engage aussi le discernement dans le choix des moyens et leurs effets prévisibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"},{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Distinguer la bienveillance et l’aide effectivement apportée","reason":"Le désir de rendre service devient destructeur faute de discernement ; une aide doit tenir compte de ce qu’elle fait réellement subir à son bénéficiaire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"la-fontaine-un-monde-dans-la-presence-aimee","code":"LF10","author":"La Fontaine","title":"Un monde dans la présence aimée","work":"Les Deux Pigeons","collection":"Fables choisies mises en vers","locator":"Livre IX, fable II · p. 247 (PDF p. 343)","quote":"Soyez-vous l’un à l’autre un monde toujours beau,\nToujours divers, toujours nouveau;","verse":true,"notions":["bonheur","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Après le retour du pigeon voyageur auprès de son compagnon, le narrateur s’adresse aux amants et évoque sa propre jeunesse.","commentary":[{"function":"Le problème","sentence":"Le bonheur exige-t-il de chercher sans cesse de nouveaux objets ?"},{"function":"L’affirmation","sentence":"La Fontaine invite les amants à trouver une diversité renouvelée dans leur présence réciproque."},{"function":"Les concepts","sentence":"Le mot monde fait de la relation un ensemble de découvertes, tandis que divers et nouveau empêchent de réduire la fidélité à une répétition."},{"function":"La raison","sentence":"La présence aimée peut ainsi offrir une diversité que le voyageur cherchait ailleurs ; cette possibilité demande une attention qui ne tient pas l’autre pour entièrement connu."},{"function":"L’exemple","sentence":"Au retour du voyageur, la proximité retrouvée prend ainsi un prix que l’éloignement avait fait oublier."},{"function":"La portée","sentence":"L’image permet de penser une fidélité vivante, dont le renouvellement reste compatible avec l’ouverture du couple à un monde plus vaste."}],"uses":[{"subject":"Comment être heureux, si rien ne dure ?","function":"Penser une durée qui accueille le renouvellement","reason":"La relation peut durer en restant diverse : la fidélité n’exige pas de retrouver sans cesse une expérience identique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Suffit-il d’être proche d’autrui pour le connaître ?","function":"Distinguer la familiarité et une attention renouvelée","reason":"L’autre demeure un monde à découvrir ; la proximité ne vaut connaissance que si elle laisse place à sa diversité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=80","sourceLabel":"Recueil académique · p. 80"}]},{"id":"la-fontaine-du-marbre-au-dieu","code":"LF11","author":"La Fontaine","title":"Du marbre au dieu","work":"Le Statuaire et la Statue de Jupiter","collection":"Fables choisies mises en vers","locator":"Livre IX, fable VI · p. 251 (PDF p. 349)","quote":"Qu’en fera, dit-il, mon ciseau ?\nSera-t-il Dieu, table ou cuvette ?","verse":true,"notions":["art","religion","technique"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Statuaire","situation":"Un sculpteur hésite sur la destination d’un bloc de marbre ; après avoir sculpté Jupiter, il redoute sa propre création.","commentary":[{"function":"Le problème","sentence":"Comment une matière travaillée peut-elle recevoir une puissance qui semble dépasser son fabricant ?"},{"function":"L’affirmation","sentence":"Le statuaire envisage plusieurs destinations pour le même marbre, dont celle d’une figure divine."},{"function":"Les concepts","sentence":"La matière ne détermine donc pas à elle seule la signification ni l’usage de l’objet."},{"function":"La raison","sentence":"Le choix d’une forme, puis le regard porté sur elle, peuvent faire d’une fabrication humaine une présence redoutée."},{"function":"L’exemple","sentence":"Dans le récit, le sculpteur finit par trembler devant le Jupiter qu’il vient lui-même de façonner."},{"function":"La portée","sentence":"La scène permet d’interroger les pouvoirs de l’image et la croyance en une idole, sans démontrer que toute religion serait une illusion."}],"uses":[{"subject":"Qu’est-ce qui fait d’un objet une œuvre d’art ?","function":"Distinguer la matière et la signification de la forme","reason":"Le même marbre peut recevoir des formes et des usages différents ; sa matière ne suffit donc pas à définir la valeur artistique de l’objet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"L’artiste est-il maître de son œuvre ?","function":"Montrer une création qui agit en retour sur son créateur","reason":"Le sculpteur choisit la figure mais subit ensuite l’effroi qu’elle suscite ; maîtriser la fabrication ne garantit pas de maîtriser les effets de l’œuvre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"}]},{"id":"la-fontaine-les-limites-de-la-ressemblance","code":"LF12","author":"La Fontaine","title":"Les limites de la ressemblance","work":"Le Cierge","collection":"Fables choisies mises en vers","locator":"Livre IX, fable XII · p. 258 (PDF p. 356)","quote":"Tout en tout est divers : ôtez-vous de l’esprit\nQu’aucun être ait été composé sur le vôtre.","verse":true,"notions":["raison","science","nature"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un cierge se jette dans le feu pour devenir aussi solide qu’une brique ; il fond au lieu de durcir.","commentary":[{"function":"Le problème","sentence":"Peut-on attribuer à un être les propriétés d’un autre parce qu’ils semblent comparables ?"},{"function":"L’affirmation","sentence":"La Fontaine avertit contre les raisonnements qui oublient la différence de constitution des choses."},{"function":"Les concepts","sentence":"Le mot « aucun » signifie ici quelque être que ce soit, et la composition désigne ce dont chacun est fait."},{"function":"La raison","sentence":"Un traitement favorable à une matière peut en détruire une autre si leur nature diffère."},{"function":"L’exemple","sentence":"Le cierge imite ainsi la brique durcie par le feu, mais sa cire fond dans les mêmes flammes."},{"function":"La portée","sentence":"Le récit demande donc de vérifier la pertinence d’une analogie, sans interdire toute comparaison ni toute connaissance générale."}],"uses":[{"subject":"Suffit-il de bien raisonner pour être raisonnable ?","function":"Montrer la nécessité d’examiner les prémisses","reason":"L’imitation paraît cohérente mais repose sur une fausse équivalence entre cire et argile ; la validité d’une déduction ne garantit pas ses points de départ.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"},{"subject":"Dans quels domaines est-il légitime de prendre la nature comme modèle ?","function":"Fixer une condition de pertinence du modèle","reason":"Une propriété ne se transpose pas à toute matière : l’efficacité d’un modèle dépend des différences de constitution que la ressemblance peut masquer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"la-fontaine-une-tache-commune-aux-castors","code":"LF13","author":"La Fontaine","title":"Une tâche commune aux castors","work":"Discours à Madame de La Sablière","collection":"Fables choisies mises en vers","locator":"Fin du livre IX · p. 268 (PDF p. 366)","quote":"Chaque Castor agit; commune en est la tâche;\nLe vieux y fait marcher le jeune sans relâche.","verse":true,"notions":["nature","technique","travail"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Pour discuter la réduction des animaux à des machines, le poète représente des castors organisant ensemble la construction de leurs ouvrages.","commentary":[{"function":"Le problème","sentence":"L’activité organisée et la construction d’ouvrages appartiennent-elles exclusivement aux humains ?"},{"function":"L’affirmation","sentence":"La Fontaine décrit des castors dont les actions particulières participent à une tâche commune."},{"function":"Les concepts","sentence":"Le travail collectif suppose ici une articulation des activités qui dépasse la simple juxtaposition de mouvements."},{"function":"La raison","sentence":"La coordination des tâches oblige à demander si leur résultat s’explique par la seule juxtaposition de mouvements mécaniques."},{"function":"L’exemple","sentence":"Le poète représente l’ancien faisant travailler le jeune pour donner à voir cette organisation."},{"function":"La portée","sentence":"Le récit adresse ainsi une objection au modèle de l’animal-machine ; sa portée argumentative dépend d’un examen des conduites animales réelles."}],"uses":[{"subject":"La technique est-elle le propre de l’homme ?","function":"Mettre à l’épreuve une définition exclusivement humaine","reason":"L’image des bâtisseurs animaux oblige à préciser si la technique se définit par l’ouvrage produit, l’organisation ou la conscience du projet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"},{"subject":"L’homme est-il une exception dans la nature ?","function":"Discuter le monopole humain de l’activité organisée","reason":"Le poème attribue une tâche commune aux castors ; s’en servir pour poser une question conceptuelle, sans transformer l’anthropomorphisme en observation scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"la-fontaine-lutilite-deguisee-en-justice","code":"LF14","author":"La Fontaine","title":"L’utilité déguisée en justice","work":"L’Homme et la Couleuvre","collection":"Fables choisies mises en vers","locator":"Livre X, fable I · p. 275 (PDF p. 375)","quote":"Mes jours sont en tes mains, tranche-les : ta justice,\nC’est ton utilité, ton plaisir, ton caprice;","verse":true,"notions":["justice","nature","devoir"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"La Couleuvre","situation":"Capturée par un homme qui invoque son droit de la tuer, la couleuvre conteste la justice de celui qui dispose d’elle.","commentary":[{"function":"Le problème","sentence":"Celui qui peut imposer une décision possède-t-il pour autant une raison juste de le faire ?"},{"function":"L’affirmation","sentence":"La couleuvre accuse l’homme de donner le nom de justice à son intérêt personnel."},{"function":"Les concepts","sentence":"La puissance de disposer d’un être se distingue d’un droit fondé sur une règle impartiale."},{"function":"La raison","sentence":"Un jugement devient arbitraire si celui qui le prononce le mesure seulement à son utilité ou à son plaisir."},{"function":"L’exemple","sentence":"Dans la fable, l’homme sollicite des témoignages mais finit par tuer malgré les accusations portées contre lui."},{"function":"La portée","sentence":"La réplique invite donc à examiner la légitimité de notre pouvoir sur les vivants, sans supposer que la nature parle réellement comme un tribunal."}],"uses":[{"subject":"La relation entre l’humanité et la nature implique-t-elle un rapport de domination ?","function":"Faire entendre le point de vue du vivant dominé","reason":"La capacité humaine de disposer d’un vivant n’établit pas le droit de le traiter selon notre seule utilité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"},{"subject":"Avons-nous des devoirs envers la nature ?","function":"Interroger l’intérêt humain comme unique mesure","reason":"La contestation du reptile oblige à demander si notre utilité suffit à justifier le traitement d’autres vivants ; la personnification sert l’examen moral.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"}]},{"id":"la-fontaine-planter-pour-ceux-qui-viendront","code":"LF15","author":"La Fontaine","title":"Planter pour ceux qui viendront","work":"Le Vieillard et les trois jeunes Hommes","collection":"Fables choisies mises en vers","locator":"Livre XI, fable VIII · p. 309 (PDF p. 409)","quote":"Mes arrière-neveux me devront cet ombrage :","verse":true,"notions":["temps","devoir","bonheur"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Vieillard","situation":"Un octogénaire plante un arbre ; trois jeunes gens lui reprochent de travailler pour un avenir dont il ne jouira pas.","commentary":[{"function":"Le problème","sentence":"Une action perd-elle son sens si son auteur ne profite pas lui-même de ses fruits ?"},{"function":"L’affirmation","sentence":"Le vieillard justifie sa plantation par l’ombre dont bénéficieront les générations futures."},{"function":"Les concepts","sentence":"Ses « arrière-neveux » désignent ici la postérité, et non les seuls enfants de ses neveux."},{"function":"La raison","sentence":"Le bien visé peut dépasser la durée d’une vie sans cesser de donner un sens à l’action présente."},{"function":"L’exemple","sentence":"L’arbre planté aujourd’hui rend possible un repos futur pour des personnes que le planteur ne connaîtra pas."},{"function":"La portée","sentence":"Ce vers permet ainsi de penser la responsabilité envers l’avenir et une joie de contribuer, sans confondre toute prévoyance avec une obligation absolue."}],"uses":[{"subject":"Sommes-nous responsables de l’avenir ?","function":"Étendre l’horizon des destinataires de l’action","reason":"Le vieillard agit pour une postérité absente : sa responsabilité porte sur les conditions de vie qu’il laissera, au-delà de son bénéfice immédiat.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Agir par devoir est-ce agir contre son intérêt ?","function":"Distinguer profit personnel et joie de contribuer","reason":"Le planteur ne profitera pas de l’ombre mais éprouve la joie de contribuer au bien d’autrui ; le devoir ne supprime donc pas nécessairement tout intérêt personnel.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"la-fontaine-tailler-les-desirs-ou-detruire-la-vie","code":"LF16","author":"La Fontaine","title":"Tailler les désirs ou détruire la vie","work":"Le Philosophe scythe","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XX · p. 349 (PDF p. 459)","quote":"Ils ôtent à nos cœurs le principal ressort;\nIls font cesser de vivre avant que l’on soit mort.","verse":true,"notions":["raison","bonheur","liberte"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Un philosophe taille tous ses arbres sans discernement ; le narrateur y voit l’image de ceux qui veulent supprimer tous les désirs.","commentary":[{"function":"Le problème","sentence":"La maîtrise des passions exige-t-elle leur suppression complète ?"},{"function":"L’affirmation","sentence":"La Fontaine reproche à une discipline excessive de détruire les forces mêmes qui animent l’existence."},{"function":"Les concepts","sentence":"Le « ressort » désigne l’élan du désir, tandis que vivre ne signifie pas ici seulement conserver ses fonctions biologiques."},{"function":"La raison","sentence":"Retrancher indistinctement les désirs nuisibles et les souhaits innocents fait disparaître ce qui donnait un prix à l’action."},{"function":"L’exemple","sentence":"Le jardin ravagé par une taille aveugle figure cette vie appauvrie au nom de son amélioration."},{"function":"La portée","sentence":"Les vers critiquent donc un ascétisme sans discernement, représenté par un stoïcien excessif, et non toute la philosophie stoïcienne ni toute maîtrise de soi."}],"uses":[{"subject":"Être raisonnable, est-ce faire taire ses désirs ?","function":"Distinguer le discernement et la suppression indifférenciée","reason":"Le jardin ravagé montre le coût d’une suppression indifférenciée : régler les désirs demande de reconnaître ceux qui nuisent et ceux qui font vivre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Le bonheur consiste-t-il à ne plus rien désirer ?","function":"Contester un idéal de tranquillité obtenu par l’appauvrissement","reason":"L’absence de trouble n’est pas encore le bonheur si la discipline a supprimé jusqu’aux désirs qui donnaient un prix à l’existence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"la-fontaine-un-adieu-qui-ne-peut-plus-se-dire","code":"LF17","author":"La Fontaine","title":"Un adieu qui ne peut plus se dire","work":"Philémon et Baucis","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXV · p. 360 (PDF p. 470)","quote":"L’un et l’autre se dit adieu de la pensée :\nLe corps n’est tantôt plus que feuillage et que bois.","verse":true,"notions":["langage","conscience","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Philémon et Baucis, vieillards unis par l’amour, se transforment en arbres ; leur métamorphose empêche les paroles et les gestes d’adieu.","commentary":[{"function":"Le problème","sentence":"La disparition de la parole rend-elle toute pensée impossible ?"},{"function":"L’affirmation","sentence":"La Fontaine imagine deux êtres qui se disent intérieurement adieu lorsque leur corps ne peut plus parler."},{"function":"Les concepts","sentence":"La pensée de l’autre se distingue ici de son expression par des mots ou des gestes."},{"function":"La raison","sentence":"L’écorce qui gagne le corps empêche la manifestation de l’amour sans que le récit fasse aussitôt disparaître cet amour."},{"function":"L’exemple","sentence":"Philémon veut tendre les bras et parler à Baucis, mais leur transformation laisse seulement subsister l’adieu pensé."},{"function":"La portée","sentence":"Ces vers donnent ainsi une forme sensible à la distinction entre pensée et expression, sans prouver une communication effective des consciences sans langage."}],"uses":[{"subject":"Peut-on séparer penser et parler ?","function":"Distinguer la vie intérieure et son expression corporelle","reason":"La métamorphose figure une pensée qui subsiste quand la parole devient impossible ; utiliser la fiction pour préciser la distinction, non pour fournir une preuve.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Les mots peuvent-ils nous manquer pour dire quelque chose ?","function":"Montrer une expérience qui excède la possibilité de la dire","reason":"L’adieu demeure pensé mais ne peut plus être exprimé ; la relation perd quelque chose lorsque le corps ne permet plus de le manifester.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"}]},{"id":"la-fontaine-laisser-reposer-leau","code":"LF18","author":"La Fontaine","title":"Laisser reposer l’eau","work":"Le Juge arbitre, l’Hospitalier, et le Solitaire","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXIX · p. 389 (PDF p. 501)","quote":"Mes Frères, dit le Saint, laissez-la reposer,\nVous verrez alors votre image.","verse":true,"notions":["conscience","temps"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le Solitaire","situation":"À deux amis absorbés par leurs tâches, le solitaire montre une eau agitée qui ne peut refléter leur visage avant de s’apaiser.","commentary":[{"function":"Le problème","sentence":"L’agitation des activités permet-elle de se connaître soi-même ?"},{"function":"L’affirmation","sentence":"Le solitaire propose à ses amis de laisser reposer l’eau pour y retrouver leur image."},{"function":"Les concepts","sentence":"La surface troublée figure une attention dispersée qui ne distingue plus ce qu’elle cherche à observer."},{"function":"La raison","sentence":"Le retour à soi demande alors une interruption des sollicitations, comme le reflet exige que la vase cesse de masquer l’eau."},{"function":"L’exemple","sentence":"Les deux amis doivent attendre au lieu d’agiter davantage la source pour tenter de mieux s’y voir."},{"function":"La portée","sentence":"L’image invite donc à ménager un temps de réflexion, sans faire de l’abandon des devoirs envers autrui une règle générale."}],"uses":[{"subject":"Peut-on se connaître soi-même ?","function":"Décrire une condition d’attention à soi","reason":"Le reflet exige une eau calme. De même, un recul temporaire permet d’examiner ses actes avec davantage de lucidité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"},{"subject":"Faut-il toujours chercher à gagner du temps ?","function":"Montrer la fécondité d’une interruption","reason":"Attendre que l’eau repose rend possible ce qu’une activité accrue empêchait. Le temps consacré à comprendre n’est donc pas nécessairement du temps perdu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"la-fontaine-le-temps-qui-rend-les-plaisirs","code":"LF19","author":"La Fontaine","title":"Le temps qui rend les plaisirs","work":"La Jeune Veuve","collection":"Fables choisies mises en vers","locator":"Livre VI, fable XXI · p. 170 (PDF p. 260)","quote":"Sur les ailes du Temps la tristesse s’envole;\nLe Temps ramène les plaisirs.","verse":true,"notions":["temps","bonheur","conscience"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Le narrateur","situation":"Le narrateur annonce l’histoire d’une jeune veuve dont le chagrin se transforme progressivement et qui envisage une nouvelle union.","commentary":[{"function":"Le problème","sentence":"Le temps ne fait-il que nous retirer ce que nous aimons ?"},{"function":"L’affirmation","sentence":"La Fontaine lui attribue aussi le pouvoir de diminuer la tristesse et de rouvrir la possibilité des plaisirs."},{"function":"Les concepts","sentence":"La durée ne désigne donc pas seulement une succession de pertes, mais une transformation de notre manière de sentir."},{"function":"La raison","sentence":"Un état affectif qui semble occuper toute l’existence présente peut cesser d’en déterminer chaque moment."},{"function":"L’exemple","sentence":"Le récit montre ainsi une veuve passant du désespoir à la perspective d’une nouvelle union."},{"function":"La portée","sentence":"Ces vers invitent à penser une puissance réparatrice du temps, sans promettre que toute souffrance disparaît ni fixer une durée au deuil."}],"uses":[{"subject":"Le temps est-il nécessairement destructeur ?","function":"Opposer à la perte une transformation réparatrice","reason":"Le temps atténue la tristesse et rend les plaisirs possibles : son pouvoir de transformation ne se réduit pas à détruire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Sommes-nous condamnés à subir le temps ?","function":"Nuancer l’assimilation de toute passivité à un mal","reason":"Une transformation que l’on ne commande pas entièrement peut rouvrir la vie ; subir le passage du temps n’est donc pas toujours subir un mal.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"la-fontaine-entendre-ce-que-lon-soupconne","code":"LF20","author":"La Fontaine","title":"Entendre ce que l’on soupçonne","work":"Les Filles de Minée","collection":"Fables choisies mises en vers","locator":"Livre XII, fable XXVIII · p. 380 (PDF p. 490)","quote":"Elle croit y trouver, non le sens qu’ils cachaient,\nMais celui seulement que ses soupçons cherchaient.","verse":true,"notions":["langage","verite","conscience"],"edition":"Édition de Georges Couton, Classiques Garnier","publisher":"Bordas","editionYear":1990,"translator":null,"originalLanguage":"français","speaker":"Clymène","situation":"Clymène raconte Procris, qui prend l’appel de Céphale à la brise pour celui d’une rivale.","commentary":[{"function":"Le problème","sentence":"Comprendre une parole consiste-t-il à y retrouver ce que l’on attendait déjà ?"},{"function":"L’affirmation","sentence":"Clymène raconte comment Procris prête aux paroles de Céphale le sens que lui suggère sa jalousie."},{"function":"Les concepts","sentence":"L’interprétation se distingue ici d’une découverte lorsque le soupçon fournit d’avance la réponse recherchée."},{"function":"La raison","sentence":"La passion sélectionne ce qui paraît confirmer sa crainte au lieu d’examiner les autres significations possibles."},{"function":"L’exemple","sentence":"Céphale invoque la brise pour se rafraîchir, mais Procris entend l’appel d’une femme aimée."},{"function":"La portée","sentence":"Le récit invite donc à confronter une interprétation à ses raisons et à son contexte, sans conclure que toute compréhension serait impossible."}],"uses":[{"subject":"Suffirait-il de parler la même langue pour se comprendre ?","function":"Montrer un obstacle affectif à la compréhension","reason":"Procris connaît les mots mais leur donne un sens dicté par sa jalousie ; le partage de la langue ne garantit pas l’examen du contexte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Toutes les interprétations se valent-elles ?","function":"Distinguer l’interprétation étayée et la confirmation d’un soupçon","reason":"La lecture jalouse néglige le contexte des paroles : les raisons qui soutiennent une interprétation valent davantage que la force du soupçon.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=77","sourceLabel":"Recueil académique · p. 77"}]},{"id":"rousseau-la-menace-et-le-coup","code":"RR01","author":"Rousseau","title":"La menace et le coup","work":"Les Rêveries du promeneur solitaire","locator":"Première promenade · p. 7 (PDF p. 79)","quote":"Leur attente me tourmente cent fois plus que leur présence, et la menace m’est plus terrible que le coup.","notions":["temps","bonheur","conscience"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Rousseau compare les maux qu’il éprouve à ceux que son imagination lui fait redouter.","commentary":[{"function":"Le problème","sentence":"Un mal encore absent peut-il nous affecter davantage qu’une souffrance présente ?"},{"function":"L’affirmation","sentence":"Rousseau décrit une attente qui amplifie les maux au point de devenir plus pénible que leur arrivée."},{"function":"Les concepts","sentence":"La menace désigne une possibilité imaginée, tandis que le coup désigne le mal effectivement éprouvé."},{"function":"La raison","sentence":"L’imagination multiplie les conséquences possibles là où l’événement réel finit par imposer ses limites."},{"function":"L’exemple","sentence":"L’annonce d’un échec peut ainsi occuper tout notre esprit avant même que nous sachions ce qui arrivera."},{"function":"La portée","sentence":"La comparaison invite à distinguer la souffrance actuelle de son anticipation, sans nier la gravité des maux réels."}],"uses":[{"subject":"L’imagination est-elle la cause de notre malheur ?","function":"Montrer comment une possibilité devient une souffrance présente","reason":"L’attente amplifie le mal redouté, mais ce mécanisme ne suffit pas à expliquer les douleurs produites par les événements eux-mêmes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"Est-il possible de vivre au présent ?","function":"Identifier ce qui nous arrache au présent","reason":"Un mal futur seulement possible peut occuper toute la vie présente ; la prévision devient une emprise lorsqu’elle empêche de répondre à ce qui arrive.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"rousseau-apprendre-trop-tard","code":"RR02","author":"Rousseau","title":"Apprendre trop tard","work":"Les Rêveries du promeneur solitaire","locator":"Troisième promenade · p. 38 (PDF p. 110)","quote":"Est-il tems au moment qu’il faut mourir, d’apprendre comment on auroit dû vivre?","notions":["temps","raison","bonheur"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Reprenant l’idée d’apprendre en vieillissant, Rousseau interroge l’usage d’une sagesse acquise à la fin de la vie.","commentary":[{"function":"Le problème","sentence":"Une leçon conserve-t-elle toute sa valeur lorsqu’il ne reste plus de temps pour la mettre en pratique ?"},{"function":"L’affirmation","sentence":"Rousseau demande ce que peut encore une connaissance de la vie acquise au moment de la quitter."},{"function":"Les concepts","sentence":"La sagesse ne consiste pas seulement à comprendre après coup, mais aussi à pouvoir orienter sa conduite."},{"function":"La raison","sentence":"Un savoir peut arriver trop tard pour transformer les choix auxquels il aurait donné un autre sens."},{"function":"L’exemple","sentence":"Comprendre au terme d’une existence ce qui méritait notre attention ne permet pas de recommencer toutes les années écoulées."},{"function":"La portée","sentence":"La question fait donc du moment de l’apprentissage un problème philosophique, sans retirer toute valeur à une compréhension tardive."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Introduire la condition temporelle de leur usage","reason":"Une connaissance utile par son contenu peut devenir difficile à employer si elle arrive lorsque l’action n’est plus possible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Quelles leçons pouvons-nous tirer de nos expériences ?","function":"Interroger le décalage entre l’expérience et sa leçon","reason":"Une leçon tardive ne permet pas de recommencer sa vie, mais peut encore orienter les décisions pour lesquelles il reste du temps.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"rousseau-ce-qui-me-convient-est-il-vrai","code":"RR03","author":"Rousseau","title":"Ce qui me convient est-il vrai","work":"Les Rêveries du promeneur solitaire","locator":"Troisième promenade · p. 53 (PDF p. 125)","quote":"Pour croire que les choses sont ainsi suffit-il qu’elles me conviennent?","notions":["verite","religion","raison"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"En examinant ses convictions religieuses, Rousseau distingue leur pouvoir de consolation des raisons de les tenir pour vraies.","commentary":[{"function":"Le problème","sentence":"Le réconfort qu’apporte une croyance suffit-il à justifier son contenu ?"},{"function":"L’affirmation","sentence":"Rousseau interroge la tentation de croire une proposition parce qu’elle répond à ses besoins."},{"function":"Les concepts","sentence":"La convenance désigne ici l’accord avec nos désirs, tandis que la vérité concerne ce qui est réellement."},{"function":"La raison","sentence":"Une raison de souhaiter qu’une idée soit vraie n’établit pas encore qu’elle le soit."},{"function":"L’exemple","sentence":"Espérer une justice après la mort peut consoler sans constituer, par ce seul effet, une preuve de son existence."},{"function":"La portée","sentence":"Cette exigence critique traverse son examen de la foi, sans signifier qu’il abandonne finalement toute conviction religieuse."}],"uses":[{"subject":"La religion a-t-elle pour but de consoler les hommes ?","function":"Séparer une fonction de la religion et la justification de ses croyances","reason":"Le soulagement peut expliquer l’attachement à une croyance ; il ne tranche pas à lui seul la question de sa vérité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Mettre en question une adhésion fondée sur le réconfort","reason":"Une croyance peut rassurer tout en demandant des raisons : le réconfort et la justification sont deux propriétés distinctes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"}]},{"id":"rousseau-inventer-sans-mentir","code":"RR04","author":"Rousseau","title":"Inventer sans mentir","work":"Les Rêveries du promeneur solitaire","locator":"Quatrième promenade · p. 85 (PDF p. 157)","quote":"J’ai souvent débité bien des fables, mais j’ai très rarement menti.","notions":["verite","art","devoir"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Rousseau examine les inventions de ses récits et leur différence avec la tromperie, puis reconnaît une exigence de vérité envers soi.","commentary":[{"function":"Le problème","sentence":"Toute parole qui s’écarte des faits constitue-t-elle un mensonge ?"},{"function":"L’affirmation","sentence":"Rousseau distingue les fables qu’il raconte des mensonges par lesquels on trompe injustement quelqu’un."},{"function":"Les concepts","sentence":"L’invention concerne le contenu du récit, tandis que le mensonge engage aussi une intention et une relation à autrui."},{"function":"La raison","sentence":"Un récit reconnu comme imaginaire ne produit pas la même tromperie qu’un fait inventé présenté comme certain."},{"function":"L’exemple","sentence":"Une fable annoncée comme telle peut instruire son lecteur sans lui faire croire que les animaux parlent réellement."},{"function":"La portée","sentence":"La distinction éclaire la fiction, mais Rousseau reconnaît ensuite que l’ornement du récit peut aussi nuire à sa propre fidélité au vrai."}],"uses":[{"subject":"Peut-on reprocher à l’art d’être mensonger ?","function":"Distinguer invention reconnue et tromperie","reason":"Une fiction annoncée comme telle n’impose pas son récit comme un fait réel ; l’écart aux faits ne suffit donc pas à constituer un mensonge.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=10","sourceLabel":"Recueil académique · p. 10"},{"subject":"Faut-il toujours dire la vérité ?","function":"Préciser ce qui est en jeu dans l’exigence de vérité","reason":"La phrase invite à examiner l’intention et les effets de la parole ; elle ne dispense pas d’une exigence de sincérité envers soi-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"rousseau-le-calme-vivant","code":"RR05","author":"Rousseau","title":"Le calme vivant","work":"Les Rêveries du promeneur solitaire","locator":"Cinquième promenade · p. 102 (PDF p. 174)","quote":"Sans mouvement, la vie n’est qu’une letargie.","notions":["bonheur","temps","nature"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"À propos de la rêverie au bord du lac, Rousseau décrit le mouvement modéré qui accompagne une tranquillité heureuse.","commentary":[{"function":"Le problème","sentence":"La tranquillité heureuse se confond-elle avec une absence complète de mouvement ?"},{"function":"L’affirmation","sentence":"Rousseau soutient qu’une vie entièrement immobile tomberait dans une forme d’engourdissement."},{"function":"Les concepts","sentence":"La léthargie désigne ici l’effacement du sentiment de vivre, distinct du calme d’une conscience éveillée."},{"function":"La raison","sentence":"Un mouvement doux et régulier peut entretenir ce sentiment sans provoquer les inquiétudes d’une agitation excessive."},{"function":"L’exemple","sentence":"Le bruit des vagues et les variations paisibles du lac accompagnent ainsi sa rêverie au lieu de la disperser."},{"function":"La portée","sentence":"Il s’agit donc de chercher une tranquillité vivante, sans faire de l’activité incessante une condition du bonheur."}],"uses":[{"subject":"Le bonheur se trouve-t-il dans le repos ?","function":"Distinguer le repos de l’engourdissement","reason":"Le calme heureux de la rêverie demeure soutenu par un mouvement sensible ; le repos ne se confond pas avec l’extinction du sentiment de vivre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Vivre et exister, est-ce la même chose ?","function":"Introduire la question du sentiment de vivre","reason":"L’opposition entre mouvement et léthargie permet d’examiner la présence à son existence ; elle ne fournit pas une définition biologique de la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=102","sourceLabel":"Recueil académique · p. 102"}]},{"id":"rousseau-la-dette-et-le-don","code":"RR06","author":"Rousseau","title":"La dette et le don","work":"Les Rêveries du promeneur solitaire","locator":"Sixième promenade · p. 113 (PDF p. 193)","quote":"Quand je paye une dette c’est un devoir que je remplis; quand je fais un don c’est un plaisir que je me donne.","notions":["devoir","liberte","bonheur"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Rousseau compare le service librement offert et l’attente qui finit par le transformer en obligation.","commentary":[{"function":"Le problème","sentence":"Accomplir une obligation et faire spontanément plaisir à quelqu’un sont-ils vécus de la même manière ?"},{"function":"L’affirmation","sentence":"Rousseau oppose le devoir de payer une dette au plaisir qu’il éprouve à faire un don."},{"function":"Les concepts","sentence":"La dette implique une obligation préalable, tandis que le don se présente ici comme une initiative libre."},{"function":"La raison","sentence":"Une attente imposée peut changer le sens affectif du même geste en faisant disparaître sa spontanéité."},{"function":"L’exemple","sentence":"Le service autrefois offert avec joie peut devenir pesant lorsque son bénéficiaire le réclame comme un dû."},{"function":"La portée","sentence":"Cette différence ne rend pas devoir et plaisir incompatibles, puisque Rousseau ajoute que l’habitude de la vertu peut les réunir."}],"uses":[{"subject":"Faire son devoir exclut-il tout plaisir ?","function":"Distinguer une opposition vécue et une incompatibilité de principe","reason":"La dette et le don ne procurent pas ici le même plaisir, mais la suite admet un plaisir propre à l’exercice habituel du devoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"},{"subject":"Peut-on rester libre et se sentir obligé ?","function":"Examiner le passage de l’initiative à l’exigence","reason":"Une obligation ressentie comme pesante peut aussi être reconnue et voulue ; la contrainte éprouvée ne décrit pas à elle seule la valeur de l’engagement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"rousseau-soublier-pour-mediter","code":"RR07","author":"Rousseau","title":"S’oublier pour méditer","work":"Les Rêveries du promeneur solitaire","locator":"Septième promenade · p. 135 (PDF p. 215)","quote":"Je ne médite, je ne rêve jamais plus délicieusement que quand je m’oublie moi-même.","notions":["conscience","nature","bonheur"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"La contemplation des plantes détourne Rousseau de ses intérêts personnels et lui donne le sentiment de participer à la nature entière.","commentary":[{"function":"Le problème","sentence":"La conscience doit-elle toujours se prendre elle-même pour centre ?"},{"function":"L’affirmation","sentence":"Rousseau décrit une méditation plus heureuse lorsqu’il cesse de se préoccuper de lui-même."},{"function":"Les concepts","sentence":"S’oublier signifie ici suspendre ses intérêts particuliers, sans perdre toute conscience de ce qui est éprouvé."},{"function":"La raison","sentence":"L’attention devient disponible pour les êtres environnants lorsque les soucis personnels cessent de l’occuper entièrement."},{"function":"L’exemple","sentence":"Au milieu des plantes, il se sent participer à un ensemble qui dépasse les limites de son histoire individuelle."},{"function":"La portée","sentence":"Le passage permet de penser une ouverture de la conscience au monde, plutôt que son abolition dans une inconscience heureuse."}],"uses":[{"subject":"La conscience n’est-elle tournée que vers elle-même ?","function":"Montrer une conscience ouverte au monde","reason":"Rousseau ne cesse pas de sentir : il décrit une attention libérée de la préoccupation personnelle et dirigée vers la nature.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"L’inconscience est-elle la condition du bonheur ?","function":"Distinguer oubli de soi et disparition de la conscience","reason":"La rêverie demeure une expérience consciente ; le bonheur peut demander de moins se préoccuper de soi sans ne plus rien éprouver.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}]},{"id":"rousseau-un-fragment-pour-retrouver-un-monde","code":"RR08","author":"Rousseau","title":"Un fragment pour retrouver un monde","work":"Les Rêveries du promeneur solitaire","locator":"Septième promenade · p. 151 (PDF p. 231)","quote":"Les fragmens des plantes que j’y ai cueillies suffisent pour me rappeller tout ce magnifique spectacle.","notions":["temps","conscience","nature"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Feuilleter son herbier permet à Rousseau de retrouver par le souvenir les paysages de ses anciennes excursions.","commentary":[{"function":"Le problème","sentence":"Comment un objet minuscule peut-il rendre présent tout un moment disparu ?"},{"function":"L’affirmation","sentence":"Rousseau décrit des fragments de plantes qui réveillent le souvenir d’un paysage entier."},{"function":"Les concepts","sentence":"La trace matérielle conservée se distingue du passé lui-même, mais elle peut en relancer l’évocation."},{"function":"La raison","sentence":"Les sensations et les circonstances associées à la plante donnent au fragment une richesse absente de sa seule apparence."},{"function":"L’exemple","sentence":"Une feuille de son herbier fait ainsi revenir les bois, les rochers et les eaux aperçus lors de la cueillette."},{"function":"La portée","sentence":"Le passage montre une médiation matérielle de la mémoire, sans garantir que le souvenir restitue intégralement les faits passés."}],"uses":[{"subject":"Tout s’en va-t-il avec le temps ?","function":"Distinguer disparition et possibilité de remémoration","reason":"Le paysage ne subsiste pas dans le fragment, mais une trace permet d’en retrouver l’expérience par la mémoire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Pourquoi revenir sur le passé ?","function":"Montrer un retour qui enrichit l’expérience présente","reason":"L’herbier réveille les sensations d’un monde disparu : revenir au passé peut enrichir le présent sans constituer un retour réel en arrière.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}]},{"id":"rousseau-combattre-lopinion-sous-son-joug","code":"RR09","author":"Rousseau","title":"Combattre l’opinion sous son joug","work":"Les Rêveries du promeneur solitaire","locator":"Huitième promenade · p. 159–160 (PDF p. 239–240)","quote":"Quand je m’élevois avec tant d’ardeur contre l’opinion, je portois encor son joug sans que je m’en apperçusse.","notions":["liberte","conscience","raison"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Rousseau reconnaît que son opposition au jugement public conservait encore le désir d’en obtenir une appréciation favorable.","commentary":[{"function":"Le problème","sentence":"S’opposer au jugement des autres suffit-il à devenir indépendant de lui ?"},{"function":"L’affirmation","sentence":"Rousseau reconnaît avoir porté le joug de l’opinion au moment même où il la combattait."},{"function":"Les concepts","sentence":"L’opposition manifeste un refus, tandis que l’indépendance demande de ne plus régler entièrement sa conduite sur le jugement combattu."},{"function":"La raison","sentence":"Celui qui veut avant tout faire reconnaître son mépris demeure attaché à l’approbation de ceux auxquels il s’oppose."},{"function":"L’exemple","sentence":"Rousseau découvre ainsi que son ardeur contre le public conservait un souci de l’estime publique."},{"function":"La portée","sentence":"Cette analyse invite à examiner les motifs d’une révolte, sans assimiler toute contestation à une dépendance cachée."}],"uses":[{"subject":"Suffit-il de se sentir libre pour l’être ?","function":"Opposer le sentiment d’indépendance à l’examen de ses motifs","reason":"La contestation peut procurer une impression de liberté alors que le jugement rejeté continue de commander la conduite.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"Peut-on être soi-même sans les autres ?","function":"Examiner une dépendance qui subsiste dans le refus","reason":"Combattre l’opinion peut encore maintenir sous son regard ; être en relation avec autrui ne signifie pourtant pas devoir régler sa vie sur son approbation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=82","sourceLabel":"Recueil académique · p. 82"}]},{"id":"rousseau-se-recueillir-pour-aimer","code":"RR10","author":"Rousseau","title":"Se recueillir pour aimer","work":"Les Rêveries du promeneur solitaire","locator":"Dixième promenade · p. 208 (PDF p. 288)","quote":"J’ai besoin de me recueillir pour aimer.","notions":["conscience","bonheur","liberte"],"edition":"Édition critique publiée par John S. Spink, d’après les manuscrits autographes","publisher":"Librairie Marcel Didier","editionYear":1948,"translator":null,"originalLanguage":"français","situation":"Évoquant Mme de Warens, Rousseau relie le calme de la solitude à la possibilité de laisser croître ses sentiments affectueux.","commentary":[{"function":"Le problème","sentence":"Le retrait dans la solitude éloigne-t-il nécessairement des autres ?"},{"function":"L’affirmation","sentence":"Rousseau présente le recueillement comme une condition de son affection."},{"function":"Les concepts","sentence":"Se recueillir consiste ici à rassembler son attention, tandis qu’aimer suppose de se rendre disponible à un autre être."},{"function":"La raison","sentence":"Le tumulte disperse les sentiments que le calme permet au contraire d’éprouver et de laisser croître."},{"function":"L’exemple","sentence":"En évoquant sa vie auprès de Mme de Warens, il associe ainsi la retraite champêtre à l’intimité affective."},{"function":"La portée","sentence":"Sa phrase montre une solitude qui prépare la relation, sans établir qu’il faudrait toujours être seul pour aimer."}],"uses":[{"subject":"La solitude est-elle sans valeur ?","function":"Montrer la valeur relationnelle d’un retrait","reason":"Le recueillement permet de mieux aimer : la solitude peut soutenir un lien au lieu de le supprimer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=82","sourceLabel":"Recueil académique · p. 82"}]},{"id":"rousseau-etre-autre-sans-etre-meilleur","code":"RC01","author":"Rousseau","title":"Être autre sans être meilleur","work":"Les Confessions","locator":"Livre I · p. 43 (PDF p. 47)","quote":"Si je ne vaux pas mieux, au moins je suis autre.","notions":["conscience","justice"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Au seuil de son autoportrait, Rousseau affirme sa singularité sans la confondre avec une supériorité morale.","commentary":[{"function":"Le problème","sentence":"Reconnaître une différence entre les personnes oblige-t-il à les classer ?"},{"function":"L’affirmation","sentence":"Rousseau affirme être autre, même s’il ne vaut pas mieux que les autres hommes."},{"function":"Les concepts","sentence":"La singularité désigne une manière propre d’exister, tandis que la supériorité suppose une comparaison selon un critère de valeur."},{"function":"La raison","sentence":"Une vie peut donc mériter d’être comprise dans sa particularité sans être proposée comme un modèle."},{"function":"L’exemple","sentence":"Le projet des Confessions donne ainsi à lire des fautes et des contradictions aussi bien que des qualités."},{"function":"La portée","sentence":"La formule permet de distinguer la connaissance d’une personne de son classement moral, sans dispenser de juger ses actes."}],"uses":[{"subject":"Pour être soi-même, faut-il se différencier des autres ?","function":"Distinguer singularité et recherche de supériorité","reason":"La singularité d’une histoire ne se réduit pas à la recherche d’une supériorité ; être soi-même n’exige pas de se rendre meilleur que tous les autres.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=82","sourceLabel":"Recueil académique · p. 82"},{"subject":"Les différences sont-elles des inégalités ?","function":"Dissocier différence et hiérarchie de valeur","reason":"Être autre ne signifie pas valoir davantage : une différence ne devient une inégalité qu’au regard d’un critère de comparaison déterminé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}]},{"id":"rousseau-sentir-avant-de-penser","code":"RC02","author":"Rousseau","title":"Sentir avant de penser","work":"Les Confessions","locator":"Livre I · p. 46 (PDF p. 50)","quote":"Je sentis avant de penser : c’est le sort commun de l’humanité.","notions":["conscience","raison"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Rousseau évoque les émotions éveillées par ses premières lectures avant qu’il sache clairement comprendre ce qu’il éprouvait.","commentary":[{"function":"Le problème","sentence":"Notre vie intérieure commence-t-elle par des idées clairement comprises ?"},{"function":"L’affirmation","sentence":"Rousseau affirme avoir d’abord senti avant de pouvoir penser ce qu’il éprouvait."},{"function":"Les concepts","sentence":"Sentir désigne ici une expérience affective, tandis que penser implique une élaboration plus distincte de ses objets."},{"function":"La raison","sentence":"Les émotions peuvent nous atteindre avant que nous sachions les expliquer ou en reconnaître les causes."},{"function":"L’exemple","sentence":"Les romans lus dans son enfance lui font ainsi éprouver des passions dont il ne possède pas encore l’expérience vécue."},{"function":"La portée","sentence":"Cette évocation souligne la profondeur affective de la pensée, sans démontrer à elle seule une loi scientifique du développement humain."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Interroger la dépendance de la pensée à la sensibilité","reason":"L’émotion précède ici la pensée réfléchie, mais cette antériorité affective ne décide pas de la validité des raisonnements ultérieurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"L’art transforme-t-il notre conscience du réel ?","function":"Montrer une formation de la sensibilité par la fiction","reason":"Les lectures éveillent des affects avant l’expérience des situations racontées ; l’œuvre modifie ainsi les manières de percevoir et d’attendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"}]},{"id":"rousseau-laveu-et-la-honte","code":"RC03","author":"Rousseau","title":"L’aveu et la honte","work":"Les Confessions","locator":"Livre I · p. 55 (PDF p. 59)","quote":"Ce n’est pas ce qui est criminel qui coûte le plus à dire, c’est ce qui est ridicule et honteux.","notions":["conscience","verite","devoir"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Après un aveu intime, Rousseau remarque que la peur du ridicule peut rendre une confession plus difficile que celle d’une faute.","commentary":[{"function":"Le problème","sentence":"La difficulté d’un aveu mesure-t-elle la gravité de ce que nous avons fait ?"},{"function":"L’affirmation","sentence":"Rousseau soutient que le ridicule et la honte peuvent coûter davantage à dire que le crime."},{"function":"Les concepts","sentence":"La honte concerne notamment l’image de soi exposée au regard d’autrui, tandis que la culpabilité concerne une faute commise."},{"function":"La raison","sentence":"La crainte d’être méprisé peut retenir la parole indépendamment du tort réellement causé."},{"function":"L’exemple","sentence":"Une maladresse sans victime peut ainsi être plus difficile à raconter qu’une action grave dont on assume le récit."},{"function":"La portée","sentence":"Cette distinction invite à examiner ce qui résiste dans l’aveu, sans minimiser la responsabilité attachée aux actes criminels."}],"uses":[{"subject":"Faut-il toujours dire la vérité ?","function":"Identifier un coût de la sincérité distinct du jugement moral","reason":"Un aveu peut exposer au ridicule sans révéler de faute grave ; sa difficulté ne suffit pas à établir qu’il constitue toujours un devoir envers autrui.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"rousseau-payer-ses-coups-pour-voler","code":"RC04","author":"Rousseau","title":"Payer ses coups pour voler","work":"Les Confessions","locator":"Livre I · p. 71 (PDF p. 75)","quote":"Je jugeais que me battre comme fripon, c’était m’autoriser à l’être.","notions":["justice","devoir","liberte"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Maltraité chez son maître d’apprentissage, le jeune Rousseau interprète les coups reçus comme une compensation qui lui permettrait de voler.","commentary":[{"function":"Le problème","sentence":"Une punition empêche-t-elle nécessairement la conduite qu’elle condamne ?"},{"function":"L’affirmation","sentence":"Rousseau raconte avoir interprété les coups de son maître comme une autorisation de devenir fripon."},{"function":"Les concepts","sentence":"La sanction cesse alors de rappeler une règle et devient, dans son raisonnement, le prix supposé d’une transgression."},{"function":"La raison","sentence":"En estimant avoir déjà payé par la souffrance, il transforme la peine subie en justification de nouvelles fautes."},{"function":"L’exemple","sentence":"Dans cet apprentissage, les mauvais traitements nourrissent ainsi la volonté de voler au lieu de la faire disparaître."},{"function":"La portée","sentence":"Le récit critique un effet possible de la violence punitive, sans valider l’excuse que le jeune homme se donnait."}],"uses":[{"subject":"Est-ce pour prévenir la récidive que la justice punit ?","function":"Éprouver les effets éducatifs attendus de la peine","reason":"Les coups reçus dans une relation de maltraitance nourrissent ici la récidive ; une peine publique doit être jugée selon d’autres garanties que cette violence privée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Analyser une justification trompeuse de l’injustice","reason":"Les coups expliquent le raisonnement de l’apprenti mais ne rendent pas son vol juste : une cause de l’acte n’est pas une autorisation morale.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}]},{"id":"rousseau-voler-le-talent-avec-ses-uvres","code":"RC05","author":"Rousseau","title":"Voler le talent avec ses œuvres","work":"Les Confessions","locator":"Livre I · p. 71 (PDF p. 75)","quote":"je croyais voler le talent avec ses productions.","notions":["art","travail","technique"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Apprenti graveur, Rousseau dérobe des outils et des productions de son maître en imaginant s’approprier aussi son savoir-faire.","commentary":[{"function":"Le problème","sentence":"Posséder les résultats d’un travail permet-il de posséder le talent qui les produit ?"},{"function":"L’affirmation","sentence":"Le jeune Rousseau croit pouvoir voler un talent en dérobant ses productions."},{"function":"Les concepts","sentence":"L’objet réalisé se distingue de la capacité acquise par laquelle il a été fabriqué."},{"function":"La raison","sentence":"Des outils et des modèles peuvent aider à apprendre, mais leur possession ne transmet pas immédiatement la maîtrise du geste."},{"function":"L’exemple","sentence":"L’apprenti s’empare ainsi d’empreintes et d’ouvrages sans acquérir par ce seul vol l’habileté de son maître."},{"function":"La portée","sentence":"L’erreur racontée fait voir la différence entre avoir une œuvre et savoir la produire, sans nier le rôle formateur des modèles."}],"uses":[{"subject":"L’activité artistique est-elle un travail ?","function":"Distinguer le résultat visible et la capacité acquise","reason":"Posséder une œuvre ne transmet pas le talent : la capacité de produire exige encore l’exercice et l’apprentissage du geste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Préciser les conditions d’un usage formateur des modèles","reason":"Disposer de productions à imiter ne suffit pas ; l’imitation doit devenir une activité d’apprentissage et de transformation du geste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"rousseau-la-foi-recue","code":"RC06","author":"Rousseau","title":"La foi reçue","work":"Les Confessions","locator":"Livre II · p. 99 (PDF p. 103)","quote":"la foi dogmatique est un fruit de l’éducation.","notions":["religion","raison","verite"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"À propos de sa conversion, Rousseau distingue les doctrines religieuses apprises de ce qu’un enfant peut comprendre par lui-même.","commentary":[{"function":"Le problème","sentence":"Nos convictions religieuses sont-elles indépendantes de ce que l’on nous a enseigné ?"},{"function":"L’affirmation","sentence":"Rousseau présente la foi dogmatique comme le produit d’une éducation."},{"function":"Les concepts","sentence":"La foi dogmatique désigne ici l’adhésion à des doctrines déterminées, distincte d’un simple sentiment religieux."},{"function":"La raison","sentence":"Le milieu dans lequel un enfant grandit lui transmet des croyances avant qu’il puisse en discuter les fondements."},{"function":"L’exemple","sentence":"Rousseau remarque ainsi qu’il reprenait les convictions inculquées autour de lui sans encore les comprendre pleinement."},{"function":"La portée","sentence":"Expliquer cette transmission invite à un examen personnel, mais ne suffit pas à prouver que toute croyance reçue serait fausse."}],"uses":[{"subject":"La religion est-elle une production culturelle comme les autres ?","function":"Identifier la transmission des doctrines religieuses","reason":"L’éducation explique la transmission d’une foi déterminée, mais son origine culturelle ne tranche pas à elle seule la question de sa vérité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"Peut-on expliquer la croyance religieuse sans la détruire ?","function":"Séparer l’origine d’une conviction et sa justification","reason":"Une croyance apprise peut ensuite être examinée et reprise ; sa provenance éducative ne constitue pas à elle seule une réfutation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"}]},{"id":"rousseau-des-impromptus-a-loisir","code":"RC07","author":"Rousseau","title":"Des impromptus à loisir","work":"Les Confessions","locator":"Livre III · p. 151 (PDF p. 155)","quote":"je fais d’excellents impromptus à loisir","notions":["art","temps","travail"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Décrivant la lenteur avec laquelle ses idées se forment, Rousseau oppose son écriture préparée à sa difficulté de répondre immédiatement.","commentary":[{"function":"Le problème","sentence":"Ce qui paraît spontané doit-il nécessairement naître dans l’instant ?"},{"function":"L’affirmation","sentence":"Rousseau associe paradoxalement l’impromptu à la disponibilité d’un temps de préparation."},{"function":"Les concepts","sentence":"L’impromptu suggère une invention immédiate, tandis que le loisir désigne le temps nécessaire à l’élaboration."},{"function":"La raison","sentence":"La vivacité d’une expression peut résulter d’une maturation que son destinataire ne voit pas."},{"function":"L’exemple","sentence":"Rousseau précise ainsi que ses manuscrits raturés témoignent du travail qui précède la clarté de ses formulations."},{"function":"La portée","sentence":"Sa formule permet de distinguer l’effet de spontanéité et les conditions de création, sans nier toute invention véritablement immédiate."}],"uses":[{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Rendre visible une préparation derrière la spontanéité","reason":"L’expression vive peut venir après un long travail ; l’apparence d’aisance ne suffit pas à expliquer l’œuvre par une inspiration instantanée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’activité artistique est-elle un travail ?","function":"Montrer le travail d’élaboration de la forme","reason":"La maturation et les ratures rendent possible l’aisance finale ; l’absence apparente d’effort ne révèle pas les conditions de création.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"rousseau-douze-heures-et-des-siecles","code":"RC08","author":"Rousseau","title":"Douze heures et des siècles","work":"Les Confessions","locator":"Livre IV · p. 177 (PDF p. 181)","quote":"Douze heures passées ensemble nous valaient des siècles de familiarité.","notions":["temps","conscience","bonheur"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Après une journée avec Mlles de Graffenried et Galley, Rousseau évoque l’intimité née d’une rencontre pourtant très brève.","commentary":[{"function":"Le problème","sentence":"La durée d’une relation se réduit-elle au nombre d’heures écoulées ?"},{"function":"L’affirmation","sentence":"Rousseau donne à douze heures partagées la valeur de siècles de familiarité."},{"function":"Les concepts","sentence":"Le temps mesuré reste bref, mais la proximité éprouvée lui donne une profondeur affective considérable."},{"function":"La raison","sentence":"L’intensité d’une expérience peut transformer rapidement le rapport que des personnes entretiennent entre elles."},{"function":"L’exemple","sentence":"La journée de promenade et de jeux racontée dans ce passage lui laisse ainsi le sentiment d’une intimité ancienne."},{"function":"La portée","sentence":"L’exagération rend sensible la différence entre durée mesurée et durée vécue, sans affirmer que les horloges avancent différemment."}],"uses":[{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer quantité mesurée et intensité vécue","reason":"Le décompte de douze heures ne décrit ni l’intimité éprouvée ni sa valeur affective ; l’expérience déborde sa mesure.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"L’éphémère a-t-il de la valeur ?","function":"Montrer la profondeur d’une rencontre brève","reason":"La brièveté n’empêche pas la familiarité ni le souvenir durable ; la valeur d’un moment ne se déduit pas seulement de sa durée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"rousseau-une-verite-mal-fondee","code":"RC09","author":"Rousseau","title":"Une vérité mal fondée","work":"Les Confessions","locator":"Livre IV · p. 191 (PDF p. 195)","quote":"lors même qu’on rencontre la vérité, l’on est sujet à se fonder sur des principes trompeurs!","notions":["verite","raison","science"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Un homme découvre que Rousseau ment sur son origine, mais emploie un test qui pourrait aussi tromper un véritable Parisien.","commentary":[{"function":"Le problème","sentence":"Une conclusion vraie garantit-elle la qualité du raisonnement qui y conduit ?"},{"function":"L’affirmation","sentence":"Rousseau rappelle qu’on peut rencontrer la vérité en partant de principes trompeurs."},{"function":"Les concepts","sentence":"La vérité d’une conclusion se distingue de la solidité des raisons proposées pour la soutenir."},{"function":"La raison","sentence":"Un indice mal choisi peut confirmer par hasard un fait réel tout en conduisant ailleurs à une erreur."},{"function":"L’exemple","sentence":"Ignorer un détail du Marché-Neuf ne prouve pas que l’on n’a jamais vécu à Paris, même si Rousseau mentait alors sur son origine."},{"function":"La portée","sentence":"Le récit invite donc à vérifier la méthode autant que le résultat, sans conclure que toute preuve serait illusoire."}],"uses":[{"subject":"Comment peut-on savoir que l’on a raison ?","function":"Distinguer conclusion vraie et connaissance justifiée","reason":"Le soupçon est confirmé, mais son critère reste trompeur ; la réussite ponctuelle ne valide pas le raisonnement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Faut-il se méfier des évidences ?","function":"Mettre à l’épreuve un indice apparemment décisif","reason":"Une personne peut avoir vécu à Paris sans connaître un détail local : ce contre-exemple montre pourquoi le critère du soupçon reste fragile, même s’il conduit ici à une conclusion vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"rousseau-aimer-sans-convoiter","code":"RC10","author":"Rousseau","title":"Aimer sans convoiter","work":"Les Confessions","locator":"Livre V · p. 234 (PDF p. 238)","quote":"Enfin, je l’aimais trop pour la convoiter : voilà ce qu’il y a de plus clair dans mes idées.","notions":["bonheur","conscience","liberte"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Rousseau décrit son attachement à Mme de Warens et la tonalité presque filiale qui rend son désir de possession difficile.","commentary":[{"function":"Le problème","sentence":"Aimer quelqu’un se confond-il nécessairement avec le désir de le posséder ?"},{"function":"L’affirmation","sentence":"Rousseau décrit un amour si tendre qu’il ne se traduit pas par la convoitise."},{"function":"Les concepts","sentence":"L’attachement à une personne se distingue ici de l’attente d’une jouissance centrée sur soi."},{"function":"La raison","sentence":"La familiarité affective et presque filiale transforme le sens de la relation au lieu d’en diminuer simplement la force."},{"function":"L’exemple","sentence":"Son lien avec Mme de Warens devient ainsi plus tendre sans rendre sa première union physique plus heureuse."},{"function":"La portée","sentence":"Le passage invite à distinguer les formes du désir et de l’amour, sans prétendre que toute affection profonde exclurait la sexualité."}],"uses":[{"subject":"Le désir nous éloigne-t-il d’autrui ?","function":"Distinguer attachement à une personne et convoitise","reason":"L’amour ne se réduit pas à vouloir posséder : un attachement peut accueillir l’autre plutôt que l’enfermer dans la satisfaction attendue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=81","sourceLabel":"Recueil académique · p. 81"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer la jouissance obtenue et l’accord affectif","reason":"L’union désirée ne donne pas automatiquement le bonheur ; considérer l’histoire et la signification du lien, au-delà de la seule satisfaction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=16","sourceLabel":"Recueil académique · p. 16"}]},{"id":"rousseau-vivre-et-sepuiser-par-ses-passions","code":"RC11","author":"Rousseau","title":"Vivre et s’épuiser par ses passions","work":"Les Confessions","locator":"Livre V · p. 255 (PDF p. 259)","quote":"Mes passions m’ont fait vivre, et mes passions m’ont tué.","notions":["bonheur","conscience","liberte"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Rousseau attribue à l’intensité de ses passions aussi bien la force de son existence que son épuisement physique.","commentary":[{"function":"Le problème","sentence":"Ce qui donne de l’intensité à la vie peut-il aussi l’épuiser ?"},{"function":"L’affirmation","sentence":"Rousseau attribue à ses passions le double effet de le faire vivre et de le détruire."},{"function":"Les concepts","sentence":"La passion désigne ici un investissement qui mobilise fortement les sensations, l’imagination et les forces du corps."},{"function":"La raison","sentence":"La même intensité nourrit l’attachement aux choses et rend difficile toute mesure dans la manière de s’y livrer."},{"function":"L’exemple","sentence":"Il évoque notamment la musique et les lectures auxquelles il se donne avec une ardeur qui finit par le fatiguer."},{"function":"La portée","sentence":"L’expression dramatise cette ambivalence sans constituer un diagnostic médical ni établir que toute passion serait nécessairement destructrice."}],"uses":[{"subject":"Toute passion est-elle déraisonnable ?","function":"Distinguer la puissance d’un attachement et son dérèglement","reason":"Le même élan anime et épuise ; sa valeur dépend de son orientation et de ses effets, pas de sa seule intensité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Être raisonnable, est-ce faire taire ses désirs ?","function":"Poser le problème d’une mesure qui ne supprime pas la vie affective","reason":"Si les passions font aussi vivre, leur extinction ne constitue pas immédiatement un idéal ; la raison doit encore en apprécier la mesure et les effets.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"}]},{"id":"rousseau-une-confiance-sans-contrainte","code":"RC12","author":"Rousseau","title":"Une confiance sans contrainte","work":"Les Confessions","locator":"Livre VI · p. 273 (PDF p. 277)","quote":"Je voulais qu’ils m’aimassent en liberté.","notions":["nature","devoir","liberte"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Rousseau évoque les animaux apprivoisés, notamment ses pigeons, et la confiance qu’il souhaite leur inspirer sans la trahir.","commentary":[{"function":"Le problème","sentence":"Une relation avec l’animal peut-elle viser autre chose que son obéissance ?"},{"function":"L’affirmation","sentence":"Rousseau souhaite être aimé des animaux tout en les laissant libres de venir à lui."},{"function":"Les concepts","sentence":"La confiance se distingue ici d’une docilité obtenue par la peur ou par une contrainte immédiate."},{"function":"La raison","sentence":"Elle demande que l’animal puisse approcher sans que sa vulnérabilité soit utilisée contre lui."},{"function":"L’exemple","sentence":"Les pigeons familiers viennent sur ses bras et sur sa tête parce qu’il les a accoutumés à ne pas le craindre."},{"function":"La portée","sentence":"Ce souhait ouvre une réflexion sur les limites de la domination, sans prouver que l’attachement animal serait identique à l’amour humain."}],"uses":[{"subject":"Avons-nous des devoirs envers la nature ?","function":"Donner un contenu concret à la responsabilité envers les animaux","reason":"La confiance suscitée chez l’animal peut engager notre conduite sans supposer qu’il ait contracté avec nous une obligation réciproque.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=23","sourceLabel":"Recueil académique · p. 23"},{"subject":"Le projet de maîtriser la nature est-il raisonnable ?","function":"Distinguer coopération et domination sans limites","reason":"La confiance laisse l’animal libre d’approcher ; une maîtrise réduite à l’obéissance ferait perdre cette qualité de la relation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"}]},{"id":"rousseau-se-sentir-petit-et-lame-elevee","code":"RC13","author":"Rousseau","title":"Se sentir petit et l’âme élevée","work":"Les Confessions","locator":"Livre VI · p. 294 (PDF p. 298)","quote":"Je sentais, tout en me faisant petit, je ne sais quoi qui m’élevait l’âme","notions":["art","conscience","technique"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Devant le pont du Gard, Rousseau éprouve sa petitesse corporelle et admire la puissance humaine manifestée par le monument.","commentary":[{"function":"Le problème","sentence":"Pourquoi la petitesse éprouvée devant un monument peut-elle s’accompagner d’une élévation intérieure ?"},{"function":"L’affirmation","sentence":"Rousseau décrit une admiration qui le fait se sentir petit tout en lui élevant l’âme."},{"function":"Les concepts","sentence":"La petitesse concerne sa place sensible dans l’espace, tandis que l’élévation désigne la valeur qu’il éprouve dans cette rencontre."},{"function":"La raison","sentence":"L’immensité de l’ouvrage dépasse son corps mais lui rend présente la puissance de ceux qui l’ont construit."},{"function":"L’exemple","sentence":"En parcourant les voûtes du pont du Gard, il se compare à un insecte et admire les bâtisseurs romains."},{"function":"La portée","sentence":"Cette expérience permet d’interroger une grandeur esthétique qui excède l’agrément, sans réduire la valeur du monument à ses seules dimensions."}],"uses":[{"subject":"L’expérience de l’œuvre d’art modifie-t-elle la conscience que nous avons du monde ?","function":"Analyser une transformation de la relation à soi et à l’espace","reason":"Le monument change le sentiment de sa propre taille et de la puissance humaine ; la perception devient une expérience de valeur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=8","sourceLabel":"Recueil académique · p. 8"},{"subject":"Beauté et utilité sont-elles incompatibles ?","function":"Montrer qu’un ouvrage utile peut susciter une expérience esthétique","reason":"L’aqueduc demeure utile tout en suscitant une expérience d’élévation ; sa fonction technique n’exclut donc pas sa valeur esthétique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"rousseau-la-vertu-et-la-fierte-de-soi","code":"RC14","author":"Rousseau","title":"La vertu et la fierté de soi","work":"Les Confessions","locator":"Livre VI · p. 298 (PDF p. 302)","quote":"L’orgueil eut peut-être autant de part à ma résolution que la vertu","notions":["devoir","conscience","verite"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Après avoir renoncé à retrouver Mme de Larnage, Rousseau s’interroge sur les motifs de sa résolution et sur sa propre estime.","commentary":[{"function":"Le problème","sentence":"Une conduite conforme au devoir révèle-t-elle toujours un motif purement moral ?"},{"function":"L’affirmation","sentence":"Rousseau reconnaît que sa fierté personnelle a peut-être autant guidé sa résolution que la vertu."},{"function":"Les concepts","sentence":"La conformité au devoir se distingue du motif qui conduit à l’accomplir, notamment le souci de sa propre estime."},{"function":"La raison","sentence":"Des motivations différentes peuvent soutenir le même choix et rester difficiles à séparer dans la conscience."},{"function":"L’exemple","sentence":"Renoncer à une aventure peut ainsi répondre à la fidélité comme au désir de ne pas démentir l’image que l’on se fait de soi."},{"function":"La portée","sentence":"Cet examen complique le jugement moral sur les intentions sans retirer toute valeur à une résolution dont les motifs sont mêlés."}],"uses":[{"subject":"Est-ce l’intention qui fait la valeur morale de nos actes ?","function":"Distinguer l’acte visible et la pluralité de ses motifs","reason":"Une résolution peut mêler vertu et orgueil : sa conformité au devoir ne suffit pas à rendre transparent le motif qui la soutient.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Mettre à l’épreuve la satisfaction de soi","reason":"L’estime éprouvée après le choix ne certifie pas la pureté de son motif ; la conscience doit encore examiner ce qui l’a guidée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"rousseau-voir-le-mal-sans-pouvoir-y-remedier","code":"RC15","author":"Rousseau","title":"Voir le mal sans pouvoir y remédier","work":"Les Confessions","locator":"Livre VI · p. 305 (PDF p. 309)","quote":"Mais que me servait de voir le mal sans savoir appliquer le remède ?","notions":["raison","technique","travail"],"edition":"Tome I, présentation de Michel Launay, Garnier-Flammarion","publisher":"Flammarion","editionYear":1968,"translator":null,"originalLanguage":"français","situation":"Précepteur chez M. de Mably, Rousseau reconnaît ses erreurs et celles de ses élèves sans parvenir à transformer sa manière de les instruire.","commentary":[{"function":"Le problème","sentence":"Comprendre ce qui ne va pas suffit-il pour savoir agir efficacement ?"},{"function":"L’affirmation","sentence":"Rousseau constate que voir le mal ne lui donnait pas la capacité d’appliquer le remède."},{"function":"Les concepts","sentence":"Le diagnostic désigne la reconnaissance d’une difficulté, tandis que le savoir pratique concerne les moyens de la résoudre."},{"function":"La raison","sentence":"Une connaissance de la situation reste insuffisante si celui qui agit manque de patience, de méthode ou de maîtrise de soi."},{"function":"L’exemple","sentence":"Comme précepteur, il comprend les ruses de ses élèves mais répond par une colère qui rend son enseignement inefficace."},{"function":"La portée","sentence":"Le passage distingue donc comprendre et savoir intervenir, sans conclure que la réflexion serait inutile à l’action."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Distinguer une aide nécessaire et une condition suffisante","reason":"Le diagnostic oriente l’action sans en donner toute la capacité ; l’efficacité exige aussi des habitudes, une méthode et un jugement pratique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La valeur d’une théorie se mesure-t-elle à son efficacité pratique ?","function":"Distinguer justesse de l’analyse et réussite de son application","reason":"Une analyse peut être juste alors que l’intervention échoue ; sa vérité et les moyens de la mettre en œuvre doivent donc être évalués séparément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=104","sourceLabel":"Recueil académique · p. 104"}]},{"id":"cioran-cahiers-rhume-savant","code":"C19","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le rhume et la Sorbonne","work":"Cahiers 1957–1972","locator":"Cahier de 1959, note « Enrhumé six mois par an ! »","quote":"Enrhumé six mois par an ! Je devrais écrire un livre au titre sorbonnard : Phénoménologie de l’enchifrènement.","notions":["langage","verite"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Un vocabulaire savant garantit-il une pensée plus précise ?"},{"function":"L’affirmation","sentence":"Cioran imagine d’élever un banal rhume au rang d’un imposant sujet universitaire."},{"function":"Les concepts","sentence":"La phénoménologie désigne une tradition philosophique ; l’enchifrènement est un encombrement nasal qui altère la voix."},{"function":"La raison","sentence":"Le contraste entre la plainte familière et le titre solennel rend comique la disproportion entre une expérience et sa présentation."},{"function":"L’exemple","sentence":"Un titre de thèse impressionnant peut annoncer une description banale, sans expliquer davantage le phénomène."},{"function":"La portée","sentence":"Cette parodie ne condamne pas toute technicité : elle invite à demander ce que les mots savants permettent réellement de comprendre."}],"uses":[{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35","function":"Distinguer précision et prestige du vocabulaire","reason":"Le titre imaginaire fait sentir qu’un nom savant peut impressionner sans rien expliquer ; il ne prouve pas que tout terme technique soit inutile."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-rhume-savant"},{"id":"cioran-cahiers-vertu-paresse","code":"C20","author":"Cioran","authorRole":"Écrivain et penseur","title":"La vertu par paresse","work":"Cahiers 1957–1972","locator":"Cahier de 1960, note « Tout ce que j’ai de bon… »","quote":"Tout ce que j’ai de bon vient de ma paresse ; sans elle, qui m’aurait empêché de mettre en application mes mauvais desseins ? Elle m’a heureusement contenu dans les limites de la « vertu ».","notions":["devoir","liberte"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Ne pas commettre le mal suffit-il à être vertueux ?"},{"function":"L’affirmation","sentence":"Cioran attribue plaisamment ce qu’il a de bon à la paresse qui l’aurait empêché de réaliser ses mauvais desseins."},{"function":"Les concepts","sentence":"La vertu désigne normalement une disposition à bien agir ; l’inaction ne garantit ni une bonne intention ni un choix moral."},{"function":"La raison","sentence":"La question sur les mauvais desseins révèle une retenue subie plutôt qu’un effort pour devenir meilleur."},{"function":"L’exemple","sentence":"Quelqu’un peut ne pas nuire faute d’énergie, tout en conservant le projet de nuire."},{"function":"La portée","sentence":"Les guillemets autour de vertu signalent l’écart entre une conduite extérieurement inoffensive et sa valeur morale ; l’ironie atteint aussi celui qui parle."}],"uses":[{"subject":"Est-ce l’intention qui fait la valeur morale de nos actes ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115","function":"Distinguer l’innocuité d’une conduite et sa valeur morale","reason":"L’aveu ironique sépare des conséquences inoffensives d’intentions mauvaises : être empêché d’agir ne suffit pas à avoir voulu le bien."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-vertu-paresse"},{"id":"cioran-cahiers-providence-diners","code":"C21","author":"Cioran","authorRole":"Écrivain et penseur","title":"La Providence à table","work":"Cahiers 1957–1972","locator":"Cahier de 1962, note « L’ennui aux dîners… »","quote":"L’ennui aux dîners est un argument contre la Providence.","notions":["religion","raison"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Une expérience déplaisante permet-elle de contester la bonté de l’ordre du monde ?"},{"function":"L’affirmation","sentence":"Cioran présente l’ennui d’un dîner comme un argument contre la Providence."},{"function":"Les concepts","sentence":"La Providence désigne ici un gouvernement divin du monde orienté vers le bien, et non la seule existence de Dieu."},{"function":"La raison","sentence":"Le rapprochement d’une gêne mondaine et d’une question théologique produit une disproportion comique."},{"function":"L’exemple","sentence":"Une conversation qui n’en finit pas fait alors figure de défaut dans l’ordre de l’univers."},{"function":"La portée","sentence":"La boutade raille autant les dîners que l’attente d’un monde agréable ; elle ne constitue pas une réfutation de l’existence de Dieu."}],"uses":[{"subject":"Est-il déraisonnable de croire en Dieu ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50","function":"Examiner ce qu’une objection permet réellement de conclure","reason":"L’ennui peut faire sourire aux dépens d’une Providence supposée bienveillante, mais il ne suffit pas à démontrer que toute croyance en Dieu est irrationnelle."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-providence-diners"},{"id":"cioran-cahiers-inspiration-rendez-vous","code":"C22","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le génie au mauvais moment","work":"Cahiers 1957–1972","locator":"Cahier de 1963, note « J’ai remarqué que l’« inspiration »… »","quote":"J’ai remarqué que l’« inspiration » ne me vient que lorsque je dois aller à un rendez-vous… J’y vais toujours avec le sentiment de manquer une occasion d’avoir du génie.","notions":["art","conscience"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"L’inspiration est-elle toujours une force créatrice, ou peut-elle servir d’excuse ?"},{"function":"L’affirmation","sentence":"Cioran remarque que son inspiration surgit précisément quand un rendez-vous va l’empêcher de travailler."},{"function":"Les concepts","sentence":"L’inspiration désigne un élan créateur ; le génie évoqué n’est ici qu’une possibilité regrettée, sans œuvre pour l’attester."},{"function":"La raison","sentence":"Les guillemets autour d’inspiration et la répétition des occasions manquées mettent à distance l’image flatteuse de l’artiste contrarié."},{"function":"L’exemple","sentence":"Se croire sur le point de créer au moment de sortir permet de préserver son talent supposé sans le confronter à une réalisation."},{"function":"La portée","sentence":"L’autodérision vise cette échappatoire possible ; elle n’établit pas que toute inspiration soit illusoire."}],"uses":[{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Mettre à l’épreuve le récit de l’inspiration","reason":"L’anecdote invite à distinguer le sentiment d’une puissance créatrice et la production effective d’une œuvre ; elle ne remplace pas l’analyse du travail artistique."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-inspiration-rendez-vous"},{"id":"cioran-cahiers-constantinople","code":"C23","author":"Cioran","authorRole":"Écrivain et penseur","title":"Tomber avec son livre","work":"Cahiers 1957–1972","locator":"Cahier de 1957, note « Lu un livre… »","quote":"Lu un livre sur la chute de Constantinople. Je suis tombé avec la ville.","notions":["art","conscience"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Peut-on être affecté par un événement auquel on n’a pas pris part ?"},{"function":"L’affirmation","sentence":"Cioran décrit sa lecture comme une chute vécue avec la ville dont parle le livre."},{"function":"Les concepts","sentence":"L’identification consiste ici à éprouver une proximité affective avec un événement éloigné, sans l’avoir réellement vécu."},{"function":"La raison","sentence":"La lecture peut donner une présence sensible à ce que l’on connaît seulement par un récit."},{"function":"L’exemple","sentence":"Un lecteur peut ressentir la défaite d’une ville disparue sans confondre cette émotion avec une expérience de témoin."},{"function":"La portée","sentence":"La formule atteste une émotion de lecture ; elle ne suffit pas à prouver une connaissance historique ni à identifier le genre du livre lu."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Distinguer participation affective et connaissance","reason":"La formule aide à examiner ce que fait éprouver un récit ; cette intensité n’établit pas, à elle seule, la vérité de ce qu’il raconte. La note ne donne pas le genre du livre : elle ne sert pas de preuve sur toutes les œuvres d’art."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-constantinople"},{"id":"cioran-cahiers-carte-postale","code":"C24","author":"Cioran","authorRole":"Écrivain et penseur","title":"La carte postale et Hegel","work":"Cahiers 1957–1972","locator":"Cahier de 1962, note « Écrire une carte postale… »","quote":"Écrire une carte postale se rapproche plus d’une activité créatrice que lire la Phénoménologie de l’esprit.","notions":["art","travail"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Le prestige de ce que l’on lit suffit-il à rendre son activité créatrice ?"},{"function":"L’affirmation","sentence":"Cioran place l’écriture d’une carte postale plus près de la création que la lecture d’un grand ouvrage philosophique."},{"function":"Les concepts","sentence":"Produire une formulation est un geste différent de recevoir un texte ; une activité créatrice n’est pas encore nécessairement une œuvre d’art."},{"function":"La raison","sentence":"La comparaison déplace l’attention de la grandeur de l’objet culturel vers ce que le sujet fait effectivement."},{"function":"L’exemple","sentence":"Rédiger une phrase personnelle peut solliciter une invention absente d’une lecture qui se contente de suivre une autorité."},{"function":"La portée","sentence":"Cette provocation laisse ouverte la possibilité d’une lecture active et ne démontre pas que toute carte postale aurait une valeur artistique."}],"uses":[{"subject":"La création artistique est-elle un travail ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68","function":"Examiner le geste de création plutôt que le prestige de son objet","reason":"La comparaison invite à chercher l’invention dans le travail d’une formulation. Elle ne permet ni d’assimiler toute écriture à l’art ni de réduire toute lecture à une réception passive."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-carte-postale"},{"id":"cioran-cahiers-lire-concierge","code":"C25","author":"Cioran","authorRole":"Écrivain et penseur","title":"Lire sans disséquer","work":"Cahiers 1957–1972","locator":"Cahier de 1967, note « J’aime lire comme lit une concierge… »","quote":"J’aime lire comme lit une concierge : m’identifier à l’auteur et au livre. Toute autre attitude me fait penser à l’espion ou au détective. Ou au dépeceur de cadavres.","notions":["art","raison"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Comprendre une œuvre exige-t-il toujours de prendre ses distances avec elle ?"},{"function":"L’affirmation","sentence":"Cioran préfère l’identification à l’auteur et au livre à une lecture conduite comme une enquête."},{"function":"Les concepts","sentence":"L’identification engage affectivement le lecteur ; l’analyse distingue des éléments et examine leurs rapports."},{"function":"La raison","sentence":"Une lecture peut perdre ce qui fait son intérêt pour le lecteur lorsqu’elle ne traite plus le livre que comme un objet à démonter."},{"function":"L’exemple","sentence":"Repérer toutes les techniques d’un récit n’explique pas encore pourquoi son expérience nous touche."},{"function":"La portée","sentence":"La violence de la comparaison défend un plaisir de lire ; elle ne prouve pas qu’une analyse attentive empêcherait nécessairement ce plaisir."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Interroger ce qu’une analyse laisse de côté","reason":"Le refus d’une lecture réduite à l’enquête oblige à examiner la part d’expérience sensible dans la rencontre avec l’œuvre. Il ne dispense pas d’argumenter ni de vérifier une interprétation."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-lire-concierge"},{"id":"cioran-cahiers-condoleances","code":"C26","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le génie d’une lettre ordinaire","work":"Cahiers 1957–1972","locator":"Cahier de 1969, note « Écrire une lettre de condoléances… »","quote":"Écrire une lettre de condoléances qui ne soit ni bête ni fausse, il y faut du génie.","notions":["langage","conscience"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Un sentiment sincère garantit-il que nous trouverons les mots justes ?"},{"function":"L’affirmation","sentence":"Cioran présente l’écriture d’une lettre de condoléances juste comme une tâche qui demanderait du génie."},{"function":"Les concepts","sentence":"La sincérité concerne ce que l’on éprouve ; la justesse d’une parole concerne aussi sa forme, son destinataire et la situation."},{"function":"La raison","sentence":"Le sentiment ne fournit pas immédiatement les mots qui évitent à la fois la banalité et la fausseté."},{"function":"L’exemple","sentence":"Une formule conventionnelle peut être sincère mais impersonnelle ; une phrase originale peut manquer de délicatesse."},{"function":"La portée","sentence":"L’exagération rend sensible une difficulté du langage sans établir que toute convention soit mensongère ou toute consolation impossible."}],"uses":[{"subject":"Le langage trahit-il la pensée ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36","function":"Distinguer sincérité du sentiment et justesse de son expression","reason":"La lettre montre qu’une intention sincère ne suffit pas à trouver une forme adéquate. La difficulté ne prouve pas l’impossibilité de communiquer : elle rend nécessaire un travail d’expression."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-condoleances"},{"id":"cioran-cahiers-ultimatum","code":"C27","author":"Cioran","authorRole":"Écrivain et penseur","title":"La résignation en guerre","work":"Cahiers 1957–1972","locator":"Cahier de 1972, note « Toutes mes pensées… »","quote":"Toutes mes pensées sont tournées vers la résignation, et il ne se passe pas de jour que je n’envoie un ultimatum à Dieu ou à ce qui en tient lieu.","notions":["conscience","liberte"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"Les dates des notes se distinguent de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Nos convictions déclarées suffisent-elles à décrire nos dispositions réelles ?"},{"function":"L’affirmation","sentence":"Cioran oppose ses pensées de résignation à ses protestations quotidiennes contre Dieu ou ce qui en tient lieu."},{"function":"Les concepts","sentence":"Se résigner signifie accepter ce que l’on ne peut changer ; envoyer un ultimatum revient à poser une exigence sous menace de rupture."},{"function":"La raison","sentence":"Une orientation intellectuelle peut donc coexister avec des réactions affectives qui lui résistent."},{"function":"L’exemple","sentence":"On peut reconnaître qu’une situation échappe à sa volonté et continuer à s’indigner de ce qu’elle impose."},{"function":"La portée","sentence":"L’aveu éclaire un désaccord avec soi-même ; il ne démontre ni une insincérité nécessaire ni l’impossibilité de toute maîtrise de soi."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45","function":"Distinguer l’adhésion à une règle et son appropriation vécue","reason":"La résignation pensée ne suffit pas à faire disparaître la colère. Cette résistance affective doit être examinée avant de conclure qu’une décision intellectuelle nous en libère."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-ultimatum"},{"id":"cioran-cahiers-style-monde","code":"C28","author":"Cioran","authorRole":"Écrivain et penseur","title":"Composer avec le mot","work":"Cahiers 1957–1972","locator":"Cahier de 1961, note débutant « Le style, si je m’y suis tant… »","quote":"Le style, si je m’y suis tant intéressé, c’est que j’y ai vu un défi au néant : faute de pouvoir composer avec le monde, il a bien fallu composer avec le mot.","notions":["art","langage"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Le langage sert-il seulement à transmettre une pensée déjà formée ?"},{"function":"L’affirmation","sentence":"Cioran présente le travail du style comme une réponse à une difficulté de vivre dans le monde."},{"function":"Les concepts","sentence":"Composer avec le monde signifie ici s’accommoder de lui ; composer avec le mot désigne aussi une activité de formulation."},{"function":"La raison","sentence":"Le langage peut donner une forme à une expérience qui résiste, sans supprimer matériellement ce qui nous atteint."},{"function":"L’exemple","sentence":"Écrire un malheur peut permettre de l’examiner et de le partager sans le faire disparaître."},{"function":"La portée","sentence":"Cette expérience du style éclaire un pouvoir de l’écriture ; elle ne démontre ni son efficacité pour tous ni son indépendance à l’égard du réel."}],"uses":[{"subject":"Le langage n’est-il qu’un outil ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35","function":"Examiner une fonction de l’écriture","reason":"Le langage peut donner une forme à une expérience qui résiste, sans supprimer matériellement ce qui nous atteint. Cette expérience du style éclaire un pouvoir de l’écriture ; elle ne démontre ni son efficacité pour tous ni son indépendance à l’égard du réel."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-style-monde"},{"id":"cioran-cahiers-amour-conviction","code":"C29","author":"Cioran","authorRole":"Écrivain et penseur","title":"Aimer sans y croire","work":"Cahiers 1957–1972","locator":"Cahier de 1962, note débutant « Quand on ne croit plus à l’amour,… »","quote":"Quand on ne croit plus à l’amour, on peut encore aimer, comme on peut combattre sans convictions. Cependant dans l’un et l’autre cas, quelque chose s’est brisé. Un édifice dont la fêlure tient lieu de style.","notions":["conscience","liberte"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Ce que nous croyons d’un sentiment suffit-il à décider de ce que nous éprouvons ?"},{"function":"L’affirmation","sentence":"Cioran envisage qu’on continue d’aimer ou de combattre après avoir perdu la conviction qui accompagnait ces conduites."},{"function":"Les concepts","sentence":"Une croyance affirme quelque chose ; un attachement ou un engagement vécu peut persister quand cette affirmation n’emporte plus l’adhésion."},{"function":"La raison","sentence":"Le changement du jugement ne transforme donc pas nécessairement d’un seul coup nos dispositions affectives."},{"function":"L’exemple","sentence":"On peut ne plus croire à l’avenir d’un amour et demeurer attaché à une personne."},{"function":"La portée","sentence":"La formule permet de distinguer conviction et sentiment ; elle ne prouve pas que toute lucidité condamnerait l’action ou rendrait l’amour faux."}],"uses":[{"subject":"Sommes-nous conscients de ce que nous désirons ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20","function":"Distinguer conscience du désir et pouvoir sur l’attachement","reason":"Le changement du jugement ne transforme donc pas nécessairement d’un seul coup nos dispositions affectives. La formule permet de distinguer conviction et sentiment ; elle ne prouve pas que toute lucidité condamnerait l’action ou rendrait l’amour faux."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-amour-conviction"},{"id":"cioran-cahiers-pensee-fragmentaire","code":"C30","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le fragment et la vie","work":"Cahiers 1957–1972","locator":"Cahier de 1962, note débutant « La pensée brisée, fragmentaire a tout le… »","quote":"La pensée brisée, fragmentaire a tout le décousu de la vie ; alors que l’autre, la cohérente, ne respecte que ses propres lois et ne condescendrait jamais à refléter la vie, encore moins à pactiser avec elle.","notions":["raison","art"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Une pensée doit-elle être entièrement continue pour rendre compte de l’expérience ?"},{"function":"L’affirmation","sentence":"Cioran prête à la pensée fragmentaire une proximité avec les discontinuités de la vie."},{"function":"Les concepts","sentence":"La cohérence organise des rapports entre les propositions ; la continuité d’une exposition ne garantit pas à elle seule sa fidélité à ce qu’elle examine."},{"function":"La raison","sentence":"Une construction peut devenir autonome au point de n’obéir qu’à ses règles, tandis qu’un fragment peut laisser apparaître une tension effective."},{"function":"L’exemple","sentence":"Des notes de recherche peuvent conserver une difficulté que l’exposé achevé tendrait à lisser."},{"function":"La portée","sentence":"L’opposition est polémique : le fragment ne dispense pas d’argumenter, et la cohérence peut aussi permettre de comprendre la vie."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Examiner ce qu’une forme fait connaître","reason":"Une construction peut devenir autonome au point de n’obéir qu’à ses règles, tandis qu’un fragment peut laisser apparaître une tension effective. L’opposition est polémique : le fragment ne dispense pas d’argumenter, et la cohérence peut aussi permettre de comprendre la vie."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-pensee-fragmentaire"},{"id":"cioran-cahiers-oeuvre-interpretations","code":"C31","author":"Cioran","authorRole":"Écrivain et penseur","title":"Une œuvre qui reste à lire","work":"Cahiers 1957–1972","locator":"Cahier de 1962, note débutant « Un livre n’est fécond et ne dure… »","quote":"Un livre n’est fécond et ne dure que s’il est susceptible de plusieurs interprétations différentes. Les œuvres qu’on peut définir sont essentiellement périssables.","notions":["art","verite"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Comprendre une œuvre consiste-t-il à lui donner une définition qui clôt sa lecture ?"},{"function":"L’affirmation","sentence":"Cioran relie la fécondité et la durée d’un livre à la diversité de ses interprétations."},{"function":"Les concepts","sentence":"Interpréter propose un sens à partir du texte ; définir une fois pour toutes prétend en fixer la portée."},{"function":"La raison","sentence":"Une œuvre peut continuer à faire penser lorsque de nouvelles lectures éclairent des rapports que la première n’avait pas épuisés."},{"function":"L’exemple","sentence":"Un même poème peut être relu pour ses enjeux politiques, sa voix et son invention formelle, à condition d’en donner les preuves."},{"function":"La portée","sentence":"La pluralité ne rend pas toute lecture valable : les mots, la composition et le contexte continuent de contraindre l’interprétation."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Distinguer ouverture du sens et arbitraire de la lecture","reason":"Une œuvre peut continuer à faire penser lorsque de nouvelles lectures éclairent des rapports que la première n’avait pas épuisés. La pluralité ne rend pas toute lecture valable : les mots, la composition et le contexte continuent de contraindre l’interprétation."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-oeuvre-interpretations"},{"id":"cioran-cahiers-vanite-capacites","code":"C32","author":"Cioran","authorRole":"Écrivain et penseur","title":"La vanité qui stimule","work":"Cahiers 1957–1972","locator":"Cahier de 1966, note débutant « Le désir de paraître intelligent augmente les… »","quote":"Le désir de paraître intelligent augmente les capacités d’une intelligence. Toute vanité stimule. Ceux qui en sont dépourvus demeurent en deçà d’eux-mêmes, laissent inexploitée une partie de leurs dons.","notions":["conscience","liberte"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Le désir de paraître nous éloigne-t-il nécessairement de nos capacités réelles ?"},{"function":"L’affirmation","sentence":"Cioran affirme que vouloir paraître intelligent peut stimuler l’intelligence."},{"function":"Les concepts","sentence":"La vanité dépend de l’image que l’on souhaite donner ; la capacité désigne ici ce que l’on parvient effectivement à faire."},{"function":"La raison","sentence":"Une motivation attachée au regard d’autrui peut donc pousser à exercer des facultés qui resteraient autrement inemployées."},{"function":"L’exemple","sentence":"Vouloir soutenir une discussion peut conduire à lire, à préciser un argument et à réviser une réponse."},{"function":"La portée","sentence":"Cette possibilité ne justifie ni toute vanité ni tout désir d’approbation : la recherche de l’effet peut aussi remplacer le travail réel."}],"uses":[{"subject":"Avons-nous besoin d’autrui pour avoir conscience de nous-mêmes ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19","function":"Examiner le rôle stimulant du regard d’autrui","reason":"Une motivation attachée au regard d’autrui peut donc pousser à exercer des facultés qui resteraient autrement inemployées. Cette possibilité ne justifie ni toute vanité ni tout désir d’approbation : la recherche de l’effet peut aussi remplacer le travail réel."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-vanite-capacites"},{"id":"cioran-cahiers-critique-deux-camps","code":"C33","author":"Cioran","authorRole":"Écrivain et penseur","title":"Examiner aussi les contestataires","work":"Cahiers 1957–1972","locator":"Cahier de 1968, note débutant « La vérité n’est ni dans la réaction… »","quote":"La vérité n’est ni dans la réaction ni dans la révolution. Elle réside dans la mise en question et de la société et de ceux qui l’attaquent.","notions":["etat","raison","verite"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"La contestation d’un ordre garantit-elle à elle seule la liberté du jugement ?"},{"function":"L’affirmation","sentence":"Cioran refuse de situer d’avance la vérité dans la réaction ou dans la révolution."},{"function":"Les concepts","sentence":"Un camp désigne une position collective ; l’examen critique porte sur ce qu’il affirme et fait, y compris lorsqu’il combat un pouvoir."},{"function":"La raison","sentence":"La critique de la société peut se retourner en nouvelle adhésion aveugle si ses acteurs deviennent eux-mêmes soustraits à l’examen."},{"function":"L’exemple","sentence":"Refuser un maître ne suffit pas à justifier toutes les exigences de ceux qui promettent de le remplacer."},{"function":"La portée","sentence":"La formule demande une vigilance symétrique ; elle ne démontre pas que tous les camps ni tous les ordres seraient équivalents."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38","function":"Éprouver l’autonomie d’un jugement contestataire","reason":"La critique de la société peut se retourner en nouvelle adhésion aveugle si ses acteurs deviennent eux-mêmes soustraits à l’examen. La formule demande une vigilance symétrique ; elle ne démontre pas que tous les camps ni tous les ordres seraient équivalents."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-critique-deux-camps"},{"id":"cioran-cahiers-doute-trompette","code":"C34","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le doute n’est pas une trompette","work":"Cahiers 1957–1972","locator":"Cahier de 1969, note débutant « Dès qu’on affecte un ton prophétique, il… »","quote":"Dès qu’on affecte un ton prophétique, il y a un début de rassemblement. Mais quand vous doutez, qui voulez-vous qui accoure ? Le doute n’est pas une trompette.","notions":["langage","raison","etat"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"L’efficacité d’un discours mesure-t-elle la valeur de ce qu’il affirme ?"},{"function":"L’affirmation","sentence":"Cioran oppose la puissance de rassemblement d’un ton prophétique à la difficulté de faire accourir autour du doute."},{"function":"Les concepts","sentence":"La certitude affichée peut mobiliser ; le doute demande de suspendre ou de reprendre le jugement."},{"function":"La raison","sentence":"Une affirmation peut donc convaincre par son assurance sans que cette force publique établisse sa vérité."},{"function":"L’exemple","sentence":"Un discours très sûr de lui peut attirer davantage qu’une réponse qui expose honnêtement ses incertitudes."},{"function":"La portée","sentence":"La comparaison décrit une difficulté de la parole critique, sans prouver que tout doute serait inaudible ni toute assurance trompeuse."}],"uses":[{"subject":"Le langage n’est-il qu’un outil ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35","function":"Distinguer force de conviction et valeur d’une affirmation","reason":"Une affirmation peut donc convaincre par son assurance sans que cette force publique établisse sa vérité. La comparaison décrit une difficulté de la parole critique, sans prouver que tout doute serait inaudible ni toute assurance trompeuse."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-doute-trompette"},{"id":"cioran-cahiers-temps-maladie","code":"C35","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le temps vu comme une maladie","work":"Cahiers 1957–1972","locator":"Cahier de 1970, note débutant « Je suis porté à voir tout phénomène… »","quote":"Je suis porté à voir tout phénomène comme l’aspect morbide d’un autre phénomène plus vaste. Ainsi le temps m’apparaît comme une maladie de l’éternité, l’Histoire comme une maladie du temps, et la vie comme une infirmité de la matière.","notions":["temps","nature","raison"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Une image de l’univers peut-elle faire connaître autre chose qu’une manière de l’éprouver ?"},{"function":"L’affirmation","sentence":"Cioran décrit le temps, l’histoire et la vie comme des altérations d’un ordre plus vaste."},{"function":"Les concepts","sentence":"La maladie sert ici d’image pour penser une dégradation ; elle ne désigne pas un diagnostic médical appliqué au temps."},{"function":"La raison","sentence":"Ce rapprochement rassemble des expériences différentes sous une même perception de l’existence."},{"function":"L’exemple","sentence":"Le passage du temps peut être vécu comme une perte, sans que cette expérience suffise à définir physiquement le temps."},{"function":"La portée","sentence":"La formule révèle un point de vue et invite à l’examiner ; sa force expressive ne vaut pas démonstration scientifique."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6","function":"Distinguer expression d’un vécu et connaissance d’un objet","reason":"Ce rapprochement rassemble des expériences différentes sous une même perception de l’existence. La formule révèle un point de vue et invite à l’examiner ; sa force expressive ne vaut pas démonstration scientifique."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-temps-maladie"},{"id":"cioran-cahiers-verite-chaine","code":"C36","author":"Cioran","authorRole":"Écrivain et penseur","title":"La vérité qui devient une chaîne","work":"Cahiers 1957–1972","locator":"Cahier de 1972, note débutant « Toute vérité donne une sensation de libération… »","quote":"Toute vérité donne une sensation de libération au moment où on la découvre ; puis, elle devient une chaîne. On peut en dire autant d’un dieu ; au début, quand on s’y attache, on respire, puis, on étouffe.","notions":["verite","liberte","raison"],"edition":"Cahiers 1957–1972, édition numérique","publisher":"Gallimard","editionYear":"2013","originalLanguage":"français","translator":null,"editionNote":"La date du cahier se distingue de celle de cette édition numérique, sans pagination fixe.","commentary":[{"function":"Le problème","sentence":"Une vérité qui libère peut-elle devenir un obstacle à l’examen ?"},{"function":"L’affirmation","sentence":"Cioran oppose la libération ressentie lors d’une découverte à l’attachement qui la transforme ensuite en chaîne."},{"function":"Les concepts","sentence":"La vérité d’une proposition se distingue du rapport que nous entretenons avec elle et de la certitude que nous lui attachons."},{"function":"La raison","sentence":"Un résultat peut ouvrir la recherche, puis la fermer si l’on traite comme intangible tout ce que l’on croit en tirer."},{"function":"L’exemple","sentence":"Une explication féconde peut devenir un schéma que l’on applique à tout sans plus tenir compte des objections."},{"function":"La portée","sentence":"La généralisation de Cioran doit être discutée : toute vérité ne devient pas nécessairement une contrainte, et une certitude peut rester révisable."}],"uses":[{"subject":"Les progrès de la connaissance nous rapprochent-ils d’une vérité définitive ?","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=72","sourceLabel":"Recueil académique · p. 72","function":"Distinguer progrès du savoir et clôture de l’examen","reason":"Un résultat peut ouvrir la recherche, puis la fermer si l’on traite comme intangible tout ce que l’on croit en tirer. La généralisation de Cioran doit être discutée : toute vérité ne devient pas nécessairement une contrainte, et une certitude peut rester révisable."}],"literaryUrl":"bibliotheque-dissertation.html#cioran-cahiers-verite-chaine"}]};
